/* =========================================================
   NO WAY! — mode CURSEUR (« à vue de nez »)
   Chaque question a une réponse CHIFFRÉE : le joueur place un
   curseur sur une échelle, et le plus proche remporte la manche.
   Structure : {t, q, n, min, max, u, e}
     t = thème (pastille) · q = énoncé · n = bonne réponse
     min/max = bornes de l'échelle · u = unité · e = explication
   Les échelles sont calculées pour que la réponse tombe tantôt au
   début, tantôt à la fin : viser le milieu ne paie pas.
   Chargé avant curseur.html ; expose la globale `QC`.
   ========================================================= */
const QC = [
/* ---------- Terre ---------- */
{t:'geo',q:"Combien de jours la Belgique a-t-elle tenu sans gouvernement ?",n:541,min:0,max:800,u:"jours",e:"541 jours entre 2010 et 2011. Les poubelles ont continué d'être ramassées, les trains de rouler : personne n'a vraiment remarqué."},
{t:'geo',q:"Quelle est la largeur moyenne du Chili ?",n:177,min:0,max:300,u:"km",e:"177 km de large pour 4 300 km de long. Le pays est plus étroit que la distance Paris-Lyon, mais s'étire sur un huitième du globe."},
{t:'geo',q:"À quelle altitude siège le gouvernement bolivien, à La Paz ?",n:3640,min:0,max:8000,u:"m",e:"3 640 m. Les moteurs y perdent un tiers de leur puissance et les visiteurs, leur souffle en montant un escalier."},
{t:'geo',q:"Quelle distance sépare les États-Unis de la Russie au point le plus proche ?",n:4,min:0,max:5,u:"km",e:"Moins de 4 km entre les deux îles Diomède. En hiver on pourrait presque traverser à pied — sauf que la ligne de changement de date passe entre les deux : 21 heures d'écart."},
{t:'geo',q:"Combien de lacs compte le Canada ?",n:2000000,min:0,max:3000000,u:"lacs",e:"Environ deux millions, soit plus que tout le reste du monde réuni. Héritage direct du rabotage des glaciers."},
{t:'geo',q:"Combien d'habitants compte le Vatican ?",n:800,min:0,max:2000,u:"habitants",e:"Environ 800 résidents, dont une large majorité de religieux. Le plus petit État du monde tient dans un rectangle qu'on traverse à pied en vingt minutes."},
{t:'geo',q:"De combien de minutes le Népal décale-t-il son heure sur ses voisins ?",n:45,min:0,max:400,u:"minutes",e:"45 minutes : l'un des rares pays au monde calé au quart d'heure, sur le méridien d'une montagne proche de Katmandou."},
{t:'geo',q:"Combien d'îles le Japon a-t-il recensées lors de son recomptage de 2023 ?",n:14125,min:0,max:50000,u:"îles",e:"14 125, soit plus du double du chiffre officiel précédent. Les cartes numériques ont simplement révélé des milliers d'îlots jamais comptés."},
{t:'geo',q:"Quelle est la profondeur du lac Baïkal ?",n:1642,min:0,max:5000,u:"m",e:"1 642 m : on pourrait y empiler cinq tours Eiffel. Il contient à lui seul près d'un cinquième de l'eau douce liquide de la planète."},
{t:'geo',q:"De combien la rive de la mer Morte se situe-t-elle sous le niveau de la mer ?",n:430,min:0,max:1200,u:"m",e:"Environ 430 m sous le niveau de la mer, le point émergé le plus bas du globe. Et il continue de descendre d'un mètre par an."},
{t:'geo',q:"À quelle distance de la terre la plus proche se trouve le point Nemo, l’endroit le plus isolé de l’océan ?",n:2688,min:0,max:4000,u:"km",e:"Perdu dans le Pacifique Sud. Quand la Station spatiale passe au-dessus, les humains les plus proches sont à 400 km… au-dessus de la tête, pas sur Terre."},
{t:'geo',q:"De combien le sommet du Chimborazo dépasse-t-il celui de l’Everest en distance au centre de la Terre ?",n:2072,min:0,max:10000,u:"m",e:"La Terre est aplatie aux pôles et renflée à l’équateur. Ce volcan équatorien culminant à 6 263 m est donc le point de la surface le plus éloigné du centre du globe."},
{t:'geo',q:"Quelle est la hauteur totale du Mauna Kea mesurée depuis sa base sous-marine ?",n:10210,min:0,max:80000,u:"m",e:"Hawaï. Émergé, il ne monte qu’à 4 207 m, mais son socle plonge à 6 000 m sous le Pacifique. De la base au sommet, il dépasse l’Everest de plus d’un kilomètre."},
{t:'geo',q:"Quelle profondeur a atteint le forage le plus profond jamais réalisé, à Kola en Russie ?",n:12262,min:0,max:80000,u:"m",e:"Vingt ans de forage pour percer 0,2 % du rayon terrestre. À 12 262 m, la roche atteignait 180 °C et se déformait comme du plastique : le trou se refermait. Ils ont abandonné."},
{t:'geo',q:"Quelle profondeur atteint le fond de la fosse des Mariannes ?",n:10935,min:0,max:15000,u:"m",e:"Environ 10 935 m au Challenger Deep. L’Everest y tiendrait entièrement avec deux kilomètres d’eau au-dessus du sommet. La pression y dépasse mille fois celle de la surface."},
{t:'geo',q:"À quelle profondeur sous le niveau de la mer descend la fosse subglaciaire de Bentley, point continental le plus bas ?",n:2540,min:0,max:4000,u:"m",e:"En Antarctique, sous deux kilomètres de glace. C’est le plus bas de toute la croûte continentale, mais nul ne peut le voir : sans la glace, l’océan s’y engouffrerait."},
{t:'geo',q:"Quelle épaisseur atteint la glace au point le plus épais de l’Antarctique ?",n:4776,min:0,max:40000,u:"m",e:"Presque cinq kilomètres de glace empilée, mesurés en terre Adélie. Le poids a enfoncé la croûte terrestre de plusieurs centaines de mètres ; elle remonterait lentement si tout fondait."},
{t:'geo',q:"De combien monterait le niveau des mers si toute la glace de l’Antarctique fondait ?",n:58,min:0,max:250,u:"m",e:"Environ 58 mètres. L’Antarctique enferme à lui seul près de 90 % de la glace du monde. Le Groenland, lui, n’ajouterait « que » sept mètres."},
{t:'geo',q:"Quelle est la température de l’air la plus élevée jamais enregistrée sur Terre ?",n:56.7,min:0,max:100,u:"°C",e:"Furnace Creek, Vallée de la Mort, 10 juillet 1913. Le record de 58 °C revendiqué en Libye a été invalidé en 2012 : thermomètre mal lu par un opérateur inexpérimenté."},
{t:'geo',q:"De combien de degrés sous zéro était l’air lors du record mondial de froid ?",n:89.2,min:0,max:250,u:"°C",e:"Base Vostok, Antarctique, juillet 1983. À cette température, une inspiration profonde brûle les poumons et l’acier devient cassant comme du verre."},
{t:'geo',q:"De combien de degrés sous zéro est descendu le thermomètre à Oïmiakon, village habité le plus froid du monde ?",n:67.7,min:0,max:80,u:"°C",e:"Sibérie, 1933. On y laisse tourner les moteurs jour et nuit, le sol est trop gelé pour creuser des tombes et l’encre fige dans les stylos."},
{t:'geo',q:"Quelle est la température la plus chaude jamais mesurée en Antarctique ?",n:18.3,min:0,max:25,u:"°C",e:"Base Esperanza, péninsule antarctique, février 2020. Une douceur de printemps breton, validée par l’Organisation météorologique mondiale. Cette péninsule se réchauffe parmi les plus vite du globe."},
{t:'geo',q:"Quelle température de sol a été relevée par satellite dans le désert du Lout, en Iran ?",n:80.8,min:0,max:120,u:"°C",e:"Ce n’est pas l’air mais la surface du sol, mesurée depuis l’espace. Le sable y devient assez chaud pour cuire un œuf. Rien ne vit en surface, pas même les bactéries."},
{t:'geo',q:"Quelle est la température moyenne annuelle de Dallol, l’endroit habité le plus chaud du monde ?",n:34.4,min:0,max:40,u:"°C",e:"Dépression du Danakil, Éthiopie. Moyenne sur l’année entière, nuits comprises. Les caravaniers y découpent des briques de sel entre des sources acides où même les microbes peinent à survivre."},
{t:'geo',q:"Quelle quantité de pluie est tombée sur Cherrapunji lors de son année record ?",n:26461,min:0,max:30000,u:"mm",e:"Plus de vingt-six mètres d’eau en douze mois, dans les collines indiennes du Meghalaya. De quoi noyer un immeuble de huit étages. Paris reçoit environ 640 mm par an."},
{t:'geo',q:"Combien de pluie est tombée en vingt-quatre heures au piton Foc-Foc, à La Réunion ?",n:1825,min:0,max:2500,u:"mm",e:"Cyclone Denise, janvier 1966 : record mondial. Près de deux mètres d’eau en un jour. La Réunion détient presque tous les records mondiaux de pluie, de douze heures à quinze jours."},
{t:'geo',q:"Combien de pluie est tombée en quinze jours au cratère Commerson, à La Réunion ?",n:6083,min:0,max:10000,u:"mm",e:"Cyclone Hyacinthe, 1980. Six mètres d’eau en deux semaines : record mondial absolu. Ce cratère volcanique est un piège à nuages parfait, ouvert plein vent d’alizé."},
{t:'geo',q:"Depuis combien de temps certaines vallées sèches de l’Antarctique n’ont-elles pas reçu de précipitations ?",n:2000000,min:0,max:4000000,u:"années",e:"Les vallées sèches de McMurdo : des vents catabatiques si violents et un air si sec que la neige s’évapore avant de toucher le sol. La NASA y teste ses instruments martiens."},
{t:'geo',q:"Quelle vitesse a atteint la rafale de vent la plus rapide jamais mesurée à la surface du globe ?",n:408,min:0,max:2500,u:"km/h",e:"Île Barrow, Australie, cyclone Olivia, avril 1996. Plus vite qu’un TGV lancé. Le record précédent, détenu par le mont Washington depuis 1934, avait tenu soixante-deux ans."},
{t:'geo',q:"Quelle vitesse a atteint la rafale record du mont Washington, aux États-Unis, en 1934 ?",n:372,min:0,max:500,u:"km/h",e:"Trois observateurs ont vu leur bâtiment, arrimé par des chaînes, trembler des heures durant. Ce sommet modeste de 1 917 m se trouve au carrefour de trois trajectoires de tempêtes."},
{t:'geo',q:"Quelle pression a été mesurée au cœur du typhon Tip, la plus basse jamais relevée au niveau de la mer ?",n:870,min:0,max:1200,u:"hPa",e:"Pacifique, octobre 1979, relevé par avion. Une pression inférieure de 13 % à la normale : les oreilles se bouchent comme dans un ascenseur lancé vers le ciel."},
{t:'geo',q:"Quel diamètre atteignait le typhon Tip, la plus grande tempête tropicale jamais observée ?",n:2220,min:0,max:3000,u:"km",e:"Sa circulation couvrait presque la moitié des États-Unis. Un tel monstre posé sur l’Europe s’étendrait de Lisbonne à Varsovie."},
{t:'geo',q:"Combien de jours a duré l’ouragan John, le cyclone tropical le plus long jamais observé ?",n:31,min:0,max:50,u:"jours",e:"En 1994, il a traversé tout le Pacifique, changé de nom en typhon en franchissant la ligne de changement de date, puis repris son nom au retour. Plus de 13 000 km parcourus."},
{t:'geo',q:"Quelle largeur atteignait la tornade d’El Reno, la plus large jamais mesurée ?",n:4.2,min:0,max:5,u:"km",e:"Oklahoma, 31 mai 2013. Un entonnoir plus large que Manhattan, avec des vents relevés à 475 km/h. Trois chasseurs de tornades chevronnés y ont perdu la vie."},
{t:'geo',q:"Quelle distance a parcourue la tornade des Trois-États, la plus longue trajectoire jamais relevée ?",n:352,min:0,max:800,u:"km",e:"18 mars 1925, du Missouri à l’Indiana. Trois heures et demie au sol sans jamais se relever, à près de 100 km/h. Aucune autre tornade n’a approché ce chiffre."},
{t:'geo',q:"Quel diamètre atteignait le plus gros grêlon jamais ramassé aux États-Unis ?",n:20,min:0,max:60,u:"cm",e:"Vivian, Dakota du Sud, 2010 : vingt centimètres et près de 900 grammes, plus gros qu’un ballon de handball. Il avait déjà fondu plusieurs heures dans un congélateur en panne avant d’être mesuré."},
{t:'geo',q:"Combien de nuits par an l’orage permanent du Catatumbo éclate-t-il au Venezuela ?",n:260,min:0,max:500,u:"nuits",e:"À l’embouchure du Catatumbo, sur le lac Maracaibo, les éclairs tombent jusqu’à dix heures d’affilée. Les marins s’en servaient de phare naturel pour se repérer la nuit."},
{t:'geo',q:"Quelle hauteur a atteint la vague la plus haute jamais observée, dans la baie de Lituya ?",n:524,min:0,max:600,u:"m",e:"Alaska, 1958 : un séisme précipite trente millions de mètres cubes de roche dans un fjord étroit. La vague a rasé la forêt jusqu’à 524 m d’altitude. Deux pêcheurs ont survécu."},
{t:'geo',q:"Quelle hauteur avait la vague scélérate de Draupner, première jamais mesurée par un instrument ?",n:25.6,min:0,max:40,u:"m",e:"Mer du Nord, 1995. Les scientifiques tenaient ces vagues géantes pour des légendes de marins jusqu’à ce qu’un laser de plateforme pétrolière en enregistre une, un jour de mer pourtant ordinaire."},
{t:'geo',q:"Quelle amplitude atteignent les marées de la baie de Fundy, les plus fortes du monde ?",n:16.3,min:0,max:150,u:"m",e:"Canada. Un immeuble de cinq étages d’eau qui monte et descend deux fois par jour. Cent milliards de tonnes d’eau entrent et sortent de la baie à chaque cycle."},
{t:'geo',q:"Quelle hauteur de chute a la plus grande cascade du monde, cachée sous l’eau dans le détroit du Danemark ?",n:3505,min:0,max:5000,u:"m",e:"De l’eau arctique froide et dense dégringole sous l’Atlantique, totalement invisible depuis la surface. Son débit dépasse deux mille fois celui des chutes du Niagara."},
{t:'geo',q:"Quelle est la hauteur totale du Salto Ángel, plus haute cascade du monde ?",n:979,min:0,max:1200,u:"m",e:"Venezuela. L’eau tombe de si haut qu’en saison sèche elle se pulvérise en brume avant d’atteindre le sol. Un aviateur américain cherchant de l’or l’a révélée au monde."},
{t:'geo',q:"Quel est le débit moyen de l’Amazone à son embouchure ?",n:209000,min:0,max:1200000,u:"m³/s",e:"Un cinquième de toute l’eau douce qui rejoint les océans. Elle repousse la mer salée à plus de 100 km au large : les marins puisaient de l’eau douce sans voir la côte."},
{t:'geo',q:"Combien de pays le Danube traverse-t-il ou longe-t-il ?",n:10,min:0,max:80,u:"pays",e:"Allemagne, Autriche, Slovaquie, Hongrie, Croatie, Serbie, Roumanie, Bulgarie, Moldavie, Ukraine. Aucun autre fleuve du monde n’en arrose autant, et il change plusieurs fois de nom au passage."},
{t:'geo',q:"Combien de pays l’équateur traverse-t-il ?",n:13,min:0,max:15,u:"pays",e:"Treize seulement, dont deux insulaires. L’Équateur, qui lui doit son nom, est loin d’être celui où la ligne parcourt le plus de kilomètres : le Brésil détient ce titre."},
{t:'geo',q:"Quelle est la longueur de la frontière entre le Canada et les États-Unis, la plus longue du monde ?",n:8891,min:0,max:60000,u:"km",e:"Une tranchée de six mètres de large est déboisée en permanence sur presque tout le tracé pour la matérialiser. Le chiffre inclut les 2 475 km avec l’Alaska."},
{t:'geo',q:"Quelle longueur fait la frontière entre le Botswana et la Zambie, la plus courte du monde ?",n:150,min:0,max:200,u:"m",e:"Un simple point de contact au milieu du fleuve Zambèze, là où quatre pays se frôlent. Un pont l’enjambe depuis 2021 : traverser prend quelques secondes."},
{t:'geo',q:"Combien de parcelles belges forment l’enclave de Baarle-Hertog, en territoire néerlandais ?",n:22,min:0,max:100,u:"parcelles",e:"Plus sept contre-enclaves néerlandaises à l’intérieur. La frontière traverse des maisons : la nationalité d’un logement dépend de sa porte d’entrée, que certains ont déplacée pour changer de fisc."},
{t:'geo',q:"Combien d’enclaves l’Inde et le Bangladesh se sont-ils échangées lors de leur accord de 2015 ?",n:162,min:0,max:500,u:"enclaves",e:"L’une contenait une enclave contenant elle-même une contre-contre-enclave, cas unique au monde. Des dizaines de milliers d’habitants y vivaient sans État, sans école ni électricité, depuis 1947."},
{t:'geo',q:"Combien de pays du monde n’ont aucun accès à la mer ?",n:44,min:0,max:80,u:"pays",e:"Dont deux entièrement entourés d’autres pays eux-mêmes sans littoral : le Liechtenstein et l’Ouzbékistan. Il faut y franchir deux frontières au minimum pour apercevoir la mer."},
{t:'geo',q:"Combien de pays au monde sont entièrement entourés par un seul autre pays ?",n:3,min:0,max:4,u:"pays",e:"Le Lesotho dans l’Afrique du Sud, Saint-Marin et le Vatican dans l’Italie. Trois États dont la totalité des importations passe par un unique voisin."},
{t:'geo',q:"À quelle altitude se trouve le point le plus bas du Lesotho ?",n:1400,min:0,max:1500,u:"m",e:"C’est le point bas le plus élevé du monde : tout le pays est au-dessus de 1 400 m. On le surnomme le royaume dans le ciel, et il y neige en pleine Afrique australe."},
{t:'geo',q:"Quelle superficie fait Bir Tawil, ce territoire que ni l’Égypte ni le Soudan ne veulent revendiquer ?",n:2060,min:0,max:15000,u:"km²",e:"Deux tracés frontaliers rivaux : réclamer Bir Tawil obligerait à renoncer au triangle d’Hala’ib, bien plus grand et côtier. Résultat, personne ne veut de ce désert."},
{t:'geo',q:"Quelle surface occupe la principauté de Sealand, micronation installée sur une plateforme en mer du Nord ?",n:550,min:0,max:800,u:"m²",e:"Un ancien fort antiaérien britannique de 1942, occupé depuis 1967 par une famille qui frappe monnaie et vend des titres de noblesse. Aucun État ne la reconnaît."},
{t:'geo',q:"Quelle est la longueur du réseau ferré du Vatican, le plus court du monde ?",n:300,min:0,max:400,u:"m",e:"Trois cents mètres et une seule gare, achevés en 1934. Les trains entrent par un portail coulissant de vingt tonnes. Jean XXIII fut le premier pape à l’emprunter."},
{t:'geo',q:"À quelle altitude culmine le point le plus haut des Maldives ?",n:2.4,min:0,max:3,u:"m",e:"Le sommet national le plus bas de la planète : moins haut qu’un plafond d’appartement. Quatre-vingts pour cent des îles se situent à moins d’un mètre au-dessus de l’eau."},
{t:'geo',q:"Quelle proportion du territoire des Pays-Bas se situe sous le niveau de la mer ?",n:26,min:0,max:100,u:"%",e:"Un quart du pays, où vit environ un tiers de la population. Sans digues ni pompes, Rotterdam et l’aéroport de Schiphol, bâti quatre mètres sous le niveau marin, seraient noyés."},
{t:'geo',q:"Quelle superficie fait le Flevopolder, plus grande île artificielle du monde ?",n:970,min:0,max:1200,u:"km²",e:"Pays-Bas. Un morceau de mer asséché puis peuplé : la ville d’Almere et ses centaines de milliers d’habitants reposent sur un ancien fond marin. Les fermiers y déterrent encore des épaves."},
{t:'geo',q:"À quelle profondeur sous le niveau de la mer se trouve Jéricho, la ville la plus basse du monde ?",n:258,min:0,max:400,u:"m",e:"Dans la vallée du Jourdain. On y descend en voiture avec les oreilles qui se bouchent à l’envers. C’est aussi l’une des plus anciennes villes continûment habitées."},
{t:'geo',q:"De combien de kilomètres le diamètre de la Terre à l’équateur dépasse-t-il son diamètre d’un pôle à l’autre ?",n:43,min:0,max:80,u:"km",e:"La rotation renfle la planète à sa taille. Notre Terre n’est donc pas une sphère mais un ballon légèrement écrasé, et l’océan lui-même est plus « haut » à l’équateur."},
{t:'geo',q:"À quelle altitude vit la population permanente la plus haute du monde, à La Rinconada au Pérou ?",n:5100,min:0,max:12000,u:"m",e:"Une ville minière accrochée sous un glacier, sans eau courante, où l’oxygène est moitié moins dense qu’au niveau de la mer. Le sang des habitants s’épaissit anormalement pour compenser."},
{t:'geo',q:"À quelle altitude se trouve la surface du lac Titicaca ?",n:3812,min:0,max:15000,u:"m",e:"Des vapeurs britanniques du XIXᵉ siècle y ont été hissés à dos de mulet, en pièces détachées. À cette altitude l’eau bout à 88 °C : impossible d’y réussir un œuf dur."},
{t:'geo',q:"À quelle altitude se trouve le lac permanent le plus haut du monde, dans le cratère de l’Ojos del Salado ?",n:6390,min:0,max:10000,u:"m",e:"Une mare d’une centaine de mètres de diamètre, perchée près du sommet du plus haut volcan du monde, entre Chili et Argentine. Bien plus haut que le camp de base de l’Everest."},
{t:'geo',q:"De combien de mètres le Denali s’élève-t-il au-dessus de sa propre base ?",n:5500,min:0,max:15000,u:"m",e:"Alaska. L’Everest, posé sur un plateau à 5 200 m, ne dépasse sa base que de 3 600 m environ. Le Denali offre donc le plus grand dénivelé continu de toutes les montagnes émergées."},
{t:'geo',q:"Quelle hauteur fait la face Rupal du Nanga Parbat, le plus haut versant de montagne du monde ?",n:4600,min:0,max:8000,u:"m",e:"Pakistan. Un mur de 4,6 km d’un seul tenant, soit quinze tours Eiffel empilées. Il a fallu attendre 1970 pour qu’un alpiniste en vienne à bout."},
{t:'geo',q:"Quelle profondeur atteint le canyon du Yarlung Tsangpo, le plus profond du monde ?",n:6009,min:0,max:25000,u:"m",e:"Tibet. Six kilomètres de dénivelé entre le fleuve et les sommets qui l’encadrent, plus de trois fois le Grand Canyon. Son cœur le plus reculé n’a été exploré qu’en 1998."},
{t:'geo',q:"Combien de lettres compte le nom de lieu le plus long du monde, une colline de Nouvelle-Zélande ?",n:85,min:0,max:300,u:"lettres",e:"Taumatawhakatangihangakoauauotamateaturipukakapikimaungahoronukupokaiwhenuakitanatahu. En maori, la phrase raconte l’histoire d’un homme qui jouait de la flûte à sa bien-aimée. La colline, elle, ne fait que 305 mètres."},
{t:'geo',q:"Quelle profondeur atteint la Verevkina, la grotte la plus profonde du monde ?",n:2212,min:0,max:3000,u:"m",e:"Massif de l’Arabika, dans le Caucase. Il faut une semaine sous terre pour toucher le fond et remonter. Une crue soudaine y a piégé une équipe de spéléologues en 2018."},
{t:'geo',q:"Quelle hauteur atteint le plafond de Son Doong, la plus grande galerie souterraine du monde ?",n:200,min:0,max:400,u:"m",e:"Vietnam. Un gratte-ciel de quarante étages y tiendrait debout, et une jungle pousse sous les effondrements du plafond. Un villageois l’avait trouvée en 1991, puis en avait perdu l’entrée."},
{t:'geo',q:"Quelle profondeur fait le trou bleu de Sansha Yongle, le plus profond du monde ?",n:300.89,min:0,max:1500,u:"m",e:"Mer de Chine méridionale. Un puits vertical percé dans le récif, sans oxygène au-delà de cent mètres : rien n’y vit en profondeur. Il a été cartographié par robot en 2016."},
{t:'geo',q:"Quelle profondeur fait le Grand Trou Bleu du Belize ?",n:124,min:0,max:200,u:"m",e:"Un cercle presque parfait de 318 m de diamètre. C’était une grotte sèche pendant la dernière glaciation : ses stalactites, formées à l’air libre, sont aujourd’hui noyées sous la mer."},
{t:'geo',q:"À quelle profondeur s’est produit le séisme le plus profond jamais détecté ?",n:751,min:0,max:800,u:"km",e:"Sous les îles Bonin, au Japon, en 2015. À cette profondeur la roche devrait être trop chaude et molle pour casser net : les géophysiciens n’ont toujours pas d’explication définitive."},
{t:'geo',q:"De combien l’île japonaise de Honshu s’est-elle déplacée lors du séisme de 2011 ?",n:2.4,min:0,max:3,u:"m",e:"L’île entière a glissé vers l’est. Le séisme a aussi décalé l’axe de rotation de la Terre d’une quinzaine de centimètres et raccourci la journée de 1,8 microseconde."},
{t:'geo',q:"À quelle distance a-t-on entendu l’explosion du Krakatoa en 1883 ?",n:4800,min:0,max:6000,u:"km",e:"Entendue jusqu’à l’île Rodrigues, dans l’océan Indien, où l’on crut à une canonnade. Le son le plus fort de l’histoire documentée : l’onde de pression a fait trois fois le tour du globe."},
{t:'geo',q:"Quel diamètre fait le cratère de Chicxulub, laissé par l’astéroïde qui a exterminé les dinosaures ?",n:180,min:0,max:200,u:"km",e:"Enfoui sous le Yucatán et le golfe du Mexique, totalement invisible depuis le sol. Ce sont des géologues pétroliers qui l’ont repéré, le prenant d’abord pour une structure volcanique."},
{t:'geo',q:"Quel diamètre avait le cratère de Vredefort, plus grande cicatrice d’impact connue sur Terre ?",n:300,min:0,max:400,u:"km",e:"Afrique du Sud, il y a environ deux milliards d’années. L’érosion n’en laisse aujourd’hui qu’un modeste arc de collines, indice d’une catastrophe d’une ampleur inimaginable."},
{t:'geo',q:"Quel diamètre fait le Meteor Crater d’Arizona ?",n:1200,min:0,max:5000,u:"m",e:"Creusé par un caillou de fer de seulement cinquante mètres de large lancé à 45 000 km/h. Les astronautes d’Apollo s’y sont entraînés à reconnaître des terrains lunaires."},
{t:'geo',q:"Quelle surface de forêt l’explosion de la Toungouska a-t-elle couchée en Sibérie ?",n:2150,min:0,max:8000,u:"km²",e:"Quatre-vingts millions d’arbres abattus par une onde de choc, sans le moindre cratère : l’objet a explosé en altitude. Vingt fois la superficie de Paris, rasée en quelques secondes."},
{t:'geo',q:"À quelle profondeur descendent les galeries de Mponeng, la mine la plus profonde du monde ?",n:4,min:0,max:6,u:"km",e:"Afrique du Sud. La roche y atteint 60 °C : il faut souffler de la glace fondue dans les galeries pour rendre l’air respirable. La descente en cage prend plus d’une heure."},
{t:'geo',q:"Quel diamètre fait le trou de la mine de diamants de Mir, en Sibérie ?",n:1200,min:0,max:2000,u:"m",e:"Profond de 525 mètres, il engendre des courants d’air si violents que le survol en hélicoptère est interdit : des appareils ont été aspirés vers le fond."},
{t:'geo',q:"Quelle profondeur atteint le Big Hole de Kimberley, creusé à la pioche et à la pelle ?",n:215,min:0,max:500,u:"m",e:"Afrique du Sud, 1871-1914. Cinquante mille chercheurs de diamants ont sorti vingt-deux millions de tonnes de terre à la main pour en extraire environ trois tonnes de pierres."},
{t:'geo',q:"Depuis combien de temps brûle la veine de charbon de Burning Mountain, en Australie ?",n:6000,min:0,max:15000,u:"années",e:"Le plus vieil incendie connu au monde, allumé bien avant les pyramides. Il progresse d’environ un mètre par an sous la colline. Les colons crurent d’abord découvrir un volcan."},
{t:'geo',q:"Combien de temps le feu souterrain de Centralia, en Pennsylvanie, pourrait-il encore brûler ?",n:250,min:0,max:800,u:"années",e:"Allumé en 1962 dans une décharge, il a gagné la veine de charbon sous la ville. Habitants évacués, code postal supprimé, et la route fendue fume toujours."},
{t:'geo',q:"Quel diamètre fait le cratère de Darvaza, la porte de l’enfer turkmène en flammes depuis des décennies ?",n:69,min:0,max:150,u:"m",e:"Un forage soviétique s’est effondré ; on a mis le feu au gaz en pensant qu’il s’éteindrait sous quelques semaines. Il brûle encore, un demi-siècle plus tard."},
{t:'geo',q:"Quelle est la longueur du tunnel de base du Saint-Gothard, le plus long tunnel du monde ?",n:57.1,min:0,max:60,u:"km",e:"Dix-sept ans de travaux sous 2 300 m de roche alpine. Il a fallu évacuer vingt-huit millions de tonnes de matériaux, soit cinq fois le volume de la pyramide de Khéops."},
{t:'geo',q:"Quelle longueur du tunnel sous la Manche se trouve réellement sous la mer ?",n:37.9,min:0,max:60,u:"km",e:"Sur 50,45 km au total. C’est la plus longue section sous-marine du monde, jusqu’à 75 m sous le fond marin, creusée dans une couche de craie choisie pour son étanchéité."},
{t:'geo',q:"Quelle est la longueur de la ligne du Transsibérien, de Moscou à Vladivostok ?",n:9289,min:0,max:20000,u:"km",e:"Sept jours de train et huit fuseaux horaires traversés. Pendant des décennies, un seul horaire était affiché dans toutes les gares : celui de Moscou, quelle que soit l’heure locale."},
{t:'geo',q:"Quelle est la longueur de la plus longue ligne droite ferroviaire du monde, dans la plaine du Nullarbor ?",n:478,min:0,max:2500,u:"km",e:"Australie. Plus de quatre heures sans le moindre virage, dans un désert calcaire si plat et si vide que son nom signifie approximativement « aucun arbre » en latin."},
{t:'geo',q:"À quelle profondeur se trouve Arsenalna, la station de métro la plus profonde du monde ?",n:105.5,min:0,max:800,u:"m",e:"À Kiev, sous une falaise du Dniepr. Il faut cinq bonnes minutes d’escalator pour remonter à l’air libre, en deux volées séparées par un hall intermédiaire."},
{t:'geo',q:"À quelle altitude se trouve la gare ferroviaire la plus haute du monde, à Tanggula au Tibet ?",n:5068,min:0,max:6000,u:"m",e:"Les wagons du train sont pressurisés comme des avions et un masque à oxygène équipe chaque siège. La voie repose sur du permafrost maintenu gelé artificiellement."},
{t:'geo',q:"Quelle est la longueur du plus long pont du monde, le viaduc de Danyang-Kunshan ?",n:164.8,min:0,max:600,u:"km",e:"Chine. Un viaduc ferroviaire qui franchit rizières, lacs et villes sans jamais toucher le sol sur 165 km. Construit en quatre ans par près de dix mille ouvriers."},
{t:'geo',q:"Quelle hauteur atteint le plus haut pylône du viaduc de Millau ?",n:343,min:0,max:1000,u:"m",e:"Plus haut que la tour Eiffel. Le tablier a été poussé par vérins depuis les deux rives, avançant de soixante centimètres toutes les quatre minutes, pour se rejoindre au millimètre près."},
{t:'geo',q:"Quelle est la longueur de la piste de Saba, la plus courte piste commerciale du monde ?",n:400,min:0,max:500,u:"m",e:"Antilles néerlandaises. Une bande d’asphalte coincée entre une falaise et deux précipices, avec la mer au bout. Seule une poignée de pilotes au monde est habilitée à s’y poser."},
{t:'geo',q:"Combien de temps dure le vol de ligne régulier le plus court du monde, entre Westray et Papa Westray ?",n:90,min:0,max:200,u:"secondes",e:"Îles Orcades, en Écosse : deux kilomètres et demi de vol. Le record établi est de 53 secondes vent arrière. Les consignes de sécurité durent plus longtemps que le trajet."},
{t:'geo',q:"Quelle est la longueur de la barrière anti-dingos qui traverse l’Australie ?",n:5614,min:0,max:20000,u:"km",e:"La plus longue clôture du monde, entretenue depuis les années 1880 pour protéger les moutons. Vue du ciel, la végétation diffère nettement de part et d’autre du grillage."},
{t:'geo',q:"Combien de marches compte l’escalier du Niesen, le plus long escalier du monde ?",n:11674,min:0,max:15000,u:"marches",e:"Suisse. Il longe un funiculaire dont il assure la maintenance et n’ouvre au public qu’un seul jour par an, pour une course. Les meilleurs le grimpent en moins d’une heure."},
{t:'geo',q:"Quelle pente atteint Baldwin Street, la rue la plus raide du monde ?",n:34.8,min:0,max:100,u:"%",e:"À Dunedin, en Nouvelle-Zélande. Un urbaniste londonien avait dessiné le plan de la ville sans jamais y mettre les pieds, ignorant totalement le relief. On y a longtemps fait rouler des bonbons."},
{t:'geo',q:"Quelle est la longueur du Grand Canal de Chine, plus long canal artificiel du monde ?",n:1794,min:0,max:4000,u:"km",e:"Creusé à la main à partir du Vᵉ siècle avant notre ère, il relie Pékin à Hangzhou. Deux mille cinq cents ans plus tard, des péniches y circulent encore."},
{t:'geo',q:"De combien de mètres les écluses du canal de Panama soulèvent-elles les navires ?",n:26,min:0,max:30,u:"m",e:"Les bateaux ne traversent pas l’isthme : ils passent par-dessus, via le lac Gatún. Chaque passage déverse environ deux cents millions de litres d’eau douce dans la mer."},
{t:'geo',q:"Quel écart d’heure maximal sépare deux endroits habités du globe au même instant ?",n:26,min:0,max:60,u:"heures",e:"Des Kiribati, à UTC+14, à l’île Baker, à UTC−12. Il peut être dix heures vendredi ici et huit heures jeudi là-bas : trois jours calendaires coexistent parfois sur Terre."},
{t:'geo',q:"Combien de jours le soleil reste-t-il sans se coucher à Longyearbyen, au Svalbard ?",n:124,min:0,max:150,u:"jours",e:"Du 20 avril au 22 août. En hiver, l’inverse : plus de cent jours sans le moindre lever de soleil. Les habitants dorment derrière des rideaux occultants en plein juillet."},
{t:'geo',q:"Combien d’îles compte la Suède ?",n:267570,min:0,max:400000,u:"îles",e:"Recensement officiel suédois : la plupart ne sont que des rochers émergés. Moins d’un millier sont habitées, et le seul archipel de Stockholm en compte environ trente mille."},
{t:'geo',q:"Combien de lacs compte la Finlande ?",n:187888,min:0,max:1200000,u:"lacs",e:"Le pays surnommé « aux mille lacs » en compte cent quatre-vingt-huit fois plus. On y dénombre aussi près de 180 000 îles : eau et terre y sont presque à égalité."},
{t:'geo',q:"Combien d’îles compte l’archipel des Philippines selon le recomptage de 2016 ?",n:7641,min:0,max:10000,u:"îles",e:"Le chiffre officiel était de 7 107 depuis les années 1940. Une cartographie moderne en a révélé cinq cent trente-quatre de plus, jusque-là simplement absentes des cartes."},
{t:'geo',q:"Quelle est la longueur du littoral du Canada, le plus long du monde ?",n:202080,min:0,max:800000,u:"km",e:"Cinq fois le tour de la Terre, îles arctiques comprises. Cela représente environ la moitié de tout le littoral de la planète, pour un seul pays."},
{t:'geo',q:"À quelle distance de l’océan le plus proche se trouve le point continental le plus enclavé du monde ?",n:2510,min:0,max:8000,u:"km",e:"Le pôle d’inaccessibilité eurasien, au Xinjiang, près de la frontière kazakhe. C’est l’endroit de la surface terrestre d’où la mer est le plus loin possible, dans toutes les directions."},
{t:'geo',q:"Combien de fois l’Afrique est-elle plus vaste que le Groenland ?",n:14,min:0,max:15,u:"fois",e:"Sur les cartes en projection de Mercator, les deux paraissent de taille comparable. En réalité l’Afrique fait trente millions de km², le Groenland à peine plus de deux millions."},
{t:'geo',q:"Quelle superficie fait le salar d’Uyuni, plus grand désert de sel du monde ?",n:10582,min:0,max:12000,u:"km²",e:"Bolivie. Si plat que son altitude varie de moins d’un mètre sur toute son étendue : les satellites s’en servent pour calibrer leurs altimètres, l’océan étant moins régulier."},
{t:'geo',q:"Quelle est la salinité de l’étang Don Juan, l’eau libre la plus salée du monde ?",n:44,min:0,max:100,u:"%",e:"En Antarctique, il refuse de geler même à −50 °C. Environ dix fois plus salé que l’océan, plus encore que la mer Morte : quasiment rien n’y survit."},
{t:'geo',q:"Depuis combien de temps le lac Vostok est-il coupé du monde sous la glace antarctique ?",n:15000000,min:0,max:40000000,u:"années",e:"Un lac de la taille de la Corse, sous quatre kilomètres de glace, isolé depuis des millions d’années. Les forages sont conduits avec des précautions dignes d’une mission spatiale."},

/* ---------- Hier ---------- */
{t:'histo',q:"Combien de temps a duré la guerre la plus courte de l'histoire ?",n:38,min:0,max:50,u:"minutes",e:"38 minutes, à Zanzibar en 1896. Le temps d'un bombardement : le café des officiers n'avait pas refroidi."},
{t:'histo',q:"Combien d'années a duré la guerre de Cent Ans ?",n:116,min:0,max:150,u:"ans",e:"116 ans, entrecoupés de longues trêves. Le nom a été inventé bien plus tard par des historiens qui cherchaient à faire simple."},
{t:'histo',q:"Combien de personnes a tuées l'inondation de mélasse de Boston, en 1919 ?",n:21,min:0,max:30,u:"morts",e:"21 morts. Un réservoir a lâché et une vague de mélasse de huit mètres a dévalé les rues à 50 km/h. L'odeur de sucre a hanté le quartier pendant des décennies."},
{t:'histo',q:"Combien pesait l'armure complète d'un chevalier en combat ?",n:25,min:0,max:50,u:"kg",e:"Entre 20 et 25 kg, répartis sur tout le corps. Assez léger pour courir, monter à cheval et se relever seul : les films exagèrent largement."},
{t:'histo',q:"Combien de jours durait une momification égyptienne ?",n:70,min:0,max:150,u:"jours",e:"70 jours, une durée rituelle fixe, dont quarante de séchage au natron. Pas un de plus, pas un de moins."},
{t:'histo',q:"Quelle était la hauteur d'origine de la pyramide de Khéops ?",n:146,min:0,max:600,u:"m",e:"146 m. Elle est restée la plus haute construction humaine pendant près de 4 000 ans, jusqu'aux cathédrales gothiques."},
{t:'histo',q:"Quelle hauteur atteint le mont Testaccio, à Rome, fait de poteries brisées ?",n:35,min:0,max:150,u:"m",e:"35 m de haut, uniquement des amphores cassées. Les Romains empilaient méthodiquement leurs pots à huile usagés : c'est la plus vieille décharge organisée du monde."},
{t:'histo',q:"Combien d’années séparent Cléopâtre de la construction de la pyramide de Khéops ?",n:2500,min:0,max:5000,u:"ans",e:"Environ 2 500 ans. Cléopâtre naît vers 69 av. J.-C., Khéops date de 2560 av. J.-C. Elle vivait donc plus près de l’invention du téléphone portable que du chantier des pyramides."},
{t:'histo',q:"Combien d’années a duré la guerre entre les îles Sorlingues et les Pays-Bas ?",n:335,min:0,max:400,u:"ans",e:"335 ans, de 1651 à 1986, sans un seul coup de feu ni la moindre victime. On avait simplement oublié de signer la paix. Un ambassadeur néerlandais est venu régler l’oubli."},
{t:'histo',q:"Combien de jours a duré le siège de Leningrad ?",n:872,min:0,max:4000,u:"jours",e:"872 jours, de septembre 1941 à janvier 1944. Près de deux ans et demi d’encerclement, ravitaillés par une route tracée sur un lac gelé. Le plus long siège de l’histoire moderne."},
{t:'histo',q:"Combien de temps a duré le plus long des quatre vols des frères Wright, le 17 décembre 1903 ?",n:59,min:0,max:300,u:"secondes",e:"59 secondes et 260 mètres. Les trois essais précédents du même jour n’avaient tenu qu’une douzaine de secondes. L’aviation est née en moins d’une minute, puis une rafale a détruit l’appareil."},
{t:'histo',q:"Combien pèse le masque funéraire en or de Toutânkhamon ?",n:10.23,min:0,max:12,u:"kg",e:"10,23 kg d’or massif posés sur la tête d’une momie. Sur une balance de cuisine, cela fait le poids d’un enfant d’un an, entièrement en métal précieux."},
{t:'histo',q:"Combien de rivets tiennent la tour Eiffel ?",n:2500000,min:0,max:5000000,u:"rivets",e:"Deux millions et demi, posés par équipes de quatre hommes. Les pièces étaient percées en atelier au millimètre : sur le chantier, presque rien n’a dû être ajusté."},
{t:'histo',q:"Combien de marches faut-il monter pour atteindre le sommet de la tour Eiffel ?",n:1665,min:0,max:2500,u:"marches",e:"1 665 marches jusqu’au sommet. Le public ne peut grimper qu’au deuxième étage, soit 674 marches. Le reste appartient au personnel et à l’ascenseur."},
{t:'histo',q:"Combien de jours a duré la construction de la tour Eiffel ?",n:793,min:0,max:4000,u:"jours",e:"793 jours : deux ans, deux mois et cinq jours. Trois cents ouvriers, et un seul décès sur le chantier, survenu en dehors des heures de travail."},
{t:'histo',q:"Combien de temps la tour Eiffel devait-elle rester debout avant sa démolition prévue ?",n:20,min:0,max:25,u:"ans",e:"Vingt ans : le permis prévoyait sa destruction en 1909. Elle doit sa survie à son sommet, devenu antenne de radiotélégraphie militaire. Une ferraille utile, donc conservée."},
{t:'histo',q:"Combien de tonnes de peinture faut-il pour repeindre la tour Eiffel ?",n:60,min:0,max:400,u:"tonnes",e:"Soixante tonnes, appliquées entièrement au pinceau, tous les sept ans environ. La dame a changé plusieurs fois de teinte depuis 1889, du rouge-brun au « brun tour Eiffel » actuel."},
{t:'histo',q:"Combien de jours Jules César est-il resté prisonnier des pirates ?",n:38,min:0,max:80,u:"jours",e:"Trente-huit jours. Il jugeait leur rançon insultante et exigea qu’ils la triplent, tout en leur promettant en riant de les crucifier une fois libéré. Il a tenu parole."},
{t:'histo',q:"Combien pesait le diamant Cullinan avant d’être taillé ?",n:3106,min:0,max:8000,u:"carats",e:"3 106 carats, soit 621 grammes : le plus gros diamant brut jamais trouvé. Le contremaître qui l’a repéré en 1905 a d’abord cru à un morceau de verre."},
{t:'histo',q:"Combien de jours la Joconde est-elle restée volée ?",n:842,min:0,max:2500,u:"jours",e:"842 jours. Un vitrier italien l’a emportée sous sa blouse en 1911. Le tableau, jusque-là discret, est devenu mondialement célèbre grâce au vol. Picasso fut brièvement soupçonné."},
{t:'histo',q:"Combien de jours a duré le pontificat le plus court de l’histoire ?",n:13,min:0,max:20,u:"jours",e:"Treize jours pour Urbain VII, en 1590, emporté par la malaria avant même son couronnement. Il eut tout de même le temps de signer la première interdiction de fumer connue."},
{t:'histo',q:"Combien de jours a duré le plus long conclave de l’histoire ?",n:1006,min:0,max:2000,u:"jours",e:"Environ 1 006 jours à Viterbe, de 1268 à 1271. Excédés, les habitants ont enfermé les cardinaux, réduit leurs repas au pain et à l’eau, puis retiré le toit."},
{t:'histo',q:"Combien de minutes le Titanic a-t-il mis à couler après avoir heurté l’iceberg ?",n:160,min:0,max:800,u:"minutes",e:"Deux heures quarante. Choc à 23 h 40, disparition à 2 h 20. Le navire était conçu pour flotter avec quatre compartiments inondés. Il y en a eu six."},
{t:'histo',q:"Combien de canots de sauvetage le Titanic embarquait-il ?",n:20,min:0,max:80,u:"canots",e:"Vingt canots pour plus de 2 200 personnes à bord, soit de la place pour la moitié. La réglementation, calculée sur le tonnage et non sur les passagers, n’en imposait que seize."},
{t:'histo',q:"Combien d’années se sont écoulées avant que l’épave du Titanic soit retrouvée ?",n:73,min:0,max:120,u:"ans",e:"73 ans. Robert Ballard l’a localisée en 1985 pendant une mission secrète consacrée à deux sous-marins nucléaires américains coulés. Le Titanic servait officiellement de prétexte."},
{t:'histo',q:"Combien a coûté la construction du Titanic ?",n:7500000,min:0,max:20000000,u:"dollars",e:"7,5 millions de dollars en 1912. Le film de James Cameron en a coûté 200 millions : reconstituer le naufrage a coûté bien plus cher que construire le navire."},
{t:'histo',q:"En combien de secondes le dirigeable Hindenburg a-t-il été dévoré par les flammes ?",n:34,min:0,max:60,u:"secondes",e:"Trente-quatre secondes. Deux cent quarante-cinq mètres de dirigeable réduits à une carcasse tordue. Sur 97 personnes à bord, 62 ont pourtant survécu, beaucoup en sautant des fenêtres."},
{t:'histo',q:"Quelle vitesse maximale la loi imposait-elle aux premières automobiles britanniques hors agglomération ?",n:6.4,min:0,max:8,u:"km/h",e:"6,4 km/h, soit 4 miles à l’heure, et un homme devait marcher devant avec un drapeau rouge. Le Locomotive Act a bridé l’automobile anglaise pendant trente ans."},
{t:'histo',q:"Combien d’heures a duré la « guerre du Football » entre le Salvador et le Honduras ?",n:100,min:0,max:120,u:"heures",e:"Cent heures, en 1969. Des tensions migratoires anciennes ont explosé après des matchs de qualification pour la Coupe du monde. Le football n’a pas causé la guerre, il a allumé la mèche."},
{t:'histo',q:"Combien de balles l’armée australienne a-t-elle tirées pendant la « guerre des émeus » ?",n:9860,min:0,max:15000,u:"balles",e:"9 860 cartouches de mitrailleuse pour environ 986 émeus abattus : dix balles par oiseau. Les émeus se dispersaient en petits groupes. L’armée s’est retirée, les oiseaux ont gagné."},
{t:'histo',q:"Combien de jours William Henry Harrison a-t-il passés à la présidence des États-Unis ?",n:31,min:0,max:150,u:"jours",e:"Trente et un jours, en 1841. Il avait prononcé sous la pluie glacée, sans manteau ni chapeau, le plus long discours d’investiture jamais tenu. Il est mort un mois plus tard."},
{t:'histo',q:"Combien de mots comptait le discours d’investiture de William Henry Harrison ?",n:8445,min:0,max:12000,u:"mots",e:"8 445 mots, près de deux heures sous un froid mordant, tête nue. Record absolu, et sans doute le discours le plus coûteux jamais prononcé par un homme politique."},
{t:'histo',q:"Combien de mots comptait le discours de Gettysburg prononcé par Lincoln ?",n:272,min:0,max:300,u:"mots",e:"272 mots, environ deux minutes. L’orateur qui l’avait précédé avait parlé deux heures. Un journal jugea le lendemain le texte de Lincoln « plat et ridicule ». On l’apprend aujourd’hui par cœur."},
{t:'histo',q:"Depuis combien d’années Ötzi, l’homme des glaces, était-il congelé quand on l’a découvert ?",n:5300,min:0,max:8000,u:"ans",e:"Environ 5 300 ans. Des randonneurs l’ont pris pour un alpiniste récent en 1991. Une pointe de flèche fichée dans l’épaule en a fait la plus vieille scène de crime résolue."},
{t:'histo',q:"Combien d’années a duré le siège de Candie, en Crète ?",n:21,min:0,max:60,u:"ans",e:"Vingt et un ans, de 1648 à 1669, entre Vénitiens et Ottomans. Des enfants y sont nés, ont grandi et ont combattu sans avoir jamais connu leur ville autrement qu’assiégée."},
{t:'histo',q:"Combien d’années le soldat japonais Hiroo Onoda a-t-il continué la guerre dans la jungle ?",n:29,min:0,max:40,u:"ans",e:"Vingt-neuf ans aux Philippines. Il tenait les tracts annonçant la paix pour une ruse ennemie. Il ne s’est rendu qu’en 1974, lorsque son ancien commandant est venu lui en donner l’ordre."},
{t:'histo',q:"Combien de temps a duré le tout premier vol de ligne commercial, en 1914 ?",n:23,min:0,max:30,u:"minutes",e:"Vingt-trois minutes entre Saint-Pétersbourg et Tampa, en Floride, avec un unique passager assis à côté du pilote. Le billet du voyage inaugural fut adjugé 400 dollars aux enchères."},
{t:'histo',q:"Combien les États-Unis ont-ils payé la Russie pour l’Alaska ?",n:7200000,min:0,max:15000000,u:"dollars",e:"7,2 millions de dollars, en 1867. La presse ricanait de « la folie de Seward », qui achetait un désert glacé. Trente ans plus tard on y trouvait de l’or, puis du pétrole."},
{t:'histo',q:"Combien les États-Unis ont-ils payé la Louisiane à la France ?",n:15000000,min:0,max:20000000,u:"dollars",e:"15 millions de dollars, en 1803, pour 2,1 millions de km². La superficie du pays a doublé d’un coup. Napoléon avait surtout besoin d’argent frais pour ses guerres européennes."},
{t:'histo',q:"Combien de florins les Néerlandais ont-ils payés pour l’île de Manhattan ?",n:60,min:0,max:120,u:"florins",e:"Soixante florins de marchandises, en 1626, d’après une lettre d’époque. La conversion populaire en « 24 dollars » date du XIXe siècle et ne vaut pas grand-chose. Le marché reste imbattable."},
{t:'histo',q:"Combien d’heures a duré la traversée de l’Atlantique par Lindbergh ?",n:33.5,min:0,max:60,u:"heures",e:"33 heures et 30 minutes, seul, sans radio ni parachute, avec un périscope parce qu’un réservoir bouchait le pare-brise. Il n’avait pas fermé l’œil la nuit précédant le départ."},
{t:'histo',q:"Combien de sandwichs Lindbergh avait-il emportés pour traverser l’Atlantique ?",n:5,min:0,max:8,u:"sandwichs",e:"Cinq sandwichs et deux gourdes d’eau. « Si j’arrive à Paris, je n’aurai pas besoin de plus ; si je n’y arrive pas, je n’en aurai pas besoin non plus. »"},
{t:'histo',q:"Combien d’hommes sont revenus du premier tour du monde de Magellan ?",n:18,min:0,max:20,u:"hommes",e:"Dix-huit, sur près de 250 partis, à bord d’un seul des cinq navires. Magellan lui-même est mort aux Philippines. Trois ans de mer pour rapporter la preuve d’une circumnavigation."},
{t:'histo',q:"Combien de morts officiellement recensés a fait le grand incendie de Londres de 1666 ?",n:6,min:0,max:40,u:"morts",e:"Six décès vérifiés, pour treize mille maisons détruites et l’essentiel de la City rasée. Les pauvres, morts anonymes, n’ont sans doute pas été comptés, mais le bilan officiel reste six."},
{t:'histo',q:"Combien d’évadés de la « Grande Évasion » de 1944 ont réellement atteint la liberté ?",n:3,min:0,max:20,u:"hommes",e:"Trois, sur soixante-seize évadés du Stalag Luft III. Cinquante furent exécutés après leur capture. Le tunnel « Harry » faisait 102 mètres et avait englouti quatre mille planches de lit."},
{t:'histo',q:"Quelle longueur totale faisait le mur de Berlin ?",n:155,min:0,max:300,u:"km",e:"155 kilomètres, dont seulement 43 traversaient la ville : le reste encerclait Berlin-Ouest. Ce n’était pas un mur coupant une ville en deux, mais un anneau autour d’une enclave."},
{t:'histo',q:"Combien d’éléphants Hannibal a-t-il emmenés pour franchir les Alpes ?",n:37,min:0,max:50,u:"éléphants",e:"Trente-sept. Presque tous sont morts durant l’hiver qui a suivi la traversée. Un seul, semble-t-il, a survécu jusqu’à la fin de la campagne d’Italie, et Hannibal le montait."},
{t:'histo',q:"Combien de jours Hannibal a-t-il mis à franchir les Alpes ?",n:15,min:0,max:50,u:"jours",e:"Quinze jours, selon Polybe, avec des dizaines de milliers d’hommes, des chevaux et des éléphants. Il aurait laissé près de la moitié de son armée dans les cols enneigés."},
{t:'histo',q:"Combien de dents naturelles restait-il à George Washington lors de son investiture ?",n:1,min:0,max:1.5,u:"dent",e:"Une seule. Ses dentiers n’étaient pas en bois mais en ivoire d’hippopotame, en or et en dents humaines achetées. Ils lui déformaient la mâchoire, ce qui se voit sur ses portraits."},
{t:'histo',q:"Combien de personnes a tuées l’inondation de bière de Londres, en 1814 ?",n:8,min:0,max:10,u:"morts",e:"Huit, noyées par une vague de bière brune après l’éclatement d’une cuve géante dans une brasserie de Tottenham Court Road. La justice a conclu à un « acte de Dieu »."},
{t:'histo',q:"Quelle taille faisait réellement Napoléon Bonaparte ?",n:1.68,min:0,max:2.5,u:"mètres",e:"Environ 1,68 m, soit la moyenne française de son temps. La légende du petit homme vient des pouces français, plus longs que les anglais, et de la propagande britannique."},
{t:'histo',q:"À quel âge Toutânkhamon est-il monté sur le trône d’Égypte ?",n:9,min:0,max:40,u:"ans",e:"Neuf ans environ. Il est mort vers dix-neuf ans, après un règne bref et sans éclat. C’est précisément son insignifiance qui a sauvé sa tombe des pilleurs pendant trois millénaires."},
{t:'histo',q:"Combien d’objets contenait la tombe de Toutânkhamon ?",n:5398,min:0,max:20000,u:"objets",e:"5 398 pièces : chars démontés, lits, sandales, jeux de société et même des pots de miel. Une capsule temporelle de trois mille ans, entassée dans quatre petites pièces."},
{t:'histo',q:"Combien d’années Howard Carter a-t-il mis à vider la tombe de Toutânkhamon ?",n:10,min:0,max:25,u:"ans",e:"Dix ans, objet par objet, chacun photographié, numéroté et consolidé. On imagine l’archéologue triomphant : ce fut surtout une décennie d’inventaire méticuleux dans une chaleur écrasante."},
{t:'histo',q:"Combien pèse le cercueil en or massif de Toutânkhamon ?",n:110.4,min:0,max:120,u:"kg",e:"110,4 kg d’or pur : c’est le plus intérieur des trois sarcophages emboîtés. À lui seul, au simple cours du métal, il vaudrait aujourd’hui plusieurs millions d’euros."},
{t:'histo',q:"Combien de jours ont été supprimés du calendrier en octobre 1582 ?",n:10,min:0,max:15,u:"jours",e:"Dix jours : on est passé du jeudi 4 au vendredi 15 octobre. Le calendrier julien avait dérivé. Des locataires ont protesté, convaincus qu’on leur avait volé un loyer."},
{t:'histo',q:"Combien de jours a duré la Commune de Paris ?",n:72,min:0,max:300,u:"jours",e:"Soixante-douze jours, du 18 mars au 28 mai 1871. Le temps de proclamer la séparation de l’Église et de l’État, l’école gratuite, et d’abattre la colonne Vendôme."},
{t:'histo',q:"Combien d’ouvriers sont morts sur les chantiers du canal de Panama ?",n:25000,min:0,max:80000,u:"morts",e:"Environ 25 000, dont plus de vingt mille sur le chantier français abandonné. Le vrai tueur n’était pas la roche mais le moustique : fièvre jaune et paludisme ont fait le gros du travail."},
{t:'histo',q:"Combien de jours a duré la traversée du Mayflower ?",n:66,min:0,max:200,u:"jours",e:"Soixante-six jours pour 102 passagers entassés sur un navire marchand de vingt-sept mètres. Un bébé est né en mer, on l’a nommé Oceanus. La moitié n’a pas passé le premier hiver."},
{t:'histo',q:"Combien de mois le Pony Express a-t-il réellement fonctionné ?",n:18,min:0,max:25,u:"mois",e:"Dix-huit mois, de 1860 à 1861. Le télégraphe transcontinental l’a tué net deux jours après son achèvement. Sa légende aura duré cent fois plus longtemps que le service lui-même."},
{t:'histo',q:"Combien d’années a duré la construction de la cathédrale de Cologne ?",n:632,min:0,max:1500,u:"ans",e:"632 ans. Commencée en 1248, abandonnée trois siècles avec une grue laissée en haut d’une tour, puis achevée en 1880 d’après les plans médiévaux retrouvés par hasard."},
{t:'histo',q:"Combien d’animaux ont été tués pendant les cent jours de jeux inaugurant le Colisée ?",n:9000,min:0,max:15000,u:"animaux",e:"Neuf mille bêtes, selon Dion Cassius : lions, ours, éléphants, autruches. Les arènes romaines ont dévoré tant de faune que certaines espèces d’Afrique du Nord ont fini par disparaître."},
{t:'histo',q:"Combien d’années le Colosse de Rhodes est-il resté debout ?",n:54,min:0,max:60,u:"ans",e:"Cinquante-quatre ans seulement. Érigé vers 280 avant notre ère, abattu par un séisme en 226. Ses débris sont restés couchés au sol huit siècles et attiraient déjà les curieux."},
{t:'histo',q:"Combien de jours a duré le règne de Jean Ier, roi de France ?",n:5,min:0,max:20,u:"jours",e:"Cinq jours. Né posthume en 1316, roi dès sa première seconde, mort presque aussitôt. Le plus court règne de l’histoire de France, et le seul roi à n’avoir jamais marché."},
{t:'histo',q:"Combien de roubles par an coûtait la taxe sur la barbe instaurée par Pierre le Grand ?",n:100,min:0,max:300,u:"roubles",e:"Cent roubles par an pour les nobles, une petite fortune. Le payeur recevait un jeton de cuivre à garder sur lui, gravé d’une devise : « la barbe est un fardeau superflu »."},
{t:'histo',q:"Quelle taille faisait le tsar Pierre le Grand ?",n:2.03,min:0,max:8,u:"mètres",e:"2,03 m : une taille de géant au XVIIIe siècle, où l’on dépassait rarement 1,65 m. Il devait se courber sous les portes de ses propres palais, qu’il avait pourtant fait bâtir."},
{t:'histo',q:"Quelle est l’épaisseur de la peau de cuivre de la statue de la Liberté ?",n:2.4,min:0,max:3,u:"mm",e:"2,4 mm, l’épaisseur de deux pièces de monnaie. Trente et une tonnes de cuivre martelé tiennent debout grâce à une charpente de fer conçue par Gustave Eiffel."},
{t:'histo',q:"Pendant combien d’années la guillotine a-t-elle été utilisée en France ?",n:185,min:0,max:300,u:"ans",e:"185 ans, de 1792 à 1977. La dernière exécution a eu lieu à Marseille l’année de la sortie du premier Star Wars au cinéma. L’abolition n’est venue qu’en 1981."},
{t:'histo',q:"Combien d’heures a duré le plus long discours d’obstruction du Sénat américain ?",n:24.3,min:0,max:80,u:"heures",e:"24 heures et 18 minutes, en 1957, sans quitter l’estrade. Strom Thurmond avait pris un long bain de vapeur avant de commencer, pour se déshydrater et éviter toute pause."},
{t:'histo',q:"Combien de jours a duré la construction de l’Empire State Building ?",n:410,min:0,max:600,u:"jours",e:"410 jours, avec des semaines à un étage tous les jours et demi. Le chantier est allé si vite qu’il s’est terminé en avance sur le calendrier et sous le budget prévu."},
{t:'histo',q:"Combien d’ouvriers sont morts pendant la construction de l’Empire State Building ?",n:5,min:0,max:8,u:"morts",e:"Cinq, selon le bilan officiel, pour 102 étages en un peu plus d’un an. Le métier citait alors volontiers une règle sinistre : un mort par étage. Le chiffre a stupéfié."},
{t:'histo',q:"Combien d’ouvriers sont morts pendant la construction du Golden Gate ?",n:11,min:0,max:12,u:"morts",e:"Onze, dont dix le même jour, quand un échafaudage a crevé le filet de sécurité tendu sous le pont. Ce filet, une première mondiale, avait déjà rattrapé dix-neuf hommes."},
{t:'histo',q:"Combien d’années a duré la construction de la tour de Pise ?",n:199,min:0,max:800,u:"ans",e:"199 ans, de 1173 à 1372, avec deux très longues interruptions dues aux guerres. Ces pauses ont laissé le sol se tasser : sans elles, la tour se serait probablement effondrée."},
{t:'histo',q:"Combien d’années le Japon est-il resté fermé au monde sous le sakoku ?",n:214,min:0,max:500,u:"ans",e:"214 ans, de 1639 à 1853. Quitter le pays était puni de mort. Seul un comptoir néerlandais installé sur l’îlot artificiel de Dejima, à Nagasaki, gardait une fenêtre entrouverte."},
{t:'histo',q:"Quelle est la longueur totale de la Grande Muraille de Chine, tous tronçons confondus ?",n:21196,min:0,max:50000,u:"km",e:"21 196 km selon le relevé officiel chinois de 2012, murs, tranchées et barrières naturelles compris. Soit plus de la moitié du tour de la Terre, bâti sur près de deux mille ans."},
{t:'histo',q:"Combien de soldats compte l’armée de terre cuite de Xi’an ?",n:8000,min:0,max:50000,u:"soldats",e:"Environ huit mille, accompagnés de chars et de centaines de chevaux, chacun avec un visage différent. Des paysans creusant un puits les ont réveillés en 1974, sous trois mètres de terre."},
{t:'histo',q:"Combien d’ouvriers ont travaillé au mausolée de l’empereur Qin Shi Huang ?",n:700000,min:0,max:3000000,u:"ouvriers",e:"700 000, selon l’historien Sima Qian. Le tombeau contiendrait des rivières de mercure : les analyses du sol ont effectivement révélé des concentrations anormales de ce métal."},
{t:'histo',q:"Combien de navires comptait l’Invincible Armada espagnole ?",n:130,min:0,max:1000,u:"navires",e:"Cent trente. La moitié seulement est rentrée en Espagne, et surtout à cause des tempêtes au large de l’Écosse et de l’Irlande, bien plus que des canons anglais."},
{t:'histo',q:"De quelle hauteur sont tombés les hommes jetés par la fenêtre lors de la défenestration de Prague de 1618 ?",n:21,min:0,max:50,u:"mètres",e:"Environ 21 mètres, et les trois hommes ont survécu. Les catholiques y ont vu un miracle, les protestants un tas de fumier providentiel. La guerre de Trente Ans a suivi."},
{t:'histo',q:"Combien de fenêtres compte le château de Versailles ?",n:2153,min:0,max:8000,u:"fenêtres",e:"2 153 fenêtres, pour environ 2 300 pièces et 67 escaliers. Il fallait une petite armée de domestiques rien que pour les ouvrir le matin et les fermer le soir."},
{t:'histo',q:"Combien de temps a duré la pose de la toute première photographie de l’histoire ?",n:8,min:0,max:25,u:"heures",e:"Environ huit heures, en 1826, sur une plaque d’étain enduite de bitume. Le soleil a tourné pendant l’exposition : sur l’image, les deux côtés de la cour sont éclairés simultanément."},
{t:'histo',q:"Combien de spectateurs ont assisté à la première séance publique payante du cinématographe Lumière ?",n:33,min:0,max:40,u:"spectateurs",e:"Trente-trois, le 28 décembre 1895, au Grand Café à Paris. Les frères Lumière estimaient leur invention sans avenir commercial. La séance a rapporté trente-trois francs."},
{t:'histo',q:"Combien de temps a mis le premier message télégraphique transatlantique à être transmis ?",n:16,min:0,max:30,u:"heures",e:"Seize heures pour les 98 mots adressés par la reine Victoria au président Buchanan, en 1858. Le câble a rendu l’âme trois semaines plus tard. Il fallut huit ans pour recommencer."},
{t:'histo',q:"Combien pèse l’obélisque de la Concorde, à Paris ?",n:220,min:0,max:1500,u:"tonnes",e:"Environ 220 tonnes de granit rose, offertes par l’Égypte en 1830. Il a fallu construire un navire sur mesure et cinq ans de manœuvres pour l’amener de Louxor jusqu’à la place."},
{t:'histo',q:"Quelle longueur fait la tapisserie de Bayeux ?",n:68.4,min:0,max:200,u:"mètres",e:"68,4 mètres de long pour cinquante centimètres de haut : une bande dessinée médiévale déroulée sur près de soixante-dix mètres. Ce n’est d’ailleurs pas une tapisserie mais une broderie de laine."},
{t:'histo',q:"Combien de barils de poudre Guy Fawkes avait-il entassés sous le Parlement anglais ?",n:36,min:0,max:80,u:"barils",e:"Trente-six barils, environ deux tonnes et demie, cachés dans une cave louée sous la Chambre des lords. De quoi souffler le bâtiment et une bonne partie du quartier."},
{t:'histo',q:"Combien d’années a régné le roi Sobhuza II du Swaziland ?",n:82,min:0,max:200,u:"ans",e:"82 ans, le plus long règne vérifié de l’histoire. Devenu roi à quatre mois, en 1899, il a vu naître l’aviation, la radio, la télévision et mourir l’empire colonial."},
{t:'histo',q:"Combien d’années a duré la République de Venise ?",n:1100,min:0,max:3000,u:"ans",e:"Environ 1 100 ans, de la fin du VIIe siècle à 1797, quand Napoléon y met fin sans combat. Le plus long régime républicain de l’histoire, dirigé par cent vingt doges successifs."},
{t:'histo',q:"Combien d’années a vécu Kongō Gumi, la plus ancienne entreprise du monde ?",n:1428,min:0,max:5000,u:"ans",e:"1 428 ans. Fondée en 578 au Japon pour bâtir des temples bouddhistes, elle a été absorbée en 2006. Quarante générations d’une même famille, arrêtées par une dette immobilière."},
{t:'histo',q:"Combien d’années après la fin des guerres puniques Rome et Carthage ont-elles signé la paix ?",n:2131,min:0,max:5000,u:"ans",e:"2 131 ans. En 1985, les maires de Rome et de Carthage ont paraphé un traité symbolique mettant officiellement fin à un conflit achevé en 146 avant notre ère."},
{t:'histo',q:"Combien de prisonniers y avait-il dans la Bastille le 14 juillet 1789 ?",n:7,min:0,max:25,u:"prisonniers",e:"Sept : quatre faussaires, deux aliénés et un noble libertin. La forteresse devait d’ailleurs être démolie pour raisons budgétaires. On a pris d’assaut un symbole presque vide."},
{t:'histo',q:"Combien d’années après sa condamnation le Vatican a-t-il officiellement réhabilité Galilée ?",n:359,min:0,max:600,u:"ans",e:"359 ans. Condamné en 1633, il n’a été reconnu injustement traité qu’en 1992, par Jean-Paul II. La commission chargée du dossier avait travaillé treize ans avant de conclure."},
{t:'histo',q:"Combien pèse la Tsar Kolokol, la plus grosse cloche jamais fondue ?",n:202,min:0,max:300,u:"tonnes",e:"202 tonnes, à Moscou, et elle n’a jamais sonné. Un incendie l’a fissurée alors qu’elle refroidissait encore dans sa fosse de fonte. L’éclat tombé pèse à lui seul onze tonnes."},
{t:'histo',q:"Combien de tonnes d’or Atahualpa a-t-il versées aux Espagnols pour sa rançon ?",n:6,min:0,max:60,u:"tonnes",e:"Environ six tonnes d’or, plus douze tonnes d’argent : une pièce entière remplie jusqu’au plafond. Pizarro a encaissé la rançon, puis a fait exécuter l’Inca malgré tout."},
{t:'histo',q:"Combien de momies de chats égyptiens ont été expédiées en Angleterre comme engrais, en 1890 ?",n:180000,min:0,max:250000,u:"chats",e:"Environ 180 000, dix-neuf tonnes de chats sacrés vendus au poids pour fertiliser les champs anglais. Un seul crâne a été sauvé du broyeur et confié à un musée londonien."},
{t:'histo',q:"Combien d’années Pompéi est-elle restée ensevelie avant sa redécouverte ?",n:1669,min:0,max:3000,u:"ans",e:"1 669 ans. Engloutie en 79, la ville n’a été identifiée qu’en 1748. Sous les cendres, on a retrouvé du pain resté dans les fours et des graffitis moqueurs sur les murs."},
{t:'histo',q:"Combien de sesterces par soldat Didius Julianus a-t-il payés pour acheter l’Empire romain aux enchères ?",n:25000,min:0,max:40000,u:"sesterces",e:"25 000 sesterces à chaque prétorien, en 193. La garde avait mis le trône aux enchères après avoir tué l’empereur précédent. L’acheteur a régné soixante-six jours avant d’être exécuté."},
{t:'histo',q:"Combien d’années a duré la construction du Parthénon ?",n:9,min:0,max:15,u:"ans",e:"Neuf ans pour le gros œuvre, de 447 à 438 avant notre ère, les sculptures demandant six années de plus. Une cathédrale gothique mettait dix fois plus de temps à sortir de terre."},
{t:'histo',q:"Combien de jurés ont jugé Socrate ?",n:501,min:0,max:1200,u:"jurés",e:"501 citoyens tirés au sort. Ils l’ont condamné à mort à une trentaine de voix près. Socrate avait proposé pour peine qu’on le nourrisse gratuitement à vie aux frais de la cité."},
{t:'histo',q:"Combien d’animaux composaient l’équipage du premier vol en montgolfière, en 1783 ?",n:3,min:0,max:12,u:"animaux",e:"Trois : un mouton, un canard et un coq, lâchés devant Louis XVI à Versailles. Le mouton testait l’air en altitude, le canard servait de témoin. Tous ont atterri vivants."},
{t:'histo',q:"Combien de minutes Louis Blériot a-t-il mis à traverser la Manche en avion ?",n:37,min:0,max:120,u:"minutes",e:"Trente-sept minutes, en 1909, sans boussole et à une centaine de mètres d’altitude. Il s’est posé en catastrophe près de Douvres, brisant l’hélice et le train d’atterrissage."},
{t:'histo',q:"Quelle taille faisait Charlemagne ?",n:1.84,min:0,max:4,u:"mètres",e:"Environ 1,84 m, d’après l’analyse de son tibia. Il dépassait ses contemporains d’une bonne tête, la moyenne de l’époque tournant autour de 1,69 m. Son biographe ne l’avait donc pas flatté."},
{t:'histo',q:"Combien de jours a duré la traversée de Christophe Colomb depuis les Canaries ?",n:36,min:0,max:100,u:"jours",e:"Trente-six jours de haute mer, avec un équipage au bord de la mutinerie. Colomb tenait deux journaux de bord : l’un exact, l’autre minorant la distance parcourue pour rassurer ses hommes."},
{t:'histo',q:"Combien de mots compte la Constitution des États-Unis ?",n:4543,min:0,max:10000,u:"mots",e:"4 543 mots, signatures comprises : la plus courte constitution nationale encore en vigueur. Celle de l’Inde en aligne plus de cent quarante mille. Elle tient sur quatre feuilles de parchemin."},
{t:'histo',q:"Combien de tonnes de roche ont été dynamitées pour sculpter le mont Rushmore ?",n:450000,min:0,max:800000,u:"tonnes",e:"Environ 450 000 tonnes de granit, l’essentiel du travail ayant été fait à l’explosif plutôt qu’au ciseau. Quatorze ans de chantier suspendu dans le vide, et pas un ouvrier tué."},
{t:'histo',q:"Combien de minutes a duré le règne de Louis XIX, roi de France ?",n:20,min:0,max:150,u:"minutes",e:"Une vingtaine de minutes, en 1830 : le temps séparant l’abdication de son père Charles X de la sienne. Sa femme l’aurait supplié, en vain, de ne pas signer le document."},
{t:'histo',q:"Combien de coureurs ont terminé le marathon olympique de 1904 ?",n:14,min:0,max:20,u:"coureurs",e:"Quatorze sur trente-deux partants, par forte chaleur et sur des routes poussiéreuses. Le premier arrivé avait fait une partie du trajet en voiture ; le vainqueur officiel carburait à la strychnine."},

/* ---------- Cerveau ---------- */
{t:'sci',q:"Combien de temps la lumière met-elle à s'échapper du cœur du Soleil ?",n:100000,min:0,max:120000,u:"ans",e:"Environ 100 000 ans à rebondir de particule en particule. Puis seulement 8 minutes pour parcourir les 150 millions de km jusqu'à nous."},
{t:'sci',q:"À quelle vitesse file l'influx nerveux le plus rapide du corps humain ?",n:430,min:0,max:800,u:"km/h",e:"Jusqu'à 430 km/h, plus vite qu'un TGV. C'est pour ça que la main se retire de la plaque brûlante avant même que la douleur soit perçue."},
{t:'sci',q:"Combien de fois le cœur humain bat-il au cours d'une vie ?",n:2500000000,min:0,max:20000000000,u:"battements",e:"Environ 2,5 milliards. Curiosité : la plupart des mammifères, de la souris à la baleine, tournent autour du même total — ils le dépensent juste plus ou moins vite."},
{t:'sci',q:"Quelle tension peut produire une anguille électrique ?",n:600,min:0,max:1500,u:"volts",e:"Jusqu'à 600 volts, cinq fois une prise de courant. Elle s'en sert aussi comme radar, en envoyant de petites décharges pour cartographier l'eau trouble."},
{t:'sci',q:"À quelle température le gallium, un métal, fond-il ?",n:30,min:0,max:50,u:"°C",e:"Environ 30 °C : une cuillère en gallium fond dans une tasse de thé. Les chimistes adorent la blague, moins les invités."},
{t:'sci',q:"Combien de temps s'écoule entre deux gouttes dans la célèbre expérience de la poix ?",n:9,min:0,max:25,u:"ans",e:"Environ 9 ans par goutte. Lancée en 1927, l'expérience tourne toujours — et le chercheur qui la surveillait est mort sans jamais avoir vu tomber une seule goutte en direct."},
{t:'sci',q:"Combien de fois la dose de radiation mortelle pour l'homme un tardigrade encaisse-t-il ?",n:1000,min:0,max:3000,u:"fois",e:"Environ 1 000 fois. Il survit aussi au vide spatial, à −272 °C et à des décennies de déshydratation. Il mesure moins d'un millimètre."},
{t:'sci',q:"Combien de neurones compte un cerveau humain ?",n:86000000000,min:0,max:250000000000,u:"neurones",e:"86 milliards, mesurés en 2009 en dissolvant le cerveau pour compter ses noyaux un par un. Le fameux chiffre de 100 milliards, répété pendant des décennies, ne reposait sur aucune mesure sérieuse."},
{t:'sci',q:"Combien de neurones se cachent dans le seul cervelet, ce petit chou-fleur sous le cerveau ?",n:69000000000,min:0,max:300000000000,u:"neurones",e:"69 milliards, soit 80 % de tous vos neurones entassés dans 10 % du volume cérébral. Le cervelet gère l’équilibre et le geste précis, sans jamais réclamer la gloire."},
{t:'sci',q:"Combien de neurones compte le cortex cérébral, siège supposé de l’intelligence ?",n:16000000000,min:0,max:30000000000,u:"neurones",e:"Seulement 16 milliards, moins d’un cinquième du total. C’est pourtant ce record parmi les mammifères, et non la taille du cerveau, qui distingue le mieux notre espèce."},
{t:'sci',q:"Combien de neurones compte le cerveau d’un éléphant d’Afrique ?",n:257000000000,min:0,max:800000000000,u:"neurones",e:"257 milliards, trois fois plus que nous. Mais 98 % sont dans son cervelet, occupé à piloter une trompe de 40 000 muscles. Son cortex, lui, n’en compte que 5,6 milliards."},
{t:'sci',q:"Combien de neurones tiennent dans le cerveau d’une abeille ?",n:960000,min:0,max:1500000,u:"neurones",e:"Moins d’un million, dans une tête grosse comme une graine de sésame. Avec ça, elle compte jusqu’à quatre, reconnaît des visages humains et décrit un lieu en dansant."},
{t:'sci',q:"Combien de neurones possède le ver C. elegans, seul animal dont le cerveau est cartographié à 100 % ?",n:302,min:0,max:800,u:"neurones",e:"302, exactement, chez chaque individu. Il a fallu douze ans de découpes au microscope pour tracer les 7 000 connexions. Ce ver reste le modèle roi des neurosciences."},
{t:'sci',q:"Combien de neurones compte une pieuvre ?",n:500000000,min:0,max:600000000,u:"neurones",e:"500 millions, dont deux tiers logés dans les bras et non dans la tête. Un bras sectionné continue d’attraper de la nourriture : il pense, littéralement, tout seul."},
{t:'sci',q:"Combien de neurones tapissent votre tube digestif, ce « deuxième cerveau » ?",n:500000000,min:0,max:600000000,u:"neurones",e:"500 millions, autant qu’une pieuvre entière. Ce réseau autonome fait avancer la digestion même si on coupe tout lien avec le cerveau, et fabrique 95 % de votre sérotonine."},
{t:'sci',q:"Quelle puissance électrique consomme un cerveau humain en fonctionnement ?",n:20,min:0,max:30,u:"watts",e:"20 watts, moins qu’une ampoule de frigo. Aucun superordinateur ne s’approche d’une telle efficacité : simuler grossièrement un cerveau demande aujourd’hui des mégawatts."},
{t:'sci',q:"Quel pourcentage de votre énergie quotidienne le cerveau engloutit-il ?",n:20,min:0,max:100,u:"%",e:"20 %, pour 2 % du poids du corps. Chez le nourrisson, la facture grimpe à près de 50 % : voilà pourquoi les bébés dorment autant et grandissent si lentement."},
{t:'sci',q:"Combien de grammes de glucose votre cerveau brûle-t-il chaque jour ?",n:120,min:0,max:150,u:"grammes",e:"Environ 120 grammes, l’équivalent de 25 morceaux de sucre. Il n’a presque aucune réserve : quelques minutes sans apport et la conscience vacille."},
{t:'sci',q:"Combien de millilitres de sang traversent le cerveau chaque minute ?",n:750,min:0,max:1500,u:"millilitres",e:"750 millilitres, soit 15 % du débit cardiaque total pour 2 % de la masse. Une bouteille de vin de sang par minute, jour et nuit, sans interruption possible."},
{t:'sci',q:"Combien pèse un cerveau humain adulte ?",n:1400,min:0,max:1500,u:"grammes",e:"Environ 1,4 kilo, la consistance d’un flan à peine pris. Hors du crâne et de son bain liquide, il s’affaisse sous son propre poids : c’est pourquoi on le durcit avant dissection."},
{t:'sci',q:"Combien pesait le cerveau d’Albert Einstein ?",n:1230,min:0,max:1500,u:"grammes",e:"1 230 grammes, soit moins que la moyenne. Le pathologiste Thomas Harvey l’avait subtilisé lors de l’autopsie et l’a gardé vingt ans dans un bocal de cidre, dans sa cave."},
{t:'sci',q:"Combien pèse le cerveau d’un cachalot, le plus gros du règne animal ?",n:7.8,min:0,max:10,u:"kg",e:"Près de 8 kilos, cinq fois le nôtre. Il lui sert notamment à émettre le son le plus puissant du monde animal, un clic capable d’assommer une proie."},
{t:'sci',q:"Quel était le volume du crâne d’un Néandertalien ?",n:1500,min:0,max:2000,u:"cm³",e:"1 500 cm³, nettement plus que nos 1 350 en moyenne. Avoir un plus gros cerveau ne l’a pas sauvé : c’est l’organisation interne, pas le volume, qui compte."},
{t:'sci',q:"Quel était le volume cérébral d’Homo floresiensis, le « hobbit » de l’île de Flores ?",n:400,min:0,max:500,u:"cm³",e:"Environ 400 cm³, la taille d’un cerveau de chimpanzé. Pourtant, ce cousin d’un mètre de haut taillait des outils et chassait. De quoi bousculer l’équation cerveau égale intelligence."},
{t:'sci',q:"Quelle est l’épaisseur du cortex cérébral, cette couche où naissent vos pensées ?",n:2.5,min:0,max:12,u:"mm",e:"2,5 millimètres, l’épaisseur d’une pièce de deux euros. Tout ce que vous savez, dites et ressentez tient dans cette fine écorce plissée pour tenir dans le crâne."},
{t:'sci',q:"Quelle surface couvrirait votre cortex cérébral s’il était entièrement déplié ?",n:2500,min:0,max:10000,u:"cm²",e:"Environ 2 500 cm², une belle serviette de table. Le crâne étant trop petit, l’évolution a tout froissé : les deux tiers de la surface sont cachés au fond des sillons."},
{t:'sci',q:"Quelle proportion d’eau contient le cerveau ?",n:75,min:0,max:100,u:"%",e:"Trois quarts d’eau. Perdre 2 % de cette eau suffit à faire chuter la concentration et la mémoire de travail : la fameuse baisse de régime de l’après-midi commence souvent là."},
{t:'sci',q:"Combien de connexions synaptiques relient les neurones d’un cerveau humain ?",n:100000000000000,min:0,max:150000000000000,u:"synapses",e:"De l’ordre de 100 000 milliards, soit mille par neurone en moyenne. C’est là, dans ces points de contact, que se logent vos souvenirs, et non dans les neurones eux-mêmes."},
{t:'sci',q:"Quelle est la largeur de la fente synaptique, l’espace que doit franchir un message entre deux neurones ?",n:20,min:0,max:25,u:"nanomètres",e:"20 nanomètres, cinq mille fois plus fin qu’un cheveu. Les molécules la traversent par simple diffusion, en quelques dizaines de microsecondes : impossible de faire plus court sans se toucher."},
{t:'sci',q:"Combien de fois par seconde un neurone peut-il décharger au maximum ?",n:1000,min:0,max:3000,u:"fois",e:"Jusqu’à 1 000 fois par seconde chez certains interneurones. Au-delà, impossible : après chaque impulsion, le neurone reste sourd environ une milliseconde, le temps de recharger sa membrane."},
{t:'sci',q:"Combien de nouvelles connexions neuronales un bébé fabrique-t-il chaque seconde ?",n:1000000,min:0,max:3000000,u:"connexions",e:"Un million par seconde durant les premières années. Puis vient l’élagage : l’adolescence supprime massivement les synapses inutilisées. Apprendre, c’est autant construire que jeter."},
{t:'sci',q:"Combien de minutes sans oxygène suffisent pour endommager le cerveau ?",n:4,min:0,max:8,u:"minutes",e:"Quatre minutes. C’est le tissu le plus vorace et le plus fragile du corps : il ne stocke rien. D’où la règle d’or des secours, où chaque minute perdue coûte 10 % de survie."},
{t:'sci',q:"En combien de temps le cerveau identifie-t-il une image qu’il n’a jamais vue ?",n:13,min:0,max:15,u:"millisecondes",e:"13 millisecondes, mesurées au MIT en 2014. C’est plus rapide qu’un battement de cil : la reconnaissance est déjà bouclée avant même que vous ayez conscience d’avoir regardé."},
{t:'sci',q:"De combien de millisecondes le cerveau devance-t-il votre décision consciente de bouger, selon l’expérience de Libet ?",n:350,min:0,max:1000,u:"millisecondes",e:"350 millisecondes. L’activité préparatoire démarre avant que vous ne « décidiez ». L’expérience de 1983 hante toujours les débats sur le libre arbitre, et personne ne l’a vraiment réfutée."},
{t:'sci',q:"Combien de temps une information survit-elle dans votre mémoire de travail sans être répétée ?",n:20,min:0,max:30,u:"secondes",e:"Une vingtaine de secondes. C’est la durée de vie d’un numéro de téléphone qu’on se récite : cessez de le répéter et il s’évapore, quel que soit votre niveau d’attention."},
{t:'sci',q:"Combien d’éléments votre mémoire immédiate peut-elle retenir en même temps, selon le célèbre article de Miller ?",n:7,min:0,max:20,u:"éléments",e:"Sept, plus ou moins deux. Publié en 1960, c’est l’un des articles de psychologie les plus cités au monde, et la raison pour laquelle les numéros de téléphone sont découpés."},
{t:'sci',q:"Avec combien de personnes un humain peut-il entretenir des relations sociales stables, selon le nombre de Dunbar ?",n:150,min:0,max:400,u:"personnes",e:"150. Ce chiffre, déduit de la taille du cortex des primates, se retrouve partout : villages néolithiques, compagnies militaires romaines, listes de vœux de fin d’année."},
{t:'sci',q:"Combien de pensées distinctes traversent un cerveau humain en une journée ?",n:6200,min:0,max:12000,u:"pensées",e:"Environ 6 200, selon une étude de 2020 qui a repéré à l’IRM les « vers de pensée », ces basculements d’une idée à la suivante. Soit une nouvelle pensée toutes les dix secondes éveillées."},
{t:'sci',q:"Jusqu’à quel âge le cerveau humain continue-t-il de mûrir ?",n:25,min:0,max:120,u:"ans",e:"25 ans environ. Le cortex préfrontal, siège du contrôle de soi et de l’évaluation du risque, finit sa myélinisation en dernier. La prudence n’est pas une vertu : c’est un câblage tardif."},
{t:'sci',q:"Combien d’heures Randy Gardner est-il resté éveillé lors du record de privation de sommeil ?",n:264,min:0,max:500,u:"heures",e:"264 heures, soit 11 jours, en 1964, pour un projet scolaire. Hallucinations, paranoïa, mémoire en miettes — puis il a dormi 14 heures et s’est réveillé apparemment intact."},
{t:'sci',q:"Combien de temps passez-vous en sommeil paradoxal, la phase des rêves, en une nuit ?",n:2,min:0,max:10,u:"heures",e:"Environ deux heures, réparties en quatre ou cinq épisodes de plus en plus longs. Le plus copieux arrive au petit matin : c’est pourquoi le réveil interrompt souvent un rêve."},
{t:'sci',q:"Quelle longueur faisait la barre de fer qui a traversé le crâne de Phineas Gage ?",n:1.1,min:0,max:1.5,u:"mètre",e:"1,10 mètre pour six kilos, propulsée par une explosion en 1848. Elle lui a emporté une partie du lobe frontal. Il a survécu douze ans, mais sa personnalité, elle, avait changé."},
{t:'sci',q:"Quel pourcentage des volontaires de Milgram sont allés jusqu’à la décharge électrique maximale ?",n:65,min:0,max:100,u:"%",e:"65 %, soit 26 sur 40, malgré les cris enregistrés du faux élève. Milgram, lui, s’attendait à moins de 2 %. Les psychiatres consultés avant l’expérience avaient prédit un sur mille."},
{t:'sci',q:"Quel voltage affichait le dernier bouton de la machine à chocs de l’expérience de Milgram ?",n:450,min:0,max:600,u:"volts",e:"450 volts, sous l’étiquette « XXX ». La machine était factice, mais les participants l’ignoraient. Beaucoup ont continué d’appuyer alors que l’élève ne répondait plus du tout."},
{t:'sci',q:"Combien de jours a duré l’expérience de la prison de Stanford, prévue pour deux semaines ?",n:6,min:0,max:20,u:"jours",e:"Six jours. Les gardiens improvisés étaient devenus si cruels que Zimbardo a tout arrêté, alerté par sa compagne. L’expérience est aujourd’hui largement contestée, mais reste un cas d’école."},
{t:'sci',q:"Combien de minutes les enfants devaient-ils résister devant le fameux marshmallow de Stanford ?",n:15,min:0,max:20,u:"minutes",e:"Quinze minutes seul face à la friandise, avec la promesse d’en avoir deux. Les enfants patients réussissaient mieux plus tard — mais des études récentes montrent que le milieu social explique beaucoup."},
{t:'sci',q:"Quel pourcentage de spectateurs ne voient pas le gorille traverser l’écran dans l’expérience du gorille invisible ?",n:50,min:0,max:100,u:"%",e:"Environ la moitié. Occupés à compter des passes de ballon, ils ratent un homme déguisé en gorille qui se frappe la poitrine au centre de l’image pendant neuf secondes."},
{t:'sci',q:"Combien de bâtonnets, les cellules de la vision nocturne, tapissent une seule rétine ?",n:120000000,min:0,max:150000000,u:"bâtonnets",e:"120 millions. Ils voient en noir et blanc et détectent des lueurs infimes, mais mettent près de 30 minutes à atteindre leur sensibilité maximale dans le noir."},
{t:'sci',q:"Combien de cônes, les cellules de la vision des couleurs, compte une rétine ?",n:6000000,min:0,max:25000000,u:"cônes",e:"6 millions seulement, vingt fois moins que les bâtonnets, et presque tous entassés au centre. Toute votre vision nette et colorée tient dans une zone grosse comme une tête d’épingle."},
{t:'sci',q:"Combien de fibres nerveuses composent un nerf optique ?",n:1000000,min:0,max:4000000,u:"fibres",e:"Environ un million d’axones dans un câble de 4 millimètres de diamètre. Ce n’est techniquement pas un nerf mais un prolongement du cerveau lui-même, sorti se promener dans l’orbite."},
{t:'sci',q:"Combien de fibres nerveuses relient les deux hémisphères du cerveau via le corps calleux ?",n:200000000,min:0,max:250000000,u:"fibres",e:"200 millions. Sectionner ce pont pour soigner l’épilepsie a créé les patients au « cerveau divisé » : une main pouvait boutonner la chemise pendant que l’autre la déboutonnait."},
{t:'sci',q:"À combien de mégapixels estime-t-on la résolution de l’œil humain ?",n:576,min:0,max:1500,u:"mégapixels",e:"Environ 576 mégapixels d’après le calcul le plus cité — mais c’est un trompe-l’œil : seul le centre est net. Le cerveau reconstitue le reste en bougeant l’œil trois fois par seconde."},
{t:'sci',q:"Combien de cellules ciliées, ces capteurs du son irremplaçables, contient une cochlée ?",n:15000,min:0,max:20000,u:"cellules",e:"15 000 par oreille, et pas une de plus : elles ne se régénèrent jamais chez l’humain. Chaque concert trop fort en tue définitivement quelques-unes."},
{t:'sci',q:"Quelle est la taille de l’étrier, le plus petit os du corps humain ?",n:3,min:0,max:6,u:"mm",e:"Trois millimètres, niché dans l’oreille moyenne. Avec le marteau et l’enclume, il amplifie vingt fois la pression des sons : sans lui, on n’entendrait presque rien sous l’eau du tympan."},
{t:'sci',q:"Combien de gènes de récepteurs olfactifs fonctionnels possédons-nous ?",n:400,min:0,max:2000,u:"gènes",e:"Environ 400 récepteurs différents, la plus grosse famille de gènes du génome humain. Leurs combinaisons expliquent qu’on distingue des milliers d’odeurs avec si peu de capteurs."},
{t:'sci',q:"Combien de récepteurs différents votre langue possède-t-elle pour détecter l’amertume ?",n:25,min:0,max:30,u:"récepteurs",e:"25 récepteurs pour l’amer, contre un seul pour le sucré. L’évolution a misé sur la détection des poisons : mieux vaut recracher cent aliments sains que d’en avaler un toxique."},
{t:'sci',q:"Combien de récepteurs tactiles se pressent sur un centimètre carré de pulpe de doigt ?",n:2500,min:0,max:20000,u:"récepteurs",e:"Environ 2 500, contre une poignée dans le dos. C’est cette densité qui permet la lecture du braille, et qui explique qu’une écharde au doigt fasse si mal."},
{t:'sci',q:"À partir de quelle distance entre deux pointes votre doigt sent-il qu’on le touche à deux endroits ?",n:2,min:0,max:4,u:"mm",e:"Deux millimètres au bout du doigt, contre quatre centimètres dans le dos. Testez sur un ami avec deux trombones : dans le dos, il jurera qu’il n’y a qu’une pointe."},
{t:'sci',q:"Quelle taille d’aspérité un doigt humain est-il capable de détecter en glissant sur une surface lisse ?",n:13,min:0,max:30,u:"nanomètres",e:"13 nanomètres, révélé par une étude suédoise de 2013. Si votre doigt avait la taille de la Terre, il sentirait la différence entre une maison et une voiture."},
{t:'sci',q:"Combien de temps dure un clignement d’œil ?",n:100,min:0,max:120,u:"millisecondes",e:"Un dixième de seconde. Vous clignez environ 15 fois par minute, soit 10 % du temps d’éveil les yeux fermés — sans jamais percevoir le moindre noir, le cerveau censurant l’interruption."},
{t:'sci',q:"Combien de fois par seconde vos yeux sautent-ils d’un point à un autre sans que vous le remarquiez ?",n:3,min:0,max:20,u:"fois",e:"Trois saccades par seconde, les mouvements les plus rapides du corps. Pendant chacune, la vision est coupée. Vous passez ainsi plusieurs années de votre vie aveugle sans le savoir."},
{t:'sci',q:"Combien d’os compte un nouveau-né ?",n:270,min:0,max:1200,u:"os",e:"Environ 270, contre 206 chez l’adulte. En grandissant, des dizaines d’os fusionnent : le crâne se soude, le sacrum se forme. On perd des os en vieillissant, on n’en gagne pas."},
{t:'sci',q:"Combien de muscles compte le corps humain ?",n:600,min:0,max:4000,u:"muscles",e:"Environ 600, dont les plus petits mesurent un millimètre et servent à tendre le tympan. Ils représentent près de 40 % du poids d’un adulte."},
{t:'sci',q:"Quelle longueur totale atteindraient vos vaisseaux sanguins mis bout à bout ?",n:100000,min:0,max:600000,u:"km",e:"Environ 100 000 kilomètres, deux fois et demie le tour de la Terre. L’essentiel n’est pas fait de grosses artères mais de capillaires plus fins qu’un cheveu."},
{t:'sci',q:"Combien de globules rouges votre moelle osseuse fabrique-t-elle chaque seconde ?",n:2400000,min:0,max:3000000,u:"globules rouges",e:"Près de 2,4 millions par seconde, jour et nuit. Il en faut autant pour compenser ceux qui meurent : votre sang se renouvelle entièrement en quatre mois."},
{t:'sci',q:"Combien de temps vit un globule rouge ?",n:120,min:0,max:200,u:"jours",e:"120 jours de bons et loyaux services. Sans noyau ni ADN, il ne peut ni se réparer ni se diviser : la rate finit par le broyer, et le fer est recyclé."},
{t:'sci',q:"Combien de temps met un globule rouge pour faire un tour complet du corps ?",n:60,min:0,max:80,u:"secondes",e:"Environ une minute pour boucler le circuit poumons-corps-poumons. Sur ses 120 jours de vie, il fera donc plus de 170 000 tours et parcourra des centaines de kilomètres."},
{t:'sci',q:"Combien d’alvéoles se cachent dans vos deux poumons ?",n:300000000,min:0,max:800000000,u:"alvéoles",e:"Environ 300 millions de minuscules bulles. Chacune est enveloppée d’un filet de capillaires : c’est là, sur une paroi mille fois plus fine qu’une feuille, que passe l’oxygène."},
{t:'sci',q:"Quelle surface d’échange offriraient vos poumons entièrement dépliés ?",n:70,min:0,max:150,u:"m²",e:"Environ 70 m², la moitié d’un court de tennis, repliés dans votre cage thoracique. Toute cette surface sert à faire passer l’oxygène dans le sang le plus vite possible."},
{t:'sci',q:"Quelle est la surface réelle de votre intestin grêle ?",n:30,min:0,max:60,u:"m²",e:"30 m², soit un studio parisien — pas les 300 m² d’un terrain de tennis répétés partout. Une étude suédoise de 2014 a corrigé cette erreur qui traînait dans les manuels."},
{t:'sci',q:"Quelle longueur mesure l’intestin grêle d’un adulte ?",n:6,min:0,max:20,u:"mètres",e:"Six mètres environ à l’autopsie, replié dans un ventre de trente centimètres. Vivant, il est plus court : ses muscles le maintiennent en tension permanente."},
{t:'sci',q:"Combien de bactéries hébergez-vous dans votre corps ?",n:38000000000000,min:0,max:150000000000000,u:"bactéries",e:"38 000 milliards, contre 30 000 milliards de cellules humaines. Le fameux ratio de dix bactéries pour une cellule, longtemps répété, a été corrigé en 2016 : on est presque à égalité."},
{t:'sci',q:"Combien pèse la totalité de votre microbiote intestinal ?",n:200,min:0,max:400,u:"grammes",e:"Environ 200 grammes, pas les deux kilos souvent avancés. Un petit pot de yaourt de bactéries qui digèrent vos fibres, fabriquent des vitamines et dialoguent avec votre cerveau."},
{t:'sci',q:"Combien de cellules composent un corps humain ?",n:37200000000000,min:0,max:100000000000000,u:"cellules",e:"37 200 milliards, selon un recomptage italien de 2013 organe par organe. Les globules rouges, minuscules, en représentent à eux seuls près de 84 %."},
{t:'sci',q:"Combien de litres de salive produisez-vous chaque jour ?",n:1.5,min:0,max:2,u:"litres",e:"Jusqu’à un litre et demi, soit une grande bouteille quotidienne. Elle contient une enzyme qui commence à digérer l’amidon dans la bouche : mâchez longtemps du pain, il devient sucré."},
{t:'sci',q:"Combien de litres de sang un adulte a-t-il dans le corps ?",n:5,min:0,max:15,u:"litres",e:"Environ cinq litres, à peine 8 % du poids. Une perte d’un tiers suffit à provoquer un choc : le corps ne dispose d’aucune réserve, contrairement à l’eau ou à la graisse."},
{t:'sci',q:"Combien de litres de sang votre cœur pompe-t-il en une journée ?",n:7000,min:0,max:40000,u:"litres",e:"Environ 7 000 litres, soit une petite piscine gonflable, avec la puissance d’une ampoule de veilleuse. Sur une vie entière, cela représente près de 200 millions de litres."},
{t:'sci',q:"Combien de litres de liquide vos reins filtrent-ils chaque jour ?",n:180,min:0,max:500,u:"litres",e:"180 litres de filtrat par jour, dont ils récupèrent plus de 99 %. Il n’en sort qu’un litre et demi d’urine : le reste est méticuleusement réabsorbé, goutte après goutte."},
{t:'sci',q:"Combien de néphrons, les minuscules unités filtrantes, contient un rein ?",n:1000000,min:0,max:1500000,u:"néphrons",e:"Un million par rein. On en perd naturellement avec l’âge et ils ne se remplacent pas : à 80 ans, il en reste souvent la moitié, ce qui suffit encore largement."},
{t:'sci',q:"Quelle longueur ferait l’ADN contenu dans une seule de vos cellules, s’il était déroulé ?",n:2,min:0,max:4,u:"mètres",e:"Deux mètres de fil, compactés dans un noyau de six micromètres. C’est comme ranger quarante kilomètres de fil de pêche dans une balle de tennis, sans jamais faire de nœud."},
{t:'sci',q:"Combien de paires de bases compte le génome humain ?",n:3100000000,min:0,max:4000000000,u:"paires de bases",e:"3,1 milliards de lettres. Imprimé en petits caractères, cela ferait 260 volumes de mille pages. Moins de 2 % code réellement des protéines."},
{t:'sci',q:"Combien de gènes codants possède l’être humain ?",n:20000,min:0,max:40000,u:"gènes",e:"Environ 20 000, à peine plus qu’un ver microscopique et moins qu’un grain de riz. Avant le séquençage, les paris allaient jusqu’à 150 000 : l’humain n’est pas si compliqué à écrire."},
{t:'sci',q:"Combien de mutations génétiques totalement nouvelles chaque bébé porte-t-il, absentes de ses deux parents ?",n:70,min:0,max:100,u:"mutations",e:"Environ 70 erreurs de copie fraîches. La plupart sont inoffensives, quelques-unes délétères, une infime fraction utile. C’est le carburant brut de l’évolution, livré à chaque naissance."},
{t:'sci',q:"Quel pourcentage d’ADN néandertalien porte un Européen aujourd’hui ?",n:2,min:0,max:100,u:"%",e:"Environ 2 %. Nos ancêtres ont croisé Néandertal il y a quelque 50 000 ans, et ce legs influence encore le sommeil, l’immunité et la sensibilité à la douleur."},
{t:'sci',q:"Avec combien d’ovocytes une petite fille vient-elle au monde ?",n:1000000,min:0,max:6000000,u:"ovocytes",e:"Un à deux millions, et pas un de plus : le stock est constitué avant la naissance puis fond sans arrêt. À la puberté, il n’en reste que 300 000."},
{t:'sci',q:"Combien d’ovules une femme libère-t-elle réellement au cours de sa vie ?",n:400,min:0,max:800,u:"ovules",e:"Environ 400, soit 0,03 % du stock de départ. Tous les autres disparaissent silencieusement. Le corps humain gaspille massivement pour ne garder que les meilleurs candidats."},
{t:'sci',q:"En combien de temps votre peau se renouvelle-t-elle entièrement ?",n:27,min:0,max:30,u:"jours",e:"Environ quatre semaines : les cellules naissent en profondeur, remontent, meurent et se détachent. La poussière de votre chambre est en bonne partie faite de vous."},
{t:'sci',q:"En combien de temps votre squelette se renouvelle-t-il en totalité ?",n:10,min:0,max:30,u:"ans",e:"Une dizaine d’années. Des cellules démolissent l’os pendant que d’autres le reconstruisent en permanence. L’os que vous aviez à vingt ans n’existe plus du tout aujourd’hui."},
{t:'sci',q:"Combien de temps vit une cellule qui tapisse votre intestin ?",n:4,min:0,max:6,u:"jours",e:"Quatre jours à peine, le tissu le plus renouvelé du corps. Frottée en permanence par l’acide et les aliments, elle est remplacée avant d’avoir le temps de s’abîmer."},
{t:'sci',q:"Quel est le pH de l’acide contenu dans votre estomac ?",n:1.5,min:0,max:2,u:"pH",e:"Autour de 1,5, assez corrosif pour dissoudre une lame de rasoir. Seule une couche de mucus renouvelée toutes les deux semaines empêche l’estomac de se digérer lui-même."},
{t:'sci',q:"Combien de grammes de fer contient un corps humain ?",n:4,min:0,max:5,u:"grammes",e:"Quatre grammes, de quoi forger un petit clou. L’essentiel circule dans l’hémoglobine, où l’atome de fer capte l’oxygène — et donne au sang sa couleur rouge."},
{t:'sci',q:"Combien de milligrammes d’or contient le corps humain ?",n:0.2,min:0,max:0.5,u:"milligrammes",e:"Deux dixièmes de milligramme, invisibles à l’œil nu, dissous dans le sang. Il faudrait 40 000 personnes pour récolter un seul lingot de huit grammes."},
{t:'sci',q:"Quelle puissance thermique dégage un corps humain au repos ?",n:100,min:0,max:400,u:"watts",e:"Environ 100 watts, comme une vieille ampoule. Une salle de cinéma pleine chauffe toute seule : les climatiseurs y luttent surtout contre les spectateurs, pas contre le soleil."},
{t:'sci',q:"Combien de litres d’air passent par vos poumons en une journée ?",n:11000,min:0,max:12000,u:"litres",e:"Environ 11 000 litres, le volume d’une petite pièce. Vous soulevez votre cage thoracique 20 000 fois par jour sans y penser une seule seconde."},
{t:'sci',q:"Combien de cheveux poussent sur une tête humaine ?",n:100000,min:0,max:120000,u:"cheveux",e:"Environ 100 000, et on en perd normalement une centaine par jour. Chacun pousse deux à six ans, se repose, tombe, puis recommence — sur environ 25 cycles maximum."},
{t:'sci',q:"De combien vos ongles s’allongent-ils chaque mois ?",n:3.5,min:0,max:5,u:"mm",e:"Trois millimètres et demi pour les mains, deux fois moins pour les pieds. Ceux de la main dominante et du majeur poussent plus vite : la circulation et l’usage stimulent la matrice."},
{t:'sci',q:"Quelle force de morsure record un humain a-t-il produite ?",n:442,min:0,max:600,u:"kg",e:"442 kilos, mesurés chez Richard Hofmann en 1986, six fois la morsure moyenne. Le masséter reste, à masse égale, le muscle le plus puissant du corps humain."},
{t:'sci',q:"Quel est le diamètre d’un capillaire sanguin, le plus fin de vos vaisseaux ?",n:8,min:0,max:20,u:"micromètres",e:"Huit micromètres, à peine la largeur d’un globule rouge. Celui-ci doit se plier en deux pour passer — et cette contorsion est précisément ce qui permet l’échange d’oxygène."},
{t:'sci',q:"Combien de jours a duré le jeûne le plus long jamais supervisé médicalement ?",n:382,min:0,max:600,u:"jours",e:"382 jours, en Écosse, pour Angus Barbieri, qui ne buvait que du thé, du café et des vitamines. Il est passé de 207 à 82 kilos et n’a pas repris de poids."},
{t:'sci',q:"Quelle température corporelle un humain a-t-il survécu à atteindre ?",n:46.5,min:0,max:80,u:"°C",e:"46,5 °C, record établi par Willie Jones lors d’une canicule à Atlanta en 1980. Il est sorti de l’hôpital 24 jours plus tard, alors que 42 °C sont réputés fatals."},
{t:'sci',q:"Jusqu’à quelle température corporelle une personne a-t-elle survécu à une hypothermie ?",n:13.7,min:0,max:25,u:"°C",e:"13,7 °C, pour la skieuse Anna Bågenholm, piégée sous la glace en Norvège. Son cœur s’est arrêté trois heures. Le froid extrême avait mis son cerveau en pause plutôt que de le tuer."},
{t:'sci',q:"Quelle était la fréquence cardiaque au repos du cycliste Miguel Indurain ?",n:28,min:0,max:30,u:"battements par minute",e:"28 battements par minute, contre 70 pour un adulte normal. Son cœur, énorme, expédiait 50 litres de sang par minute à l’effort. Chez vous, ce chiffre déclencherait une alarme."},
{t:'sci',q:"Combien de g le colonel John Stapp a-t-il encaissés sur son chariot-fusée ?",n:46.2,min:0,max:200,u:"g",e:"46,2 fois son poids en 1954, freinant de 1 000 km/h à zéro en une seconde. Ses yeux ont saigné, mais il a prouvé qu’un humain sanglé pouvait survivre : les ceintures lui doivent tout."},
{t:'sci',q:"Quelle température atteint l’air traversé par un éclair ?",n:30000,min:0,max:50000,u:"°C",e:"30 000 °C, cinq fois la surface du Soleil. Cette chauffe instantanée dilate l’air si brutalement qu’elle crée une onde de choc : le tonnerre n’est rien d’autre que ce claquement."},
{t:'sci',q:"Combien d’éclairs frappent la Terre chaque seconde ?",n:44,min:0,max:60,u:"éclairs",e:"Environ 44 par seconde, mesurés par satellite, soit près de quatre millions par jour. Le Venezuela en concentre une part énorme, avec des orages presque toutes les nuits."},
{t:'sci',q:"Combien de neutrinos venus du Soleil traversent chaque centimètre carré de votre peau à chaque seconde ?",n:65000000000,min:0,max:300000000000,u:"neutrinos",e:"65 milliards, de jour comme de nuit — ils traversent la Terre entière sans ralentir. Pour en arrêter un seul, il faudrait une épaisseur de plomb d’une année-lumière."},
{t:'sci',q:"À quelle vitesse la lumière ralentit-elle en traversant un diamant ?",n:124000,min:0,max:250000,u:"km/s",e:"124 000 km/s, contre 300 000 dans le vide : deux fois moins vite. Ce freinage brutal dévie les rayons dans tous les sens, et c’est exactement ce qui fait scintiller la pierre."},

/* ---------- Là-haut ---------- */
{t:'espace',q:"À quelle vitesse la Station spatiale internationale file-t-elle autour de la Terre ?",n:27600,min:0,max:60000,u:"km/h",e:"27 600 km/h, soit un tour complet en 90 minutes. À cette allure, Paris-New York prendrait douze minutes."},
{t:'espace',q:"Combien de levers de soleil les astronautes de l'ISS voient-ils par jour ?",n:16,min:0,max:30,u:"levers",e:"16 par jour. Pour dormir, ils s'attachent dans un sac et se bandent les yeux : leur horloge biologique reste calée sur Greenwich."},
{t:'espace',q:"Quel est le record de séjour continu dans l'espace ?",n:437,min:0,max:500,u:"jours",e:"437 jours d'affilée pour Valeri Poliakov, à bord de Mir. Il est parti d'Union soviétique et rentré dans une Russie qui n'existait pas à son départ."},
{t:'espace',q:"Quel pourcentage de la gravité terrestre règne à l'altitude de l'ISS ?",n:90,min:0,max:100,u:"%",e:"90 %. Les astronautes ne flottent pas parce qu'il n'y a plus de gravité, mais parce qu'ils sont en chute libre permanente autour de la Terre."},
{t:'espace',q:"Combien de temps Armstrong et Aldrin ont-ils marché sur la Lune ?",n:151,min:0,max:300,u:"minutes",e:"2 h 31 dehors, pas plus. Après des années de préparation et 380 000 km de voyage, la sortie a duré le temps d'un film."},
{t:'espace',q:"Quelle température règne à la surface de Vénus ?",n:465,min:0,max:800,u:"°C",e:"465 °C, de jour comme de nuit, partout sur la planète. C'est plus chaud que Mercure, pourtant deux fois plus proche du Soleil : l'effet de serre y est total."},
{t:'espace',q:"Combien de mémoire vive avait l’ordinateur de bord qui a posé Apollo 11 sur la Lune ?",n:4,min:0,max:6,u:"kilo-octets",e:"4 ko. Une carte de vœux musicale d’aujourd’hui en contient davantage. L’engin a quand même piloté un alunissage manuel avec deux alarmes de surcharge en pleine descente."},
{t:'espace',q:"Quelle hauteur faisait la fusée Saturn V ?",n:111,min:0,max:200,u:"mètres",e:"111 mètres, soit un immeuble de 36 étages posé debout sur un pas de tir. Elle reste la fusée opérationnelle la plus puissante jamais construite."},
{t:'espace',q:"Combien pesait une Saturn V au décollage ?",n:2970,min:0,max:5000,u:"tonnes",e:"Près de 3 000 tonnes, dont 90 % de carburant. Le reste, la charge utile envoyée vers la Lune, tenait dans le petit cône du sommet."},
{t:'espace',q:"De combien de pièces était composée une fusée Saturn V ?",n:3000000,min:0,max:10000000,u:"pièces",e:"Environ trois millions. Avec une fiabilité de 99,9 %, cela laisserait quand même 3 000 pièces défaillantes par vol. Aucune Saturn V n’a pourtant échoué."},
{t:'espace',q:"Combien de personnes ont travaillé sur le programme Apollo ?",n:400000,min:0,max:1500000,u:"personnes",e:"400 000, réparties dans des milliers d’entreprises. La plupart n’ont jamais vu une fusée : elles cousaient des combinaisons, tressaient des mémoires à la main ou vérifiaient des soudures."},
{t:'espace',q:"Combien d’êtres humains ont marché sur la Lune ?",n:12,min:0,max:30,u:"hommes",e:"Douze, tous entre 1969 et 1972, en six missions. Plus personne depuis. Le douzième, Eugene Cernan, a laissé les dernières empreintes en remontant dans son module."},
{t:'espace',q:"Combien de kilos de roches lunaires les missions Apollo ont-elles rapportés ?",n:382,min:0,max:600,u:"kg",e:"382 kg, soit le poids de cinq adultes. Une partie dort encore sous vide, jamais ouverte, en attendant des instruments d’analyse plus fins que ceux des années 1970."},
{t:'espace',q:"À quelle distance record de la Terre des humains se sont-ils déjà trouvés ?",n:400171,min:0,max:2000000,u:"km",e:"400 171 km, l’équipage d’Apollo 13, contraint de contourner la Lune par une trajectoire plus large après l’explosion de son réservoir. Un record établi par accident."},
{t:'espace',q:"Quelle était l’épaisseur de la paroi du module lunaire d’Apollo par endroits ?",n:0.3,min:0,max:0.8,u:"mm",e:"0,3 mm, l’épaisseur de deux feuilles de papier aluminium. On pouvait la percer avec un tournevis. Chaque gramme gagné valait du carburant pour redécoller."},
{t:'espace',q:"Combien pesait le module lunaire d’Apollo ?",n:15,min:0,max:20,u:"tonnes",e:"15 tonnes au complet, dont l’essentiel en ergols. La cabine où vivaient deux hommes offrait à peine le volume de deux cabines téléphoniques, sans siège."},
{t:'espace',q:"Combien de jours de quarantaine les astronautes d’Apollo 11 ont-ils subis au retour ?",n:21,min:0,max:80,u:"jours",e:"21 jours enfermés, par crainte de microbes lunaires. Ils ont dû enfiler des combinaisons d’isolement dès la sortie de la capsule, puis vivre dans une caravane blindée."},
{t:'espace',q:"Combien de couches comptait la combinaison lunaire des astronautes d’Apollo ?",n:21,min:0,max:25,u:"couches",e:"21 couches superposées, du sous-vêtement refroidi par eau au tissu pare-micrométéorites. Chacune était cousue à la main par des couturières formées chez un fabricant de corsets."},
{t:'espace',q:"Combien de drapeaux américains ont été plantés sur la Lune ?",n:6,min:0,max:8,u:"drapeaux",e:"Six, un par mission. Cinq tiennent encore debout : celui d’Apollo 11 a été renversé par le souffle du décollage, sous les yeux d’Aldrin. Le soleil les a tous décolorés en blanc."},
{t:'espace',q:"Combien de sacs d’excréments humains les missions Apollo ont-elles laissés sur la Lune ?",n:96,min:0,max:120,u:"sacs",e:"96 sacs abandonnés pour alléger les modules au décollage. Des biologistes rêvent d’aller les récupérer : des bactéries y ont peut-être survécu un demi-siècle sous vide."},
{t:'espace',q:"Quelle vitesse maximale le rover lunaire d’Apollo a-t-il atteint ?",n:18,min:0,max:150,u:"km/h",e:"18 km/h, en descente, par Eugene Cernan. Un record de vitesse extraterrestre toujours debout. En rebondissant à cette allure, les roues quittaient le sol plusieurs mètres."},
{t:'espace',q:"Combien de temps Apollo 11 a-t-il mis pour rejoindre l’orbite lunaire ?",n:76,min:0,max:200,u:"heures",e:"76 heures, soit trois jours et quatre heures pour 384 000 km. Les astronautes flottaient, jouaient de la musique et faisaient des retransmissions télé pendant le trajet."},
{t:'espace',q:"Combien de décibels le décollage d’une Saturn V produisait-il ?",n:204,min:0,max:400,u:"décibels",e:"204 décibels mesurés au pas de tir, l’un des sons les plus forts jamais produits par l’homme. À 5 km, le grondement faisait vibrer les côtes des spectateurs."},
{t:'espace',q:"Combien de personnes ont regardé en direct les premiers pas sur la Lune ?",n:600000000,min:0,max:4000000000,u:"spectateurs",e:"Environ 600 millions, un cinquième de l’humanité de l’époque. Beaucoup ont vu une image floue en noir et blanc, filmée par une caméra fixée à une trappe."},
{t:'espace',q:"Combien d’années séparent le premier vol des frères Wright des premiers pas sur la Lune ?",n:66,min:0,max:100,u:"ans",e:"66 ans. Des gens nés avant le premier avion motorisé ont vu un homme marcher sur la Lune. Le premier vol des Wright avait duré douze secondes."},
{t:'espace',q:"Quelle distance moyenne sépare la Terre de la Lune ?",n:384400,min:0,max:800000,u:"km",e:"384 400 km. Toutes les planètes du système solaire, mises bout à bout, tiendraient dans cet intervalle. Sur les schémas d’école, la Lune est toujours dessinée bien trop près."},
{t:'espace',q:"Combien de temps mettrait une voiture roulant à 100 km/h pour atteindre la Lune ?",n:160,min:0,max:300,u:"jours",e:"160 jours sans jamais s’arrêter. Apollo 11 a fait le trajet en trois jours parce qu’il partait à 40 000 km/h, puis se laissait freiner par la gravité terrestre."},
{t:'espace',q:"De combien la Lune s’éloigne-t-elle de la Terre chaque année ?",n:3.8,min:0,max:8,u:"cm",e:"3,8 cm par an, mesuré au laser sur les réflecteurs posés par Apollo. C’est la vitesse à laquelle poussent les ongles. Les marées lui volent lentement de l’énergie."},
{t:'espace',q:"Dans combien d’années la Lune sera-t-elle trop loin pour provoquer des éclipses totales ?",n:600000000,min:0,max:800000000,u:"années",e:"Environ 600 millions d’années. Nous vivons dans la fenêtre où le disque lunaire couvre exactement le Soleil. Les dinosaures ont vu de meilleures éclipses que nos descendants."},
{t:'espace',q:"Combien de fois le Soleil est-il plus éloigné de nous que la Lune ?",n:400,min:0,max:800,u:"fois",e:"400 fois plus loin, et il se trouve aussi être 400 fois plus grand. Cette coïncidence sans explication est ce qui rend les éclipses totales possibles."},
{t:'espace',q:"Combien pèserait sur la Lune un homme de 80 kg ?",n:13,min:0,max:40,u:"kg",e:"13 kg, un sixième de son poids. Avec 90 kg de combinaison et de sac dorsal, les astronautes d’Apollo pesaient encore moins qu’un enfant et avançaient en sautillant."},
{t:'espace',q:"Combien de temps a duré le tout premier vol spatial habité, celui de Youri Gagarine ?",n:108,min:0,max:150,u:"minutes",e:"108 minutes, un seul tour de Terre. Gagarine n’a rien piloté : les commandes étaient verrouillées par un code, au cas où l’apesanteur lui ferait perdre la raison."},
{t:'espace',q:"Combien de temps a duré la première sortie dans l’espace, celle d’Alexeï Leonov ?",n:12,min:0,max:30,u:"minutes",e:"12 minutes, qui ont failli être les dernières : sa combinaison a gonflé au point qu’il ne pouvait plus rentrer par le sas. Il a purgé son air pour dégonfler."},
{t:'espace',q:"Combien pesait Spoutnik 1, le premier satellite artificiel ?",n:83.6,min:0,max:120,u:"kg",e:"83,6 kg pour une sphère de 58 cm munie de quatre antennes. Elle ne faisait que biper. Ce bip, capté par des radioamateurs du monde entier, a déclenché la course à l’espace."},
{t:'espace',q:"Combien pèse le plus vieux satellite encore en orbite autour de la Terre ?",n:1.47,min:0,max:3,u:"kg",e:"1,47 kg : Vanguard 1, lancé en 1958, surnommé « pamplemousse » par Khrouchtchev. Muet depuis 1964, il continue de tourner et tiendra encore des siècles."},
{t:'espace',q:"Combien de jours Borman et Lovell ont-ils passé enfermés dans la capsule Gemini 7 ?",n:14,min:0,max:30,u:"jours",e:"14 jours à deux dans un volume comparable à l’avant d’une petite voiture, sans pouvoir se lever. Ils ont fini par retirer leurs combinaisons tant la chaleur était insupportable."},
{t:'espace',q:"Combien de temps le cosmonaute Sergueï Krikalev est-il resté bloqué en orbite pendant la chute de l’URSS ?",n:311,min:0,max:800,u:"jours",e:"311 jours. Parti citoyen soviétique, il est revenu russe : le pays qui l’avait envoyé n’existait plus, et personne n’avait le budget pour le faire redescendre plus tôt."},
{t:'espace',q:"Combien de temps a duré la plus longue sortie extravéhiculaire de l’histoire ?",n:536,min:0,max:1000,u:"minutes",e:"536 minutes, soit 8 heures 56, par Susan Helms et James Voss en 2001. Presque neuf heures dans une combinaison, sans s’asseoir, sans se gratter le nez."},
{t:'espace',q:"Combien de vols la navette spatiale américaine a-t-elle effectués au total ?",n:135,min:0,max:250,u:"vols",e:"135 missions en trente ans, avec cinq orbiteurs. La flotte devait voler une fois par semaine pour un coût modique : elle n’a jamais dépassé neuf vols par an."},
{t:'espace',q:"Combien de tuiles de protection thermique recouvraient une navette spatiale ?",n:24000,min:0,max:120000,u:"tuiles",e:"Environ 24 000, chacune unique, numérotée et collée à la main. Elles encaissaient 1 500 °C à la rentrée tout en restant assez froides pour être tenues à main nue quelques secondes après."},
{t:'espace',q:"Quelle amende la ville australienne d’Esperance a-t-elle infligée à la NASA après la chute de Skylab ?",n:400,min:0,max:1000,u:"dollars",e:"400 dollars pour dépôt sauvage d’ordures, la station s’étant désintégrée au-dessus de son territoire. La NASA n’a jamais payé ; un animateur radio américain a réglé la note trente ans plus tard."},
{t:'espace',q:"Combien pèse la Station spatiale internationale ?",n:420,min:0,max:500,u:"tonnes",e:"420 tonnes, l’équivalent de 300 voitures, assemblées pièce par pièce en orbite au fil de plus de quarante vols. C’est l’objet le plus cher jamais construit par l’humanité."},
{t:'espace',q:"Quelle longueur de câbles électriques court à l’intérieur de la Station spatiale internationale ?",n:13,min:0,max:80,u:"km",e:"Près de 13 km de câblage, davantage que dans un gros avion de ligne. Les astronautes passent une partie de leur temps à traquer des pannes derrière les panneaux."},
{t:'espace',q:"De combien un astronaute grandit-il pendant un séjour prolongé en apesanteur ?",n:5,min:0,max:20,u:"cm",e:"Jusqu’à 5 cm : sans gravité, les disques de la colonne vertébrale se décompriment. Le gain disparaît en quelques jours au retour, souvent accompagné de sérieux maux de dos."},
{t:'espace',q:"Combien pèse sur Terre une combinaison de sortie extravéhiculaire de la NASA ?",n:127,min:0,max:200,u:"kg",e:"127 kg avec son sac dorsal : impossible à porter debout au sol. En orbite elle ne pèse rien, mais reste si rigide que fermer le poing épuise les avant-bras."},
{t:'espace',q:"Combien de couches superposées compose une combinaison spatiale moderne de sortie ?",n:14,min:0,max:25,u:"couches",e:"14 couches, du refroidissement liquide au blindage anti-micrométéorites. C’est un vaisseau spatial individuel avec sa propre pression, son oxygène et son épurateur de gaz carbonique."},
{t:'espace',q:"Combien de secondes reste-t-on conscient si l’on est exposé au vide spatial ?",n:15,min:0,max:20,u:"secondes",e:"Environ 15 secondes de conscience utile : c’est le manque d’oxygène au cerveau qui frappe, pas le froid ni l’explosion des films. Un technicien de la NASA l’a vécu en 1966 et s’en est remis."},
{t:'espace',q:"Quelle dose de radiations un aller-retour vers Mars ferait-il encaisser à un astronaute ?",n:0.66,min:0,max:1.2,u:"sievert",e:"0,66 sievert, mesuré par la sonde Curiosity pendant son propre voyage. C’est l’équivalent d’un scanner du corps entier tous les cinq jours pendant tout le trajet."},
{t:'espace',q:"À quelle vitesse Felix Baumgartner est-il tombé lors de son saut depuis la stratosphère ?",n:1357,min:0,max:2000,u:"km/h",e:"1 357 km/h, plus vite que le son, en chute libre. L’air était si rare à 39 km d’altitude qu’il n’y avait presque rien pour le freiner pendant les premières secondes."},
{t:'espace',q:"À quelle altitude commence officiellement l’espace ?",n:100,min:0,max:150,u:"km",e:"100 km, la ligne de Kármán : au-delà, il faudrait voler plus vite que la vitesse orbitale pour que des ailes portent encore. C’est un Paris-Rouen à la verticale."},
{t:'espace',q:"À quelle altitude se trouvent les satellites géostationnaires ?",n:35786,min:0,max:300000,u:"km",e:"35 786 km, la seule altitude où un satellite tourne exactement à la vitesse de la Terre. C’est un dixième de la distance à la Lune, et c’est de là que vient la télévision par satellite."},
{t:'espace',q:"De combien les horloges des satellites GPS se décalent-elles chaque jour à cause de la relativité ?",n:38,min:0,max:100,u:"microsecondes",e:"38 microsecondes par jour : le temps passe plus vite là-haut. Sans cette correction d’Einstein, votre GPS vous placerait à 10 km de votre position après une seule journée."},
{t:'espace',q:"À quelle vitesse faut-il lancer un objet pour qu’il échappe définitivement à la Terre ?",n:11.2,min:0,max:50,u:"km/s",e:"11,2 km/s, soit 40 000 km/h : Paris-Marseille en une minute. En dessous, quelle que soit la puissance, l’objet finit toujours par retomber."},
{t:'espace',q:"À quelle vitesse la surface de la Terre tourne-t-elle à l’équateur ?",n:1670,min:0,max:3000,u:"km/h",e:"1 670 km/h, soit plus vite qu’un avion de chasse, sans que personne ne le sente. C’est pour cela que les bases de lancement sont installées le plus près possible de l’équateur."},
{t:'espace',q:"À quelle vitesse la Terre file-t-elle autour du Soleil ?",n:107000,min:0,max:200000,u:"km/h",e:"107 000 km/h, soit 30 km par seconde. Le temps de lire cette phrase, vous avez parcouru la distance Paris-Bruxelles, assis sans bouger."},
{t:'espace',q:"Combien de temps peut durer au maximum la totalité d’une éclipse solaire ?",n:7.5,min:0,max:15,u:"minutes",e:"7 minutes 32 secondes au grand maximum, et la plupart durent moins de trois minutes. Des gens traversent la planète et attendent des années pour ces quelques instants d’obscurité."},
{t:'espace',q:"À quelle vitesse le Soleil entraîne-t-il le système solaire autour de la galaxie ?",n:230,min:0,max:1500,u:"km/s",e:"230 km par seconde, soit 828 000 km/h. Nous ne tournons pas seulement autour du Soleil : nous filons avec lui dans un immense virage de la Voie lactée."},
{t:'espace',q:"Combien de temps le Soleil met-il à faire un tour complet de la Voie lactée ?",n:225000000,min:0,max:600000000,u:"années",e:"Environ 225 millions d’années. Lors de son dernier passage au même endroit, les dinosaures venaient d’apparaître. Le Soleil n’a bouclé qu’une vingtaine de tours depuis sa naissance."},
{t:'espace',q:"Quelle taille aurait la Terre si on la comprimait en trou noir ?",n:9,min:0,max:12,u:"mm",e:"9 mm de rayon, une bille. Toute la masse de la planète tiendrait dans le creux de la main — enfin, si la main pouvait s’en approcher."},
{t:'espace',q:"Combien de temps mettrait un avion de ligne pour atteindre le Soleil ?",n:19,min:0,max:30,u:"ans",e:"19 ans de vol sans escale à 900 km/h pour couvrir 150 millions de km. Et le Soleil est, à l’échelle cosmique, notre voisin de palier."},
{t:'espace',q:"Combien de Terres tiendraient à l’intérieur du Soleil ?",n:1300000,min:0,max:1500000,u:"Terres",e:"Environ 1,3 million. Et pourtant le Soleil est une étoile parfaitement banale, plutôt petite : certaines géantes rouges engloberaient l’orbite de Jupiter."},
{t:'espace',q:"Quel pourcentage de la masse du système solaire le Soleil représente-t-il ?",n:99.86,min:0,max:100,u:"%",e:"99,86 %. Tout le reste — les huit planètes, les lunes, les astéroïdes, les comètes — se partage les miettes. Jupiter compte pour presque tout ce qui reste."},
{t:'espace',q:"Combien de matière le Soleil transforme-t-il en pure énergie chaque seconde ?",n:4000000,min:0,max:10000000,u:"tonnes",e:"Environ 4 millions de tonnes par seconde, converties en lumière selon E=mc². Le Soleil maigrit en permanence, mais il lui reste encore cinq milliards d’années de réserves."},
{t:'espace',q:"Combien de tonnes d’hydrogène le Soleil consomme-t-il chaque seconde ?",n:600000000,min:0,max:1500000000,u:"tonnes",e:"600 millions de tonnes par seconde. Cela dure depuis 4,6 milliards d’années et le réservoir est à peine entamé : c’est l’échelle de l’étoile qui est démesurée."},
{t:'espace',q:"Quelle température règne au cœur du Soleil ?",n:15000000,min:0,max:60000000,u:"°C",e:"15 millions de degrés. La surface, elle, n’en fait que 5 500 — mais la couronne, bien plus haut, remonte à un million de degrés, un mystère qui occupe encore les physiciens."},
{t:'espace',q:"Combien de neutrinos solaires traversent chaque centimètre carré de votre peau chaque seconde ?",n:65000000000,min:0,max:120000000000,u:"neutrinos",e:"65 milliards, jour et nuit, y compris à travers toute l’épaisseur de la Terre quand il fait sombre. Ils ne vous font rien : la matière leur est presque transparente."},
{t:'espace',q:"Combien de Terres tiendraient à l’intérieur de Jupiter ?",n:1321,min:0,max:8000,u:"Terres",e:"1 321. Jupiter est si massive que le centre autour duquel elle tourne avec le Soleil se trouve légèrement au-dessus de la surface de celui-ci."},
{t:'espace',q:"Combien pèserait un litre de Saturne ?",n:0.69,min:0,max:2,u:"kg",e:"0,69 kg : moins qu’un litre d’eau. Saturne est la seule planète du système solaire qui flotterait dans une baignoire assez grande — en y laissant un fameux cerne."},
{t:'espace',q:"Combien de temps dure une journée sur Vénus ?",n:243,min:0,max:400,u:"jours",e:"243 jours terrestres, soit plus longtemps que son année, qui n’en dure que 225. Sur Vénus, une journée dure plus longtemps qu’une année, et le Soleil s’y lève à l’ouest."},
{t:'espace',q:"De combien de minutes un jour martien est-il plus long qu’un jour terrestre ?",n:39.6,min:0,max:150,u:"minutes",e:"39 minutes et 35 secondes. Les équipes des rovers ont vécu sur ce rythme, décalant leur réveil chaque jour : au bout de deux semaines, ils déjeunaient à trois heures du matin."},
{t:'espace',q:"Combien de degrés sous zéro fait-il en moyenne à la surface de Mars ?",n:63,min:0,max:300,u:"°C sous zéro",e:"-63 °C de moyenne, avec des pointes à -140 aux pôles l’hiver. Mais l’air y est si ténu qu’un thermomètre au soleil peut afficher des valeurs positives au niveau du sol."},
{t:'espace',q:"Quelle hauteur atteint Olympus Mons, le plus haut volcan de Mars ?",n:22,min:0,max:50,u:"km",e:"22 km, presque trois fois l’Everest, pour une base large comme la France. Ses pentes sont si douces qu’un promeneur à son sommet ne verrait qu’une plaine sans fin."},
{t:'espace',q:"Combien de temps un signal radio met-il au maximum pour aller de Mars à la Terre ?",n:22,min:0,max:60,u:"minutes",e:"Jusqu’à 22 minutes dans un sens. Impossible de piloter un rover en direct : on lui envoie sa journée de travail le matin et on découvre le résultat le soir."},
{t:'espace',q:"À quelle vitesse soufflent les vents les plus rapides du système solaire, sur Neptune ?",n:2100,min:0,max:4000,u:"km/h",e:"2 100 km/h, six fois plus vite que les pires ouragans terrestres, sur une planète qui reçoit mille fois moins de lumière que nous. Personne ne sait bien ce qui les alimente."},
{t:'espace',q:"Quel est le diamètre de Pluton ?",n:2377,min:0,max:5000,u:"km",e:"2 377 km, soit moins que notre Lune, et à peu près la largeur des États-Unis. Sa lune Charon fait la moitié de sa taille : les deux tournent autour d’un point situé dans le vide."},
{t:'espace',q:"De combien de degrés l’axe d’Uranus est-il incliné ?",n:98,min:0,max:120,u:"degrés",e:"98 degrés : la planète roule sur le flanc, sans doute après une collision colossale. Ses pôles connaissent 42 ans de jour continu, puis 42 ans de nuit."},
{t:'espace',q:"Combien de jours de mission étaient prévus pour le rover martien Opportunity ?",n:90,min:0,max:500,u:"jours",e:"90 jours. Il a tenu quinze ans. Son dernier message, après une tempête de poussière, a été traduit par ses ingénieurs : « ma batterie est faible et il commence à faire noir »."},
{t:'espace',q:"Quelle distance le rover Opportunity a-t-il parcourue sur Mars ?",n:45,min:0,max:300,u:"km",e:"45 km en quinze ans, soit environ huit mètres par jour : un record de conduite extraterrestre battu à la vitesse d’un escargot très prudent et très bien piloté."},
{t:'espace',q:"Combien de temps a duré la descente périlleuse du rover Curiosity vers le sol martien ?",n:7,min:0,max:25,u:"minutes",e:"Sept minutes, surnommées « les sept minutes de terreur ». Le signal mettant quatorze minutes à arriver, le rover était posé — ou détruit — depuis longtemps quand la Terre l’a appris."},
{t:'espace',q:"Combien de vols l’hélicoptère martien Ingenuity devait-il effectuer au départ ?",n:5,min:0,max:8,u:"vols",e:"Cinq, en démonstration technologique. Il en a réussi 72 en trois ans avant de casser une pale : le premier engin à voler dans une atmosphère cent fois plus fine que la nôtre."},
{t:'espace',q:"Combien d’années la sonde Rosetta a-t-elle voyagé avant d’atteindre sa comète ?",n:10,min:0,max:12,u:"ans",e:"Dix ans et six milliards de kilomètres, avec trois passages près de la Terre et deux ans d’hibernation, pour rejoindre un caillou de 4 km filant à 100 000 km/h."},
{t:'espace',q:"Combien de temps la sonde Huygens a-t-elle émis depuis le sol de Titan ?",n:72,min:0,max:500,u:"minutes",e:"72 minutes après s’être posée sur une lune de Saturne, à 1,2 milliard de km. Elle n’était garantie que quelques minutes : ses batteries ont tenu bien au-delà."},
{t:'espace',q:"Combien d’années la sonde Cassini a-t-elle tourné autour de Saturne ?",n:13,min:0,max:100,u:"ans",e:"Treize ans, après sept ans de voyage. Elle a fini volontairement plongée dans l’atmosphère de la planète, pour éviter de contaminer un jour une de ses lunes habitables."},
{t:'espace',q:"De combien la sonde DART a-t-elle raccourci l’orbite de l’astéroïde qu’elle a percuté ?",n:32,min:0,max:60,u:"minutes",e:"32 minutes, alors que les ingénieurs espéraient au minimum 73 secondes. Premier test de déviation d’astéroïde de l’histoire : l’humanité sait désormais bousculer un caillou céleste."},
{t:'espace',q:"Quelle vitesse record la sonde Parker a-t-elle atteinte en frôlant le Soleil ?",n:692000,min:0,max:1000000,u:"km/h",e:"692 000 km/h, soit 190 km par seconde : l’objet le plus rapide jamais construit. À cette allure, un Paris-New York prendrait une demi-seconde."},
{t:'espace',q:"À quelle vitesse la sonde Voyager 1 s’éloigne-t-elle du Soleil ?",n:17,min:0,max:20,u:"km/s",e:"17 km par seconde, soit 61 000 km/h. Lancée en 1977, elle est le premier objet humain à avoir quitté la bulle du vent solaire pour l’espace interstellaire."},
{t:'espace',q:"Quelle est la puissance de l’émetteur radio de Voyager 1 ?",n:23,min:0,max:80,u:"watts",e:"23 watts, comme l’ampoule d’un réfrigérateur. Le signal qui nous parvient après des milliards de kilomètres est mille milliards de fois plus faible qu’une pile de montre."},
{t:'espace',q:"Combien de langues sont enregistrées sur le disque d’or emporté par les sondes Voyager ?",n:55,min:0,max:100,u:"langues",e:"55 salutations, de l’akkadien au mandarin, plus des chants de baleines et du Chuck Berry. Un message glissé dans une bouteille lancée pour un milliard d’années."},
{t:'espace',q:"Combien d’années la sonde New Horizons a-t-elle mis pour atteindre Pluton ?",n:9.5,min:0,max:80,u:"ans",e:"Neuf ans et demi, malgré le lancement le plus rapide jamais réalisé. Elle a franchi l’orbite de la Lune en neuf heures, là où Apollo mettait trois jours."},
{t:'espace',q:"Quel pourcentage de la masse de la Lune représente toute la ceinture d’astéroïdes ?",n:4,min:0,max:100,u:"%",e:"Environ 4 %. Le champ d’astéroïdes des films n’existe pas : les corps y sont si dispersés qu’une sonde traverse la ceinture sans jamais rien apercevoir."},
{t:'espace',q:"Quel diamètre fait le cratère laissé par l’astéroïde qui a éliminé les dinosaures ?",n:180,min:0,max:200,u:"km",e:"180 km, enfoui sous le Yucatán. L’objet ne mesurait que 10 km, mais il est arrivé à 20 km par seconde : l’impact a soulevé une vague de roche vaporisée."},
{t:'espace',q:"Combien d’arbres l’explosion de la Toungouska a-t-elle abattus en Sibérie ?",n:80000000,min:0,max:150000000,u:"arbres",e:"80 millions d’arbres couchés sur 2 000 km². L’objet, une vingtaine de mètres, a explosé en altitude sans laisser de cratère. Personne n’est allé voir avant dix-neuf ans."},
{t:'espace',q:"Combien pèse la plus grosse météorite jamais retrouvée sur Terre ?",n:60,min:0,max:100,u:"tonnes",e:"60 tonnes de fer, la météorite de Hoba en Namibie. Elle n’a laissé aucun cratère : elle a probablement ricoché dans l’atmosphère et s’est posée presque en douceur."},
{t:'espace',q:"Combien de personnes ont été blessées par le météore de Tcheliabinsk en Russie ?",n:1500,min:0,max:2000,u:"personnes",e:"Environ 1 500, presque toutes par des éclats de vitres soufflées. Le caillou de 20 mètres n’a jamais touché le sol : il a explosé à 30 km d’altitude, sans avoir été détecté."},
{t:'espace',q:"Quel âge a l’univers ?",n:13800000000,min:0,max:30000000000,u:"années",e:"13,8 milliards d’années, connu à quelques dizaines de millions près grâce au rayonnement fossile. La Terre, elle, n’a que 4,5 milliards d’années : elle a raté les deux premiers tiers."},
{t:'espace',q:"Combien de temps après le Big Bang l’univers est-il devenu transparent à la lumière ?",n:380000,min:0,max:2000000,u:"ans",e:"380 000 ans. Avant cela, le cosmos était un brouillard opaque. La lumière libérée ce jour-là baigne encore l’univers : c’est le rayonnement fossile que captent nos antennes."},
{t:'espace',q:"À quelle température le rayonnement fossile de l’univers baigne-t-il tout l’espace ?",n:2.7,min:0,max:4,u:"kelvins",e:"2,7 kelvins, soit -270 °C : à peine au-dessus du zéro absolu. Environ 1 % de la neige des vieux téléviseurs mal réglés venait directement de cet écho du Big Bang."},
{t:'espace',q:"Combien pèserait une cuillère à café de matière d’étoile à neutrons ?",n:1000000000,min:0,max:2000000000,u:"tonnes",e:"Un milliard de tonnes, l’équivalent d’une montagne dans une petite cuillère. Les protons et les électrons y ont été écrasés ensemble jusqu’à supprimer tout espace vide."},
{t:'espace',q:"Combien de tours sur elle-même par seconde effectue l’étoile la plus rapide connue ?",n:716,min:0,max:2500,u:"tours",e:"716 tours par seconde : un astre plus massif que le Soleil, large de 20 km, qui tourne plus vite qu’une lame de mixeur. Son équateur file à un quart de la vitesse de la lumière."},
{t:'espace',q:"À quelle distance se trouve Proxima du Centaure, l’étoile la plus proche du Soleil ?",n:4.24,min:0,max:12,u:"années-lumière",e:"4,24 années-lumière, soit 40 000 milliards de km. Si le Soleil était une orange à Paris, cette étoile serait une autre orange posée à New York."},
{t:'espace',q:"Combien de temps mettrait un avion de ligne pour rejoindre l’étoile la plus proche ?",n:5000000,min:0,max:8000000,u:"années",e:"Cinq millions d’années à 900 km/h. Nos ancêtres n’étaient pas encore debout au moment du décollage. C’est l’étoile voisine, la plus accessible de toutes."},
{t:'espace',q:"À quelle distance se trouve la galaxie d’Andromède ?",n:2500000,min:0,max:15000000,u:"années-lumière",e:"2,5 millions d’années-lumière, et pourtant on la voit à l’œil nu par nuit noire. La lumière qui vous atteint est partie quand nos ancêtres taillaient leurs premiers galets."},
{t:'espace',q:"Combien de jours le télescope Hubble a-t-il fixé un carré de ciel apparemment vide pour son champ profond ?",n:10,min:0,max:30,u:"jours",e:"Dix jours d’exposition sur une zone grande comme une tête d’épingle à bout de bras. Résultat : 3 000 galaxies dans ce qui semblait un morceau de vide absolu."},
{t:'espace',q:"De combien le miroir du télescope Hubble était-il mal poli lors de son lancement ?",n:2.2,min:0,max:5,u:"micromètres",e:"2,2 micromètres, un cinquantième de cheveu. Assez pour rendre les images floues et humilier la NASA jusqu’à une mission de réparation en orbite, trois ans plus tard."},
{t:'espace',q:"Combien de points de défaillance unique le déploiement du télescope James Webb comportait-il ?",n:344,min:0,max:600,u:"points",e:"344 mécanismes dont un seul raté aurait condamné le télescope, à 1,5 million de km de toute réparation possible. Le déploiement a duré un mois. Tout a fonctionné."},
{t:'espace',q:"À combien de degrés sous zéro le miroir du télescope James Webb est-il maintenu ?",n:233,min:0,max:250,u:"°C sous zéro",e:"-233 °C, obtenus grâce à un pare-soleil de la taille d’un court de tennis. Plus chaud, l’instrument s’éblouirait de sa propre chaleur infrarouge et ne verrait plus rien."},

/* ---------- Pop ---------- */
{t:'pop',q:"Combien d'exemplaires de l'album Thriller ont été vendus ?",n:70,min:0,max:500,u:"millions",e:"Environ 70 millions, record absolu. À sa sortie, il se vendait un million d'exemplaires par semaine."},
{t:'pop',q:"Combien de figurants ont participé à la scène des funérailles du film Gandhi ?",n:300000,min:0,max:800000,u:"figurants",e:"Environ 300 000 personnes, un record jamais battu. La scène a été tournée en une seule journée, à la date anniversaire des vraies funérailles."},
{t:'pop',q:"Quel était le budget du film d'horreur le plus rentable de l'histoire, Paranormal Activity ?",n:15000,min:0,max:20000,u:"dollars",e:"15 000 dollars, tourné dans la maison du réalisateur en une semaine. Il a rapporté près de 200 millions."},
{t:'pop',q:"Quel était le budget du film Titanic de James Cameron ?",n:200000000,min:0,max:1500000000,u:"dollars",e:"Environ 200 millions de dollars en 1997, plus cher que la construction du vrai paquebot, inflation comprise. La Fox était persuadée de courir au désastre : le film a rapporté plus de dix fois sa mise."},
{t:'pop',q:"Combien a coûté le tournage de Cléopâtre avec Elizabeth Taylor ?",n:31000000,min:0,max:150000000,u:"dollars",e:"Trente et un millions de dollars en 1963, record absolu de l’époque. Pour éponger la note, la Fox a vendu une partie de son terrain : il est devenu le quartier de Century City."},
{t:'pop',q:"Quel était le budget de Waterworld, le film le plus cher du monde en 1995 ?",n:175000000,min:0,max:600000000,u:"dollars",e:"175 millions de dollars. L’atoll flottant grandeur nature dérivait au gré des courants, a fini par couler, et Kevin Costner a bien failli se noyer pour de vrai pendant une tempête."},
{t:'pop',q:"Combien a coûté La Porte du paradis, le fiasco qui a coulé un studio ?",n:44000000,min:0,max:100000000,u:"dollars",e:"Quarante-quatre millions dépensés, trois millions et demi récoltés. Le désastre a englouti United Artists et mis fin au règne des réalisateurs tout-puissants du Nouvel Hollywood."},
{t:'pop',q:"Quel était le budget du premier Star Wars, en 1977 ?",n:11000000,min:0,max:20000000,u:"dollars",e:"Onze millions de dollars, et la Fox n’y croyait pas une seconde. Lucas a échangé une partie de son salaire contre les droits dérivés : la meilleure affaire de l’histoire du cinéma."},
{t:'pop',q:"Combien a finalement coûté Les Dents de la mer ?",n:9000000,min:0,max:15000000,u:"dollars",e:"Neuf millions au lieu des quatre prévus : le requin mécanique tombait sans arrêt en panne dans l’eau salée. Spielberg l’a caché, et la peur de l’invisible a fait le chef-d’œuvre."},
{t:'pop',q:"Quel était le budget d’E.T. l’extra-terrestre ?",n:10500000,min:0,max:30000000,u:"dollars",e:"Dix millions et demi. Spielberg a tourné dans l’ordre chronologique, luxe rarissime, pour que les enfants vivent réellement la séparation finale au moment de la jouer."},
{t:'pop',q:"Combien a coûté le premier Alien, de Ridley Scott ?",n:11000000,min:0,max:15000000,u:"dollars",e:"Onze millions de dollars. Pour la scène du monstre jaillissant du thorax, l’équipe n’avait pas prévenu les acteurs de la quantité d’abats et de sang prévue : leur terreur est authentique."},
{t:'pop',q:"Quel était le budget du premier Terminator, en 1984 ?",n:6400000,min:0,max:60000000,u:"dollars",e:"6,4 millions de dollars. Cameron avait vendu son scénario un dollar symbolique à la productrice Gale Anne Hurd, à la seule condition qu’on le laisse réaliser le film lui-même."},
{t:'pop',q:"Combien a coûté Terminator 2, premier film à franchir une barre symbolique ?",n:102000000,min:0,max:300000000,u:"dollars",e:"102 millions de dollars en 1991, premier film à dépasser les cent millions. Le T-1000 liquide n’occupe pourtant que quelques minutes d’images de synthèse dans tout le film."},
{t:'pop',q:"Quel était le budget du Halloween de John Carpenter, en 1978 ?",n:300000,min:0,max:800000,u:"dollars",e:"Environ 300 000 dollars. Le masque de Michael Myers est un masque de William Shatner en capitaine Kirk, acheté deux dollars dans une boutique de farces, puis repeint en blanc."},
{t:'pop',q:"Combien a coûté La Nuit des morts-vivants de George Romero ?",n:114000,min:0,max:200000,u:"dollars",e:"114 000 dollars, en noir et blanc, près de Pittsburgh. Le sang était du sirop de chocolat Bosco et les entrailles dévorées à l’écran venaient d’un boucher du coin."},
{t:'pop',q:"Quel était le budget de Clerks, de Kevin Smith ?",n:27575,min:0,max:40000,u:"dollars",e:"27 575 dollars, empruntés sur des cartes de crédit. Smith tournait la nuit dans la supérette où il travaillait le jour : d’où le rideau de fer baissé pendant tout le film."},
{t:'pop',q:"Avec quel budget Robert Rodriguez a-t-il tourné El Mariachi ?",n:7000,min:0,max:10000,u:"dollars",e:"Environ 7 000 dollars. Rodriguez a financé son film en se faisant cobaye pour un laboratoire pharmaceutique, et a écrit une partie du scénario entre deux prises de sang."},
{t:'pop',q:"Quel était le budget du premier Rocky ?",n:1000000,min:0,max:1200000,u:"dollars",e:"Environ un million de dollars. Stallone, fauché, a refusé de vendre son scénario 350 000 dollars tant qu’on ne le laissait pas jouer Rocky lui-même. Le film en a rapporté plus de deux cents."},
{t:'pop',q:"En combien de jours le premier Saw a-t-il été tourné ?",n:18,min:0,max:25,u:"jours",e:"Dix-huit jours, pour 1,2 million de dollars. Presque tout se passe dans une seule salle de bains carrelée. La saga a depuis dépassé le milliard de dollars de recettes."},
{t:'pop',q:"Quel était le budget de Get Out, de Jordan Peele ?",n:4500000,min:0,max:6000000,u:"dollars",e:"4,5 millions de dollars pour plus de 250 millions de recettes. Peele, jusque-là connu comme humoriste, a décroché l’Oscar du scénario : du jamais-vu pour un film d’horreur."},
{t:'pop',q:"Combien a coûté John Carter, l’un des plus gros gouffres financiers d’Hollywood ?",n:263700000,min:0,max:400000000,u:"dollars",e:"Environ 264 millions de dollars. Disney a officiellement annoncé 200 millions de pertes sur ce seul film, et le patron du studio a quitté son poste dans la foulée."},
{t:'pop',q:"Quel est le budget du film le plus cher jamais homologué, Pirates des Caraïbes : La Fontaine de Jouvence ?",n:379000000,min:0,max:600000000,u:"dollars",e:"379 millions de dollars, record inscrit au Guinness. Le seul cachet de Johnny Depp dépasse le budget total de la plupart des films oscarisés de la décennie."},
{t:'pop',q:"Combien a coûté Apocalypse Now à Francis Ford Coppola ?",n:31500000,min:0,max:100000000,u:"dollars",e:"31,5 millions, dont une partie de sa poche : il a hypothéqué sa maison. Un typhon a rasé les décors, et Brando est arrivé obèse, sans avoir lu le livre à adapter."},
{t:'pop',q:"Quel était le budget de Blanche-Neige et les Sept Nains, en 1937 ?",n:1490000,min:0,max:3000000,u:"dollars",e:"Environ 1,49 million de dollars, quatre fois le budget prévu. Tout Hollywood pariait sur la faillite de Disney ; le film est devenu le plus gros succès de son époque."},
{t:'pop',q:"Combien a coûté James Bond 007 contre Dr No, le tout premier Bond ?",n:1100000,min:0,max:1200000,u:"dollars",e:"1,1 million de dollars. Sean Connery, ancien livreur de lait et culturiste amateur, a été payé 6 000 livres pour endosser le smoking et lancer la plus longue saga du cinéma."},
{t:'pop',q:"Combien Elizabeth Taylor a-t-elle touché pour jouer Cléopâtre ?",n:1000000,min:0,max:1200000,u:"dollars",e:"Un million de dollars : premier cachet à sept chiffres de l’histoire du cinéma. Avec les retards de tournage et ses pourcentages, elle aurait finalement empoché près de sept millions."},
{t:'pop',q:"Pendant combien d’années Richard Linklater a-t-il tourné Boyhood ?",n:12,min:0,max:80,u:"ans",e:"Douze ans, quelques jours chaque été, avec les mêmes acteurs qui vieillissaient pour de vrai. Un contrat d’acteur ne pouvant dépasser sept ans en Californie, tout reposait sur une poignée de main."},
{t:'pop',q:"Combien touchait chaque acteur de Friends par épisode lors des dernières saisons ?",n:1000000,min:0,max:6000000,u:"dollars",e:"Un million de dollars chacun, par épisode. Les six comédiens négociaient en bloc pour que personne ne soit payé moins que les autres : une stratégie devenue légendaire à Hollywood."},
{t:'pop',q:"Combien de jours de tournage a-t-il fallu pour Les Dents de la mer ?",n:159,min:0,max:1000,u:"jours",e:"Cinquante-cinq jours étaient prévus, il en a fallu 159. Tourner en pleine mer avec un requin hydraulique capricieux a bien failli coûter sa carrière à Spielberg, alors âgé de vingt-sept ans."},
{t:'pop',q:"Combien de jours a duré le tournage d’Eyes Wide Shut, record homologué ?",n:400,min:0,max:2000,u:"jours",e:"Quatre cents jours, le plus long tournage continu jamais homologué par le Guinness. Kubrick refaisait les scènes des dizaines de fois ; deux acteurs ont abandonné et ont dû être remplacés."},
{t:'pop',q:"Combien de jours de tournage a nécessité Metropolis, de Fritz Lang ?",n:310,min:0,max:600,u:"jours",e:"310 jours et 60 nuits, un budget qui a failli ruiner le studio UFA. Les figurants ont passé des journées entières dans l’eau glacée pour la scène de l’inondation."},
{t:'pop',q:"Combien de figurants ont été engagés sur le tournage de Metropolis ?",n:36000,min:0,max:50000,u:"figurants",e:"Environ 36 000 figurants, dont 750 enfants. Pour la seule scène de la tour de Babel, 1 100 hommes ont accepté de se faire raser le crâne, contre un cachet dérisoire."},
{t:'pop',q:"En combien de jours le premier Rocky a-t-il été tourné ?",n:28,min:0,max:250,u:"jours",e:"Vingt-huit jours. Faute d’autorisations et d’argent, plusieurs scènes de course dans Philadelphie sont volées caméra à l’épaule, sans que les passants soient prévenus de rien."},
{t:'pop',q:"En combien de jours Whiplash a-t-il été tourné ?",n:19,min:0,max:30,u:"jours",e:"Dix-neuf jours seulement. Miles Teller, batteur depuis l’enfance, a joué lui-même ses parties et terminé le tournage avec les mains couvertes d’ampoules. J.K. Simmons y a gagné un Oscar."},
{t:'pop',q:"En combien de jours Le Projet Blair Witch a-t-il été tourné ?",n:8,min:0,max:40,u:"jours",e:"Huit jours. Les trois acteurs, lâchés seuls en forêt, recevaient leurs consignes dans des boîtes cachées et ignoraient totalement ce que l’équipe leur réservait pendant la nuit."},
{t:'pop',q:"Combien de jours a duré le tournage principal de la trilogie du Seigneur des anneaux ?",n:438,min:0,max:2000,u:"jours",e:"Environ 438 jours, les trois films tournés d’un seul bloc en Nouvelle-Zélande. Jusqu’à sept équipes filmaient parfois le même jour sur des sites différents du pays."},
{t:'pop',q:"Combien de nuits de tournage a demandé la bataille de Winterfell, dans Game of Thrones ?",n:55,min:0,max:80,u:"nuits",e:"Cinquante-cinq nuits dans le froid et la boue, pour un seul épisode. L’équipe a reçu un badge de « survivant » ; la bataille dure 82 minutes à l’écran."},
{t:'pop',q:"Combien de mois le tournage de Seul au monde a-t-il été interrompu ?",n:12,min:0,max:15,u:"mois",e:"Un an de pause pour laisser Tom Hanks perdre vingt-cinq kilos et laisser pousser sa barbe. Pendant ce temps, Zemeckis a tourné un autre long-métrage entier avec la même équipe."},
{t:'pop',q:"Combien de kilos Robert De Niro a-t-il pris pour la fin de Raging Bull ?",n:27,min:0,max:40,u:"kg",e:"Vingt-sept kilos, gagnés en quelques mois en s’empiffrant à travers la France et l’Italie. Scorsese a arrêté le tournage le temps de la métamorphose ; De Niro a eu l’Oscar."},
{t:'pop',q:"Combien de kilos Christian Bale a-t-il perdus pour The Machinist ?",n:28,min:0,max:30,u:"kg",e:"Vingt-huit kilos : pommes, thon en boîte, café et cigarettes. Il voulait descendre encore, la production a refusé. Six mois plus tard, il tournait Batman Begins musclé."},
{t:'pop',q:"Combien d’heures de maquillage Jim Carrey subissait-il chaque jour pour Le Grinch ?",n:8.5,min:0,max:40,u:"heures",e:"Huit heures et demie au début, réduites ensuite. Au bord de la crise de nerfs sous le costume en poils de yak, Carrey a pris des cours auprès d’un spécialiste de la résistance à la torture."},
{t:'pop',q:"Combien de prises Kubrick a-t-il exigées pour la scène de la batte, dans Shining ?",n:127,min:0,max:1000,u:"prises",e:"127 prises pour une seule scène dialoguée, record homologué. Shelley Duvall en a perdu ses cheveux par poignées, et Kubrick recommençait sans jamais expliquer pourquoi."},
{t:'pop',q:"Combien de jours a demandé le tournage de la scène de la douche, dans Psychose ?",n:7,min:0,max:60,u:"jours",e:"Sept jours de tournage pour quarante-cinq secondes à l’écran, découpées en dizaines de plans. Le couteau ne touche jamais la peau, et le sang est du sirop de chocolat Bosco."},
{t:'pop',q:"Combien de candidates ont été auditionnées pour le rôle de Scarlett dans Autant en emporte le vent ?",n:1400,min:0,max:2000,u:"candidates",e:"Environ 1 400 actrices vues en deux ans de casting national. C’est finalement une Anglaise, Vivien Leigh, qui a décroché le rôle, alors que le tournage avait déjà commencé."},
{t:'pop',q:"Combien de réalisateurs se sont succédé sur Le Magicien d’Oz ?",n:5,min:0,max:6,u:"réalisateurs",e:"Cinq, dont George Cukor resté quelques jours à peine. Victor Fleming, le seul crédité, a lui-même quitté le plateau en cours de route pour aller sauver Autant en emporte le vent."},
{t:'pop',q:"Combien d’acteurs de petite taille jouaient les Munchkins dans Le Magicien d’Oz ?",n:124,min:0,max:200,u:"acteurs",e:"Cent vingt-quatre, recrutés dans toute l’Amérique et parfois en Europe. Leurs voix ont été accélérées en post-production, et leurs frasques à l’hôtel sont devenues une légende hollywoodienne."},
{t:'pop',q:"En combien de semaines le jeu Atari E.T. a-t-il été programmé ?",n:5,min:0,max:12,u:"semaines",e:"Cinq semaines et demie, Noël approchait. Le résultat, jugé injouable, a été enterré par milliers dans le désert du Nouveau-Mexique — des cartouches exhumées trente ans plus tard."},
{t:'pop',q:"Combien d’années a duré le développement de Duke Nukem Forever ?",n:15,min:0,max:20,u:"ans",e:"Quinze ans, trois moteurs graphiques successifs, un studio coulé en route. Annoncé comme révolutionnaire, le jeu est sorti en 2011 et s’est fait démolir par la critique entière."},
{t:'pop',q:"En combien de jours est fabriqué un épisode de South Park ?",n:6,min:0,max:40,u:"jours",e:"Six jours entre le premier storyboard et la diffusion. Cette cadence permet à la série de réagir à l’actualité de la semaine, quitte à livrer l’épisode quelques heures avant l’antenne."},
{t:'pop',q:"Combien d’heures machine a demandé le calcul des images du premier Toy Story ?",n:800000,min:0,max:6000000,u:"heures",e:"Environ 800 000 heures machine pour 81 minutes de film, réparties sur une ferme de plus de cent ordinateurs. Certaines images ont demandé jusqu’à trente heures de calcul, chacune."},
{t:'pop',q:"Quelle proportion de Toy Story 2 a été effacée par erreur pendant la production ?",n:90,min:0,max:100,u:"%",e:"Une commande mal tapée a supprimé 90 % du film sur les serveurs, et les sauvegardes ne fonctionnaient pas. Le film a été retrouvé sur l’ordinateur personnel d’une employée en congé maternité."},
{t:'pop',q:"Combien de poils compte Sulley, le monstre bleu de Monstres et Cie ?",n:2320413,min:0,max:4000000,u:"poils",e:"2 320 413 poils animés individuellement. Chaque image demandait des heures de calcul rien que pour faire onduler sa fourrure de façon crédible : Pixar a dû écrire un logiciel exprès."},
{t:'pop',q:"Combien de taches ont été comptées dans le dessin animé Les 101 Dalmatiens ?",n:6469952,min:0,max:12000000,u:"taches",e:"6 469 952 taches sur l’ensemble du film. Pour éviter de les redessiner une par une, Disney a adopté la xérographie : c’est de là que vient le trait crayonné si reconnaissable."},
{t:'pop',q:"Combien de ballons ont été animés dans le plan du décollage de la maison, dans Là-haut ?",n:10297,min:0,max:60000,u:"ballons",e:"10 297 ballons, comptés un par un par les animateurs. Ils avaient calculé qu’il en aurait fallu plusieurs millions pour soulever vraiment la maison : la poésie a gagné contre la physique."},
{t:'pop',q:"Combien de boucles de cheveux distinctes ont été créées pour Merida, l’héroïne de Rebelle ?",n:1500,min:0,max:8000,u:"boucles",e:"Mille cinq cents boucles animées individuellement, grâce à un logiciel écrit spécialement pour elle. La chevelure de Merida a demandé près de trois ans de recherche à Pixar."},
{t:'pop',q:"Combien de dessins ont été retenus dans le montage final de Blanche-Neige et les Sept Nains ?",n:250000,min:0,max:300000,u:"dessins",e:"Environ 250 000 dessins conservés, sur plus de deux millions réalisés. Le studio employait des centaines d’artistes, et le projet était surnommé « la folie de Disney » dans tout Hollywood."},
{t:'pop',q:"Combien d’années a demandé l’animation de la ruée des gnous, dans Le Roi Lion ?",n:3,min:0,max:15,u:"ans",e:"Environ trois ans pour deux minutes et demie à l’écran. Un logiciel a été écrit uniquement pour multiplier des milliers de bêtes lancées au galop, sans les dessiner une à une."},
{t:'pop',q:"Combien de celluloïds peints à la main compte le film d’animation Akira ?",n:160000,min:0,max:200000,u:"celluloïds",e:"Environ 160 000 celluloïds, un record pour l’animation japonaise. Les voix ont été enregistrées avant l’animation, à l’inverse de l’usage : c’est pourquoi les bouches collent si bien aux dialogues."},
{t:'pop',q:"Combien d’appareils photo ont été alignés pour créer le « bullet time » de Matrix ?",n:120,min:0,max:150,u:"appareils",e:"Cent vingt appareils photo disposés en arc autour de l’acteur, déclenchés en cascade au millième de seconde. La technique a été copiée dans les publicités du monde entier pendant dix ans."},
{t:'pop',q:"Combien de mois d’entraînement aux arts martiaux les acteurs de Matrix ont-ils suivis avant le tournage ?",n:4,min:0,max:6,u:"mois",e:"Quatre mois à temps plein avant le premier jour de tournage. Keanu Reeves s’entraînait en minerve, à peine opéré du cou : il ne pouvait pas encore donner de coups de pied."},
{t:'pop',q:"Combien de pièces d’armure Weta Workshop a-t-il fabriquées pour Le Seigneur des anneaux ?",n:48000,min:0,max:150000,u:"pièces",e:"Environ 48 000 pièces d’armure, plus des milliers d’épées et de flèches. Les artisans chargés des cottes de mailles ont fini le tournage avec des tendinites et des attelles aux mains."},
{t:'pop',q:"Combien de paires de faux pieds de hobbit ont été utilisées sur Le Seigneur des anneaux ?",n:1600,min:0,max:8000,u:"paires",e:"Environ 1 600 paires de pieds en latex, détruites après chaque journée de tournage. Il fallait plus d’une heure pour les coller sur chaque acteur, tous les matins, avant même le maquillage."},
{t:'pop',q:"Combien d’hectares de maïs Christopher Nolan a-t-il fait planter pour Interstellar ?",n:200,min:0,max:600,u:"hectares",e:"Environ deux cents hectares plantés pour de vrai, plutôt que d’ajouter les champs en images de synthèse. La récolte a ensuite été revendue, et la production y a même gagné de l’argent."},
{t:'pop',q:"Combien de litres de faux sang ont été utilisés pour le massacre de la Maison des feuilles bleues, dans Kill Bill ?",n:1700,min:0,max:8000,u:"litres",e:"Environ 1 700 litres, pour huit semaines de tournage sur cette seule séquence. Aux États-Unis, elle passe brusquement en noir et blanc afin d’éviter une interdiction aux mineurs."},
{t:'pop',q:"Combien de litres de faux sang ont jailli de l’ascenseur de Shining ?",n:1100,min:0,max:1200,u:"litres",e:"Environ 1 100 litres. Kubrick a refait le plan pendant des jours : à chaque essai, il fallait tout nettoyer, sécher le décor et repeindre les murs avant de recommencer."},
{t:'pop',q:"Combien de litres de faux sang la scène finale de Braindead a-t-elle consommés ?",n:300,min:0,max:600,u:"litres",e:"Environ 300 litres pour la seule séquence de la tondeuse à gazon. Peter Jackson signait là le film le plus sanglant jamais tourné, dix ans avant Le Seigneur des anneaux."},
{t:'pop',q:"Combien de serpents ont été rassemblés pour la fosse des Aventuriers de l’arche perdue ?",n:7000,min:0,max:15000,u:"serpents",e:"Environ 7 000. Spielberg en voulait dix mille : les manipulateurs ont vidé les animaleries et les élevages d’Europe. La vitre censée protéger Harrison Ford se voit dans certains plans."},
{t:'pop',q:"Quelle taille faisait la maquette de King Kong dans le film de 1933 ?",n:46,min:0,max:120,u:"cm",e:"Environ 46 centimètres de caoutchouc, d’aluminium et de fourrure de lapin, animés image par image. Sa fourrure semble frémir toute seule à l’écran : ce sont les doigts des animateurs."},
{t:'pop',q:"Combien pesait le costume de Godzilla dans le film japonais de 1954 ?",n:100,min:0,max:800,u:"kg",e:"Environ cent kilos de caoutchouc bourré de mousse. L’acteur enfermé dedans perdait plusieurs kilos par jour de tournage, et l’équipe vidait la sueur du costume à la tasse."},
{t:'pop',q:"Combien de plongées James Cameron a-t-il faites sur l’épave du Titanic pour préparer son film ?",n:12,min:0,max:80,u:"plongées",e:"Douze descentes à près de 3 800 mètres de fond, en submersible russe. Cameron a passé plus de temps près de l’épave que les passagers n’en ont passé à bord en 1912."},
{t:'pop',q:"Combien d’heures de rushes ont dû être montées pour Mad Max : Fury Road ?",n:480,min:0,max:600,u:"heures",e:"Environ 480 heures de rushes, soit vingt jours de projection non-stop. La monteuse Margaret Sixel, épouse du réalisateur, y a gagné l’Oscar du meilleur montage."},
{t:'pop',q:"Combien de minutes dure Autant en emporte le vent ?",n:238,min:0,max:250,u:"minutes",e:"Trois heures cinquante-huit, entracte inclus. Corrigé de l’inflation, ce film de 1939 reste le plus gros succès commercial de toute l’histoire du cinéma, loin devant les blockbusters modernes."},
{t:'pop',q:"Combien de minutes dure le Titanic de James Cameron ?",n:194,min:0,max:500,u:"minutes",e:"Trois heures quatorze. Les exploitants râlaient : une séance de moins par jour et par salle. Le film a pulvérisé tous les records malgré une durée jugée suicidaire par Hollywood."},
{t:'pop',q:"Combien de minutes dure la version longue du Retour du roi ?",n:263,min:0,max:500,u:"minutes",e:"Quatre heures vingt-trois, soit cinquante minutes de plus qu’en salle. Enchaîner les trois versions longues demande plus de onze heures de marche vers la Montagne du Destin."},
{t:'pop',q:"Combien de minutes dure Avengers : Endgame ?",n:181,min:0,max:400,u:"minutes",e:"Trois heures et une minute. Les réalisateurs ont conseillé au public de ne pas boire avant la séance, et des applications sont nées pour indiquer les meilleurs moments d’aller aux toilettes."},
{t:'pop',q:"Combien de minutes dure Empire, le film d’Andy Warhol ?",n:485,min:0,max:600,u:"minutes",e:"Huit heures et cinq minutes d’un plan fixe sur l’Empire State Building, projeté au ralenti. Rien ne bouge, sinon la lumière du jour qui tombe et les fenêtres qui s’allument."},
{t:'pop',q:"Combien d’heures dure Logistics, le film le plus long jamais réalisé ?",n:857,min:0,max:1500,u:"heures",e:"857 heures, soit trente-cinq jours sans interruption. Deux artistes suédois ont remonté à l’envers tout le trajet d’un podomètre, du magasin suédois jusqu’à l’usine chinoise qui l’a fabriqué."},
{t:'pop',q:"Combien d’Oscars le Ben-Hur de 1959 a-t-il remportés ?",n:11,min:0,max:12,u:"oscars",e:"Onze statuettes, record depuis égalé par Titanic et Le Retour du roi. La course de chars a demandé des mois de tournage et un cirque romain reconstruit grandeur nature en Italie."},
{t:'pop',q:"Combien pèse une statuette des Oscars ?",n:3.85,min:0,max:6,u:"kg",e:"3,85 kilos de métal plaqué or, pour trente-quatre centimètres. Pendant la Seconde Guerre mondiale, faute de métal disponible, les lauréats ont reçu des statuettes en plâtre peint."},
{t:'pop',q:"Quelle est la hauteur des lettres du panneau Hollywood ?",n:14,min:0,max:20,u:"m",e:"Environ quatorze mètres par lettre. À l’origine, l’enseigne disait « HOLLYWOODLAND » et vantait un simple programme immobilier : elle ne devait rester en place que dix-huit mois."},
{t:'pop',q:"Combien d’Américains ont regardé le dernier épisode de M*A*S*H ?",n:105900000,min:0,max:150000000,u:"spectateurs",e:"Près de 106 millions en 1983, record jamais battu pour une fiction. Les réseaux d’égouts de New York ont enregistré un pic de débit historique dès la fin de la diffusion."},
{t:'pop',q:"Combien d’épisodes compte la série Friends ?",n:236,min:0,max:500,u:"épisodes",e:"236 épisodes en dix saisons. Tout tient dans un café et deux appartements new-yorkais dont le loyer réel serait aujourd’hui hors de portée pour un serveur ou un cuisinier."},
{t:'pop',q:"Combien d’épisodes compte le western télévisé Gunsmoke ?",n:635,min:0,max:2500,u:"épisodes",e:"635 épisodes en vingt ans d’antenne. À raison d’un épisode par jour, il faudrait presque deux années entières pour arriver au bout de la série."},
{t:'pop',q:"Combien coûtait un épisode de la dernière saison de Game of Thrones ?",n:15000000,min:0,max:20000000,u:"dollars",e:"Environ quinze millions de dollars par épisode, soit le budget d’un long-métrage indépendant entier pour moins d’une heure de série. Les nuits de bataille expliquent une bonne part de la facture."},
{t:'pop',q:"Combien de joueurs participent au jeu mortel dans la première saison de Squid Game ?",n:456,min:0,max:3000,u:"joueurs",e:"456 joueurs au départ. Le chiffre correspond exactement à la cagnotte : 45,6 milliards de wons, soit cent millions de wons ajoutés à chaque mort."},
{t:'pop',q:"Quelle est la somme des six nombres maudits de la série Lost ?",n:108,min:0,max:300,u:"points",e:"4, 8, 15, 16, 23 et 42 donnent 108 — et c’est précisément toutes les 108 minutes qu’il fallait retaper la séquence dans le bunker pour éviter la catastrophe."},
{t:'pop',q:"À quel niveau Pac-Man devient-il injouable à cause d’un bug ?",n:256,min:0,max:300,u:"niveaux",e:"Au 256e tableau, un débordement de mémoire coupe l’écran en deux et remplit la moitié droite de symboles. Les programmeurs n’avaient jamais imaginé qu’un humain irait aussi loin."},
{t:'pop',q:"Quel est le poids total du jeu Super Mario Bros. sur NES ?",n:40,min:0,max:50,u:"ko",e:"Quarante kilo-octets pour tout le jeu : niveaux, musiques, graphismes et code. Une seule photo prise avec un téléphone d’aujourd’hui pèse une centaine de fois plus lourd."},
{t:'pop',q:"Combien d’étoiles peut-on collecter dans Super Mario 64 ?",n:120,min:0,max:300,u:"étoiles",e:"Cent vingt, alors que soixante-dix suffisent pour affronter Bowser. Le jeu a inventé la caméra à la troisième personne, officiellement tenue par un Lakitu cameraman qui vous suit en nuage."},
{t:'pop',q:"Combien de graines de Korogu sont cachées dans Zelda : Breath of the Wild ?",n:900,min:0,max:1200,u:"graines",e:"Neuf cents graines dispersées sur la carte. La récompense pour les avoir toutes trouvées est une crotte dorée, plaisanterie assumée des développeurs à l’intention des joueurs complétistes."},
{t:'pop',q:"Combien de Pokémon comptait la toute première génération ?",n:151,min:0,max:250,u:"pokémon",e:"Cent cinquante et un, dont Mew, glissé en douce dans la mémoire libérée après le débogage par un programmeur, à l’insu de sa hiérarchie. Il devait rester introuvable à jamais."},
{t:'pop',q:"Combien de répliques ont été enregistrées pour le jeu Skyrim ?",n:60000,min:0,max:80000,u:"répliques",e:"Plus de soixante mille lignes de dialogue. Une poignée de comédiens double des centaines de personnages : c’est pourquoi tous les gardes semblent avoir exactement la même voix."},
{t:'pop',q:"Combien de répliques de dialogue contient Red Dead Redemption 2 ?",n:500000,min:0,max:600000,u:"répliques",e:"Environ cinq cent mille, pour sept ans de développement. Le souci du détail va jusqu’aux chevaux dont l’anatomie réagit au froid : un caprice de programmation devenu célèbre."},
{t:'pop',q:"Combien a coûté le développement de Grand Theft Auto V ?",n:265000000,min:0,max:800000000,u:"dollars",e:"Environ 265 millions de dollars, marketing compris : plus cher que la plupart des blockbusters hollywoodiens. Le jeu a remboursé la totalité en vingt-quatre heures de mise en vente."},
{t:'pop',q:"Combien de temps dure un cycle jour-nuit complet dans Minecraft ?",n:20,min:0,max:25,u:"minutes",e:"Vingt minutes réelles, dont sept de nuit noire. C’est ce rythme serré qui transforme chaque coucher de soleil en course contre la montre pour bâtir un abri avant les monstres."},
{t:'pop',q:"À combien de blocs du centre se trouve la bordure du monde dans Minecraft ?",n:60000000,min:0,max:100000000,u:"blocs",e:"Soixante millions de blocs dans chaque direction. Marcher jusqu’à la bordure demanderait plus de cinq mois de marche continue, sans jamais s’arrêter ni dormir une seule nuit."},
{t:'pop',q:"Combien de touches faut-il taper pour entrer le fameux code Konami ?",n:10,min:0,max:12,u:"touches",e:"Dix entrées : haut, haut, bas, bas, gauche, droite, gauche, droite, B, A. Ajouté par un programmeur qui trouvait son propre jeu trop dur, il a été oublié dans la version finale."},
{t:'pop',q:"Combien de jeux Rovio avait-il sortis avant de créer Angry Birds ?",n:51,min:0,max:200,u:"jeux",e:"Cinquante et un jeux sans succès, et un studio au bord de la faillite avec une poignée d’employés restants. Le cinquante-deuxième a été téléchargé des milliards de fois."},
{t:'pop',q:"Combien Flappy Bird rapportait-il par jour à son créateur au sommet de son succès ?",n:50000,min:0,max:60000,u:"dollars",e:"Cinquante mille dollars de publicité quotidienne, de l’aveu même de Dong Nguyen. Écrasé par la pression et la culpabilité, il a retiré le jeu des boutiques en pleine gloire."},
{t:'pop',q:"Combien d’exemplaires du Virtual Boy Nintendo a-t-il vendus avant de l’abandonner ?",n:770000,min:0,max:1500000,u:"consoles",e:"Environ 770 000, puis l’arrêt en moins d’un an. L’écran rouge monochrome donnait des maux de tête ; Nintendo évite soigneusement de mentionner cette console dans son histoire officielle."},
{t:'pop',q:"Combien de temps a duré la plus grande bataille spatiale d’EVE Online, à B-R5RB ?",n:21,min:0,max:30,u:"heures",e:"Vingt et une heures de combat ininterrompu, plusieurs milliers de joueurs connectés. Les vaisseaux détruits représentaient environ 300 000 dollars réels — et tout est parti d’un loyer virtuel impayé."},
{t:'pop',q:"Combien de temps dure le trajet dans le jeu Desert Bus, sans pouvoir mettre en pause ?",n:8,min:0,max:10,u:"heures",e:"Huit heures de conduite en temps réel entre Tucson et Las Vegas, en ligne parfaitement droite. Le bus dévie légèrement vers la droite : impossible de lâcher le volant une seconde."},
{t:'pop',q:"Combien d’épisodes compte la série originale Star Trek, annulée pour audiences insuffisantes ?",n:79,min:0,max:250,u:"épisodes",e:"Soixante-dix-neuf épisodes seulement, avant l’annulation pure et simple. Ce sont les rediffusions, des années plus tard, qui ont transformé cet échec commercial en phénomène planétaire."},

/* ---------- Terrain ---------- */
{t:'sport',q:"Combien de rounds a duré le plus long combat de boxe officiel ?",n:110,min:0,max:150,u:"rounds",e:"110 rounds en 1893, plus de sept heures. Les deux boxeurs étaient trop épuisés pour continuer : le match a été déclaré nul et personne n'a touché la bourse."},
{t:'sport',q:"À quel âge le plus vieux médaillé olympique a-t-il décroché sa médaille ?",n:72,min:0,max:150,u:"ans",e:"72 ans, pour le tireur suédois Oscar Swahn en 1920. Il s'était déjà qualifié pour les Jeux suivants, à 76 ans, mais la maladie l'en a empêché."},
{t:'sport',q:"Combien de temps a duré le plus long échange de tennis de table, pour un seul point ?",n:132,min:0,max:150,u:"minutes",e:"2 h 12 pour un unique point, en 1936. Les deux joueurs se contentaient de renvoyer sans jamais attaquer. La règle du temps limite est née de ce match."},
{t:'sport',q:"En combien de temps Abebe Bikila a-t-il gagné le marathon de Rome, pieds nus ?",n:135,min:0,max:500,u:"minutes",e:"2 h 15 et un record du monde, sans chaussures. Les siennes le blessaient : il a préféré courir comme il s'entraînait, sur les pavés de la voie Appienne."},
{t:'sport',q:"Combien de temps a duré le plus long match de tennis de l’histoire, Isner-Mahut à Wimbledon ?",n:665,min:0,max:2500,u:"minutes",e:"11 heures 5 minutes étalées sur trois jours. Le tableau d’affichage électronique a rendu l’âme en cours de route : il n’avait pas été programmé pour aller au-delà de 47 jeux."},
{t:'sport',q:"Combien de jeux a duré le cinquième set du match Isner-Mahut ?",n:138,min:0,max:300,u:"jeux",e:"70-68. À lui seul, ce set a duré plus de huit heures, soit plus longtemps que la quasi-totalité des matchs de tennis jamais joués, finales de Grand Chelem comprises."},
{t:'sport',q:"Combien d’aces John Isner a-t-il servis pendant ce marathon de Wimbledon ?",n:113,min:0,max:1200,u:"aces",e:"113 aces en un seul match, quand un très bon serveur en réussit vingt sur une rencontre. Mahut en a mis 103 : à eux deux, 216 balles que personne n’a touchées."},
{t:'sport',q:"Combien de frappes a compté le plus long échange de l’histoire du tennis, en 1984 ?",n:643,min:0,max:1000,u:"frappes",e:"Vicki Nelson contre Jean Hepner, à Richmond : 643 frappes pour un seul point, soit 29 minutes d’échange. Les deux joueuses renvoyaient en cloche, attendant que l’autre craque la première."},
{t:'sport',q:"Combien de temps a duré le match de tennis le plus court jamais disputé en compétition ?",n:18,min:0,max:100,u:"minutes",e:"En 1946, l’Australien Jack Harper expédie son adversaire 6-0 6-0 en 18 minutes. Il n’a concédé que 17 points sur l’ensemble de la rencontre."},
{t:'sport',q:"À quelle hauteur exacte le gazon des courts de Wimbledon est-il tondu pendant le tournoi ?",n:8,min:0,max:20,u:"millimètres",e:"8 millimètres, ni plus ni moins, mesurés quotidiennement. En dessous, la balle rebondirait trop bas ; au-dessus, elle ralentirait. Le ray-grass est semé chaque automne et roulé tout l’hiver."},
{t:'sport',q:"Quelle épaisseur fait la couche de brique pilée rouge sur les courts de Roland-Garros ?",n:2,min:0,max:2.5,u:"millimètres",e:"Deux malheureux millimètres de poudre de brique posés sur 80 centimètres de calcaire, mâchefer et cailloux. La terre battue mythique n’est qu’un maquillage : tout le travail se joue dessous."},
{t:'sport',q:"Combien pèse une balle de tennis de table de compétition ?",n:2.7,min:0,max:4,u:"grammes",e:"2,7 grammes, soit le poids d’une pièce de monnaie. Ce grain de celluloïd de 40 mm peut pourtant filer à plus de 100 km/h et tourner sur lui-même des dizaines de fois par seconde."},
{t:'sport',q:"Combien de plumes compte un volant de badminton de compétition ?",n:16,min:0,max:40,u:"plumes",e:"Exactement 16 plumes, toutes prélevées sur la même aile — la gauche — de l’oie, pour que la courbure soit identique. Mélanger les ailes fait vriller le volant de travers."},
{t:'sport',q:"Combien de matchs consécutifs Jahangir Khan a-t-il gagnés au squash sans jamais perdre ?",n:555,min:0,max:1000,u:"matchs",e:"555 victoires d’affilée entre 1981 et 1986, cinq ans et demi sans connaître la défaite. Aucun sportif professionnel n’a jamais aligné une telle série, tous sports confondus."},
{t:'sport',q:"Quel diamètre fait un trou de golf, sur tous les greens du monde ?",n:108,min:0,max:1000,u:"millimètres",e:"108 mm, soit 4,25 pouces, figés depuis 1891. La mesure vient d’un tuyau de drainage que les greenkeepers de Musselburgh avaient sous la main pour renforcer les bords du trou."},
{t:'sport',q:"De quelle distance a été réussi le plus long trou en un jamais homologué ?",n:409,min:0,max:4000,u:"mètres",e:"447 yards, réussis par Robert Mitera en 1965 à Omaha. Un vent violent dans le dos, un green en contrebas et une balle qui roule : un par 4 avalé d’un seul coup."},
{t:'sport',q:"Quelle distance a parcouru le plus long drive jamais frappé en compétition officielle ?",n:471,min:0,max:800,u:"mètres",e:"515 yards par Mike Austin en 1974, à 64 ans, avec un driver à manche en acier et tête en persimmon. La balle a dépassé le green de 60 mètres."},
{t:'sport',q:"Combien de bunkers piègent les joueurs sur le Old Course de St Andrews ?",n:112,min:0,max:400,u:"bunkers",e:"112 sur 18 trous, dont certains si profonds qu’il faut jouer à reculons pour en sortir. Le plus redouté, Hell Bunker, mesure trois mètres de profondeur et avale des cartes entières."},
{t:'sport',q:"Combien de tournois consécutifs Byron Nelson a-t-il remportés lors de sa saison 1945 ?",n:11,min:0,max:15,u:"tournois",e:"Onze victoires d’affilée, plus dix-huit sur l’année. Aucun golfeur ne s’en est approché depuis : Tiger Woods a plafonné à sept. Nelson a pris sa retraite l’année suivante, à 34 ans."},
{t:'sport',q:"À quelle hauteur se trouve un panier de basket réglementaire ?",n:3.05,min:0,max:12,u:"mètres",e:"3,05 mètres, soit 10 pieds. James Naismith a cloué ses paniers de pêches à la balustrade du gymnase de Springfield en 1891 : elle se trouvait à cette hauteur-là, et personne n’y a jamais retouché."},
{t:'sport',q:"Quel diamètre fait l’anneau d’un panier de basket ?",n:45,min:0,max:200,u:"centimètres",e:"45 centimètres, pour un ballon de 24 cm de diamètre. Deux ballons passent donc côte à côte dans le cercle — une image qui rassure peu les joueurs au moment du lancer franc."},
{t:'sport',q:"Combien de points a marqué l’équipe gagnante du tout premier match de basket, en 1891 ?",n:1,min:0,max:4,u:"point",e:"1-0. En trente minutes, un seul panier, signé William Chase depuis sept mètres. Les paniers de pêches ayant un fond, il fallait grimper à l’échelle pour récupérer le ballon."},
{t:'sport',q:"Combien de rebonds Wilt Chamberlain a-t-il pris dans un seul match NBA ?",n:55,min:0,max:400,u:"rebonds",e:"55 rebonds en 1960, contre les Celtics de Bill Russell. Aucune équipe entière n’en prend souvent autant aujourd’hui. Le record tient depuis plus de soixante ans sans avoir jamais été menacé."},
{t:'sport',q:"Combien de minutes Wilt Chamberlain a-t-il joué en moyenne par match lors de la saison 1961-62 ?",n:48.5,min:0,max:80,u:"minutes",e:"48,5 minutes de moyenne… pour des matchs de 48 minutes. Prolongations comprises, il n’a quitté le parquet que huit minutes de toute la saison, après une expulsion."},
{t:'sport',q:"Combien de points a marqué l’équipe gagnante du match NBA le plus pauvre de l’histoire ?",n:19,min:0,max:60,u:"points",e:"19-18 en 1950, Fort Wayne contre Minneapolis. Les visiteurs gardaient le ballon sans tirer pour neutraliser George Mikan. Le public a sifflé, et la ligue a inventé le chronomètre des 24 secondes."},
{t:'sport',q:"Combien de prolongations a-t-il fallu pour départager les deux équipes du plus long match NBA ?",n:6,min:0,max:10,u:"prolongations",e:"Six prolongations en 1951, Indianapolis contre Rochester, pour un score final de 75-73. À l’époque, chaque prolongation commençait par un entre-deux : les équipes se contentaient de garder le ballon."},
{t:'sport',q:"Combien de minutes de jeu réellement actif compte un match de football américain de NFL ?",n:11,min:0,max:40,u:"minutes",e:"Environ onze minutes de ballon en mouvement pour plus de trois heures de diffusion. Le reste : replacements, réunions d’équipe, ralentis et publicités. Le sport le plus regardé d’Amérique est surtout une longue attente."},
{t:'sport',q:"De quelle distance Tom Dempsey a-t-il réussi son field goal légendaire en 1970 ?",n:63,min:0,max:80,u:"yards",e:"63 yards, à deux secondes de la fin. Dempsey était né sans main droite et avec un pied droit incomplet : il frappait avec une chaussure à bout plat spécialement conçue."},
{t:'sport',q:"Combien pèse le trophée Vince Lombardi remis au vainqueur du Super Bowl ?",n:3.2,min:0,max:20,u:"kilos",e:"3,2 kilos d’argent sterling, façonnés à la main par Tiffany. Le dessin original a été griffonné par un cadre de Tiffany sur une serviette de restaurant lors d’un déjeuner avec le patron de la NFL."},
{t:'sport',q:"Quelle longueur fait un terrain de polo, le plus grand terrain de sport collectif au monde ?",n:274,min:0,max:1200,u:"mètres",e:"274 mètres sur 146, soit la surface de neuf terrains de football. À la mi-temps, le public est invité à descendre piétiner les mottes de gazon arrachées par les sabots."},
{t:'sport',q:"À quelle distance du batteur se trouve le monticule du lanceur, au baseball ?",n:18.44,min:0,max:30,u:"mètres",e:"60 pieds et 6 pouces. Les six pouces viendraient d’une faute de lecture sur les plans de 1893 : un « 60 ft 0 in » déchiffré « 60 ft 6 in », jamais corrigé depuis."},
{t:'sport',q:"Combien de points de couture compte une balle de baseball officielle ?",n:108,min:0,max:400,u:"coutures",e:"108 points doubles, cousus à la main, en rouge. Aucune machine n’a jamais su reproduire le geste : chaque balle de Major League passe encore entre les doigts d’un couturier."},
{t:'sport',q:"Combien de matchs de suite Cal Ripken Jr. a-t-il disputés sans en manquer un seul ?",n:2632,min:0,max:5000,u:"matchs",e:"2632 matchs consécutifs, soit plus de seize saisons sans un jour d’absence : ni grippe, ni entorse, ni repos. Il a battu un record que tout le monde croyait intouchable."},
{t:'sport',q:"Combien de manches a duré le plus long match de baseball professionnel jamais joué ?",n:33,min:0,max:80,u:"manches",e:"33 manches en 1981 entre Pawtucket et Rochester, soit huit heures et vingt-cinq minutes. Interrompu à quatre heures du matin, il fut achevé deux mois plus tard : il ne fallut qu’une manche."},
{t:'sport',q:"À quelle vitesse Aroldis Chapman a-t-il expédié le lancer le plus rapide jamais mesuré ?",n:169.1,min:0,max:300,u:"km/h",e:"169,1 km/h. Le batteur dispose d’environ quatre dixièmes de seconde pour voir, décider et frapper : moins de temps qu’il n’en faut pour cligner des yeux deux fois."},
{t:'sport',q:"Quelle hauteur fait le « Green Monster », le mur gauche de Fenway Park ?",n:11.3,min:0,max:40,u:"mètres",e:"11,3 mètres de tôle verte. Il n’a pas été construit pour le spectacle mais pour empêcher les curieux de regarder le match gratuitement depuis la rue voisine."},
{t:'sport',q:"Combien pèse un palet de hockey sur glace ?",n:170,min:0,max:200,u:"grammes",e:"Environ 170 grammes de caoutchouc vulcanisé, congelés avant chaque match pour les empêcher de rebondir. Un palet gelé glisse droit ; un palet tiède part n’importe où."},
{t:'sport',q:"Combien de minutes de prolongation a-t-il fallu pour conclure le plus long match de NHL ?",n:116.5,min:0,max:250,u:"minutes",e:"116 minutes et 30 secondes de prolongation en 1936, soit six périodes supplémentaires. Detroit l’emporte 1-0 à 2h25 du matin ; le buteur, Mud Bruneteau, était une recrue de vingt-deux ans."},
{t:'sport',q:"Combien pèse la Coupe Stanley que les vainqueurs soulèvent à bout de bras ?",n:15.5,min:0,max:40,u:"kilos",e:"15,5 kilos d’argent et de nickel, dont un socle gravé de milliers de noms. Elle a servi de vasque à baptême, de mangeoire à chien et a passé une nuit au fond d’une piscine."},
{t:'sport',q:"Combien de points Wayne Gretzky a-t-il inscrits lors de sa saison record 1985-86 ?",n:215,min:0,max:400,u:"points",e:"215 points en 80 matchs, dont 163 passes décisives. À lui seul, avec ses seules passes, il aurait terminé meilleur marqueur de la ligue cette saison-là."},
{t:'sport',q:"Combien pèse le trophée de la Coupe du monde de football ?",n:6.175,min:0,max:30,u:"kilos",e:"6,175 kilos d’or 18 carats. Massif, il pèserait plus de 70 kilos : il est donc creux. Les capitaines qui le brandissent d’une main soulèvent surtout une belle illusion."},
{t:'sport',q:"Combien de buts ont été marqués lors du match de football le plus déséquilibré de l’histoire ?",n:149,min:0,max:200,u:"buts",e:"149-0 à Madagascar en 2002. Furieux d’un arbitrage, les joueurs de Stade Olympique l’Emyrne ont marqué contre leur propre camp pendant tout le match, sur des remises en jeu au centre."},
{t:'sport',q:"Combien de buts l’Australie a-t-elle passés aux Samoa américaines lors de leur match record ?",n:31,min:0,max:40,u:"buts",e:"31-0 en 2001, en qualifications de Coupe du monde. Archie Thompson en a mis treize à lui seul. Les Samoans alignaient une équipe d’adolescents faute de joueurs éligibles."},
{t:'sport',q:"Au bout de combien de temps a été distribué le carton rouge le plus rapide du football ?",n:2,min:0,max:3,u:"secondes",e:"Deux secondes. En 2000, Lee Todd sursaute au coup de sifflet, lâche un juron sonore juste derrière l’arbitre, et rentre au vestiaire avant même d’avoir touché le ballon."},
{t:'sport',q:"Au bout de combien de secondes a été inscrit le but le plus rapide de l’histoire des Coupes du monde ?",n:10.8,min:0,max:30,u:"secondes",e:"10,8 secondes pour Hakan Şükür en 2002, lors du match pour la troisième place. Une erreur de relance sud-coréenne, et le Turc avait marqué avant que certains spectateurs ne soient assis."},
{t:'sport',q:"Combien de tirs au but a-t-il fallu pour départager les équipes lors de la plus longue séance jamais jouée ?",n:48,min:0,max:250,u:"tirs",e:"48 tirs et un score de 17-16, en Namibie en 2005. Tous les joueurs, gardiens compris, sont passés deux fois. La séance a duré plus longtemps qu’une mi-temps."},
{t:'sport',q:"Combien de cartons rouges ont été distribués lors du match de football le plus violent recensé ?",n:36,min:0,max:60,u:"cartons rouges",e:"36 en 2011, en Argentine : les 22 joueurs, plus les remplaçants et les staffs. L’arbitre a d’abord vidé le terrain, puis les bancs de touche, avant d’abandonner la rencontre."},
{t:'sport',q:"Combien de buts ont été marqués lors du match le plus prolifique de l’histoire des Coupes du monde ?",n:12,min:0,max:15,u:"buts",e:"Autriche 7 - Suisse 5, en 1954 à Berne, sous une chaleur écrasante. La Suisse menait 3-0 après vingt minutes ; l’Autriche a renversé le match en neuf minutes."},
{t:'sport',q:"Combien de spectateurs ont assisté au Maracanazo, le match Brésil-Uruguay de 1950 ?",n:173850,min:0,max:600000,u:"spectateurs",e:"173 850 entrées payantes officielles, sans doute près de 200 000 personnes dans l’enceinte. Aucun match de football n’a jamais réuni autant de monde, et le Brésil a perdu."},
{t:'sport',q:"Combien de minutes le ballon est-il réellement en jeu pendant un match de football de 90 minutes ?",n:55,min:0,max:300,u:"minutes",e:"Environ 55 minutes en moyenne. Le reste part en remises en jeu, fautes, célébrations, soins et sorties de but. Un tiers de la rencontre se joue donc ballon immobile."},
{t:'sport',q:"Quelle distance totale faisait le Tour de France de 1926, le plus long de l’histoire ?",n:5745,min:0,max:20000,u:"kilomètres",e:"5745 kilomètres en 17 étapes, soit près de 340 km par étape. Les coureurs partaient parfois à minuit et roulaient plus de vingt heures d’affilée, sans oreillette ni ravitaillement organisé."},
{t:'sport',q:"Quelle distance faisait l’étape la plus longue jamais courue sur le Tour de France ?",n:482,min:0,max:1500,u:"kilomètres",e:"482 km entre Les Sables-d’Olonne et Bayonne, en 1919. Le vainqueur a mis plus de dix-huit heures. Aujourd’hui, une étape dépasse rarement 230 kilomètres."},
{t:'sport',q:"Combien de coureurs ont terminé le tout premier Tour de France, en 1903 ?",n:21,min:0,max:50,u:"coureurs",e:"21 arrivants sur 60 partants, après six étapes gigantesques. Le vainqueur, Maurice Garin, ramoneur de métier, a devancé le deuxième de près de trois heures."},
{t:'sport',q:"Combien de coureurs ont franchi la ligne d’arrivée du Tour de France 1919 ?",n:10,min:0,max:12,u:"coureurs",e:"Dix rescapés sur 69 partants. Premier Tour d’après-guerre, sur des routes défoncées par les obus, avec des vélos en acier de vingt kilos et des boyaux de rechange en bandoulière."},
{t:'sport',q:"Combien de virages compte la montée de l’Alpe d’Huez ?",n:21,min:0,max:25,u:"virages",e:"21 lacets numérotés à rebours, chacun portant le nom d’un vainqueur d’étape. Quand la liste a dépassé vingt et un noms, il a fallu doubler les plaques sur les premiers virages."},
{t:'sport',q:"Quelle distance Eddy Merckx a-t-il parcourue en une heure lors de son record de 1972 à Mexico ?",n:49.431,min:0,max:60,u:"kilomètres",e:"49,431 km en soixante minutes. Merckx a déclaré ensuite n’avoir jamais autant souffert et refusé de retenter l’expérience. Son vélo pesait 5,75 kilos, sans freins ni dérailleur."},
{t:'sport',q:"Quel poids minimum un vélo doit-il peser pour être autorisé en course professionnelle ?",n:6.8,min:0,max:15,u:"kilos",e:"6,8 kilos, règle figée par l’UCI depuis 2000. Les fabricants savent descendre bien plus bas : ils rajoutent donc du lest dans les cadres pour atteindre la limite légale."},
{t:'sport',q:"À quelle vitesse Denise Mueller-Korenek a-t-elle roulé à vélo derrière un véhicule d’entraînement ?",n:296,min:0,max:600,u:"km/h",e:"296 km/h sur le lac salé de Bonneville, en 2018, dans l’aspiration d’un dragster. À cette allure, un coup de pédale propulse le vélo sur plus de trente mètres."},
{t:'sport',q:"À quelle vitesse Éric Barone a-t-il dévalé une pente enneigée en VTT ?",n:227,min:0,max:400,u:"km/h",e:"227,72 km/h à Vars, en 2017, sur une piste de ski à 98 % de pente. Il portait une combinaison profilée et un casque de bobeur, sur un vélo aux roues carénées."},
{t:'sport',q:"De combien de mètres Uwe Hohn a-t-il lancé le javelot, obligeant à redessiner l’engin ?",n:104.8,min:0,max:150,u:"mètres",e:"104,80 m en 1984 : les javelots atterrissaient à plat au bout des stades. La fédération a déplacé le centre de gravité de l’engin en 1986, rendant ce record éternel et inbattable."},
{t:'sport',q:"Combien d’années le record du monde de saut en longueur de Bob Beamon a-t-il tenu ?",n:23,min:0,max:100,u:"ans",e:"23 ans. En 1968 à Mexico, Beamon saute 8,90 m, cinquante-cinq centimètres au-delà du record ; l’appareil de mesure optique était trop court, il a fallu ressortir un mètre ruban."},
{t:'sport',q:"En combien de temps Jesse Owens a-t-il battu quatre records du monde le même jour, en 1935 ?",n:45,min:0,max:300,u:"minutes",e:"45 minutes, à Ann Arbor, le dos douloureux après une chute d’escalier. Quatre records dans quatre disciplines différentes en trois quarts d’heure : l’après-midi la plus productive de l’athlétisme."},
{t:'sport',q:"Combien de records du monde Sergueï Bubka a-t-il battus au saut à la perche ?",n:35,min:0,max:40,u:"records",e:"35 records du monde, en salle et en plein air, souvent améliorés d’un seul centimètre. Chaque record était primé : il a méthodiquement grignoté sa propre marque pendant dix ans."},
{t:'sport',q:"Combien de courses consécutives Edwin Moses a-t-il gagnées sur 400 m haies ?",n:122,min:0,max:150,u:"courses",e:"122 victoires d’affilée entre 1977 et 1987, soit neuf ans, neuf mois et neuf jours sans perdre. Il franchissait les dix haies en treize foulées, là où ses rivaux en faisaient quatorze."},
{t:'sport',q:"En combien de secondes Roger Bannister a-t-il couru le premier mile sous les quatre minutes ?",n:239.4,min:0,max:500,u:"secondes",e:"3 minutes 59 secondes et 4 dixièmes, en 1954 à Oxford. Étudiant en médecine, il s’entraînait pendant sa pause déjeuner. Six semaines plus tard, son record était déjà battu."},
{t:'sport',q:"Combien pèse le boulet du lancer de poids masculin ?",n:7.26,min:0,max:40,u:"kilos",e:"7,26 kilos, soit exactement 16 livres anglaises. Le poids vient d’un boulet de canon standard : les soldats écossais s’amusaient à les projeter le plus loin possible entre deux batailles."},
{t:'sport',q:"Combien d’années Shizo Kanakuri a-t-il mis pour terminer le marathon olympique de Stockholm ?",n:54,min:0,max:120,u:"ans",e:"54 ans. Épuisé en 1912, il s’arrête chez des habitants, boit un jus d’orange et rentre au Japon sans prévenir. La Suède l’a invité en 1967 pour franchir enfin la ligne."},
{t:'sport',q:"Combien de coureurs ont terminé le marathon olympique de 1904, le plus chaotique de l’histoire ?",n:14,min:0,max:15,u:"coureurs",e:"14 arrivants sur 32 partants, par 32 degrés et sur des pistes poussiéreuses. Le vainqueur avait reçu de la strychnine et du cognac ; un autre a été chassé par des chiens."},
{t:'sport',q:"Combien de coureurs ont pris le départ du tout premier marathon de Boston, en 1897 ?",n:15,min:0,max:60,u:"coureurs",e:"Quinze hommes. Le vainqueur, John McDermott, a marché plusieurs fois et perdu quatre kilos en route. Aujourd’hui, la course en rassemble environ trente mille."},
{t:'sport',q:"Combien de coureurs ont terminé le premier marathon de New York, en 1970 ?",n:55,min:0,max:60,u:"coureurs",e:"55 arrivants sur 127 partants, avec quatre boucles dans Central Park devant une poignée de curieux. Les frais d’inscription étaient d’un dollar, et les trophées avaient été payés par l’organisateur."},
{t:'sport',q:"Quelle distance parcourent les concurrents de la Badwater, la course la plus chaude du monde ?",n:217,min:0,max:800,u:"kilomètres",e:"217 km de la Vallée de la Mort au mont Whitney, en juillet, par 50 degrés. Les coureurs restent sur la ligne blanche : le bitume fait fondre les semelles."},
{t:'sport',q:"Combien de tours d’un même pâté de maisons faut-il boucler pour finir la course la plus longue du monde ?",n:5649,min:0,max:12000,u:"tours",e:"5649 tours d’un bloc du Queens, à New York, pour couvrir 4989 kilomètres. Les concurrents ont 52 jours et usent une dizaine de paires de chaussures autour du même trottoir."},
{t:'sport',q:"Combien de temps les concurrents ont-ils pour boucler les cinq boucles de la Barkley Marathons ?",n:60,min:0,max:500,u:"heures",e:"60 heures pour environ 200 km hors sentier et 20 000 mètres de dénivelé, sans GPS. En quarante ans, une vingtaine de personnes seulement ont réussi. Le départ est donné à la cigarette."},
{t:'sport',q:"Quelle distance couvre l’Ultra-Trail du Mont-Blanc autour du massif ?",n:171,min:0,max:200,u:"kilomètres",e:"Environ 171 km et 10 000 mètres de dénivelé positif, à travers trois pays. Les derniers arrivants courent deux nuits complètes ; les meilleurs dorment parfois moins de dix minutes."},
{t:'sport',q:"Combien de marches les concurrents de l’Empire State Building Run-Up doivent-ils grimper ?",n:1576,min:0,max:6000,u:"marches",e:"1576 marches jusqu’au 86e étage, avalées en une dizaine de minutes par les meilleurs. La cage d’escalier est étroite et chaude : beaucoup terminent en s’aidant de la rampe."},
{t:'sport',q:"Quelle distance totale un athlète parcourt-il lors d’un triathlon Ironman ?",n:226,min:0,max:250,u:"kilomètres",e:"226 km : 3,8 à la nage, 180 à vélo, puis un marathon complet. La distance vient d’un pari entre militaires à Hawaï, qui ont simplement additionné trois épreuves locales existantes."},
{t:'sport',q:"Combien de temps Matthew Webb a-t-il nagé pour traverser la Manche le premier, en 1875 ?",n:21.75,min:0,max:25,u:"heures",e:"21 heures 45, en brasse, enduit d’huile de marsouin, en avalant du café chaud et du brandy passés depuis une barque. Il avait dérivé si loin qu’il a nagé près de 60 kilomètres."},
{t:'sport',q:"Combien de temps Diana Nyad a-t-elle nagé sans cage pour relier Cuba à la Floride ?",n:52.9,min:0,max:100,u:"heures",e:"52 heures 54 minutes, à 64 ans, à sa cinquième tentative. Un masque en silicone la protégeait des méduses-boîtes ; sa langue et sa bouche étaient tellement enflées qu’elle ne pouvait plus parler."},
{t:'sport',q:"Combien de litres d’eau contient un bassin olympique de 50 mètres ?",n:2500000,min:0,max:5000000,u:"litres",e:"Environ 2,5 millions de litres. Il faut plus d’une journée pour le remplir, et l’eau est filtrée en continu : le volume complet passe dans les filtres toutes les quatre heures."},
{t:'sport',q:"Quelle longueur fait une piste de curling, de la ligne de lancer à la cible ?",n:45.72,min:0,max:100,u:"mètres",e:"45,72 mètres de glace, arrosée en gouttelettes qui gèlent en petites bosses. C’est sur ces aspérités que la pierre glisse et tourne ; les balais réchauffent la glace pour la faire courir plus loin."},
{t:'sport',q:"Combien pèse une pierre de curling de compétition ?",n:20,min:0,max:50,u:"kilos",e:"Environ 20 kilos de granite, extrait presque exclusivement de l’îlot écossais d’Ailsa Craig. Cette roche ne retient pas l’eau et ne gèle donc pas de l’intérieur : aucune autre carrière ne convient."},
{t:'sport',q:"Quelle longueur fait la piste sur laquelle s’affrontent deux escrimeurs ?",n:14,min:0,max:20,u:"mètres",e:"14 mètres sur deux de large. Reculer jusqu’au bout de la piste donne une touche à l’adversaire : le duel ne se gagne pas seulement à l’épée, mais aussi en gérant ses arrières."},
{t:'sport',q:"Quel diamètre fait le cercle central valant 10 points, en tir à l’arc olympique ?",n:12.2,min:0,max:60,u:"centimètres",e:"12,2 cm, visés à 70 mètres. À cette distance, la cible entière paraît large comme une pièce tenue à bout de bras, et le dix comme une tête d’épingle."},
{t:'sport',q:"Quel diamètre fait la cible que les biathlètes doivent toucher en position couchée ?",n:45,min:0,max:200,u:"millimètres",e:"45 millimètres à 50 mètres, avec un cœur à 150 pulsations. En position debout, la cible passe à 115 mm : c’est le seul répit accordé à des skieurs à bout de souffle."},
{t:'sport',q:"À quelle distance de la cible se tient un joueur de fléchettes professionnel ?",n:2.37,min:0,max:3,u:"mètres",e:"2,37 mètres, mesurés depuis la ligne de lancer, la cible étant accrochée à 1,73 m du sol. Le triple 20 visé mesure moins d’un centimètre de large."},
{t:'sport',q:"Quel diamètre fait le cercle de combat, le dohyo, où s’affrontent les lutteurs de sumo ?",n:4.55,min:0,max:8,u:"mètres",e:"4,55 mètres, délimités par des ballots de paille de riz enterrés dans l’argile. Deux colosses de 150 kilos disposent donc d’un espace plus petit qu’une chambre pour se pousser dehors."},
{t:'sport',q:"Combien pesait Konishiki, le lutteur de sumo le plus lourd de l’histoire de la discipline ?",n:287,min:0,max:400,u:"kilos",e:"287 kilos au sommet de sa carrière, ce qui lui a valu le surnom de « camion à vidange ». Hawaïen, il fut le premier étranger à atteindre le rang d’ozeki."},
{t:'sport',q:"Combien pèse un gant de boxe professionnel dans les catégories légères ?",n:227,min:0,max:400,u:"grammes",e:"8 onces, soit 227 grammes de rembourrage. Contrairement à l’intuition, le gant protège surtout les mains du frappeur : il permet de cogner plus souvent, pas moins fort."},
{t:'sport',q:"Combien de temps a duré le combat Mike Tyson - Michael Spinks en 1988 ?",n:91,min:0,max:250,u:"secondes",e:"91 secondes. Spinks, invaincu, est tombé deux fois. Des spectateurs venus en jet privé sont repartis en ayant vu moins de deux minutes de boxe pour plus de mille dollars la place."},
{t:'sport',q:"Combien de combats professionnels le boxeur Len Wickwar a-t-il disputés au cours de sa carrière ?",n:463,min:0,max:600,u:"combats",e:"463 combats entre 1928 et 1947, parfois plusieurs par semaine. Record absolu de la boxe professionnelle : les boxeurs modernes en disputent une cinquantaine dans toute leur vie."},
{t:'sport',q:"Combien de temps a duré le KO le plus rapide de l’histoire de l’UFC ?",n:5,min:0,max:8,u:"secondes",e:"Cinq secondes : Jorge Masvidal traverse la cage en courant et place un coup de genou sauté sur Ben Askren, encore accroupi. Le combat était terminé avant que l’arbitre n’ait fait trois pas."},
{t:'sport',q:"Quelle distance a parcourue l’équipage recordman des 24 Heures du Mans ?",n:5410,min:0,max:40000,u:"kilomètres",e:"5410 km en 2010, soit 397 tours et l’équivalent d’un Paris-Moscou aller-retour, en un jour et une nuit. La moyenne dépasse 225 km/h, arrêts au stand compris."},
{t:'sport',q:"À quelle vitesse la WM P88 a-t-elle été chronométrée dans la ligne droite des Hunaudières, au Mans ?",n:405,min:0,max:2000,u:"km/h",e:"405 km/h en 1988, sur une portion de route départementale ouverte au public le reste de l’année. Deux chicanes ont été ajoutées dès 1990 pour que cela ne se reproduise jamais."},
{t:'sport',q:"Combien de tours a duré le Grand Prix de Formule 1 le plus court jamais couru en 1991 ?",n:14,min:0,max:120,u:"tours",e:"14 tours à Adélaïde, sous un déluge, avant l’arrêt définitif de la course. Ayrton Senna a gagné en 24 minutes et n’a reçu que la moitié des points."},
{t:'sport',q:"Quelle longueur fait la boucle Nordschleife du Nürburgring ?",n:20.832,min:0,max:80,u:"kilomètres",e:"20,832 km et plus de 70 virages, taillés dans une forêt de l’Eifel. Jackie Stewart l’avait surnommée « l’Enfer vert » ; la Formule 1 l’a désertée après l’accident de Lauda en 1976."},
{t:'sport',q:"Quelle longueur fait un tour du circuit du Tourist Trophy de l’île de Man ?",n:60.7,min:0,max:600,u:"kilomètres",e:"60,7 km de routes publiques bordées de murs de pierre, de trottoirs et de maisons. Les pilotes y roulent à plus de 300 km/h et mémorisent près de 200 virages."},
{t:'sport',q:"De combien de longueurs Secretariat a-t-il gagné les Belmont Stakes en 1973 ?",n:31,min:0,max:50,u:"longueurs",e:"31 longueurs, soit près de 80 mètres : les caméras ne parvenaient plus à cadrer le peloton et le vainqueur ensemble. Aucun cheval n’a jamais dominé une course classique à ce point."},
{t:'sport',q:"À quelle vitesse a été chronométré le cheval de course le plus rapide jamais mesuré ?",n:70.76,min:0,max:80,u:"km/h",e:"70,76 km/h sur 400 mètres, par une pouliche nommée Winning Brew, en 2008. Sur un sprint court, le pur-sang bat donc largement le guépard en endurance mais reste loin de sa pointe."},
{t:'sport',q:"À quelle vitesse file la pelote lors d’une partie de cesta punta, la balle la plus rapide du sport ?",n:302,min:0,max:2500,u:"km/h",e:"302 km/h, propulsée par un gant d’osier long d’un demi-mètre. La pelote, en peau de chèvre sur noyau de caoutchouc, est plus dure qu’une balle de golf : le port du casque est obligatoire."},
{t:'sport',q:"À quelle vitesse descend un skieur de vitesse au record du monde ?",n:255,min:0,max:500,u:"km/h",e:"Près de 255 km/h sur une pente à 98 %, en position d’œuf, avec des skis de 2,40 m et un casque en goutte d’eau. Plus rapide qu’un parachutiste en chute libre."},
{t:'sport',q:"De quelle hauteur a été effectué le plus haut plongeon jamais réalisé, en 2015 ?",n:58.8,min:0,max:300,u:"mètres",e:"58,8 mètres depuis une cascade suisse par Laso Schaller, soit un immeuble de vingt étages. Trois secondes de chute, une entrée dans l’eau à près de 120 km/h, et une hanche luxée."},
{t:'sport',q:"À quelle profondeur Herbert Nitsch est-il descendu en apnée « no limit » ?",n:214,min:0,max:250,u:"mètres",e:"214 mètres en 2007, en descendant sur une gueuse lestée et en remontant grâce à un ballon gonflable. À cette profondeur, ses poumons étaient comprimés à la taille d’un poing."},
{t:'sport',q:"Quelle est la pente maximale de la Streif de Kitzbühel, la descente la plus redoutée du ski alpin ?",n:85,min:0,max:100,u:"%",e:"85 % dans la Mausefalle, où les skieurs décollent sur plus de soixante mètres deux secondes après le départ. La piste entière se dévale en moins de deux minutes."},
{t:'sport',q:"À quelle vitesse peut dévaler la meule de fromage lors de la course de Cooper’s Hill ?",n:112,min:0,max:600,u:"km/h",e:"Jusqu’à 112 km/h sur une pente à 50 %. Personne ne rattrape jamais le fromage : les concurrents dégringolent derrière lui et le premier arrivé en bas, souvent blessé, remporte la meule."},

/* ---------- WTF ---------- */
{t:'wtf',q:"Combien d'années a duré le plus long hoquet jamais enregistré ?",n:68,min:0,max:120,u:"ans",e:"68 ans, de 1922 à 1990, pour l'Américain Charles Osborne. Il a eu une vie normale, deux mariages et huit enfants — en hoquetant."},
{t:'wtf',q:"Quelle longueur atteignaient les ongles d'une seule main de Shridhar Chillal ?",n:9,min:0,max:30,u:"mètres",e:"9 mètres cumulés sur cinq doigts, après 66 ans sans les couper. Sa main gauche est devenue inutilisable et il dormait sans bouger."},
{t:'wtf',q:"Combien de Big Mac Don Gorske a-t-il mangés dans sa vie ?",n:34000,min:0,max:40000,u:"Big Mac",e:"Plus de 34 000, un par jour depuis 1972. Son taux de cholestérol est normal et il a gardé toutes ses dents."},
{t:'wtf',q:"Combien de personnes ont été prises dans l'épidémie de danse de Strasbourg en 1518 ?",n:400,min:0,max:800,u:"personnes",e:"Environ 400. Elles ont dansé des jours durant, certaines jusqu'à l'épuisement. Les autorités, croyant à un remède, ont fait venir des musiciens pour les accompagner."},
{t:'wtf',q:"Combien d'émeus l'armée australienne a-t-elle abattus pendant la « guerre des émeus » ?",n:986,min:0,max:1500,u:"émeus",e:"986 sur les 20 000 visés, pour 10 000 cartouches. Les oiseaux se dispersaient dès les premiers tirs : l'armée a battu en retraite."},
{t:'wtf',q:"Combien de mois a vécu Mike, le poulet sans tête ?",n:18,min:0,max:120,u:"mois",e:"18 mois. La hache avait épargné une oreille et l'essentiel du tronc cérébral. Son propriétaire le nourrissait à la pipette et l'exhibait dans les foires."},
{t:'wtf',q:"Combien d’enfants avaient les gagnantes de la « course à la cigogne » de Toronto ?",n:9,min:0,max:30,u:"enfants",e:"Un millionnaire excentrique légua sa fortune à la Torontoise qui ferait le plus de bébés en dix ans. Quatre femmes finirent ex æquo avec neuf enfants chacune, et se partagèrent le magot."},
{t:'wtf',q:"Combien de fois le garde forestier Roy Sullivan a-t-il été frappé par la foudre ?",n:7,min:0,max:25,u:"fois",e:"Sept fois entre 1942 et 1977 : cheveux en feu, sourcils brûlés, ongle d’orteil arraché. Il a survécu à chaque coup. Il est mort d’une balle, pour un chagrin d’amour."},
{t:'wtf',q:"Combien de victimes a fait la « guerre du cochon » de 1859 entre Américains et Britanniques ?",n:1,min:0,max:2,u:"cochon",e:"Un porc britannique broutait des pommes de terre américaines sur l’île de San Juan. Un colon l’abat, deux empires envoient navires et canons. Seule victime de la crise : le cochon."},
{t:'wtf',q:"Combien d’obus l’armée américaine a-t-elle tirés pendant la « bataille de Los Angeles » de 1942 ?",n:1400,min:0,max:4000,u:"obus",e:"Une nuit de février, la DCA a arrosé le ciel californien pendant une heure contre un ennemi invisible. Aucun avion japonais retrouvé. Le coupable probable : un ballon météo égaré."},
{t:'wtf',q:"Combien d’années le soldat Hiroo Onoda a-t-il continué la Seconde Guerre mondiale dans la jungle ?",n:29,min:0,max:40,u:"ans",e:"Vingt-neuf ans aux Philippines, persuadé que la reddition était une ruse ennemie. Il n’a déposé les armes qu’en 1974, quand son ancien commandant est venu en personne lui en donner l’ordre."},
{t:'wtf',q:"Combien d’années saint Siméon le Stylite a-t-il vécu au sommet de sa colonne ?",n:37,min:0,max:150,u:"ans",e:"Trente-sept ans debout sur une plateforme de quelques mètres carrés, en Syrie, au Ve siècle. Les pèlerins venaient de loin ; on lui montait sa nourriture avec une échelle."},
{t:'wtf',q:"Combien de jours a jeûné Angus Barbieri, sous surveillance médicale ?",n:382,min:0,max:500,u:"jours",e:"Un an et deux semaines sans rien manger, en Écosse, avec vitamines, thé et café. Il est passé de 207 à 82 kilos. Il n’a jamais repris tout ce poids."},
{t:'wtf',q:"Combien d’heures Randy Gardner est-il resté éveillé pour son record de privation de sommeil ?",n:264,min:0,max:400,u:"heures",e:"Onze jours sans dormir, en 1963, pour un projet de lycée. Hallucinations, paranoïa, mémoire en miettes. Après l’exploit, il a dormi quatorze heures et s’est réveillé presque normal."},
{t:'wtf',q:"Combien de jours Michel Siffre a-t-il passé seul dans une grotte, sans repère de temps ?",n:205,min:0,max:800,u:"jours",e:"En 1972, au Texas, sans montre ni lumière du jour. Son corps a inventé des journées de 48 heures. En sortant, il pensait être en août : on était en septembre."},
{t:'wtf',q:"Combien d’années Paul Alexander a-t-il vécu dans un poumon d’acier ?",n:72,min:0,max:300,u:"ans",e:"Polio à six ans, en 1952, puis toute une vie dans un cylindre métallique. Il est devenu avocat et a écrit un livre en tenant un stylo entre ses dents."},
{t:'wtf',q:"De quelle altitude Vesna Vulović est-elle tombée avant de survivre ?",n:10160,min:0,max:12000,u:"mètres",e:"Hôtesse de l’air, elle chute avec un tronçon de DC-9 explosé en 1972. Coincée par un chariot, amortie par la neige et une pente boisée. Un mois de coma, puis la vie."},
{t:'wtf',q:"De quelle hauteur Juliane Koepcke est-elle tombée avant de marcher onze jours en Amazonie ?",n:3000,min:0,max:5000,u:"mètres",e:"Foudroyé, son avion se disloque en 1971. Attachée à son siège, elle traverse la canopée. Seule survivante, clavicule cassée, elle suit un ruisseau pendant onze jours jusqu’à des bûcherons."},
{t:'wtf',q:"De quelle altitude Nicholas Alkemade a-t-il sauté sans parachute ?",n:5500,min:0,max:6000,u:"mètres",e:"Mitrailleur de la RAF, son bombardier en feu, il saute plutôt que de brûler vif. Sapins, buissons et un mètre de neige l’ont freiné. Bilan : une entorse à la cheville."},
{t:'wtf',q:"Avec combien de ballons Larry Walters s’est-il envolé sur sa chaise de jardin ?",n:42,min:0,max:300,u:"ballons",e:"En 1982, il gonfle 42 ballons météo à l’hélium, s’assoit avec un pistolet à plombs et des sandwichs. Il monte à 4 900 mètres et croise des avions de ligne."},
{t:'wtf',q:"Combien de secondes dure le vol commercial le plus court du monde ?",n:90,min:0,max:150,u:"secondes",e:"Entre les îles écossaises de Westray et Papa Westray : 2,7 kilomètres. Par bon vent, le record officiel tombe à 53 secondes, moins que l’annonce de sécurité."},
{t:'wtf',q:"De quel étage l’avocat Garry Hoy est-il tombé en voulant prouver la solidité d’une vitre ?",n:24,min:0,max:80,u:"étage",e:"À Toronto en 1993, il aimait montrer aux stagiaires qu’on pouvait s’y jeter sans risque. La vitre a tenu : c’est le cadre qui a cédé, avec la fenêtre entière."},
{t:'wtf',q:"En combien de morceaux le cerveau d’Einstein a-t-il été découpé ?",n:240,min:0,max:300,u:"morceaux",e:"Le pathologiste Thomas Harvey l’a prélevé sans autorisation en 1955, découpé en 240 blocs, puis gardé des décennies dans des bocaux chez lui avant d’en distribuer des bouts à des chercheurs."},
{t:'wtf',q:"Combien pesait le grêlon le plus lourd jamais officiellement mesuré ?",n:1.02,min:0,max:1.5,u:"kg",e:"Plus d’un kilo de glace tombé du ciel au Bangladesh en 1986, lors d’un orage qui fit 92 morts. L’équivalent d’un gros paquet de farine lâché de plusieurs kilomètres."},
{t:'wtf',q:"Combien de fois environ la cloche électrique d’Oxford a-t-elle sonné depuis 1840 ?",n:10000000000,min:0,max:40000000000,u:"tintements",e:"Deux pupitres de laiton et une bille qui rebondit, alimentés par une pile sèche jamais remplacée. Environ dix milliards d’oscillations. Personne n’ose ouvrir la pile pour voir ce qu’elle contient."},
{t:'wtf',q:"Quel âge a le plus vieux chewing-gum jamais retrouvé ?",n:9000,min:0,max:20000,u:"ans",e:"Des boulettes de résine de bouleau mâchées puis recrachées, exhumées en Suède. Les empreintes dentaires sont encore visibles, et l’ADN salivaire a révélé les mâcheurs : surtout des adolescents."},
{t:'wtf',q:"Combien de temps Michel Lotito a-t-il mis pour manger un avion Cessna ?",n:2,min:0,max:8,u:"ans",e:"« Monsieur Mangetout » découpait le métal en petits morceaux avalés avec de l’eau et de l’huile. Un Cessna 150 entier entre 1978 et 1980, plus des vélos et un cercueil."},
{t:'wtf',q:"À quelle hauteur sautent les asticots vivants du fromage sarde casu marzu ?",n:15,min:0,max:30,u:"centimètres",e:"Ce pecorino est volontairement colonisé par des mouches. Les larves digèrent la pâte et bondissent jusqu’à quinze centimètres quand on les dérange : les amateurs mangent en se protégeant les yeux."},
{t:'wtf',q:"Combien de parts de pâtisserie le roi Adolphe-Frédéric de Suède a-t-il englouties à son dernier repas ?",n:14,min:0,max:15,u:"parts",e:"En 1771, après homard, caviar, choucroute et champagne, il réclame quatorze portions de semla, la brioche à la crème. Il meurt dans la nuit : « le roi qui s’est mangé à mort »."},
{t:'wtf',q:"Combien de jours ont été purement et simplement supprimés du calendrier en octobre 1582 ?",n:10,min:0,max:15,u:"jours",e:"Pour recaler les saisons, Grégoire XIII fait passer le jeudi 4 octobre au vendredi 15. Dix jours effacés : les loyers, les salaires et les fêtes ont dû être renégociés."},
{t:'wtf',q:"À quelle valeur un projet de loi de l’Indiana a-t-il failli fixer le nombre π, en 1897 ?",n:3.2,min:0,max:10,u:"valeur de π",e:"Un médecin amateur croyait avoir résolu la quadrature du cercle. Le texte est passé à la Chambre à l’unanimité. Un mathématicien de passage au Sénat a stoppé le ridicule."},
{t:'wtf',q:"Quelle pointure chausserait la Statue de la Liberté ?",n:879,min:0,max:8000,u:"pointure",e:"Sa sandale mesure plus de 7,5 mètres de long. Son nez fait 1,37 mètre, son index 2,4 mètres. À l’intérieur, la structure est signée Gustave Eiffel."},
{t:'wtf',q:"De combien la tour Eiffel grandit-elle en plein été ?",n:15,min:0,max:25,u:"centimètres",e:"Le fer se dilate à la chaleur : jusqu’à quinze centimètres entre le grand froid et la canicule. Elle penche aussi légèrement, en s’éloignant du soleil comme une fleur à l’envers."},
{t:'wtf',q:"À quelle vitesse dévale la meule de fromage de la course de Cooper’s Hill ?",n:112,min:0,max:250,u:"km/h",e:"Une roue de Double Gloucester lâchée sur une pente à 45 degrés, dans le Gloucestershire. Personne ne la rattrape jamais : on court derrière, on tombe, et le premier en bas gagne le fromage."},
{t:'wtf',q:"Combien de votes le nom « Boaty McBoatface » a-t-il récoltés dans le sondage public britannique ?",n:124109,min:0,max:200000,u:"votes",e:"Le centre de recherche polaire avait demandé au public de baptiser son navire de 200 millions de livres. Le gagnant fut retoqué ; le nom fut recyclé sur un petit sous-marin jaune."},
{t:'wtf',q:"Combien d’années le chat Stubbs a-t-il été maire honoraire de Talkeetna, en Alaska ?",n:20,min:0,max:100,u:"ans",e:"Élu en 1997 faute de candidat humain convaincant, il a régné vingt ans depuis le magasin général, où les touristes venaient lui serrer la patte autour d’un verre d’eau au whisky."},
{t:'wtf',q:"Combien s’est vendu aux enchères le pigeon voyageur New Kim ?",n:1600000,min:0,max:6000000,u:"euros",e:"Une pigeonne belge de deux ans, adjugée en 2020 à un acheteur chinois après une bataille d’enchères. Prix d’une villa, pour un oiseau qui ne pesait pas 500 grammes."},
{t:'wtf',q:"Combien s’est vendu sur eBay un sandwich au fromage portant le visage de la Vierge Marie ?",n:28000,min:0,max:60000,u:"dollars",e:"Grillé dix ans plus tôt, conservé sans moisir dans une boîte, il fut acheté en 2004 par un casino en ligne. La vendeuse jurait qu’il lui portait chance au jeu."},
{t:'wtf',q:"Combien s’est vendu un pétale de céréale ayant la forme de l’Illinois ?",n:1350,min:0,max:1500,u:"dollars",e:"Deux sœurs de l’Iowa repèrent le flocon dans leur bol, refusent de le manger et le mettent en vente. eBay bloque d’abord l’annonce pour « vente de nourriture entamée »."},
{t:'wtf',q:"Combien s’est vendue la photographie d’une pomme de terre par Kevin Abosch ?",n:1000000,min:0,max:1500000,u:"euros",e:"« Potato #345 » : une patate sur fond noir, tirée en trois exemplaires. Un homme d’affaires en a acheté un après un dîner arrosé, disant y voir un portrait."},
{t:'wtf',q:"Quelle longueur atteignait la plus longue moustache du monde, celle de Ram Singh Chauhan ?",n:4.29,min:0,max:12,u:"mètres",e:"Plus longue qu’une voiture citadine. Il ne la coupait plus depuis 1982, l’enroulait autour de sa tête et l’entretenait chaque jour à l’huile de coco et d’olive."},
{t:'wtf',q:"Quelle longueur atteignait la plus longue barbe jamais mesurée, celle de Hans Langseth ?",n:5.33,min:0,max:6,u:"mètres",e:"Le Norvégien l’enroulait dans un sachet accroché à son cou pour marcher. À sa mort en 1927, la barbe fut coupée et léguée au musée Smithsonian, où elle dort encore."},
{t:'wtf',q:"Quelle longueur mesuraient les cheveux de Xie Qiuping, les plus longs du monde ?",n:5.627,min:0,max:12,u:"mètres",e:"Elle a cessé de les couper à treize ans, en 1973. Il lui fallait de l’aide pour les laver et les porter, et deux bonnes heures pour un simple séchage."},
{t:'wtf',q:"Quelle longueur atteint la plus longue langue humaine mesurée ?",n:10.1,min:0,max:25,u:"centimètres",e:"Mesurée de la lèvre fermée au bout de la langue chez l’Américain Nick Stoeberl. Il s’en sert pour peindre des tableaux, la langue protégée par un film alimentaire."},
{t:'wtf',q:"Quelle largeur atteint la plus grande bouche du monde, ouverte au maximum ?",n:17,min:0,max:20,u:"centimètres",e:"L’Angolais Francisco Domingo Joaquim y fait entrer une canette de soda entière, à l’horizontale. Son surnom local : « la bouche ». Il a été repéré grâce à une vidéo amateur."},
{t:'wtf',q:"Combien de doigts et d’orteils compte Devendra Suthar, l’homme le plus polydactyle ?",n:28,min:0,max:50,u:"doigts",e:"Sept à chaque main, sept à chaque pied. Il est menuisier, et confie faire particulièrement attention en maniant la scie électrique. Aucun n’est atrophié : tous fonctionnent."},
{t:'wtf',q:"Quelle taille faisait Chandra Bahadur Dangi, le plus petit homme jamais mesuré ?",n:54.6,min:0,max:200,u:"centimètres",e:"Le Népalais tenait dans les bras comme un nourrisson, à 72 ans. Il a passé sa vie dans son village à tisser des sangles, sans jamais avoir consulté de médecin."},
{t:'wtf',q:"Quelle taille atteignait Robert Wadlow, l’homme le plus grand de l’histoire ?",n:272,min:0,max:300,u:"centimètres",e:"Encore en croissance à sa mort, à 22 ans. Il chaussait du 75, marchait avec des attelles et ne sentait plus ses pieds : c’est une ampoule infectée qui l’a emporté."},
{t:'wtf',q:"Combien de jours d’affilée Donna Griffiths a-t-elle éternué sans s’arrêter ?",n:976,min:0,max:1200,u:"jours",e:"Deux ans et huit mois d’éternuements, à partir de 1981, à raison d’un par minute au début. Le dernier éternuement « normal » est tombé un 16 septembre, après un million de secousses."},
{t:'wtf',q:"Combien pesait le plus gros bébé jamais né et documenté ?",n:10.2,min:0,max:20,u:"kg",e:"Né en 1879 d’Anna Bates, elle-même haute de 2,41 mètres. Le nourrisson mesurait 76 centimètres, la taille d’un enfant d’un an. Il n’a vécu que onze heures."},
{t:'wtf',q:"Combien d’enfants les archives attribuent-elles à Valentina Vassilieva, la femme la plus féconde ?",n:69,min:0,max:100,u:"enfants",e:"Vingt-sept accouchements au XVIIIe siècle en Russie : seize paires de jumeaux, sept triplés, quatre quadruplés. Deux seulement seraient morts en bas âge. Le monastère a soigneusement consigné le tout."},
{t:'wtf',q:"Combien d’années les travaux de la Winchester Mystery House ont-ils duré sans interruption ?",n:38,min:0,max:60,u:"ans",e:"Persuadée d’être hantée par les victimes des fusils Winchester, la veuve fit clouer et scier jour et nuit jusqu’à sa mort. Résultat : des escaliers vers le plafond et des portes sur le vide."},
{t:'wtf',q:"Combien de prisonniers se sont échappés par le tunnel de la « Grande Évasion » de 1944 ?",n:76,min:0,max:100,u:"évadés",e:"Trois tunnels creusés à la main sous un camp allemand, 4 000 planches de lit récupérées. Soixante-seize hommes sortis avant l’alerte. Trois seulement ont rejoint l’Angleterre."},
{t:'wtf',q:"Combien coûtait par an la taxe sur la barbe instaurée par Pierre le Grand ?",n:100,min:0,max:120,u:"roubles",e:"Le tsar voulait des visages rasés à l’européenne. Les nobles payaient cent roubles par an et recevaient un jeton de cuivre à montrer : « la barbe est un fardeau superflu »."},
{t:'wtf',q:"Combien de lettres compte le nom de lieu le plus long du monde, en Nouvelle-Zélande ?",n:85,min:0,max:400,u:"lettres",e:"Taumatawhakatangihangakoauauotamateaturipukakapikimaungahoronukupokaiwhenuakitanatahu, une colline maorie. Le nom raconte l’histoire d’un homme jouant de la flûte pour sa bien-aimée. Le panneau routier fait plusieurs mètres."},
{t:'wtf',q:"Combien de lettres compte le nom chimique complet de la titine, la plus grande protéine humaine ?",n:189819,min:0,max:400000,u:"lettres",e:"Le lire à voix haute prend plus de trois heures. La titine sert de ressort dans nos muscles. Aucun dictionnaire ne l’accepte : ce n’est pas un mot, c’est une formule."},
{t:'wtf',q:"Combien la CIA a-t-elle englouti environ dans le projet « Acoustic Kitty », le chat espion ?",n:20000000,min:0,max:40000000,u:"dollars",e:"Micro dans l’oreille, antenne dans la queue, émetteur sous la peau. Lors du premier test, le chat a traversé la rue et a été renversé par un taxi. Programme abandonné."},
{t:'wtf',q:"À combien d’années de prison Chamoy Thipyaso a-t-elle été condamnée en Thaïlande ?",n:141078,min:0,max:150000,u:"ans",e:"Une pyramide financière ayant ruiné 16 000 personnes, dont des militaires. Le juge a additionné les peines de chaque victime. La loi thaïlandaise plafonnant l’exécution, elle a purgé huit ans."},
{t:'wtf',q:"Combien de secondes a duré le plus long vol de poule jamais chronométré ?",n:13,min:0,max:20,u:"secondes",e:"Treize secondes en l’air pour une poule domestique, soit une petite cinquantaine de mètres. Ses ancêtres sauvages volaient très bien : la sélection pour la viande a plombé l’aérodynamique."},
{t:'wtf',q:"Combien de corbeaux la Tour de Londres doit-elle héberger en permanence, par tradition royale ?",n:6,min:0,max:8,u:"corbeaux",e:"La légende veut que le royaume s’effondre s’ils partent. Un « Ravenmaster » les nourrit de viande crue trempée dans le sang, et on en garde toujours un septième en réserve."},
{t:'wtf',q:"Combien d’argent D. B. Cooper a-t-il emporté en sautant en parachute d’un Boeing 727 ?",n:200000,min:0,max:250000,u:"dollars",e:"En 1971, il détourne l’avion, libère les passagers contre la rançon, puis saute en pleine nuit au-dessus des forêts. Jamais retrouvé. Une liasse a refait surface neuf ans plus tard, sur une plage."},
{t:'wtf',q:"Combien d’années le facteur Ferdinand Cheval a-t-il mis à bâtir son Palais idéal ?",n:33,min:0,max:250,u:"ans",e:"Il bute sur une pierre en tournée, la ramasse, et continue pendant trente-trois ans à charrier des cailloux dans sa brouette, la nuit, à la lueur d’une lampe à pétrole."},
{t:'wtf',q:"Combien de tonnes de roche Edward Leedskalnin a-t-il taillées seul pour bâtir son Coral Castle ?",n:1100,min:0,max:1500,u:"tonnes",e:"Un Letton d’1,52 mètre, 45 kilos, travaillant seul et de nuit en Floride, sans machine. Une porte de neuf tonnes y tourne encore d’une poussée du doigt. Il n’a jamais expliqué sa méthode."},
{t:'wtf',q:"Combien d’années Dashrath Manjhi a-t-il mis pour percer une route dans la montagne, seul ?",n:22,min:0,max:50,u:"ans",e:"Sa femme est morte faute d’avoir pu contourner la colline à temps pour voir un médecin. Marteau et burin en main, il a taillé un passage de 110 mètres. Le détour est passé de 55 à 15 kilomètres."},
{t:'wtf',q:"Les restes de combien de personnes reposent dans les catacombes de Paris ?",n:6000000,min:0,max:10000000,u:"personnes",e:"Vidées des cimetières saturés à partir de 1786, les ossements ont été convoyés de nuit, en charrettes, sous escorte de prêtres. Ils tapissent aujourd’hui 1,7 kilomètre de galeries ouvertes au public."},
{t:'wtf',q:"Quelle distance parcourt-on au championnat du monde de plongée en tourbière, au pays de Galles ?",n:110,min:0,max:250,u:"mètres",e:"Deux allers-retours dans une tranchée de tourbe glacée, palmes et tuba obligatoires, nage classique interdite. Le fond est invisible et grouillant. Le grand prix : la gloire, et une tourbe plein le masque."},
{t:'wtf',q:"Combien de rounds compte un match officiel de chessboxing ?",n:11,min:0,max:20,u:"rounds",e:"Six manches d’échecs et cinq de boxe en alternance. On gagne par KO ou par échec et mat. Après un round de coups, il faut se rasseoir et calculer une ouverture."},
{t:'wtf',q:"Combien de joueurs compte chaque équipe au calcio storico de Florence ?",n:27,min:0,max:200,u:"joueurs",e:"Vingt-sept par camp, sur du sable, en costume Renaissance. Coups de poing et de tête autorisés, cinquante minutes sans remplacement. Le trophée historique du tournoi : une vache blanche."},
{t:'wtf',q:"Combien de minutes Reg Mellor a-t-il tenu avec des furets vivants dans son pantalon ?",n:326,min:0,max:1200,u:"minutes",e:"Cinq heures et demie de « ferret legging », discipline anglaise : pantalon fermé aux chevilles, pas de sous-vêtement, furets non limés. Il déclarait qu’il fallait « être un homme d’acier »."},
{t:'wtf',q:"Combien de coups a duré la plus longue partie d’échecs officielle de l’histoire ?",n:269,min:0,max:300,u:"coups",e:"Nikolić contre Arsović, Belgrade 1989 : vingt heures et quinze minutes de jeu pour une partie nulle. La règle des cinquante coups avait été temporairement assouplie. Elle a vite été remise en place."},
{t:'wtf',q:"Combien de jours a duré la plus longue partie de Monopoly homologuée ?",n:70,min:0,max:200,u:"jours",e:"Soixante-dix jours de jeu ininterrompu. D’autres records du même genre existent sous l’eau, dans une baignoire ou en montgolfière : la marque officielle du jeu les a longtemps encouragés."},
{t:'wtf',q:"Sur combien de jours s’est étalé le « Timeless Test », le match de cricket sans limite de durée ?",n:12,min:0,max:60,u:"jours",e:"Afrique du Sud contre Angleterre, 1939. On devait jouer jusqu’au vainqueur. Au douzième jour, match nul décrété : les Anglais devaient attraper leur bateau pour rentrer chez eux."},
{t:'wtf',q:"Combien de manches a duré le plus long match de baseball professionnel ?",n:33,min:0,max:100,u:"manches",e:"Pawtucket contre Rochester, 1981 : huit heures et vingt-cinq minutes, interrompues à quatre heures du matin, reprises deux mois plus tard. Dix-neuf spectateurs tenaient encore à la fin de la nuit."},
{t:'wtf',q:"Combien de minutes a duré le plus long match de tennis de l’histoire, à Wimbledon ?",n:665,min:0,max:2000,u:"minutes",e:"Isner contre Mahut, 2010 : onze heures cinq réparties sur trois jours, un cinquième set fini 70-68. Le tableau d’affichage a buggé, incapable d’afficher des scores aussi élevés."},
{t:'wtf',q:"Combien de kilomètres Fred Lorz a-t-il parcourus en voiture pendant le marathon olympique de 1904 ?",n:18,min:0,max:40,u:"kilomètres",e:"Épuisé, il monte dans une auto, redescend frais comme un gardon et franchit la ligne en vainqueur. Démasqué au moment de la remise du prix, il jura que c’était une blague."},
{t:'wtf',q:"Combien d’années Shizo Kanakuri a-t-il mis pour terminer le marathon olympique de 1912 ?",n:54,min:0,max:120,u:"ans",e:"Malade sur le parcours, le Japonais s’arrête boire chez des riverains, s’endort et rentre au pays sans prévenir. La Suède l’invite en 1967 : il coupe enfin la ligne, cinquante-quatre ans plus tard."},
{t:'wtf',q:"Combien de secondes Éric l’Anguille a-t-il mis pour nager son 100 mètres olympique ?",n:112.72,min:0,max:800,u:"secondes",e:"Le Guinéen équatorial Eric Moussambani avait appris à nager huit mois plus tôt, dans un bassin de vingt mètres. Seul dans l’eau, il a fini deux fois plus lentement que le record, sous les acclamations."},
{t:'wtf',q:"Combien d’or contenait la cuvette de toilettes en état de marche volée au palais de Blenheim ?",n:98,min:0,max:150,u:"kg",e:"Une œuvre de Maurizio Cattelan en or 18 carats, installée pour que le public puisse réellement s’en servir. Volée en 2019 après une nuit de fête, elle n’a jamais été retrouvée : sans doute fondue."},
{t:'wtf',q:"Combien s’est vendu aux enchères le violon retrouvé du chef d’orchestre du Titanic ?",n:900000,min:0,max:2000000,u:"livres",e:"Wallace Hartley jouait pour calmer les passagers pendant le naufrage. L’instrument, sanglé dans un étui de cuir retrouvé sur son corps, s’est vendu en 2013 en dix minutes d’enchères."},
{t:'wtf',q:"Combien de mois a duré l’épidémie de rire du Tanganyika, en 1962 ?",n:18,min:0,max:50,u:"mois",e:"Partie d’un pensionnat de filles, la crise de fou rire contagieux a fermé quatorze écoles et touché près d’un millier de personnes. Diagnostic retenu : une hystérie collective liée au stress scolaire."},
{t:'wtf',q:"Combien de personnes le lac Nyos a-t-il tuées en une seule nuit, en 1986 ?",n:1746,min:0,max:8000,u:"morts",e:"Un lac de cratère camerounais a relâché d’un coup un nuage de CO₂ dissous. Plus lourd que l’air, il a dévalé les vallées et asphyxié villages et troupeaux dans leur sommeil."},
{t:'wtf',q:"Combien d’années encore l’incendie souterrain de Centralia pourrait-il brûler ?",n:250,min:0,max:400,u:"ans",e:"Un feu de décharge a atteint une veine de charbon en 1962, en Pennsylvanie. La ville a été évacuée et rayée des cartes. Le filon sous terre a de quoi alimenter les flammes deux siècles et demi."},
{t:'wtf',q:"Combien de jours de marche compte l’épreuve du kaihōgyō, chez les moines du mont Hiei ?",n:1000,min:0,max:1200,u:"jours",e:"Sept ans de course-marche autour de la montagne, jusqu’à 84 kilomètres par jour sur la fin. Le moine porte une corde et une lame : la tradition veut qu’il renonce à la vie s’il abandonne."},
{t:'wtf',q:"Combien pèse la boule de cristal qui descend à Times Square pour le Nouvel An ?",n:5386,min:0,max:6000,u:"kg",e:"Plus de cinq tonnes de triangles de cristal et de LED, pour une chute de vingt-trois mètres en soixante secondes. La toute première boule, en 1907, était en fer et en bois, avec cent ampoules."},
{t:'wtf',q:"Combien de masse le prototype international du kilogramme a-t-il perdu en un siècle ?",n:50,min:0,max:400,u:"microgrammes",e:"Le cylindre de platine iridié gardé sous trois cloches à Sèvres a maigri par rapport à ses copies. Comme il définissait le kilo, c’est le monde entier qui grossissait. On a changé la définition."},
{t:'wtf',q:"Combien d’heures dure « Logistics », le film le plus long jamais tourné ?",n:857,min:0,max:1000,u:"heures",e:"Trente-cinq jours de projection. Deux Suédois ont remonté à l’envers le trajet d’un podomètre, du magasin à l’usine chinoise, dont plusieurs semaines de plans fixes sur un cargo."},
{t:'wtf',q:"Combien de prises Stanley Kubrick a-t-il exigées pour la scène de l’escalier dans « Shining » ?",n:127,min:0,max:600,u:"prises",e:"Shelley Duvall a brandi sa batte de baseball cent vingt-sept fois, en larmes et perdant ses cheveux par poignées. Le tournage a duré plus d’un an pour un huis clos."},
{t:'wtf',q:"Combien de minutes a duré le plus long discours prononcé à l’Assemblée générale de l’ONU ?",n:269,min:0,max:1200,u:"minutes",e:"Fidel Castro, en 1960 : quatre heures et vingt-neuf minutes au pupitre, alors que le temps de parole conseillé est de quinze minutes. Les traducteurs se sont relayés plusieurs fois."},
{t:'wtf',q:"Combien de jours a duré le monstrueux embouteillage de Pékin, en 2010 ?",n:12,min:0,max:15,u:"jours",e:"Cent kilomètres de bouchon sur l’autoroute Pékin-Tibet, à cause de travaux et de convois de charbon. Des vendeurs ambulants sillonnaient les files, vendant nouilles et eau au triple du prix."},
{t:'wtf',q:"Quel âge avait le plus vieux message dans une bouteille jamais retrouvé ?",n:132,min:0,max:400,u:"ans",e:"Jetée d’un navire allemand en 1886 pour étudier les courants, la bouteille a été ramassée en 2018 sur une plage australienne par une famille en pique-nique. Le formulaire à l’intérieur était encore lisible."},
{t:'wtf',q:"Combien de canards en plastique sont tombés d’un cargo dans le Pacifique en 1992 ?",n:28800,min:0,max:50000,u:"canards",e:"Un conteneur passé par-dessus bord. Les jouets ont dérivé pendant des années, franchi le détroit de Béring pris dans les glaces, et échoué jusqu’en Écosse. Les océanographes s’en servent encore."},
{t:'wtf',q:"Combien de pièces de Lego un cargo a-t-il perdues au large de la Cornouailles en 1997 ?",n:4756940,min:0,max:8000000,u:"pièces",e:"Une vague scélérate emporte un conteneur du Tokio Express. Ironie du sort : le chargement comprenait des milliers de pièces sur le thème de la mer. On ramasse encore des poulpes verts sur les plages."},
{t:'wtf',q:"Combien de kilomètres le chien Bobbie a-t-il parcourus pour rentrer chez lui ?",n:4100,min:0,max:8000,u:"kilomètres",e:"Perdu dans l’Indiana pendant les vacances de ses maîtres, il traverse les États-Unis en six mois, l’hiver, et retrouve leur maison en Oregon, pattes en sang. Il est devenu une star nationale."},
{t:'wtf',q:"Quel âge avait Annie Edson Taylor quand elle a franchi les chutes du Niagara dans un tonneau ?",n:63,min:0,max:80,u:"ans",e:"Institutrice sans le sou, elle espérait faire fortune. Elle a testé le tonneau avec un chat, y est entrée avec un matelas et un coussin, et en est ressortie vivante. Elle est morte pauvre."},
{t:'wtf',q:"De quelle altitude Felix Baumgartner s’est-il jeté lors de son saut stratosphérique ?",n:38969,min:0,max:50000,u:"mètres",e:"Une capsule sous ballon d’hélium, une combinaison pressurisée, et une chute où il a passé le mur du son en tombant : 1 357 km/h, en vrille pendant plusieurs dizaines de secondes."},
{t:'wtf',q:"De combien d’étages Betty Lou Oliver est-elle tombée dans un ascenseur, en survivant ?",n:75,min:0,max:80,u:"étages",e:"Un bombardier B-25 percute l’Empire State Building en 1945. Blessée, elle est placée dans un ascenseur dont les câbles ont fondu. Les câbles entassés au fond de la cage ont amorti la chute."},
{t:'wtf',q:"Quelle longueur faisait le tunnel creusé pour le braquage de la Banque centrale de Fortaleza ?",n:78,min:0,max:150,u:"mètres",e:"Trois mois de creusement sous une fausse entreprise de gazon synthétique, avec éclairage et ventilation. Repartis avec 3,5 tonnes de billets usagés, non traçables : le plus gros butin de l’histoire du Brésil."},
{t:'wtf',q:"Combien d’heures a duré le plus long baiser homologué ?",n:58,min:0,max:400,u:"heures",e:"Un couple thaïlandais, en 2013 : cinquante-huit heures et trente-cinq minutes lèvres collées, debout, sans dormir. Boire à la paille était autorisé, se séparer une seconde non. Deux concurrents ont été hospitalisés."},
{t:'wtf',q:"Combien de jours un petit Cessna est-il resté en vol sans jamais se poser ?",n:64,min:0,max:400,u:"jours",e:"En 1958, deux hommes ont volé au-dessus du Nevada pendant plus de deux mois. Ravitaillement en essence et en nourriture en frôlant une voiture lancée sur une route droite du désert."},

/* ---------- Récits ---------- */
{t:'litt',q:"Combien d'éditeurs ont refusé le premier Harry Potter ?",n:12,min:0,max:80,u:"éditeurs",e:"12 refus avant que Bloomsbury n'accepte — sur les conseils de la fille de huit ans du patron, qui avait lu le premier chapitre."},
{t:'litt',q:"Combien de mots compte « À la recherche du temps perdu » ?",n:1267000,min:0,max:10000000,u:"mots",e:"Environ 1 267 000 mots, l'un des plus longs romans jamais publiés. À raison d'une page par jour, il faut plus de sept ans pour le lire."},
{t:'litt',q:"Combien de mois la Joconde est-elle restée disparue après son vol en 1911 ?",n:28,min:0,max:60,u:"mois",e:"28 mois. Le voleur l'avait cachée sous son lit à Paris. Paradoxe : c'est ce vol qui a rendu le tableau mondialement célèbre."},
{t:'litt',q:"Combien de semaines Anthony Burgess a-t-il mis à écrire « Orange mécanique » ?",n:3,min:0,max:4,u:"semaines",e:"Trois semaines, en 1961. On venait de lui diagnostiquer une tumeur au cerveau : il écrivait à toute vitesse pour laisser des droits d’auteur à sa femme. Le diagnostic était faux."},
{t:'litt',q:"Combien de jours Stevenson a-t-il mis à écrire la première version de « L’Étrange Cas du docteur Jekyll » ?",n:3,min:0,max:6,u:"jours",e:"Trois jours de transe, après un cauchemar. Sa femme trouva le texte raté : il jeta le manuscrit au feu et recommença tout, en trois jours de plus."},
{t:'litt',q:"Quelle longueur faisait le rouleau de papier sur lequel Kerouac a tapé « Sur la route » ?",n:36,min:0,max:80,u:"mètres",e:"Trente-six mètres de feuilles collées bout à bout, tapées en trois semaines et quasiment sans ponctuation. Kerouac refusait de perdre le fil en changeant de page."},
{t:'litt',q:"Combien de jours Stendhal a-t-il mis à dicter « La Chartreuse de Parme » ?",n:52,min:0,max:100,u:"jours",e:"Cinquante-deux jours, fin 1838. Près de cinq cents pages dictées d’une traite à un secrétaire. Balzac, enthousiaste, lui suggéra ensuite de tout réécrire : Stendhal n’en fit rien."},
{t:'litt',q:"Combien de jours Dostoïevski a-t-il mis à écrire « Le Joueur » ?",n:26,min:0,max:100,u:"jours",e:"Vingt-six jours, sous un contrat léonin : sans livre à la date prévue, il perdait les droits sur toute son œuvre. Il dicta le roman à une sténographe… qu’il épousa."},
{t:'litt',q:"Combien de jours Faulkner a-t-il mis à écrire « Tandis que j’agonise » ?",n:47,min:0,max:80,u:"jours",e:"Quarante-sept jours, écrits la nuit sur une brouette renversée pendant ses gardes à la centrale électrique de l’université. Il affirmait n’avoir ensuite changé aucun mot."},
{t:'litt',q:"Combien de jours le marquis de Sade a-t-il mis à écrire « Les Cent Vingt Journées de Sodome » à la Bastille ?",n:37,min:0,max:80,u:"jours",e:"Trente-sept nuits de l’automne 1785, à la bougie. Il crut le manuscrit perdu lors de la prise de la Bastille et dit en avoir pleuré des larmes de sang."},
{t:'litt',q:"Quelle longueur faisait le rouleau de papier que Sade cachait dans sa cellule de la Bastille ?",n:12,min:0,max:50,u:"mètres",e:"Douze mètres de feuillets collés, larges de onze centimètres, couverts recto verso d’une écriture minuscule, puis enroulés pour tenir dans une fente du mur de sa cellule."},
{t:'litt',q:"Combien d’heures d’affilée Kafka a-t-il mis à écrire « Le Verdict » ?",n:8,min:0,max:10,u:"heures",e:"Huit heures d’une seule traite, de vingt-deux heures à six heures du matin. Il nota dans son journal que seule cette façon d’écrire, corps et âme ouverts, valait quelque chose."},
{t:'litt',q:"Combien de mois García Márquez a-t-il mis à écrire « Cent ans de solitude » ?",n:18,min:0,max:100,u:"mois",e:"Dix-huit mois enfermé, sa femme faisant crédit chez les commerçants. Au moment de poster le manuscrit, il n’avait de quoi n’en envoyer que la moitié — et envoya la mauvaise."},
{t:'litt',q:"Combien de semaines Dickens a-t-il mis à écrire « Un chant de Noël » ?",n:6,min:0,max:10,u:"semaines",e:"Six semaines, à l’automne 1843, en marchant la nuit dans Londres. Endetté, il finança lui-même une édition dorée sur tranche : triomphe immédiat, bénéfices dérisoires."},
{t:'litt',q:"Combien d’années Tolstoï a-t-il mis à écrire « Guerre et Paix » ?",n:6,min:0,max:20,u:"années",e:"Six ans. Sa femme Sofia aurait recopié le manuscrit entier sept fois à la main, à la bougie, en déchiffrant des ratures que lui seul comprenait."},
{t:'litt',q:"Combien de pages de brouillon Flaubert a-t-il noircies pour « Madame Bovary » ?",n:4500,min:0,max:25000,u:"pages",e:"Environ 4500 pages de brouillons conservées à Rouen, pour un roman d’à peine cinq cents. Flaubert gueulait ses phrases à voix haute pour en éprouver le rythme."},
{t:'litt',q:"Combien d’années Tolkien a-t-il mis à écrire « Le Seigneur des anneaux » ?",n:12,min:0,max:20,u:"années",e:"Douze ans, de 1937 à 1949, entre deux copies d’étudiants. Il tapa deux fois le manuscrit entier avec deux doigts, en équilibre sur son lit, faute de bureau."},
{t:'litt',q:"Combien d’années Joyce a-t-il mis à écrire « Ulysse » ?",n:7,min:0,max:40,u:"années",e:"Sept ans pour raconter une seule journée à Dublin, le 16 juin 1904. Joyce disait y avoir mis assez d’énigmes pour occuper les professeurs pendant des siècles."},
{t:'litt',q:"Combien d’années Joyce a-t-il mis à écrire « Finnegans Wake » ?",n:17,min:0,max:25,u:"années",e:"Dix-sept ans, quasi aveugle, traçant d’énormes lettres au crayon gras. Le livre mêle une soixantaine de langues et reste, un siècle plus tard, largement illisible."},
{t:'litt',q:"Combien de mots Anthony Trollope s’imposait-il d’écrire par quart d’heure ?",n:250,min:0,max:600,u:"mots",e:"Deux cent cinquante mots tous les quarts d’heure, montre posée devant lui, de cinq heures et demie à huit heures du matin — avant de partir travailler à la poste."},
{t:'litt',q:"Combien de mots Ian Fleming s’imposait-il chaque jour en écrivant ses James Bond ?",n:2000,min:0,max:2500,u:"mots",e:"Deux mille mots par jour, pendant deux mois d’hiver dans sa villa jamaïcaine. Il s’interdisait de se relire avant la fin : un Bond était bouclé en huit semaines."},
{t:'litt',q:"Combien d’éditeurs ont refusé « Dune » de Frank Herbert ?",n:23,min:0,max:60,u:"éditeurs",e:"Vingt-trois refus, avant qu’un éditeur de manuels de réparation automobile n’accepte le pari. « Dune » est depuis le roman de science-fiction le plus vendu de l’histoire."},
{t:'litt',q:"Combien d’éditeurs ont refusé « Traité du zen et de l’entretien des motocyclettes » ?",n:121,min:0,max:150,u:"éditeurs",e:"Cent vingt et un refus, record homologué par le Guinness pour un futur best-seller. Le suivant versa 3000 dollars en pensant ne jamais les revoir : il s’en vendit des millions."},
{t:'litt',q:"Combien de fois « Carrie » de Stephen King a-t-il été refusé avant d’être publié ?",n:30,min:0,max:300,u:"refus",e:"Trente refus. King avait jeté les premières pages à la poubelle ; sa femme les en sortit et l’obligea à continuer. Les droits de poche rapportèrent ensuite 400000 dollars."},
{t:'litt',q:"Combien d’éditeurs ont refusé « Autant en emporte le vent » de Margaret Mitchell ?",n:38,min:0,max:200,u:"éditeurs",e:"Trente-huit refus. Le manuscrit dormait en piles désordonnées sous un divan et l’héroïne s’appelait Pansy. Le roman décrocha le Pulitzer ; Mitchell n’en écrivit jamais d’autre."},
{t:'litt',q:"Combien d’éditeurs ont refusé « Gens de Dublin » de James Joyce ?",n:22,min:0,max:30,u:"éditeurs",e:"Vingt-deux refus en neuf ans. Un imprimeur, effrayé par le texte, détruisit les feuilles déjà composées. Joyce dut attendre 1914 pour voir ses nouvelles enfin paraître."},
{t:'litt',q:"Combien d’exemplaires s’est-il vendu du premier recueil de poèmes des sœurs Brontë ?",n:2,min:0,max:2.5,u:"exemplaires",e:"Deux. Publié à compte d’auteur sous les pseudonymes masculins Currer, Ellis et Acton Bell. L’année suivante paraissaient « Jane Eyre » et « Les Hauts de Hurlevent »."},
{t:'litt',q:"Combien d’exemplaires de « Pierre Lapin » Beatrix Potter a-t-elle fait imprimer à ses frais ?",n:250,min:0,max:1000,u:"exemplaires",e:"Deux cent cinquante, payés de sa poche après six refus d’éditeurs. Le petit lapin en veste bleue s’est depuis vendu à des dizaines de millions d’exemplaires."},
{t:'litt',q:"Combien d’exemplaires de « Moby Dick » se sont vendus aux États-Unis du vivant de Melville ?",n:3215,min:0,max:6000,u:"exemplaires",e:"3215 exemplaires en quarante ans, soit environ 556 dollars de droits d’auteur. Melville finit inspecteur des douanes à New York ; sa nécrologie orthographiait mal son nom."},
{t:'litt',q:"Combien Ray Bradbury a-t-il dépensé en location de machine à écrire pour taper « Fahrenheit 451 » ?",n:9.8,min:0,max:12,u:"dollars",e:"Neuf dollars quatre-vingts, à dix cents la demi-heure sur une machine à pièces, au sous-sol de la bibliothèque d’UCLA. Il y descendait pour fuir le vacarme de ses enfants."},
{t:'litt',q:"Combien Stephen King a-t-il touché comme avance pour l’édition reliée de « Carrie » ?",n:2500,min:0,max:4000,u:"dollars",e:"2500 dollars. Il vivait en caravane et enseignait l’anglais. Quelques mois plus tard, les droits de poche partaient pour 400000 dollars : il dut s’asseoir pour encaisser la nouvelle."},
{t:'litt',q:"Combien Bloomsbury a-t-il avancé à J. K. Rowling pour le premier « Harry Potter » ?",n:1500,min:0,max:2000,u:"livres sterling",e:"1500 livres, avec le conseil de garder un vrai métier : la littérature jeunesse ne nourrit pas son auteur. La décision de publier avait été emportée par la fille de huit ans du patron."},
{t:'litt',q:"Combien Jane Austen a-t-elle touché en vendant les droits d’« Orgueil et Préjugés » ?",n:110,min:0,max:400,u:"livres sterling",e:"Cent dix livres, à forfait, en 1812. Elle ne vit jamais un centime des ventes suivantes et publia toute sa vie anonymement, signée « une dame »."},
{t:'litt',q:"Combien Milton a-t-il touché en tout pour « Le Paradis perdu » ?",n:10,min:0,max:25,u:"livres sterling",e:"Dix livres, en deux versements de cinq. Devenu aveugle, il composait la nuit dans sa tête une dizaine de vers et attendait le matin qu’on vienne, disait-il, le traire."},
{t:'litt',q:"Combien vaut le chèque remis au lauréat du prix Goncourt ?",n:10,min:0,max:15,u:"euros",e:"Dix euros, un chèque que les lauréats encadrent au lieu de l’encaisser. Le vrai prix est ailleurs : quelques centaines de milliers d’exemplaires vendus dans les semaines qui suivent."},
{t:'litt',q:"Combien Mark Twain a-t-il perdu en investissant dans une machine à composer les caractères ?",n:300000,min:0,max:400000,u:"dollars",e:"Environ 300000 dollars de l’époque engloutis dans la machine Paige, rendue obsolète par la Linotype. Ruiné, Twain repartit en tournée de conférences autour du monde pour éponger ses dettes."},
{t:'litt',q:"Quel a été le premier tirage de « Harry Potter à l’école des sorciers » ?",n:500,min:0,max:1000,u:"exemplaires",e:"Cinq cents exemplaires, dont trois cents expédiés en bibliothèque. Les rares survivants en bon état se négocient aujourd’hui plusieurs dizaines de milliers d’euros pièce."},
{t:'litt',q:"Quel a été le premier tirage du « Hobbit » de Tolkien ?",n:1500,min:0,max:6000,u:"exemplaires",e:"1500 exemplaires en 1937, épuisés en trois mois. Le manuscrit avait été validé par le fils de dix ans de l’éditeur, payé un shilling pour son rapport de lecture."},
{t:'litt',q:"Quel a été le premier tirage de « Frankenstein » de Mary Shelley ?",n:500,min:0,max:1000,u:"exemplaires",e:"Cinq cents exemplaires, publiés anonymement en 1818. Beaucoup crurent l’auteur masculin : Mary Shelley avait dix-huit ans quand elle commença le roman, lors d’un concours d’histoires de fantômes."},
{t:'litt',q:"Combien d’exemplaires comptait la première édition d’« Ulysse » de Joyce ?",n:1000,min:0,max:1200,u:"exemplaires",e:"Mille, imprimés à Paris par la libraire Sylvia Beach parce qu’aucun éditeur anglophone n’osait s’y risquer. Des exemplaires furent saisis et brûlés par la douane américaine."},
{t:'litt',q:"Combien d’exemplaires d’« Un chant de Noël » se sont vendus dans la première semaine ?",n:6000,min:0,max:25000,u:"exemplaires",e:"Six mille, écoulés avant même le soir de Noël 1843. Mais Dickens avait exigé une reliure luxueuse à prix cassé : le triomphe ne lui rapporta presque rien."},
{t:'litt',q:"À combien d’exemplaires les livraisons mensuelles des « Papiers posthumes du Pickwick Club » sont-elles montées ?",n:40000,min:0,max:400000,u:"exemplaires",e:"De quatre cents exemplaires au premier fascicule à quarante mille au dernier. Dickens avait vingt-quatre ans ; son illustrateur s’était suicidé après le deuxième numéro."},
{t:'litt',q:"À combien d’exemplaires « L’Aurore » a-t-elle tiré le jour du « J’accuse » de Zola ?",n:300000,min:0,max:400000,u:"exemplaires",e:"Trois cent mille, contre trente mille d’ordinaire, vendus à la criée dans Paris en quelques heures. Zola fut condamné à un an de prison et s’enfuit à Londres."},
{t:'litt',q:"Combien d’exemplaires du « Petit Livre rouge » de Mao ont été imprimés ?",n:1000000000,min:0,max:1200000000,u:"exemplaires",e:"Plus d’un milliard, ce qui en fait l’un des livres les plus imprimés de l’histoire. Circuler sans l’avoir sur soi pouvait valoir de très sérieux ennuis."},
{t:'litt',q:"Combien de mots compte la plus longue phrase des « Misérables » ?",n:823,min:0,max:5000,u:"mots",e:"823 mots d’un seul souffle, souvent citée comme la plus longue phrase de la littérature française. Hugo y déroule tout le Paris politique en une cascade de propositions."},
{t:'litt',q:"Combien de mots compte la plus longue phrase jamais publiée dans un roman anglais, signée Jonathan Coe ?",n:13955,min:0,max:60000,u:"mots",e:"13955 mots sans le moindre point, à la fin de « Bienvenue au club ». Coe voulait détrôner le monologue final d’« Ulysse » : c’est fait, et très largement."},
{t:'litt',q:"Combien de mots compte « Gadsby », le roman écrit sans jamais employer la lettre e ?",n:50110,min:0,max:80000,u:"mots",e:"50110 mots sans un seul e, en anglais. Wright avait bloqué la touche E de sa machine pour ne pas tricher. Paru en 1939, le livre fut un échec complet."},
{t:'litt',q:"Combien de mots compte « Harry Potter et l’Ordre du Phénix », le plus long de la série ?",n:257045,min:0,max:300000,u:"mots",e:"257045 mots, soit plus de trois fois le premier tome. Rowling refusa la moindre coupe et ses éditeurs, devant le succès, n’insistèrent pas."},
{t:'litt',q:"Combien de mots compte l’ensemble des sept « Harry Potter » ?",n:1084170,min:0,max:6000000,u:"mots",e:"1084170 mots. Lus à voix haute, cela représente environ cent vingt heures : cinq jours et cinq nuits sans dormir ni cesser de parler."},
{t:'litt',q:"Combien de mots compte « Guerre et Paix » ?",n:587000,min:0,max:4000000,u:"mots",e:"Environ 587000 mots, soit une soixantaine d’heures de lecture. Tolstoï refusait d’appeler cela un roman : ni roman, disait-il, ni poème, ni chronique historique."},
{t:'litt',q:"Combien de mots compte la Bible du roi Jacques ?",n:783137,min:0,max:2500000,u:"mots",e:"783137 mots, traduits en sept ans par quarante-sept savants répartis en six comités séparés. Une bonne part des expressions courantes de l’anglais en sort directement."},
{t:'litt',q:"Combien de mots compte l’œuvre complète de Shakespeare ?",n:884647,min:0,max:5000000,u:"mots",e:"884647 mots pour l’ensemble des pièces et des poèmes, dont environ 31000 mots différents. On lui attribue le premier emploi écrit de près de 1700 d’entre eux."},
{t:'litt',q:"Combien de mots compte le Mahabharata, la plus longue épopée du monde ?",n:1800000,min:0,max:6000000,u:"mots",e:"Environ 1,8 million de mots : près de dix fois l’Iliade et l’Odyssée réunies. Le texte a été récité de mémoire pendant des siècles avant d’être fixé par écrit."},
{t:'litt',q:"Combien de mots compte le journal intime le plus long jamais tenu ?",n:37500000,min:0,max:50000000,u:"mots",e:"37,5 millions de mots. L’Américain Robert Shields consignait sa vie par tranches de cinq minutes et se réveillait toutes les deux heures pour noter ses rêves."},
{t:'litt',q:"Combien de mots compte le journal de Samuel Pepys ?",n:1250000,min:0,max:2000000,u:"mots",e:"Environ 1,25 million de mots en dix ans, écrits en sténographie pour que nul ne lise ses infidélités. Il y raconte l’incendie de Londres et l’enfouissement de son fromage."},
{t:'litt',q:"Combien de pages compte « Artamène », le plus long roman jamais publié en français ?",n:13095,min:0,max:20000,u:"pages",e:"13095 pages en dix volumes, signées Madeleine de Scudéry au XVIIe siècle. Environ deux millions de mots : quatre fois « Guerre et Paix », et le tout se lisait en salon."},
{t:'litt',q:"Combien de personnages nommés compte « Guerre et Paix » ?",n:559,min:0,max:600,u:"personnages",e:"559, dont près de deux cents ayant réellement existé. Les éditions modernes ajoutent un index : sans lui, beaucoup de lecteurs se perdent dès la deuxième soirée mondaine."},
{t:'litt',q:"Combien de personnages peuplent « La Comédie humaine » de Balzac ?",n:2472,min:0,max:10000,u:"personnages",e:"2472 personnages recensés, dont plusieurs centaines reviennent d’un roman à l’autre. Agonisant, Balzac aurait réclamé son propre médecin de fiction, le docteur Bianchon."},
{t:'litt',q:"Combien de tasses de café Balzac buvait-il par jour dans ses périodes d’écriture ?",n:50,min:0,max:60,u:"tasses",e:"Jusqu’à cinquante, souvent à jeun et parfois en croquant la mouture. Il écrivait quinze heures d’affilée en robe de chambre et est mort à cinquante et un ans."},
{t:'litt',q:"Combien d’œuvres Balzac avait-il prévues pour « La Comédie humaine » ?",n:137,min:0,max:400,u:"œuvres",e:"Cent trente-sept, dont il n’acheva que quatre-vingt-onze. Le plan complet aurait couvert toute la société française : il est mort en pleine construction de sa cathédrale."},
{t:'litt',q:"Combien de chapitres compte « Moby Dick » ?",n:135,min:0,max:150,u:"chapitres",e:"135 chapitres et un épilogue, dont des dizaines consacrés à la baleine elle-même : anatomie, peinture, cuisine, cordages. Le monstre n’apparaît vraiment que dans les dernières pages."},
{t:'litt',q:"Combien de chapitres compte « Don Quichotte » ?",n:126,min:0,max:400,u:"chapitres",e:"126 chapitres en deux parties séparées de dix ans. Entre les deux, un inconnu publia une suite pirate : Cervantès se vengea en faisant croiser à ses héros les personnages du faussaire."},
{t:'litt',q:"Combien de chapitres compte « Le Petit Prince » ?",n:27,min:0,max:30,u:"chapitres",e:"Vingt-sept chapitres, souvent d’une seule page. Saint-Exupéry a peint lui-même les aquarelles et refait son petit prince des dizaines de fois pour lui trouver le bon regard."},
{t:'litt',q:"Combien de chapitres compte « La Vie mode d’emploi » de Georges Perec ?",n:99,min:0,max:120,u:"chapitres",e:"Quatre-vingt-dix-neuf. Perec visite un immeuble parisien case par case, comme un cavalier d’échecs sur un damier de cent pièces : il a volontairement sauté la centième."},
{t:'litt',q:"En combien de phrases s’écrit le dernier chapitre d’« Ulysse » de Joyce ?",n:8,min:0,max:40,u:"phrases",e:"Huit phrases pour une quarantaine de pages, sans ponctuation, dans la tête de Molly Bloom qui glisse vers le sommeil. Le dernier mot du livre est « oui »."},
{t:'litt',q:"Combien de narrateurs différents racontent « Tandis que j’agonise » de Faulkner ?",n:15,min:0,max:40,u:"narrateurs",e:"Quinze voix se relaient, dont celle de la morte elle-même, pour raconter un enterrement qui tourne au désastre. Au lecteur de reconstituer l’histoire par recoupements."},
{t:'litt',q:"Combien de mots compte le plus court chapitre de « Tandis que j’agonise » ?",n:5,min:0,max:8,u:"mots",e:"Cinq mots en anglais : « Ma mère est un poisson. » C’est tout le chapitre, signé par le plus jeune fils, et l’une des phrases les plus commentées du roman."},
{t:'litt',q:"Combien de notes de fin compte « L’Infinie Comédie » de David Foster Wallace ?",n:388,min:0,max:500,u:"notes",e:"388 notes rejetées en fin de volume, dont certaines font plusieurs pages et possèdent leurs propres notes. Les lecteurs tiennent deux marque-pages en permanence."},
{t:'litt',q:"Combien de lettres compte le premier « mot-tonnerre » de « Finnegans Wake » ?",n:100,min:0,max:150,u:"lettres",e:"Cent lettres d’affilée pour imiter le fracas de la chute d’Adam. Joyce en a semé dix dans le livre ; le dernier en compte cent une, pour faire déborder le compte."},
{t:'litt',q:"Combien de poèmes différents peut-on former avec les « Cent mille milliards de poèmes » de Queneau ?",n:100000000000000,min:0,max:400000000000000,u:"poèmes",e:"Dix sonnets découpés vers par vers en languettes : chaque ligne peut venir de n’importe lequel. Queneau calcula qu’en lisant jour et nuit, il faudrait des millions d’années pour tout épuiser."},
{t:'litt',q:"Avec combien de mots différents « Green Eggs and Ham » de Dr Seuss a-t-il été écrit ?",n:50,min:0,max:120,u:"mots différents",e:"Cinquante, pas un de plus : son éditeur avait parié cinquante dollars qu’il n’y arriverait pas. L’album est devenu l’un des livres pour enfants les plus vendus au monde."},
{t:'litt',q:"Combien de mots différents contient « Le Chat chapeauté » de Dr Seuss ?",n:236,min:0,max:1000,u:"mots différents",e:"236, puisés dans une liste de vocabulaire imposée aux jeunes lecteurs. L’album devait prouver qu’un livre d’apprentissage pouvait être plus drôle que les manuels scolaires de l’époque."},
{t:'litt',q:"Combien de souvenirs Georges Perec a-t-il alignés dans « Je me souviens » ?",n:480,min:0,max:2500,u:"souvenirs",e:"480 souvenirs minuscules commençant tous par « Je me souviens ». Le livre s’achève sur des pages blanches, laissées au lecteur pour qu’il y inscrive les siens."},
{t:'litt',q:"Combien de mots compte la nouvelle la plus courte attribuée à Hemingway ?",n:6,min:0,max:20,u:"mots",e:"Six mots en anglais : « À vendre : chaussons de bébé, jamais portés. » L’histoire du pari qu’il aurait gagné avec est probablement une légende, mais elle lui colle à la peau."},
{t:'litt',q:"Combien de romans policiers Agatha Christie a-t-elle écrits ?",n:66,min:0,max:80,u:"romans",e:"Soixante-six romans policiers, plus des recueils de nouvelles et des pièces de théâtre. Elle affirmait avoir eu ses meilleures idées de crime dans sa baignoire, en mangeant des pommes."},
{t:'litt',q:"Combien de romans Barbara Cartland a-t-elle publiés ?",n:723,min:0,max:800,u:"romans",e:"723 romans sentimentaux, dictés allongée sur un divan à des secrétaires qui se relayaient, une couverture de fourrure sur les jambes et un chien sur les genoux."},
{t:'litt',q:"Combien de romans Barbara Cartland a-t-elle publiés en une seule année ?",n:23,min:0,max:30,u:"romans",e:"Vingt-trois en 1983, record homologué : un roman toutes les deux semaines et demie. Elle dictait plusieurs milliers de mots chaque après-midi sans jamais se relire."},
{t:'litt',q:"Combien de romans mettant en scène le commissaire Maigret Simenon a-t-il écrits ?",n:75,min:0,max:150,u:"romans",e:"Soixante-quinze romans, plus vingt-huit nouvelles. Simenon bouclait un Maigret en une dizaine de jours d’isolement total et passait un examen médical avant chaque livre."},
{t:'litt',q:"Combien d’exemplaires de sa Bible Gutenberg a-t-il imprimés ?",n:180,min:0,max:300,u:"exemplaires",e:"Environ 180, dont une quarantaine sur parchemin — il fallait la peau de plus de cent cinquante veaux pour un seul exemplaire. Gutenberg fit faillite avant d’avoir vendu son stock."},
{t:'litt',q:"Combien d’exemplaires de la Bible de Gutenberg subsistent aujourd’hui ?",n:49,min:0,max:120,u:"exemplaires",e:"Quarante-neuf, dont une vingtaine seulement sont complets. Le dernier passé en salle des ventes l’a été en 1978 : les autres ne quitteront plus jamais leurs bibliothèques."},
{t:'litt',q:"Combien de lignes par colonne compte la Bible de Gutenberg, qui lui vaut son surnom ?",n:42,min:0,max:120,u:"lignes",e:"Quarante-deux, d’où le nom de « Bible à 42 lignes ». Gutenberg avait commencé à quarante, puis resserré la composition pour économiser le parchemin, hors de prix."},
{t:'litt',q:"Combien pèse le Codex Gigas, le plus grand manuscrit médiéval conservé ?",n:75,min:0,max:200,u:"kilos",e:"Soixante-quinze kilos pour quatre-vingt-douze centimètres de haut. La légende veut qu’un moine l’ait écrit en une nuit avec l’aide du diable, dont le portrait occupe une page entière."},
{t:'litt',q:"Combien de pages compte le manuscrit de Voynich, toujours indéchiffré ?",n:240,min:0,max:600,u:"pages",e:"Environ 240 pages de plantes inconnues, de femmes dans des bassins et d’une écriture que personne n’a jamais lue. Le parchemin date du XVe siècle : ce n’est pas un faux récent."},
{t:'litt',q:"Combien de feuillets compte le Livre de Kells ?",n:340,min:0,max:600,u:"feuillets",e:"340 feuillets de vélin enluminés par des moines irlandais vers l’an 800. Une seule page peut cacher des centaines d’entrelacs invisibles à l’œil nu sans loupe."},
{t:'litt',q:"Combien de volumes comptait l’encyclopédie chinoise du Yongle Dadian ?",n:11095,min:0,max:40000,u:"volumes",e:"11095 volumes copiés à la main par plus de deux mille lettrés au XVe siècle. Jamais imprimée faute de moyens, elle a presque entièrement disparu : moins de quatre cents volumes subsistent."},
{t:'litt',q:"De combien d’années le Jikji coréen précède-t-il la Bible de Gutenberg ?",n:78,min:0,max:500,u:"années",e:"Soixante-dix-huit ans. Imprimé en 1377 avec des caractères métalliques mobiles, ce recueil bouddhiste est conservé à Paris. L’Europe croyait avoir tout inventé."},
{t:'litt',q:"Combien de rouleaux carbonisés a-t-on retrouvés dans la villa des Papyrus à Herculanum ?",n:1800,min:0,max:15000,u:"rouleaux",e:"Environ 1800 rouleaux changés en charbon par le Vésuve. Toute tentative de les dérouler les détruisait ; on commence seulement à les lire par scanner et intelligence artificielle."},
{t:'litt',q:"Quelle longueur fait le grand rouleau d’Isaïe, le plus complet des manuscrits de la mer Morte ?",n:7.34,min:0,max:12,u:"mètres",e:"7,34 mètres de peaux cousues bout à bout, vieilles de plus de deux mille ans, retrouvées dans une jarre par un berger. Le texte est presque identique aux bibles hébraïques actuelles."},
{t:'litt',q:"Combien de lettres compte exactement un rouleau de la Torah ?",n:304805,min:0,max:600000,u:"lettres",e:"304805 lettres tracées à la main par un scribe, à raison d’environ un an de travail. Une seule erreur rend le rouleau inutilisable pour la lecture publique tant qu’elle n’est pas corrigée."},
{t:'litt',q:"Combien de feuillets compte le Talmud de Babylone ?",n:2711,min:0,max:3000,u:"feuillets",e:"2711 feuillets. Le cycle mondial qui consiste à en étudier un par jour dure sept ans et cinq mois ; des dizaines de milliers de personnes le suivent au même rythme."},
{t:'litt',q:"Combien d’années a duré la fabrication de la première édition de l’Oxford English Dictionary ?",n:70,min:0,max:250,u:"années",e:"Soixante-dix ans, de l’idée lancée en 1857 au dernier fascicule de 1928. Les éditeurs avaient prévu dix ans. James Murray, mort en 1915, n’en vit jamais la fin."},
{t:'litt',q:"Combien de sens le mot anglais « set » comptait-il dans la première édition de l’Oxford English Dictionary ?",n:430,min:0,max:2500,u:"sens",e:"430 sens, record absolu du dictionnaire : des dizaines de colonnes pour un mot de trois lettres. La révision moderne en a encore ajouté quelques centaines."},
{t:'litt',q:"Combien de citations un pensionnaire d’asile a-t-il fournies à l’Oxford English Dictionary ?",n:10000,min:0,max:15000,u:"citations",e:"Environ dix mille, envoyées par William Minor, chirurgien américain interné pour meurtre. Le rédacteur en chef, qui le croyait médecin de l’établissement, ne découvrit la vérité qu’après des années."},
{t:'litt',q:"Combien d’articles compte l’Encyclopédie de Diderot et d’Alembert ?",n:71818,min:0,max:80000,u:"articles",e:"71818 articles en dix-sept volumes de texte et onze de planches. Vingt ans de travail, deux interdictions royales, et un éditeur qui censurait en douce les passages les plus explosifs."},
{t:'litt',q:"Combien d’années a duré la rédaction du grand dictionnaire allemand commencé par les frères Grimm ?",n:123,min:0,max:150,u:"années",e:"123 ans, de 1838 à 1961. Les Grimm, morts en pleine lettre F, tenaient ce dictionnaire pour l’œuvre de leur vie ; la postérité n’a retenu que leurs contes."},
{t:'litt',q:"À quel âge Rimbaud a-t-il définitivement cessé d’écrire de la poésie ?",n:20,min:0,max:50,u:"ans",e:"Vingt ans. Toute son œuvre tient en quatre ou cinq années d’adolescence. Il partit ensuite trafiquer armes et café en Abyssinie et mourut à trente-sept ans, ignorant sa gloire."},
{t:'litt',q:"Combien d’années après leur condamnation les poèmes censurés des « Fleurs du mal » ont-ils été réhabilités ?",n:92,min:0,max:300,u:"années",e:"Quatre-vingt-douze ans. Six poèmes interdits en 1857 pour outrage aux bonnes mœurs, Baudelaire condamné à une amende. La Cour de cassation n’a annulé le jugement qu’en 1949."},
{t:'litt',q:"Combien d’années séparent les deux seuls romans publiés par Harper Lee ?",n:55,min:0,max:300,u:"années",e:"Cinquante-cinq ans. Après « Ne tirez pas sur l’oiseau moqueur », elle n’a plus rien publié jusqu’à un manuscrit de jeunesse sorti quelques mois avant sa mort, dans des conditions contestées."},
{t:'litt',q:"Combien d’années Salinger a-t-il vécu sans rien publier ?",n:45,min:0,max:60,u:"années",e:"Quarante-cinq ans, de 1965 à sa mort en 2010, retiré dans le New Hampshire. Il continuait d’écrire chaque jour dans un abri de béton, sans montrer une ligne à quiconque."},
{t:'litt',q:"Combien d’années après la mort de son auteur « La Conjuration des imbéciles » a-t-il été publié ?",n:11,min:0,max:15,u:"années",e:"Onze ans. John Kennedy Toole s’était suicidé après une avalanche de refus ; sa mère harcela un professeur d’université jusqu’à ce qu’il lise le carbone. Prix Pulitzer à titre posthume."},
{t:'litt',q:"Combien d’années le premier roman refusé de Jules Verne a-t-il attendu avant d’être publié ?",n:131,min:0,max:400,u:"années",e:"131 ans. « Paris au XXe siècle », jugé trop noir par son éditeur en 1863, a dormi dans un coffre de famille jusqu’à sa redécouverte, et n’est paru qu’en 1994."},
{t:'litt',q:"Combien de jours Anne Frank est-elle restée cachée dans l’Annexe ?",n:761,min:0,max:4000,u:"jours",e:"761 jours à huit personnes dans quelques pièces derrière une bibliothèque pivotante, sans jamais sortir ni écarter un rideau. Le journal s’interrompt trois jours avant l’arrestation."},
{t:'litt',q:"Combien de romans inachevés de Terry Pratchett ont été écrasés par un rouleau compresseur ?",n:10,min:0,max:15,u:"romans",e:"Dix, sur un disque dur broyé en 2017 selon sa volonté testamentaire, sous les chenilles d’un rouleau compresseur à vapeur. Les débris sont aujourd’hui exposés dans un musée."},

/* ---------- Sons ---------- */
{t:'musique',q:"Combien de personnes ont assisté au plus grand concert de l'histoire ?",n:3500000,min:0,max:10000000,u:"personnes",e:"3,5 millions sur la plage de Copacabana pour Rod Stewart, au Nouvel An 1994. La foule dépassait la population de nombreux pays."},
{t:'musique',q:"Quel niveau sonore atteint une vuvuzela à un mètre ?",n:127,min:0,max:200,u:"décibels",e:"127 décibels, plus qu'un marteau-piqueur ou une tronçonneuse. Les médecins ont recommandé des bouchons d'oreilles pendant la Coupe du monde 2010."},
{t:'musique',q:"Combien de temps doit durer l’exécution intégrale d’« Organ²/ASLSP » de John Cage à Halberstadt ?",n:639,min:0,max:800,u:"ans",e:"Un orgue allemand joue la pièce depuis 2001 : fin prévue en 2640. Les changements d’accord attirent des centaines de curieux, parfois à sept ans d’intervalle. Les tuyaux sont ajoutés au fur et à mesure."},
{t:'musique',q:"Par combien de temps de silence a commencé cette exécution de Cage à Halberstadt ?",n:17,min:0,max:20,u:"mois",e:"La partition débute par une pause. Le public est venu assister au lancement en 2001… et n’a rien entendu pendant un an et demi, jusqu’au premier accord de 2003."},
{t:'musique',q:"Combien de secondes dure « 4’33” » de John Cage ?",n:273,min:0,max:300,u:"secondes",e:"Quatre minutes trente-trois de silence en trois mouvements. Le pianiste ouvre et referme le couvercle. Cage soutenait que la vraie musique était la toux du public et la pluie sur le toit."},
{t:'musique',q:"Combien de fois faut-il répéter le même motif dans « Vexations » d’Erik Satie ?",n:840,min:0,max:1200,u:"fois",e:"Satie a griffonné « 840 fois » en marge. La première exécution intégrale, en 1963, a demandé une relève de pianistes et duré plus de dix-huit heures. Un spectateur a tenu jusqu’au bout."},
{t:'musique',q:"Combien de temps doit jouer sans se répéter la composition « Longplayer » de Jem Finer ?",n:1000,min:0,max:2500,u:"ans",e:"Lancée le 31 décembre 1999 à Londres, l’œuvre pour bols tibétains est générée par ordinateur et ne doit boucler qu’en l’an 2999. Une fondation a été créée pour la maintenir en vie."},
{t:'musique',q:"Combien de temps dure « You Suffer » de Napalm Death, la chanson la plus courte jamais enregistrée ?",n:1.316,min:0,max:8,u:"secondes",e:"Guinness l’a homologuée. Le morceau compte quatre mots hurlés : « You suffer, but why ? ». En concert, le groupe la joue parfois deux fois de suite, car personne n’a le temps de réagir."},
{t:'musique',q:"Combien de temps dure « Her Majesty », le morceau caché d’Abbey Road des Beatles ?",n:23,min:0,max:40,u:"secondes",e:"McCartney trouvait la chansonnette ratée et avait demandé qu’on la coupe. L’ingénieur, à qui on interdisait de jeter la moindre bande, l’a recollée à la fin : elle est restée sur le disque."},
{t:'musique',q:"Combien de secondes dure « Bohemian Rhapsody » de Queen ?",n:355,min:0,max:400,u:"secondes",e:"Cinq minutes cinquante-cinq, une éternité pour une radio de 1975. Le label voulait couper ; Freddie Mercury a refusé et fait passer le morceau en douce à un DJ, qui l’a diffusé quatorze fois."},
{t:'musique',q:"Combien de couches vocales superposées compte le passage opéra de « Bohemian Rhapsody » ?",n:180,min:0,max:1200,u:"couches",e:"Environ 180 empilements de Mercury, May et Taylor. À force de repasser la bande, l’oxyde s’effaçait : en la regardant à contre-jour, on voyait à travers. Il a fallu tout recopier en urgence."},
{t:'musique',q:"Combien de temps a pris l’enregistrement de « Bohemian Rhapsody » en studio ?",n:3,min:0,max:4,u:"semaines",e:"Trois semaines en 1975, dans six studios différents, pour un morceau de six minutes. À l’époque, un album entier se bouclait souvent en moins de temps que ça."},
{t:'musique',q:"Combien de secondes dure « Hey Jude » des Beatles ?",n:431,min:0,max:800,u:"secondes",e:"Sept minutes onze : le plus long numéro un de l’histoire des charts américains à sa sortie. Les quatre dernières minutes ne sont que des « na na na ». Personne ne s’en est plaint."},
{t:'musique',q:"Combien de secondes dure « Stairway to Heaven » de Led Zeppelin ?",n:482,min:0,max:2000,u:"secondes",e:"Huit minutes deux, jamais sorti en single par Led Zeppelin, et pourtant l’un des morceaux les plus diffusés en radio de tous les temps. Les magasins de guitare ont fini par l’interdire à l’essai."},
{t:'musique',q:"Combien de secondes dure la version originale d’« American Pie » de Don McLean ?",n:522,min:0,max:600,u:"secondes",e:"Huit minutes quarante-deux. Trop long pour un 45 tours : on l’a coupé en deux faces. Les radios ont refusé de retourner le disque et passaient le tout, d’un bloc."},
{t:'musique',q:"Combien de secondes dure la version originale de « Rapper’s Delight » du Sugarhill Gang ?",n:875,min:0,max:1500,u:"secondes",e:"Quatorze minutes trente-cinq de rap sur une boucle de Chic. Le morceau fondateur du hip-hop commercial a été enregistré en une seule prise, par des rappeurs recrutés le jour même."},
{t:'musique',q:"Combien de minutes dure « In-A-Gadda-Da-Vida » d’Iron Butterfly ?",n:17,min:0,max:40,u:"minutes",e:"Dix-sept minutes qui occupent toute une face. Le titre viendrait d’un chanteur trop éméché pour articuler « In the Garden of Eden » ; l’ingénieur a noté ce qu’il entendait."},
{t:'musique',q:"Combien de temps résonne l’accord de piano final d’« A Day in the Life » des Beatles ?",n:40,min:0,max:200,u:"secondes",e:"Trois pianos frappés simultanément, puis les ingénieurs ont monté les micros à fond pour capter l’extinction. On entend à la fin la climatisation du studio et une chaise qui craque."},
{t:'musique',q:"Combien de musiciens d’orchestre les Beatles ont-ils convoqués pour le crescendo d’« A Day in the Life » ?",n:40,min:0,max:80,u:"musiciens",e:"Quarante instrumentistes classiques, à qui on a demandé de monter de leur note la plus grave à la plus aiguë, chacun à son rythme. On leur avait fait porter des faux nez et des chapeaux."},
{t:'musique',q:"Combien d’heures de studio a demandé l’album « Sgt. Pepper » des Beatles ?",n:700,min:0,max:1000,u:"heures",e:"Environ 700 heures étalées sur cinq mois. Leur premier album, quatre ans plus tôt, avait été bouclé en une seule journée. Le groupe ne tournait plus : le studio était devenu l’instrument."},
{t:'musique',q:"Sur combien de pistes « Sgt. Pepper » a-t-il été enregistré ?",n:4,min:0,max:8,u:"pistes",e:"Quatre. Les ingénieurs remplissaient les quatre pistes, les mixaient sur une seule d’un second magnétophone, et recommençaient. Chaque report dégradait le son : impossible de revenir en arrière."},
{t:'musique',q:"Combien de minutes a duré l’enregistrement de l’album « Please Please Me » des Beatles ?",n:585,min:0,max:3000,u:"minutes",e:"585 minutes, soit une seule journée de février 1963. Lennon avait un mauvais rhume ; sa voix éraillée sur « Twist and Shout » est celle d’un homme qui n’en pouvait plus."},
{t:'musique',q:"Combien de prises a-t-il fallu aux Beatles pour « Twist and Shout » ?",n:1,min:0,max:1.5,u:"prise",e:"Une seule, en fin de journée, avec un Lennon aphone gargarisé au lait. Il a tenté une deuxième prise : sa voix a lâché. C’est la première qui est sur le disque."},
{t:'musique',q:"Combien de prises George Harrison a-t-il exigées pour « Not Guilty » pendant les sessions de l’Album blanc ?",n:102,min:0,max:120,u:"prises",e:"Cent deux prises, et le morceau n’a même pas été retenu sur l’album. Harrison l’a ressorti dix ans plus tard, en solo, en une poignée de prises."},
{t:'musique',q:"Combien de fois les Beatles ont-ils joué au Cavern Club de Liverpool ?",n:292,min:0,max:800,u:"concerts",e:"292 passages entre 1961 et 1963, dans une cave humide sans issue de secours, souvent pour quelques livres. Le club a été démoli en 1973, puis reconstruit avec les briques d’origine."},
{t:'musique',q:"Combien de temps a duré le concert des Beatles sur le toit d’Apple, leur dernier en public ?",n:42,min:0,max:150,u:"minutes",e:"Quarante-deux minutes en janvier 1969, sur un toit de Savile Row, jusqu’à ce que la police monte les faire taire. Lennon a conclu : « J’espère qu’on a réussi l’audition. »"},
{t:'musique',q:"Combien de spectateurs les Beatles ont-ils réunis au Shea Stadium en 1965 ?",n:55600,min:0,max:150000,u:"spectateurs",e:"55 600 personnes, record absolu pour l’époque. La sono du stade était si faible face aux cris que les Beatles ne s’entendaient pas jouer. Le concert a duré une trentaine de minutes."},
{t:'musique',q:"Combien de téléspectateurs américains ont regardé les Beatles au Ed Sullivan Show en février 1964 ?",n:73000000,min:0,max:200000000,u:"téléspectateurs",e:"Environ 73 millions, soit près de quatre Américains sur dix. La légende veut que la criminalité ait chuté ce soir-là dans plusieurs villes : les adolescents étaient tous devant la télévision."},
{t:'musique',q:"Combien Michael Jackson a-t-il payé en 1985 pour racheter le catalogue des chansons des Beatles ?",n:47500000,min:0,max:150000000,u:"dollars",e:"47,5 millions de dollars. C’est McCartney lui-même qui lui avait expliqué que l’édition musicale rapportait gros. Jackson a surenchéri sur son ami, qui ne le lui a jamais vraiment pardonné."},
{t:'musique',q:"Combien d’heures de bande Brian Wilson a-t-il consommées pour le seul « Good Vibrations » ?",n:90,min:0,max:150,u:"heures",e:"Environ 90 heures de bande pour trois minutes trente-cinq. Wilson enregistrait des fragments qu’il assemblait ensuite comme un puzzle : une méthode de cinéma appliquée à un tube pop."},
{t:'musique',q:"Dans combien de studios différents « Good Vibrations » des Beach Boys a-t-il été enregistré ?",n:4,min:0,max:15,u:"studios",e:"Quatre studios de Los Angeles, chacun choisi pour sa couleur sonore. Le morceau a coûté une somme record pour un single de 1966 et a bien failli ne jamais sortir."},
{t:'musique',q:"Combien a coûté « Chinese Democracy » de Guns N’ Roses, l’album le plus cher de l’histoire ?",n:13000000,min:0,max:30000000,u:"dollars",e:"Treize millions de dollars et quatorze ans de studio. Axl Rose a usé des dizaines de musiciens et d’ingénieurs. Un producteur a raconté avoir facturé un million rien qu’en essais de batterie."},
{t:'musique',q:"Combien a coûté l’album « Hysteria » de Def Leppard ?",n:4500000,min:0,max:6000000,u:"dollars",e:"4,5 millions de dollars et trois ans, notamment parce que le batteur Rick Allen a perdu un bras dans un accident et a dû réapprendre à jouer avec un kit à pédales."},
{t:'musique',q:"Combien de minutes Queen a-t-il joué au Live Aid de 1985 ?",n:21,min:0,max:60,u:"minutes",e:"Vingt et une minutes seulement, considérées comme la meilleure prestation live de l’histoire du rock. Le groupe avait répété trois jours pour un set de six chansons tronquées, minuté à la seconde."},
{t:'musique',q:"Combien de temps Eddie Van Halen a-t-il mis pour enregistrer son solo sur « Beat It » de Michael Jackson ?",n:20,min:0,max:25,u:"minutes",e:"Une vingtaine de minutes, deux prises, entre deux avions. Il n’a rien demandé en échange et n’est même pas crédité : il l’a fait, dit-il, « pour rendre service »."},
{t:'musique',q:"Combien de fois la caisse claire répète-t-elle le même rythme dans le « Boléro » de Ravel ?",n:169,min:0,max:200,u:"fois",e:"169 répétitions du même motif, sans jamais varier, pendant un quart d’heure. Ravel qualifiait lui-même sa pièce d’« orchestration sans musique ». C’est devenue l’œuvre classique la plus jouée au monde."},
{t:'musique',q:"Combien d’exécutants ont participé à la création de la 8e Symphonie de Mahler, dite « des Mille » ?",n:1029,min:0,max:1200,u:"exécutants",e:"Environ 1 029 personnes à Munich en 1910 : 171 instrumentistes et plus de 850 choristes, dont un chœur d’enfants. Mahler est mort huit mois plus tard, sans jamais revoir une telle armée."},
{t:'musique',q:"Combien de musiciens restent sur scène à la fin de la Symphonie des adieux de Haydn ?",n:2,min:0,max:2.5,u:"musiciens",e:"Deux violons. Dans le dernier mouvement, les musiciens soufflent leur bougie et sortent un à un. Haydn faisait ainsi comprendre au prince Esterházy que l’orchestre voulait rentrer chez lui."},
{t:'musique',q:"En combien de jours Haendel a-t-il composé « Le Messie » ?",n:24,min:0,max:40,u:"jours",e:"Vingt-quatre jours en 1741, plus de deux cents pages. On raconte que son domestique retrouvait ses repas intacts. À la fin de l’« Alléluia », Haendel aurait dit avoir vu le ciel s’ouvrir."},
{t:'musique',q:"Combien d’œuvres compte le catalogue Köchel de Mozart ?",n:626,min:0,max:1200,u:"œuvres",e:"626 numéros, dont le dernier est le Requiem inachevé. Mozart est mort à 35 ans : cela fait environ une œuvre toutes les trois semaines, du berceau à la tombe."},
{t:'musique',q:"À quel âge Mozart a-t-il composé sa première symphonie ?",n:8,min:0,max:12,u:"ans",e:"Huit ans, à Londres, pendant que son père se remettait d’une angine et qu’on interdisait le clavecin à la maison. Sa sœur affirmait qu’il lui dictait les notes en jouant."},
{t:'musique',q:"Combien de concertos Vivaldi a-t-il composés ?",n:500,min:0,max:800,u:"concertos",e:"Environ 500, soit plus que la plupart des compositeurs n’écrivent d’œuvres tout court. Stravinsky ricanait qu’il avait écrit « le même concerto cinq cents fois ». Il les écrivait pour ses élèves orphelines."},
{t:'musique',q:"Combien d’heures de musique compte la tétralogie « L’Anneau du Nibelung » de Wagner ?",n:15,min:0,max:60,u:"heures",e:"Quinze heures réparties sur quatre soirées. Wagner a fait construire un théâtre exprès à Bayreuth, avec une fosse d’orchestre invisible, parce qu’aucune salle existante ne convenait à son projet."},
{t:'musique',q:"Combien de temps Wagner a-t-il mis à composer sa tétralogie ?",n:26,min:0,max:40,u:"ans",e:"Vingt-six ans, avec une interruption de douze ans au beau milieu du deuxième acte de Siegfried — pendant laquelle il a écrit Tristan et Les Maîtres chanteurs, comme pour se détendre."},
{t:'musique',q:"Combien de rappels Luciano Pavarotti a-t-il obtenus à Berlin en 1988, record homologué ?",n:165,min:0,max:200,u:"rappels",e:"165 rappels après « L’Élixir d’amour », pour 67 minutes d’applaudissements ininterrompus. Le personnel du Deutsche Oper a fini par rester, faute de pouvoir fermer la salle."},
{t:'musique',q:"Combien de métronomes faut-il pour jouer le « Poème symphonique » de György Ligeti ?",n:100,min:0,max:150,u:"métronomes",e:"Cent métronomes remontés à fond, lâchés ensemble, qui s’arrêtent un à un. La première télévisée en 1963 a été déprogrammée et remplacée par un match de football : le public était furieux."},
{t:'musique',q:"Combien de tuyaux compte l’orgue du Boardwalk Hall d’Atlantic City, le plus grand du monde ?",n:33112,min:0,max:40000,u:"tuyaux",e:"33 112 tuyaux, sept claviers, construits dans les années 1930 pour remplir une salle de 40 000 places. Sa soufflerie consomme l’équivalent d’une petite centrale : personne n’a jamais tout fait sonner ensemble."},
{t:'musique',q:"Quelle est la fréquence de la note la plus grave de cet orgue géant d’Atlantic City ?",n:8,min:0,max:10,u:"hertz",e:"Environ 8 hertz, produits par un tuyau de près de vingt mètres. C’est sous le seuil de l’audition humaine : on ne l’entend pas, on la reçoit dans la cage thoracique."},
{t:'musique',q:"Combien de tuyaux compte l’orgue de la cathédrale de Passau, le plus grand d’Europe ?",n:17974,min:0,max:25000,u:"tuyaux",e:"17 974 tuyaux répartis en cinq orgues jouables depuis une seule console. Le plus petit fait la taille d’un crayon, le plus grand celle d’un poteau télégraphique."},
{t:'musique',q:"Combien de tuyaux compte le grand orgue de Notre-Dame de Paris ?",n:8000,min:0,max:10000,u:"tuyaux",e:"Environ 8 000 tuyaux, sauvés des flammes en 2019 mais recouverts de poussière de plomb. Leur nettoyage a demandé de démonter l’instrument tuyau par tuyau, puis de le réaccorder pendant des mois."},
{t:'musique',q:"Combien de cordes compte un piano à queue de concert ?",n:230,min:0,max:1000,u:"cordes",e:"Environ 230 cordes pour 88 touches : les notes aiguës en ont trois chacune, les graves une seule, plus épaisse et filée de cuivre. L’accordeur les règle une par une."},
{t:'musique',q:"Quelle tension totale exercent les cordes d’un piano à queue sur son cadre ?",n:20,min:0,max:25,u:"tonnes",e:"Près de vingt tonnes, l’équivalent de deux bus suspendus au cadre de fonte. C’est pour cela qu’un piano ne se fabrique pas en bois seul : le cadre est coulé comme une pièce de moteur."},
{t:'musique',q:"Combien de pièces distinctes assemble-t-on pour fabriquer un piano de concert ?",n:12000,min:0,max:15000,u:"pièces",e:"Environ 12 000 pièces, plus qu’une voiture n’en compte de visibles. Un seul marteau met en jeu une vingtaine d’éléments articulés, et il y en a 88 à régler au dixième de millimètre."},
{t:'musique',q:"Quelle longueur mesure un piano à queue de concert Steinway modèle D ?",n:2.74,min:0,max:5,u:"mètres",e:"2,74 mètres, la taille standard des salles de concert du monde entier. Plus la corde est longue, plus le grave est riche : c’est de la physique, pas du luxe."},
{t:'musique',q:"Combien pèse un piano à queue de concert Steinway modèle D ?",n:480,min:0,max:2000,u:"kg",e:"Environ 480 kilos, dont une bonne moitié pour le seul cadre de fonte. Il faut six personnes pour le déplacer, et les salles prévoient des monte-charges dimensionnés exprès."},
{t:'musique',q:"Quelle est la fréquence de la note la plus grave d’un piano ?",n:27.5,min:0,max:150,u:"hertz",e:"27,5 hertz, le la le plus bas. À cette fréquence, l’oreille perçoit à peine une hauteur : on entend surtout un grondement. Le cerveau reconstitue la note grâce aux harmoniques."},
{t:'musique',q:"Quelle est la fréquence de la note la plus aiguë d’un piano ?",n:4186,min:0,max:5000,u:"hertz",e:"4 186 hertz pour le dernier do. Au-delà, l’oreille distingue mal les intervalles : les facteurs ont arrêté le clavier là où la musique cessait d’être utile."},
{t:'musique',q:"Combien de cordes compte une harpe de concert ?",n:47,min:0,max:250,u:"cordes",e:"Quarante-sept cordes et sept pédales à trois positions, actionnées des deux pieds. Une harpiste change ainsi de tonalité en pleine phrase, un peu comme un organiste jouerait du pédalier."},
{t:'musique',q:"Quelle longueur de tube contient un cor d’harmonie une fois déroulé ?",n:3.7,min:0,max:8,u:"mètres",e:"Environ 3,7 mètres enroulés en spirale. La main droite reste enfoncée dans le pavillon pour corriger la justesse : c’est le seul cuivre où l’on joue littéralement à l’intérieur de l’instrument."},
{t:'musique',q:"Quelle longueur de tubulure contient un tuba une fois déroulé ?",n:5.5,min:0,max:6,u:"mètres",e:"Environ 5,5 mètres pour un tuba grave, soit la longueur d’une voiture. L’air met un temps mesurable à traverser tout ça : les tubistes doivent attaquer légèrement avant les autres."},
{t:'musique',q:"Quelle longueur de tube contient une trompette une fois déroulée ?",n:1.48,min:0,max:5,u:"mètres",e:"Environ 1,48 mètre replié en un objet de cinquante centimètres. Les pistons ne font qu’ajouter des rallonges de tuyau : appuyer sur les trois allonge le circuit d’un bon tiers."},
{t:'musique',q:"Combien de pièces de bois assemble-t-on pour construire un violon ?",n:70,min:0,max:150,u:"pièces",e:"Environ soixante-dix pièces collées, sans une seule vis. La colle utilisée est volontairement faible : on doit pouvoir rouvrir l’instrument sans le casser, parfois trois siècles plus tard."},
{t:'musique',q:"Combien d’instruments d’Antonio Stradivari existent encore aujourd’hui ?",n:650,min:0,max:800,u:"instruments",e:"Environ 650 sur le millier construits. Chacun est suivi, nommé, photographié. Certains sont prêtés à des solistes par des fondations, avec assurance et garde du corps compris."},
{t:'musique',q:"Combien s’est vendu le violon Stradivarius « Lady Blunt » en 2011 ?",n:15900000,min:0,max:100000000,u:"dollars",e:"15,9 millions de dollars, au profit des victimes du tsunami japonais. L’instrument, resté quasi inutilisé pendant trois siècles, est dans un état de conservation presque irréel pour son âge."},
{t:'musique',q:"Combien s’est vendue la guitare acoustique de Kurt Cobain jouée sur l’Unplugged de MTV ?",n:6010000,min:0,max:10000000,u:"dollars",e:"6,01 millions de dollars en 2020, un record pour une guitare. C’est une Martin de 1959 qui valait quelques milliers de dollars avant que Cobain ne s’assoie devant les caméras."},
{t:'musique',q:"Combien coûtait une Fender Stratocaster neuve lors de son lancement en 1954 ?",n:249.5,min:0,max:500,u:"dollars",e:"249,50 dollars, étui compris. Les modèles de cette première année valent aujourd’hui des centaines de milliers de dollars. Leo Fender, lui, ne savait pas jouer de la guitare."},
{t:'musique',q:"Quelle est la fréquence de la note la plus grave jamais chantée par un humain, homologuée par Guinness ?",n:0.189,min:0,max:0.5,u:"hertz",e:"0,189 hertz, produits par l’Américain Tim Storms. C’est huit octaves sous la limite basse de l’audition : personne ne l’entend, il a fallu des capteurs pour prouver que la note existait."},
{t:'musique',q:"Quelle est l’étendue vocale record de Tim Storms, homologuée par Guinness ?",n:10,min:0,max:40,u:"octaves",e:"Dix octaves, contre trois ou quatre pour un chanteur professionnel entraîné. Ses cordes vocales, anormalement longues et souples, lui interdisent en revanche la plupart des rôles écrits pour voix normales."},
{t:'musique',q:"Quel niveau sonore atteint le cri humain le plus fort jamais homologué ?",n:129,min:0,max:600,u:"décibels",e:"129 décibels, poussés par une institutrice britannique lors d’un concours en 2000. C’est le niveau d’un marteau-piqueur à un mètre, produit par une seule paire de cordes vocales."},
{t:'musique',q:"Quel niveau sonore a été mesuré à un concert des Who en 1976, record longtemps homologué ?",n:126,min:0,max:150,u:"décibels",e:"126 décibels mesurés à trente-deux mètres de la scène, à Londres. Pete Townshend en a gardé des acouphènes à vie et milite depuis pour la protection auditive des musiciens."},
{t:'musique',q:"Quel niveau sonore l’éruption du Krakatoa a-t-elle atteint à 160 kilomètres de distance ?",n:172,min:0,max:200,u:"décibels",e:"172 décibels à cent soixante kilomètres, le son le plus fort documenté de l’histoire. L’onde a fait le tour du globe plusieurs fois et a crevé les tympans de marins à soixante kilomètres."},
{t:'musique',q:"Quel niveau sonore atteint le clic d’un cachalot, l’animal le plus bruyant du monde ?",n:230,min:0,max:400,u:"décibels",e:"230 décibels sous l’eau, un claquement si puissant qu’il pourrait théoriquement assommer une proie. Le cachalot s’en sert comme d’un sonar pour chasser des calmars à un kilomètre de profondeur."},
{t:'musique',q:"Quel niveau sonore atteint le chant d’une baleine bleue ?",n:188,min:0,max:800,u:"décibels",e:"188 décibels, plus fort qu’un réacteur d’avion, mais à des fréquences si basses qu’un humain à la surface n’entendrait presque rien. Ces chants portent sur des centaines de kilomètres."},
{t:'musique',q:"Quel niveau sonore produit la crevette-pistolet en claquant sa pince ?",n:210,min:0,max:250,u:"décibels",e:"Environ 210 décibels, pour un animal de quelques centimètres. Le claquement crée une bulle qui implose en atteignant brièvement des milliers de degrés. Les sous-marins s’en servaient pour se cacher des sonars."},
{t:'musique',q:"À quelle fréquence les éléphants communiquent-ils entre eux à longue distance ?",n:14,min:0,max:20,u:"hertz",e:"Autour de 14 hertz, sous le seuil de l’audition humaine. Ces infrasons portent à plusieurs kilomètres et se propagent aussi par le sol : les éléphants les captent par la plante des pieds."},
{t:'musique',q:"Jusqu’à quelle fréquence certaines chauves-souris émettent-elles leurs cris de chasse ?",n:200,min:0,max:250,u:"kilohertz",e:"Jusqu’à environ 200 kilohertz, dix fois au-dessus de la limite humaine. Plus la fréquence est haute, plus le détail perçu est fin : elles repèrent un fil de la taille d’un cheveu."},
{t:'musique',q:"Quel niveau sonore a atteint le public de l’Arrowhead Stadium en 2014, record homologué ?",n:142.2,min:0,max:300,u:"décibels",e:"142,2 décibels produits par des spectateurs de football américain, au-delà du seuil de douleur. Les joueurs sur le terrain ne s’entendaient plus et communiquaient uniquement par signes."},
{t:'musique',q:"Combien de temps peut-on rester exposé à 100 décibels avant risque, selon les normes américaines ?",n:15,min:0,max:20,u:"minutes",e:"Un quart d’heure. C’est le niveau d’un concert de rock ou d’un casque poussé à fond. Chaque tranche de trois décibels en plus divise la durée tolérable par deux."},
{t:'musique',q:"Quelle longueur mesure la cochlée humaine une fois déroulée ?",n:3.5,min:0,max:8,u:"centimètres",e:"Trois centimètres et demi de tube spiralé, enroulé deux fois et demie comme un escargot. Toute la musique du monde y est décomposée en fréquences avant d’atteindre le cerveau."},
{t:'musique',q:"Combien de cellules ciliées la cochlée humaine contient-elle ?",n:15000,min:0,max:40000,u:"cellules",e:"Environ 15 000 par oreille, contre 100 millions de photorécepteurs dans un œil. Et contrairement à la peau, elles ne repoussent jamais : chaque concert trop fort en tue définitivement quelques-unes."},
{t:'musique',q:"Quelle taille fait l’étrier, le plus petit os du corps humain, logé dans l’oreille ?",n:3,min:0,max:4,u:"millimètres",e:"Trois millimètres, à peine un grain de riz. Avec le marteau et l’enclume, il amplifie mécaniquement les vibrations du tympan pour les transmettre à un liquide, mille fois plus dense que l’air."},
{t:'musique',q:"À quelle vitesse le son se propage-t-il dans l’eau ?",n:1500,min:0,max:2500,u:"m/s",e:"Environ 1 500 mètres par seconde, plus de quatre fois plus vite que dans l’air. C’est pourquoi, en plongée, on entend un bateau sans jamais pouvoir dire d’où il vient."},
{t:'musique',q:"Combien de spectateurs ont assisté au concert de Metallica en Antarctique ?",n:120,min:0,max:150,u:"spectateurs",e:"Cent vingt personnes en 2013, sous un dôme, sans amplification extérieure : le public écoutait au casque pour ne pas perturber la faune. Le groupe est devenu le premier à jouer sur les sept continents."},
{t:'musique',q:"Combien de minutes de musique un disque compact peut-il contenir, dans sa norme d’origine ?",n:74,min:0,max:150,u:"minutes",e:"74 minutes. La légende du studio veut qu’un dirigeant de Sony ait exigé que la Neuvième de Beethoven tienne sur un seul disque. Le diamètre a été fixé en conséquence."},
{t:'musique',q:"Combien de morceaux de musique figurent sur le Voyager Golden Record envoyé dans l’espace ?",n:27,min:0,max:30,u:"morceaux",e:"Vingt-sept, de Bach à Chuck Berry en passant par un chant pygmée. Les Beatles manquent : le label a refusé les droits. Le disque file depuis dans l’espace interstellaire, gravé pour un milliard d’années."},
{t:'musique',q:"Combien de langues différentes prononcent un salut sur le Voyager Golden Record ?",n:55,min:0,max:60,u:"langues",e:"Cinquante-cinq, de l’akkadien au chinois wu. Le message anglais a été enregistré par le fils de Carl Sagan, six ans, qui a dit : « Salut les habitants de l’espace lointain. »"},
{t:'musique',q:"Combien de temps dure la boucle de batterie « Amen break », le sample le plus utilisé de l’histoire ?",n:6,min:0,max:50,u:"secondes",e:"Six secondes jouées en 1969 par Gregory Coleman des Winstons. Elle a fondé la jungle, la drum’n’bass et des milliers de tubes. Le batteur est mort sans avoir touché un centime de droits."},
{t:'musique',q:"À quel tempo bat « Stayin’ Alive » des Bee Gees, chanson recommandée pour rythmer un massage cardiaque ?",n:103,min:0,max:400,u:"battements/min",e:"103 battements par minute, pile la cadence de compression recommandée. Les formations aux premiers secours l’utilisent vraiment ; le titre, lui, tombe assez bien."},
{t:'musique',q:"Quelle part des droits de « Bittersweet Symphony » The Verve a-t-il dû céder aux Rolling Stones ?",n:100,min:0,max:100,u:"%",e:"La totalité, pour un extrait orchestral de cinq notes utilisé au-delà de la licence accordée. Le groupe n’a rien touché sur son plus gros tube pendant vingt ans, avant que Jagger et Richards ne renoncent."},
{t:'musique',q:"Combien George Harrison a-t-il dû payer pour le plagiat involontaire de « My Sweet Lord » ?",n:587000,min:0,max:1000000,u:"dollars",e:"587 000 dollars. Le juge a estimé qu’il avait copié « He’s So Fine » de façon « subconsciente » : une notion inventée pour l’occasion, qui fait encore trembler les compositeurs aujourd’hui."},
{t:'musique',q:"Quel montant le jury a-t-il d’abord accordé aux héritiers de Marvin Gaye dans l’affaire « Blurred Lines » ?",n:7400000,min:0,max:12000000,u:"dollars",e:"7,4 millions de dollars, réduits ensuite en appel. Aucune mélodie n’avait été copiée : le verdict portait sur l’« ambiance » du morceau. Des centaines de compositeurs ont signé une pétition contre ce précédent."},
{t:'musique',q:"Combien a coûté le règlement judiciaire libérant la chanson « Joyeux anniversaire » de ses droits d’auteur ?",n:14000000,min:0,max:15000000,u:"dollars",e:"Quatorze millions de dollars remboursés en 2016 par l’éditeur qui percevait des royalties depuis des décennies. Les documentaristes payaient jusqu’à cinq chiffres pour filmer un gâteau."},
{t:'musique',q:"Combien de minutes dure le clip de « Thriller » de Michael Jackson ?",n:14,min:0,max:20,u:"minutes",e:"Quatorze minutes, avec générique et scénario, réalisé par le cinéaste de Loup-garou américain à Londres. MTV, qui passait des clips de trois minutes, a diffusé ce court-métrage deux fois par heure."},
{t:'musique',q:"Combien a coûté le clip de « Thriller » de Michael Jackson ?",n:500000,min:0,max:1500000,u:"dollars",e:"500 000 dollars en 1983, une somme délirante pour l’époque. Le label refusant de payer, Jackson a financé lui-même une partie en vendant les droits d’un documentaire sur le tournage."},
{t:'musique',q:"Combien a coûté le clip « Scream » de Michael et Janet Jackson, le plus cher jamais tourné ?",n:7000000,min:0,max:25000000,u:"dollars",e:"Sept millions de dollars pour six minutes en noir et blanc dans un vaisseau spatial. Chaque décor a été construit puis détruit. Le record tient depuis les années 1990."},
{t:'musique',q:"Combien de semaines l’album « Thriller » a-t-il passé en tête du classement américain ?",n:37,min:0,max:50,u:"semaines",e:"Trente-sept semaines, soit plus de huit mois cumulés au sommet. À un moment, un foyer américain sur trois possédait le disque, un taux de pénétration qu’aucun album n’a jamais retrouvé."},
{t:'musique',q:"Combien d’exemplaires s’est vendu « White Christmas » de Bing Crosby, le single le plus vendu de l’histoire ?",n:50000000,min:0,max:150000000,u:"exemplaires",e:"Environ 50 millions. Crosby l’a enregistré en dix-huit minutes et trouvait la chanson quelconque. La matrice originale s’est usée à force de pressages : il a dû la réenregistrer à l’identique."},
{t:'musique',q:"Combien de haut-parleurs comptait le « Wall of Sound » du Grateful Dead ?",n:604,min:0,max:3000,u:"haut-parleurs",e:"604 enceintes empilées sur onze mètres de haut, montées et démontées à chaque date par des dizaines de techniciens. Le système coûtait si cher qu’il a mis le groupe en pause."},
{t:'musique',q:"Combien d’instruments Prince a-t-il joués lui-même sur son premier album ?",n:27,min:0,max:100,u:"instruments",e:"Vingt-sept, tous enregistrés seul, à dix-neuf ans. Son contrat lui accordait le contrôle artistique total, une exception absolue pour un débutant. Le label lui avait donné un studio et fermé la porte."},
{t:'musique',q:"Combien de temps le FBI a-t-il enquêté sur les paroles de la chanson « Louie Louie » ?",n:2,min:0,max:3,u:"ans",e:"Deux ans d’enquête fédérale sur des paroles jugées obscènes. Le laboratoire a passé le disque à toutes les vitesses et conclu que le texte était « incompréhensible à n’importe quel régime »."},
{t:'musique',q:"Combien de couplets Leonard Cohen a-t-il écrits avant de retenir la version finale de « Hallelujah » ?",n:80,min:0,max:300,u:"couplets",e:"Environ quatre-vingts brouillons, étalés sur des années. Cohen racontait s’être cogné la tête sur la moquette d’une chambre d’hôtel, en sous-vêtements. Son label a d’abord refusé de sortir l’album."},
{t:'musique',q:"Combien de morceaux Brian Eno a-t-il composés avant de retenir le son de démarrage de Windows 95 ?",n:84,min:0,max:100,u:"morceaux",e:"Quatre-vingt-quatre versions, pour un jingle de trois secondes et demie. Le cahier des charges demandait quelque chose d’« inspirant, universel, optimiste ». Eno l’a composé sur un Mac."},

/* ---------- Pinceau ---------- */
{t:'art',q:"Combien s'est vendu le Salvator Mundi, tableau le plus cher du monde ?",n:450,min:0,max:2500,u:"millions de dollars",e:"450 millions de dollars en 2017. Il avait été racheté 1 000 dollars en 2005, alors qu'on le croyait peint par un simple élève de Léonard."},
{t:'art',q:"Combien Abu Dhabi a-t-elle payé pour utiliser le nom « Louvre » ?",n:400,min:0,max:600,u:"millions d'euros",e:"400 millions d'euros pour trente ans, plus les prêts d'œuvres. Le nom d'un musée valait à lui seul plus que la plupart des tableaux qu'il abrite."},
{t:'art',q:"Combien s'est vendue la banane scotchée au mur de Maurizio Cattelan ?",n:120000,min:0,max:500000,u:"dollars",e:"120 000 dollars — pour un certificat d'authenticité et le mode d'emploi. Un artiste l'a mangée pendant l'exposition : l'œuvre a simplement été remplacée."},
{t:'art',q:"Quelle est la hauteur de La Joconde ?",n:77,min:0,max:100,u:"cm",e:"77 sur 53 cm, la taille d’un sous-main. Les visiteurs traversent des salles de fresques monumentales pour finir devant un petit panneau de peuplier, protégé par une vitrine bien plus grande que le tableau lui-même."},
{t:'art',q:"Quelle largeur fait Guernica de Picasso ?",n:776,min:0,max:1000,u:"cm",e:"Presque 7,8 mètres de long pour 3,5 de haut. L’atelier parisien était si bas de plafond que Picasso devait incliner la toile contre le mur et peindre le sommet perché sur une échelle."},
{t:'art',q:"En combien de jours Picasso a-t-il peint Guernica ?",n:35,min:0,max:50,u:"jours",e:"Du 1er mai au 4 juin 1937, dans l’urgence, après le bombardement de la ville basque. Dora Maar a photographié chaque état de la toile : on connaît ce tableau comme on connaît un film."},
{t:'art',q:"Quelle largeur fait Les Noces de Cana, le plus grand tableau du Louvre ?",n:994,min:0,max:2000,u:"cm",e:"Près de 10 mètres de large et 67 mètres carrés de toile. Décroché à Venise par les troupes de Bonaparte en 1797, il fut découpé en deux pour le voyage, puis recousu à Paris."},
{t:'art',q:"Quelle largeur fait Le Radeau de La Méduse de Géricault ?",n:716,min:0,max:1000,u:"cm",e:"Plus de 7 mètres. Géricault s’est rasé le crâne pour ne plus oser sortir de son atelier, où il entassait des membres et des têtes récupérés à l’hôpital afin de peindre la chair des morts."},
{t:'art',q:"Quelle est la hauteur de La Persistance de la mémoire, les montres molles de Dalí ?",n:24,min:0,max:30,u:"cm",e:"24 sur 33 cm : le tableau surréaliste le plus célèbre du monde tient dans une feuille A4. Dalí racontait l’avoir peint en quelques heures, après avoir contemplé un camembert qui coulait au soleil."},
{t:'art',q:"Quelle est la hauteur de La Jeune Fille à la perle de Vermeer ?",n:44.5,min:0,max:60,u:"cm",e:"44,5 sur 39 cm. En 1881, ce panneau noirci a été adjugé deux florins et trente cents à La Haye. L’acheteur l’a légué au Mauritshuis, qui en a fait l’icône que l’on sait."},
{t:'art',q:"Quelle largeur fait La Cène de Léonard de Vinci ?",n:880,min:0,max:2000,u:"cm",e:"8,8 mètres sur 4,6, peints à même le mur d’un réfectoire milanais. Léonard a refusé la fresque, trop rapide pour lui, au profit d’une technique à l’huile : elle s’écaillait déjà de son vivant."},
{t:'art',q:"Combien de temps a duré la dernière restauration de La Cène de Léonard ?",n:21,min:0,max:60,u:"ans",e:"De 1978 à 1999. Pinin Brambilla Barcilon a gratté au scalpel, sous microscope, les repeints de cinq siècles. Résultat : un tableau fantôme, où ne subsiste qu’une fraction de la main de Léonard."},
{t:'art',q:"Combien de temps Michel-Ange a-t-il mis pour peindre le plafond de la chapelle Sixtine ?",n:4,min:0,max:5,u:"ans",e:"De 1508 à 1512, debout sur un échafaudage de sa conception, pas allongé contrairement à la légende. Il en est sorti le cou tordu, et un poème de sa main se plaint que la peinture lui dégoulinait au visage."},
{t:'art',q:"Combien de temps a duré la restauration de la chapelle Sixtine ?",n:14,min:0,max:20,u:"ans",e:"De 1980 à 1994. Sous la suie des bougies et des siècles, on a découvert des couleurs criardes, presque acidulées. Des historiens ont hurlé au massacre : ils avaient appris à aimer la crasse."},
{t:'art',q:"Combien de personnages Michel-Ange a-t-il peints au plafond de la chapelle Sixtine ?",n:300,min:0,max:400,u:"personnages",e:"Plus de 300, sur environ 500 mètres carrés de voûte. Michel-Ange se disait sculpteur, pas peintre, et a accepté le chantier en râlant. Quatre ans plus tard, il parlait encore d’une corvée."},
{t:'art',q:"Combien de tableaux de Vermeer nous sont parvenus ?",n:34,min:0,max:80,u:"tableaux",e:"Trente-quatre, dont un contesté. Vermeer achevait deux ou trois toiles par an, est mort criblé de dettes avec onze enfants, puis fut oublié pendant deux siècles avant d’être redécouvert vers 1860."},
{t:'art',q:"Combien de tableaux Van Gogh a-t-il vendus de son vivant ?",n:1,min:0,max:6,u:"tableau",e:"Un seul, selon la version admise : La Vigne rouge, acheté 400 francs par la peintre belge Anna Boch. Il est mort quelques mois plus tard, persuadé d’avoir raté sa vie et ruiné son frère."},
{t:'art',q:"Combien de peintures à l’huile Van Gogh a-t-il laissées ?",n:860,min:0,max:1500,u:"peintures",e:"Environ 860 huiles, plus un millier de dessins, en dix ans de carrière seulement. Certaines semaines il achevait un tableau tous les deux jours, tout en écrivant à Theo qu’il n’avançait pas."},
{t:'art',q:"Combien d’autoportraits peints Van Gogh a-t-il laissés ?",n:35,min:0,max:150,u:"autoportraits",e:"Plus de trente-cinq, en quatre ans. Ce n’était pas du narcissisme : un modèle coûtait cher, un miroir ne coûtait rien. Dans ses lettres, il s’excuse presque de se prendre pour sujet."},
{t:'art',q:"Combien d’étoiles Van Gogh a-t-il peintes dans La Nuit étoilée ?",n:11,min:0,max:12,u:"étoiles",e:"Onze, plus un croissant de lune. Le paysage est vu depuis la fenêtre grillagée de sa chambre d’asile à Saint-Rémy, mais le village au clocher pointu, lui, est entièrement inventé."},
{t:'art',q:"Combien de tableaux Picasso a-t-il peints au cours de sa vie ?",n:13500,min:0,max:40000,u:"tableaux",e:"Environ 13 500, auxquels s’ajoutent des dizaines de milliers de gravures et de dessins : le peintre le plus prolifique jamais recensé. Soixante-quinze ans de travail, parfois plusieurs toiles dans la même journée."},
{t:'art',q:"Combien de toiles Monet a-t-il consacrées aux Nymphéas ?",n:250,min:0,max:1500,u:"toiles",e:"Environ 250, peintes durant les trente dernières années de sa vie, presque toutes dans son jardin de Giverny. À la fin, la cataracte brouillait tellement ses couleurs qu’il peignait de mémoire."},
{t:'art',q:"Quelle longueur totale développent les Nymphéas de Monet au musée de l’Orangerie ?",n:100,min:0,max:400,u:"mètres",e:"Près de 100 mètres de toiles courbes, en huit panneaux répartis dans deux salles ovales. Monet a offert l’ensemble à la France au lendemain de l’armistice de 1918, comme un monument à la paix."},
{t:'art',q:"Combien de tableaux Frida Kahlo a-t-elle peints ?",n:143,min:0,max:200,u:"tableaux",e:"143 seulement, dont 55 autoportraits. Elle a commencé alitée, après un accident de bus, avec un miroir fixé au-dessus de son lit : c’est ce miroir qui explique tous ces visages."},
{t:'art',q:"Combien d’années Camille Claudel a-t-elle passées enfermée en asile ?",n:30,min:0,max:50,u:"ans",e:"Trente ans, de 1913 à sa mort en 1943, internée à la demande de sa famille alors que les médecins jugeaient sa sortie possible. Elle n’a plus jamais sculpté et repose dans une fosse commune."},
{t:'art',q:"Quelle taille faisait Toulouse-Lautrec ?",n:152,min:0,max:800,u:"cm",e:"Environ 1,52 m. Une maladie osseuse a stoppé la croissance de ses jambes après deux fractures adolescentes, laissant un buste d’adulte sur des jambes d’enfant. Les tables des cabarets, elles, étaient à sa hauteur."},
{t:'art',q:"À quel âge Grandma Moses s’est-elle mise à peindre ?",n:78,min:0,max:200,u:"ans",e:"À 78 ans, quand l’arthrite l’a empêchée de continuer à broder. Elle a produit plus de mille tableaux, exposé à New York, fait la une des magazines et travaillé jusqu’à sa mort, à 101 ans."},
{t:'art',q:"Quel âge avait Michel-Ange à sa mort ?",n:88,min:0,max:100,u:"ans",e:"88 ans, trois semaines avant son quatre-vingt-neuvième anniversaire, à une époque où l’on vivait rarement au-delà de quarante. Il sculptait encore une Pietà quelques jours avant la fin."},
{t:'art',q:"Combien pèse le David de Michel-Ange ?",n:5660,min:0,max:40000,u:"kg",e:"Près de 5,7 tonnes de marbre de Carrare, tirées d’un bloc que deux sculpteurs avaient déjà entamé puis abandonné comme irrécupérable. Michel-Ange a récupéré ce rebut et en a fait la statue la plus célèbre du monde."},
{t:'art',q:"Quelle hauteur fait le David de Michel-Ange, socle non compris ?",n:517,min:0,max:1000,u:"cm",e:"5,17 mètres : on l’imagine à taille humaine, il fait trois hommes. Il devait couronner la cathédrale de Florence, vu d’en bas, d’où sa tête et ses mains volontairement surdimensionnées."},
{t:'art',q:"Combien d’années le David est-il resté en plein air sur une place de Florence ?",n:369,min:0,max:400,u:"ans",e:"De 1504 à 1873, exposé à la pluie et au soleil devant le Palazzo Vecchio, avant d’être mis à l’abri. Ce qui trône aujourd’hui sur la place est une copie que personne ne regarde vraiment."},
{t:'art',q:"Quel âge avait Michel-Ange quand il a commencé le David ?",n:26,min:0,max:30,u:"ans",e:"Vingt-six ans. Le bloc traînait depuis des décennies dans la cour de la cathédrale, jugé bon à rien par les maîtres en place. Le jeune homme a emporté le contrat et travaillé plus de deux ans, souvent la nuit."},
{t:'art',q:"Combien de coups de marteau la Pietà de Michel-Ange a-t-elle reçus en 1972 ?",n:15,min:0,max:20,u:"coups",e:"Quinze, portés par un géologue australien qui hurlait qu’il était Jésus-Christ. Le bras gauche de la Vierge s’est brisé, son nez et sa paupière ont volé en éclats, et des touristes ont emporté des morceaux."},
{t:'art',q:"Combien de temps a duré la restauration de la Pietà après l’attaque au marteau ?",n:10,min:0,max:12,u:"mois",e:"Dix mois de puzzle. Les restaurateurs ont recollé une centaine d’éclats et comblé les manques avec de la poussière de marbre prélevée sur la statue elle-même. Elle vit depuis derrière une vitre blindée."},
{t:'art',q:"Combien de temps a duré la restauration de la Victoire de Samothrace au Louvre ?",n:10,min:0,max:15,u:"mois",e:"Dix mois, en 2013 et 2014, pour nettoyer un marbre grisonnant et redresser la proue de navire qui lui sert de socle. La statue a retrouvé sa blancheur, et beaucoup l’ont trouvée méconnaissable."},
{t:'art',q:"Combien de temps Ghiberti a-t-il mis pour réaliser les Portes du Paradis de Florence ?",n:27,min:0,max:120,u:"ans",e:"Vingt-sept ans, de 1425 à 1452, après en avoir déjà passé vingt et un sur une première porte. Michel-Ange, en les découvrant, aurait dit qu’elles méritaient d’ouvrir le paradis : le surnom est resté."},
{t:'art',q:"Pendant combien d’années Rodin a-t-il travaillé à La Porte de l’Enfer ?",n:37,min:0,max:100,u:"ans",e:"Trente-sept ans, de 1880 jusqu’à sa mort, sans jamais la livrer : le musée qui l’avait commandée n’a même pas vu le jour. Le Penseur et Le Baiser en sont des fragments devenus autonomes."},
{t:'art',q:"Combien de temps a duré la sculpture du mont Rushmore ?",n:14,min:0,max:30,u:"ans",e:"Quatorze ans, de 1927 à 1941, avec environ quatre cents ouvriers et beaucoup de dynamite : neuf dixièmes de la roche ont été arrachés à l’explosif. Aucun mort sur le chantier, ce qui tient du miracle."},
{t:'art',q:"Combien a coûté la sculpture du mont Rushmore ?",n:989992.32,min:0,max:1200000,u:"dollars",e:"989 992,32 dollars, au centime près, pour quatre visages de dix-huit mètres taillés dans une falaise. Le sculpteur Gutzon Borglum est mort quelques mois avant la fin, et son fils a arrêté le chantier."},
{t:'art',q:"Combien pèse la statue du Christ Rédempteur de Rio ?",n:635,min:0,max:2000,u:"tonnes",e:"635 tonnes de béton armé et de stéatite, hissées au sommet du Corcovado par un petit train à crémaillère. Ses bras ouverts font vingt-huit mètres d’envergure, presque autant que sa hauteur."},
{t:'art',q:"Combien pèse la pierre de Rosette ?",n:760,min:0,max:2500,u:"kg",e:"Environ 760 kg de granodiorite, et ce n’est qu’un fragment de stèle brisée, trouvé par hasard dans le mur d’un fort par des soldats de Bonaparte. Champollion a mis une vingtaine d’années à en tirer les hiéroglyphes."},
{t:'art',q:"Combien pèse le Codex Gigas, surnommé la Bible du Diable ?",n:75,min:0,max:200,u:"kg",e:"75 kg pour 92 cm de haut : il faut deux personnes pour le soulever. Environ 160 peaux de bêtes ont servi à le fabriquer, et la légende veut qu’un moine l’ait copié en une nuit, aidé par Satan."},
{t:'art',q:"Quelle proportion de la lumière le Vantablack, le noir le plus profond, absorbe-t-il ?",n:99.965,min:0,max:100,u:"%",e:"99,965 % : un objet recouvert de ce noir perd tout relief, l’œil ne voit plus qu’un trou. Anish Kapoor s’en est offert l’exclusivité artistique, déclenchant une guerre de pigments avec les autres artistes."},
{t:'art',q:"Combien d’ambre contenait la Chambre d’ambre disparue en 1945 ?",n:6,min:0,max:10,u:"tonnes",e:"Six tonnes d’ambre de la Baltique sur 55 mètres carrés de panneaux, offerts par la Prusse au tsar. Démontée par les nazis à Tsarskoïe Selo puis évacuée vers Königsberg, elle n’a jamais reparu."},
{t:'art',q:"Combien de temps a duré la reconstruction à l’identique de la Chambre d’ambre ?",n:24,min:0,max:150,u:"ans",e:"Vingt-quatre ans, de 1979 à 2003, par des artisans russes qui ont dû réinventer des techniques oubliées. Le chantier, à court d’argent, a été sauvé in extremis par un mécène allemand."},
{t:'art',q:"Combien de temps la grotte de Lascaux est-elle restée ouverte au public ?",n:15,min:0,max:40,u:"ans",e:"Quinze ans, de 1948 à 1963. Le souffle de plus d’un millier de visiteurs par jour a fait proliférer algues et calcite sur des peintures intactes depuis dix-sept millénaires. On a refermé en catastrophe."},
{t:'art',q:"Combien de temps a-t-il fallu pour construire le fac-similé Lascaux II ?",n:11,min:0,max:12,u:"ans",e:"Onze ans, de 1972 à 1983, à deux cents mètres de la vraie grotte. Les parois de béton ont été moulées au millimètre, puis repeintes avec les pigments et les gestes du Paléolithique."},
{t:'art',q:"Combien a coûté la réplique de la grotte Chauvet, ouverte en 2015 ?",n:55,min:0,max:100,u:"millions d’euros",e:"55 millions d’euros pour le plus grand fac-similé du monde : trois mille mètres carrés reproduisant une caverne que presque personne n’a le droit de voir. L’original abrite des peintures vieilles de 36 000 ans."},
{t:'art',q:"Quel âge a la plus ancienne peinture figurative connue, découverte en Indonésie ?",n:45500,min:0,max:80000,u:"ans",e:"45 500 ans : un cochon verruqueux grandeur nature, peint à l’ocre sur une paroi de Sulawesi et daté en 2021. Il devance de plusieurs millénaires les fresques européennes qu’on croyait pionnières."},
{t:'art',q:"Quelle est la hauteur de la Vénus de Willendorf ?",n:11.1,min:0,max:25,u:"cm",e:"11,1 cm : la plus célèbre statuette de la préhistoire tient dans une paume. Sculptée voici environ 30 000 ans dans un calcaire absent de la région, elle a voyagé sur des centaines de kilomètres."},
{t:'art',q:"Combien de personnages humains figurent sur la tapisserie de Bayeux ?",n:626,min:0,max:800,u:"personnages",e:"626, dont seulement trois femmes, au milieu de centaines de chevaux, de chiens et de navires. On y trouve aussi la plus ancienne représentation datée de la comète de Halley, prise pour un présage funeste."},
{t:'art',q:"Combien d’estampes compte la série des Trente-six vues du mont Fuji d’Hokusai ?",n:46,min:0,max:60,u:"estampes",e:"Quarante-six. Le succès fut tel que l’éditeur en commanda dix de plus sans se donner la peine de changer le titre. La Grande Vague n’était que la première planche de la série."},
{t:'art',q:"Combien de versions du Carré noir Malevitch a-t-il peintes ?",n:4,min:0,max:20,u:"versions",e:"Quatre, entre 1915 et 1932. La première a craquelé très vite, et sous les fissures les rayons X ont révélé deux compositions colorées cachées dessous, plus une inscription au crayon de la main du peintre."},
{t:'art',q:"Combien de peintures noires Goya a-t-il peintes sur les murs de sa maison ?",n:14,min:0,max:15,u:"peintures",e:"Quatorze, dont Saturne dévorant un de ses fils, appliquées à même le plâtre de sa villa alors qu’il était sourd et vieillissant. Il ne les a ni montrées ni titrées : on les a transposées sur toile après sa mort."},
{t:'art',q:"Combien d’espèces de fleurs Botticelli a-t-il peintes dans Le Printemps ?",n:190,min:0,max:500,u:"espèces",e:"190 espèces identifiables parmi cinq cents plantes recensées dans le tableau. Les botanistes en ont déduit la saison exacte de la scène, tant les détails de la campagne toscane sont fidèles."},
{t:'art',q:"Combien de personnages figurent dans La Ronde de nuit de Rembrandt ?",n:34,min:0,max:80,u:"personnages",e:"Trente-quatre, dont un chien et une fillette lumineuse jamais identifiée. La scène ne se passe même pas la nuit : c’est le vernis noirci qui a valu au tableau son surnom, deux siècles plus tard."},
{t:'art',q:"Combien Rembrandt a-t-il été payé pour La Ronde de nuit ?",n:1600,min:0,max:5000,u:"florins",e:"1 600 florins, financés par les miliciens eux-mêmes : chacun payait sa place dans le tableau, plus cher au premier rang. Ceux relégués dans l’ombre ont, dit-on, trouvé l’addition un peu salée."},
{t:'art',q:"Quelle définition atteint la photographie officielle de La Ronde de nuit ?",n:717,min:0,max:1200,u:"gigapixels",e:"717 gigapixels : chaque pixel couvre cinq micromètres, moins qu’un globule rouge. On peut zoomer jusqu’aux grains de pigment et voir les repentirs que Rembrandt croyait avoir définitivement recouverts."},
{t:'art',q:"Combien d’épisodes de son émission de peinture Bob Ross a-t-il tournés ?",n:403,min:0,max:500,u:"épisodes",e:"403, en trente et une saisons, chacun bouclé en moins d’une demi-heure devant la caméra. Il peignait chaque tableau trois fois : un modèle, un à l’antenne, un pour le livre. Presque aucun n’a été vendu."},
{t:'art',q:"Combien de fois Tehching Hsieh a-t-il pointé à l’horloge pour sa performance d’un an ?",n:8627,min:0,max:10000,u:"pointages",e:"8 627 fois, une par heure, jour et nuit, pendant une année entière. Il s’était rasé le crâne au départ pour que ses cheveux mesurent le temps. Il n’a raté que cent trente-trois pointages, en dormant."},
{t:'art',q:"Combien de coups de hachoir une suffragette a-t-elle portés à la Vénus au miroir de Vélasquez ?",n:7,min:0,max:10,u:"coups",e:"Sept, à la National Gallery en 1914, pour protester contre l’arrestation d’Emmeline Pankhurst. Mary Richardson expliqua détester la façon dont les visiteurs masculins bayaient devant ce nu toute la journée."},
{t:'art',q:"Combien a coûté la réparation du Rêve de Picasso après le coup de coude de son propriétaire ?",n:90000,min:0,max:300000,u:"dollars",e:"90 000 dollars pour recoudre une déchirure de quinze centimètres. Steve Wynn montrait la toile à des amis la veille de la vendre 139 millions ; la vente est tombée à l’eau. Il l’a cédée 155 millions plus tard."},
{t:'art',q:"Combien de jours un tableau de Matisse est-il resté accroché à l’envers au MoMA ?",n:47,min:0,max:80,u:"jours",e:"47 jours en 1961, devant plus de cent mille visiteurs, avant qu’un habitué ne signale l’erreur. Le tableau, Le Bateau, est un reflet sur l’eau : personne n’avait su dire où était le haut."},
{t:'art',q:"Pendant combien d’années un tableau de Mondrian est-il resté accroché à l’envers ?",n:75,min:0,max:600,u:"ans",e:"Environ 75 ans. New York City I est exposé tête en bas depuis 1945 ; une conservatrice l’a compris en 2022 grâce à une photo d’atelier. Le musée refuse de le retourner : les rubans risqueraient de se décoller."},
{t:'art',q:"Combien de temps La Joconde est-elle restée introuvable après son vol de 1911 ?",n:28,min:0,max:40,u:"mois",e:"Vingt-huit mois. Un vitrier italien employé au Louvre l’avait décrochée un lundi de fermeture et gardée dans une malle sous son lit, à trois kilomètres du musée, pendant que la police fouillait l’Europe."},
{t:'art',q:"Combien de temps le voleur de La Joconde a-t-il passé en prison ?",n:7,min:0,max:40,u:"mois",e:"Sept mois. Vincenzo Peruggia plaidait le patriotisme : il voulait rendre le tableau à l’Italie, ignorant que François Ier l’avait acheté. Les jurés italiens l’ont trouvé plutôt sympathique."},
{t:'art',q:"À quelle valeur La Joconde a-t-elle été assurée pour son voyage aux États-Unis en 1962 ?",n:100000000,min:0,max:150000000,u:"dollars",e:"100 millions de dollars, l’évaluation d’assurance la plus élevée jamais consignée. On a finalement renoncé à payer la prime : renforcer la garde coûtait moins cher que d’assurer l’inassurable."},
{t:'art',q:"Combien d’œuvres ont été volées au musée Isabella Stewart Gardner de Boston en 1990 ?",n:13,min:0,max:15,u:"œuvres",e:"Treize, dont l’unique marine connue de Rembrandt et un Vermeer. Les cadres vides sont toujours accrochés aux murs : le testament de la fondatrice interdit de modifier l’accrochage, même après un vol."},
{t:'art',q:"Combien de temps les voleurs sont-ils restés à l’intérieur du musée Gardner ?",n:81,min:0,max:300,u:"minutes",e:"81 minutes, déguisés en policiers, après avoir menotté deux gardiens au sous-sol. Ils ont pris leur temps, découpé les toiles, et laissé sur place des œuvres bien plus précieuses que celles emportées."},
{t:'art',q:"Combien de briques composent Equivalent VIII, l’œuvre de Carl Andre qui a scandalisé le Royaume-Uni ?",n:120,min:0,max:400,u:"briques",e:"120 briques réfractaires posées à plat sur le sol de la Tate. Quand la presse a révélé la somme payée par le musée, le pays a hurlé au gaspillage, et un visiteur est venu vider un colorant bleu dessus."},
{t:'art',q:"Combien de temps a duré le vol du Cri de Munch à Oslo en 1994 ?",n:50,min:0,max:60,u:"secondes",e:"Cinquante secondes : une échelle contre la façade, une vitre brisée, et un mot laissé sur place remerciant le musée pour sa faible sécurité. C’était le matin de l’ouverture des Jeux de Lillehammer."},
{t:'art',q:"Combien de versions du Cri Munch a-t-il réalisées ?",n:4,min:0,max:8,u:"versions",e:"Quatre, deux peintes et deux au pastel, sans compter une lithographie. Sur l’une d’elles, une phrase minuscule au crayon affirme que le tableau n’a pu être peint que par un fou. L’écriture est celle de Munch."},
{t:'art',q:"Combien d’œuvres le voleur Stéphane Breitwieser a-t-il dérobées ?",n:239,min:0,max:400,u:"œuvres",e:"239 pièces dans 172 musées européens, en sept ans, simplement glissées sous son manteau. Il ne revendait rien : il décorait sa chambre, et sa mère a détruit une partie du butin à son arrestation."},
{t:'art',q:"À combien d’années de prison le faussaire Wolfgang Beltracchi a-t-il été condamné ?",n:6,min:0,max:12,u:"ans",e:"Six ans, en 2011, pour des faux vendus des dizaines de millions. Il ne copiait rien : il inventait les tableaux que les maîtres auraient pu peindre. Un tube de blanc contenant du titane l’a trahi."},
{t:'art',q:"Combien Hermann Göring a-t-il payé le faux Vermeer peint par Van Meegeren ?",n:1650000,min:0,max:2000000,u:"florins",e:"1,65 million de florins. Accusé après-guerre d’avoir vendu un trésor national aux nazis, Van Meegeren n’a échappé à la trahison qu’en peignant un Vermeer devant les experts pour prouver que le tableau était de lui."},
{t:'art',q:"Combien de fois L’Agneau mystique de Van Eyck a-t-il été volé ou pillé ?",n:13,min:0,max:20,u:"fois",e:"Treize crimes recensés en six siècles : révolutionnaires, Napoléon, les deux guerres mondiales. Un panneau, Les Juges intègres, s’est volatilisé en 1934 et n’a jamais reparu ; l’enquête reste ouverte."},
{t:'art',q:"Combien d’années ont passé avant que les deux Van Gogh volés à Amsterdam en 2002 ne soient retrouvés ?",n:14,min:0,max:15,u:"ans",e:"Quatorze ans. Les toiles ont refait surface en 2016 dans une ferme près de Naples, chez un baron de la cocaïne, emballées dans du tissu et dissimulées derrière un mur de la cuisine."},
{t:'art',q:"Combien le Salvator Mundi avait-il été payé lors d’une vente de succession en 2005 ?",n:1175,min:0,max:10000,u:"dollars",e:"1 175 dollars. Noirci et lourdement repeint, le tableau passait pour une copie d’atelier sans intérêt. Douze ans et une restauration plus tard, il devenait l’œuvre la plus chère jamais adjugée."},
{t:'art',q:"Combien s’est vendu Interchange de Willem de Kooning en 2015 ?",n:300000000,min:0,max:400000000,u:"dollars",e:"300 millions de dollars, de gré à gré, entre deux milliardaires américains. Le même tableau était parti pour quatre mille dollars en 1955, quand de Kooning peignait encore dans un atelier sans chauffage."},
{t:'art',q:"Combien l’émir du Qatar a-t-il payé Les Joueurs de cartes de Cézanne ?",n:250000000,min:0,max:400000000,u:"dollars",e:"250 millions de dollars en 2011, plus du double du record mondial de l’époque, pour deux paysans qui jouent en silence sans un sou sur la table. Cézanne a peint cinq versions de la scène."},
{t:'art',q:"Combien s’est vendu le portrait de Marilyn Monroe par Warhol en 2022 ?",n:195000000,min:0,max:250000000,u:"dollars",e:"195 millions de dollars, record aux enchères pour une œuvre du XXe siècle. Warhol l’avait sérigraphiée d’après une simple photo promotionnelle du film Niagara, sans jamais avoir rencontré l’actrice."},
{t:'art',q:"Combien s’est vendu le Nu couché de Modigliani en 2015 ?",n:170400000,min:0,max:1500000000,u:"dollars",e:"170,4 millions de dollars, payés par un ancien chauffeur de taxi devenu magnat chinois. En 1917, la seule exposition de ces nus avait été fermée par la police parisienne pour outrage aux mœurs."},
{t:'art',q:"Combien s’est vendu L’Homme au doigt de Giacometti en 2015 ?",n:141300000,min:0,max:500000000,u:"dollars",e:"141,3 millions de dollars, record mondial pour une sculpture. Giacometti racontait l’avoir modelée en une seule nuit, entre minuit et neuf heures du matin, juste avant l’arrivée du fondeur."},
{t:'art',q:"Combien s’est vendu le Portrait du docteur Gachet de Van Gogh en 1990 ?",n:82500000,min:0,max:400000000,u:"dollars",e:"82,5 millions de dollars, record absolu à l’époque, pour un peintre qui n’avait presque rien vendu vivant. L’acheteur japonais a évoqué l’idée de se faire incinérer avec la toile ; elle a ensuite disparu des radars."},
{t:'art',q:"Combien d’images composent la mosaïque numérique Everydays vendue par Beeple ?",n:5000,min:0,max:8000,u:"images",e:"5 000, soit une image par jour sans exception pendant treize ans et demi. Les premières sont des gribouillis maladroits. L’ensemble a été adjugé par une maison de ventes vieille de deux siècles."},
{t:'art',q:"Combien s’est vendu le Portrait d’Edmond de Belamy, premier tableau signé par un algorithme ?",n:432500,min:0,max:3000000,u:"dollars",e:"432 500 dollars en 2018, contre une estimation de dix mille. Le portrait flou est signé d’une formule mathématique, et le code utilisé par le collectif français avait été publié gratuitement par un adolescent."},
{t:'art',q:"Combien s’est vendue la photographie Le Violon d’Ingres de Man Ray en 2022 ?",n:12400000,min:0,max:80000000,u:"dollars",e:"12,4 millions de dollars, record mondial pour une photographie. L’image ? Un dos de femme sur lequel Man Ray a simplement dessiné à l’encre les deux ouïes d’un violon avant de rephotographier le tirage."},
{t:'art',q:"Combien s’est vendue la toile de Banksy autodétruite, rebaptisée Love is in the Bin ?",n:18600000,min:0,max:30000000,u:"livres",e:"18,6 millions de livres en 2021, soit dix-huit fois le prix atteint juste avant que le broyeur caché dans le cadre ne se déclenche, trois ans plus tôt. Le mécanisme s’est enrayé à mi-course : c’est ce qui a tout fait."},
{t:'art',q:"Combien l’Art Institute de Chicago a-t-il payé Nighthawks d’Edward Hopper en 1942 ?",n:3000,min:0,max:10000,u:"dollars",e:"3 000 dollars, quelques mois après l’achèvement du tableau. Hopper disait avoir peint sans le vouloir la solitude d’une grande ville ; le diner du tableau n’a jamais été localisé et n’a sans doute jamais existé."},
{t:'art',q:"Quel prix American Gothic a-t-il remporté au concours de l’Art Institute en 1930 ?",n:300,min:0,max:1000,u:"dollars",e:"300 dollars, un simple troisième prix. Les modèles sont la sœur du peintre et son dentiste, et les fermières de l’Iowa se sont senties si caricaturées que l’une d’elles a menacé de lui mordre l’oreille."},
{t:'art',q:"Combien de toiles compose la série des boîtes de soupe Campbell d’Andy Warhol ?",n:32,min:0,max:80,u:"toiles",e:"Trente-deux, une par variété vendue à l’époque. La galerie les a d’abord alignées sur une étagère comme dans un supermarché, à cent dollars pièce ; un marchand voisin en a mis en vente à trente-trois cents par dérision."},
{t:'art',q:"Combien de boîtes composent les Time Capsules d’Andy Warhol ?",n:610,min:0,max:1200,u:"boîtes",e:"610 cartons dans lesquels il jetait tout : factures, invitations, ongles coupés, une part de gâteau de mariage, un pied momifié. Un musée a mis des décennies à en dresser l’inventaire complet."},
{t:'art',q:"Combien de temps dure Empire, le film d’Andy Warhol montrant l’Empire State Building ?",n:485,min:0,max:5000,u:"minutes",e:"485 minutes, soit plus de huit heures d’un unique plan fixe au ralenti, sans son. À la première projection, le public a hué puis déserté la salle. Warhol trouvait cela parfaitement réussi."},
{t:'art',q:"Combien de vitres compte la pyramide du Louvre ?",n:673,min:0,max:1500,u:"vitres",e:"673, et non 666 comme le veut la rumeur diabolique tenace : 603 losanges et 70 triangles. Le verre a été fabriqué sur mesure, extra-blanc, pour ne pas verdir la vue sur le palais."},
{t:'art',q:"Combien de portiques safran Christo a-t-il installés dans Central Park pour The Gates ?",n:7503,min:0,max:12000,u:"portiques",e:"7 503, plantés sur trente-sept kilomètres d’allées pendant seize jours de février 2005. Le projet avait attendu vingt-six ans une autorisation de la ville, et l’artiste a tout financé lui-même."},
{t:'art',q:"Combien de graines de porcelaine composent l’œuvre Sunflower Seeds d’Ai Weiwei ?",n:100000000,min:0,max:250000000,u:"graines",e:"Cent millions, peintes une à une à la main par mille six cents artisans de Jingdezhen, l’ancienne capitale de la porcelaine impériale. Étalées, elles couvraient tout le hall de la Tate Modern."},
{t:'art',q:"Combien de diamants sont sertis sur le crâne en platine de Damien Hirst ?",n:8601,min:0,max:20000,u:"diamants",e:"8 601, pour plus de mille carats, sur un moulage de crâne humain du XVIIIe siècle dont les vraies dents ont été conservées. Titre de l’œuvre : Pour l’amour de Dieu, ce qu’aurait soupiré sa mère devant le devis."},
{t:'art',q:"Combien d’heures Marina Abramović est-elle restée assise face au public au MoMA ?",n:736,min:0,max:1000,u:"heures",e:"736 heures, immobile sur une chaise pendant près de trois mois, sans manger ni parler de la journée. Des milliers d’inconnus se sont assis en face ; beaucoup ont fondu en larmes sans savoir pourquoi."},

/* ---------- Miam ---------- */
{t:'cuisine',q:"Combien de litres de bière recevaient chaque jour les bâtisseurs des pyramides ?",n:4,min:0,max:20,u:"litres",e:"Environ 4 litres par jour, versés en guise de salaire. C'était une boisson nourrissante et plus sûre que l'eau du Nil."},
{t:'cuisine',q:"Combien d'unités Scoville atteint le piment Pepper X ?",n:2693000,min:0,max:4000000,u:"unités",e:"2 693 000 unités, environ mille fois un jalapeño. Son créateur dit avoir passé trois heures et demie au sol, pris de crampes."},
{t:'cuisine',q:"Combien de graines porte une fraise en moyenne ?",n:200,min:0,max:250,u:"graines",e:"Environ 200 — et ce ne sont pas des graines mais de minuscules fruits secs. La fraise elle-même n'est donc pas un fruit au sens botanique."},
{t:'cuisine',q:"Combien s'est vendu le melon Yubari le plus cher du monde ?",n:45000,min:0,max:60000,u:"dollars",e:"45 000 dollars la paire, lors d'une enchère au Japon. Ces melons sont massés, coiffés d'un petit chapeau contre le soleil et vendus comme des cadeaux de prestige."},
{t:'cuisine',q:"Après combien d'années du miel retrouvé en Égypte était-il encore comestible ?",n:3000,min:0,max:5000,u:"ans",e:"Plus de 3 000 ans. Trop acide et trop pauvre en eau pour les bactéries, le miel est l'un des rares aliments qui ne périment jamais."},
{t:'cuisine',q:"Combien de mois minimum un Parmigiano Reggiano doit-il s’affiner ?",n:12,min:0,max:20,u:"mois",e:"Douze mois, et un expert vient frapper chaque meule au marteau pour écouter le son. Une meule qui sonne creux est déclassée et perd le droit au nom."},
{t:'cuisine',q:"Combien de litres de lait faut-il pour fabriquer une seule meule de Parmigiano Reggiano ?",n:550,min:0,max:1000,u:"litres",e:"Environ 550 litres, soit la traite quotidienne d’une vingtaine de vaches. Tout ça pour un disque de 40 kg qui attendra ensuite un an minimum sur une étagère."},
{t:'cuisine',q:"Combien pèse une meule entière de Parmigiano Reggiano ?",n:40,min:0,max:80,u:"kg",e:"Environ 40 kg. Les meules sont si précieuses qu’une banque italienne, le Credem, les accepte en garantie de prêt et en stocke des centaines de milliers dans ses coffres."},
{t:'cuisine',q:"Combien de mois le vin jaune du Jura doit-il rester en fût sans être touché ?",n:75,min:0,max:120,u:"mois",e:"Six ans et trois mois, soit 75 mois, sous un voile de levures. Interdit de compléter le tonneau : l’évaporation fait son œuvre pendant que le vin prend son goût de noix."},
{t:'cuisine',q:"Quelle est la contenance de la bouteille de vin jaune, le clavelin ?",n:62,min:0,max:100,u:"cl",e:"62 cl, seule bouteille de ce format autorisée en Europe. C’est ce qu’il reste d’un litre après six ans et trois mois d’évaporation en fût. Le manque est devenu le format officiel."},
{t:'cuisine',q:"Combien d’années minimum vieillit un vrai vinaigre balsamique traditionnel de Modène ?",n:12,min:0,max:25,u:"ans",e:"Douze ans minimum, transvasé de fût en fût de bois différents. La version extravecchio en demande 25. Le liquide industriel du supermarché, lui, sort en quelques heures."},
{t:'cuisine',q:"Combien de jours minimum le Roquefort doit-il s’affiner ?",n:90,min:0,max:100,u:"jours",e:"Quatre-vingt-dix jours, dont une partie obligatoire dans les caves naturelles du Combalou. Les fissures de la falaise, les fleurines, y soufflent un air humide et frais toute l’année."},
{t:'cuisine',q:"Combien de mois minimum sèche un jambon de Bayonne ?",n:7,min:0,max:20,u:"mois",e:"Sept mois au minimum, souvent douze. Le vent du sud, le foehn, sèche les jambons pendus dans les séchoirs : c’est lui, autant que le sel, qui fait le goût."},
{t:'cuisine',q:"Combien de mois minimum sèche un jambon de Parme avant d’être couronné ?",n:12,min:0,max:100,u:"mois",e:"Douze mois minimum avant l’inspection finale. Un expert enfonce une aiguille en os de cheval dans cinq points du jambon et sent : l’os absorbe et relâche l’odeur instantanément."},
{t:'cuisine',q:"Combien d’années la purée de piments du Tabasco vieillit-elle en fût de chêne ?",n:3,min:0,max:5,u:"ans",e:"Trois ans dans d’anciens fûts de whisky, scellés au sel de la mine d’Avery Island. La sauce contient trois ingrédients : piments, sel, vinaigre. Tout le reste, c’est du temps."},
{t:'cuisine',q:"Combien de mois la sauce Worcestershire mature-t-elle avant d’être mise en bouteille ?",n:18,min:0,max:60,u:"mois",e:"Dix-huit mois. La recette originale, jugée immangeable, avait été abandonnée dans une cave par ses inventeurs ; redécouverte par hasard des mois plus tard, elle était devenue délicieuse."},
{t:'cuisine',q:"Combien de mois la sauce soja japonaise traditionnelle fermente-t-elle ?",n:6,min:0,max:12,u:"mois",e:"Six mois environ pour le moromi, la pâte de soja, blé et saumure. Les sauces chimiques bas de gamme, elles, sont obtenues en quelques jours par hydrolyse à l’acide."},
{t:'cuisine',q:"Combien de jours l’ail noir doit-il vieillir en étuve pour devenir noir et sucré ?",n:60,min:0,max:80,u:"jours",e:"Environ 60 jours vers 60-70 °C. Aucune fermentation microbienne : c’est la réaction de Maillard, la même qui brunit un steak, mais étalée sur deux mois au lieu de deux minutes."},
{t:'cuisine',q:"Combien de mois minimum un champagne millésimé doit-il reposer sur ses lies ?",n:36,min:0,max:100,u:"mois",e:"Trente-six mois pour un millésimé, contre quinze pour un brut sans année. Les grandes maisons vont souvent bien au-delà : c’est là que naissent les notes de brioche et de noisette."},
{t:'cuisine',q:"Combien d’années minimum un whisky doit-il vieillir en fût pour avoir droit au nom Scotch ?",n:3,min:0,max:10,u:"ans",e:"Trois ans en fût de chêne sur le sol écossais. En dessous, légalement, ce n’est pas du whisky : c’est du « spirit ». Le fût donne jusqu’à 70 % du goût final."},
{t:'cuisine',q:"Combien d’années minimum vieillit un cognac portant la mention XO ?",n:10,min:0,max:15,u:"ans",e:"Dix ans depuis 2018, contre six auparavant. VS en demande deux, VSOP quatre. L’âge affiché est toujours celui de la plus jeune eau-de-vie de l’assemblage, jamais la moyenne."},
{t:'cuisine',q:"Quel pourcentage d’un fût de cognac s’évapore chaque année, la fameuse « part des anges » ?",n:2,min:0,max:100,u:"%",e:"Environ 2 % par an. Sur les grands millésimes, cela représente l’équivalent de millions de bouteilles envolées. Un champignon noir, le Torula, se nourrit de ces vapeurs et noircit les murs de Cognac."},
{t:'cuisine',q:"Quelle est la contenance d’une barrique bordelaise traditionnelle ?",n:225,min:0,max:600,u:"litres",e:"225 litres, format figé depuis le XIXe siècle. Cette taille précise a été choisie pour le rapport idéal entre le volume de vin et la surface de bois qui l’aromatise."},
{t:'cuisine',q:"Combien de bouteilles de 75 cl remplit une barrique bordelaise ?",n:300,min:0,max:600,u:"bouteilles",e:"Exactement 300 bouteilles pour 225 litres. C’est l’unité de compte des châteaux : on parle d’une production en barriques bien avant d’en parler en cols."},
{t:'cuisine',q:"Combien de mois minimum s’affine un comté ?",n:4,min:0,max:15,u:"mois",e:"Quatre mois minimum, mais les meilleurs dépassent 24 mois. Chaque meule reçoit une note sur 20 : en dessous de 12, elle perd sa bande verte et son identité de comté."},
{t:'cuisine',q:"Combien de mois minimum s’affine un beaufort ?",n:5,min:0,max:15,u:"mois",e:"Cinq mois sur planches d’épicéa, retournées et frottées au sel. Sa croûte concave vient du cercle de bois de hêtre qui l’enserre pendant le pressage, signature unique du beaufort."},
{t:'cuisine',q:"À quelle température chauffe-t-on le vin de Madère pendant l’estufagem ?",n:45,min:0,max:80,u:"°C",e:"Environ 45 °C pendant au moins trois mois. La technique imite les traversées de l’équateur en cale de navire, quand la chaleur des tropiques « cuisait » le vin et l’améliorait par accident."},
{t:'cuisine',q:"Combien de mois faut-il pour qu’un rhizome de wasabi véritable arrive à maturité ?",n:24,min:0,max:30,u:"mois",e:"Environ deux ans dans une eau de source courante à température constante. C’est l’une des cultures les plus exigeantes au monde : la plupart des « wasabi » servis sont du raifort teinté."},
{t:'cuisine',q:"Combien de mois une gousse de vanille mûrit-elle sur la liane avant récolte ?",n:9,min:0,max:20,u:"mois",e:"Neuf mois sur la liane, puis six mois de préparation, échaudage et séchage, pour qu’elle devienne noire et parfumée. Verte et fraîche, la gousse n’a aucune odeur."},
{t:'cuisine',q:"Combien d’heures la fleur de vanille reste-t-elle ouverte pour être pollinisée ?",n:12,min:0,max:80,u:"heures",e:"Une seule matinée, une douzaine d’heures. Hors du Mexique il n’y a pas de pollinisateur : chaque fleur est fécondée à la main, une par une, technique trouvée par un esclave de 12 ans à La Réunion."},
{t:'cuisine',q:"À quelle température monte le four à bois d’une vraie pizza napolitaine ?",n:485,min:0,max:1500,u:"°C",e:"Environ 485 °C sur la sole, soit deux fois plus qu’un four ménager à fond. À cette chaleur, la pâte gonfle avant d’avoir le temps de sécher : c’est ce qui fait la bordure boursouflée."},
{t:'cuisine',q:"Combien de secondes cuit une pizza napolitaine dans son four à bois ?",n:90,min:0,max:100,u:"secondes",e:"Quatre-vingt-dix secondes maximum selon le cahier des charges napolitain. Le pizzaiolo la tourne une fois en cours de route. Une minute d’inattention et il ne reste qu’un disque de charbon."},
{t:'cuisine',q:"À quelle température un grain de maïs explose-t-il en pop-corn ?",n:180,min:0,max:400,u:"°C",e:"Vers 180 °C. L’eau piégée dans le grain devient vapeur sous près de 9 bars, l’enveloppe cède et l’amidon se retourne comme un gant. Le « pop » est l’onde de choc de la vapeur."},
{t:'cuisine',q:"Quel pourcentage d’eau un grain de maïs doit-il contenir pour éclater correctement ?",n:14,min:0,max:100,u:"%",e:"Environ 14 %. Un point de moins et il n’explose pas, un point de plus et il gonfle mollement. C’est pourquoi les vieux paquets ratent : le grain a séché en silence."},
{t:'cuisine',q:"À partir de quelle température démarre la réaction de Maillard qui dore les aliments ?",n:140,min:0,max:150,u:"°C",e:"Vers 140 °C. En dessous, l’aliment cuit mais reste pâle : c’est pour ça qu’on ne dore rien dans de l’eau bouillante, bloquée à 100 °C. Il faut sécher la surface pour la brunir."},
{t:'cuisine',q:"À quelle température le sucre de table commence-t-il à caraméliser ?",n:160,min:0,max:250,u:"°C",e:"Environ 160 °C. Le saccharose se décompose alors en centaines de molécules nouvelles, dont celles du goût de caramel. Vingt degrés plus haut, tout devient amer et noir."},
{t:'cuisine',q:"À quelle température le blanc d’œuf commence-t-il à coaguler ?",n:62,min:0,max:150,u:"°C",e:"Vers 62 °C, alors que le jaune attend 65 °C. Cet écart de trois degrés est tout le secret de l’œuf parfait : cuit à 64 °C, il sort avec un blanc pris et un jaune crémeux."},
{t:'cuisine',q:"À quelle température se forme la gelée d’une confiture ?",n:105,min:0,max:200,u:"°C",e:"À 105 °C environ. Ce n’est pas une durée mais une température : le sirop atteint la bonne concentration en sucre, et la pectine peut enfin nouer son réseau en refroidissant."},
{t:'cuisine',q:"À quelle température fond le beurre de cacao du chocolat ?",n:34,min:0,max:80,u:"°C",e:"Vers 34 °C, juste sous la température du corps. C’est la raison exacte pour laquelle le chocolat fond dans la bouche et pas dans la poche : aucune autre matière grasse ne fait ça."},
{t:'cuisine',q:"À quelle température faut-il faire redescendre le chocolat noir pour le tempérer ?",n:31,min:0,max:40,u:"°C",e:"Autour de 31 °C après un passage à 50 puis 28. Le but : ne garder que les bons cristaux de beurre de cacao. Ratez la courbe et le chocolat sort terne, mou et blanchi."},
{t:'cuisine',q:"À quelle température chauffe-t-on le lait UHT ?",n:140,min:0,max:150,u:"°C",e:"Environ 140 °C, mais deux à quatre secondes seulement. Ce choc éclair tue tout sans cuire le lait, et permet à une brique fermée de tenir des mois hors du réfrigérateur."},
{t:'cuisine',q:"À quelle température monte l’intérieur d’une cocotte-minute ?",n:120,min:0,max:1000,u:"°C",e:"Environ 120 °C. La pression fait bouillir l’eau au-dessus de 100 °C, et ces vingt degrés supplémentaires divisent les temps de cuisson par trois. Même principe que l’autoclave des hôpitaux."},
{t:'cuisine',q:"Sous quelle pression l’eau traverse-t-elle le café dans une machine à espresso ?",n:9,min:0,max:15,u:"bars",e:"Neuf bars, soit près de dix fois la pression atmosphérique, ou celle qu’on subirait à 90 mètres sous l’eau. C’est cette violence qui arrache les huiles et crée la crema."},
{t:'cuisine',q:"Combien de grains de café faut-il environ pour un seul espresso ?",n:50,min:0,max:120,u:"grains",e:"Une cinquantaine, pour sept grammes de mouture. Comme un caféier donne à peine 500 g de café torréfié par an, un seul arbre couvre environ soixante-dix espressos annuels."},
{t:'cuisine',q:"À quelle température les grains de café éclatent-ils lors du premier crack en torréfaction ?",n:196,min:0,max:400,u:"°C",e:"Vers 196 °C. Le grain double presque de volume et craque comme du pop-corn : c’est le signal sonore que le torréfacteur attend. Le second crack, plus loin, annonce déjà le brûlé."},
{t:'cuisine',q:"À quelle température fait-on fermenter un yaourt ?",n:45,min:0,max:200,u:"°C",e:"Autour de 45 °C pendant quelques heures. Deux bactéries y travaillent en duo : l’une acidifie, l’autre épaissit. En dessous de 40 °C elles boudent, au-dessus de 50 °C elles meurent."},
{t:'cuisine',q:"Quelle pression règne dans une bouteille de champagne fermée ?",n:6,min:0,max:10,u:"bars",e:"Environ 6 bars, trois fois un pneu de voiture. Le verre pèse près de 900 g pour tenir le coup, et le muselet fait exactement six tours et demi de fil de fer."},
{t:'cuisine',q:"Combien de bulles contient une flûte de champagne ?",n:1000000,min:0,max:3000000,u:"bulles",e:"Environ un million, selon les travaux du physicien Gérard Liger-Belair. Chacune naît sur une minuscule fibre de cellulose collée au verre : dans un verre parfaitement propre, presque aucune bulle ne monte."},
{t:'cuisine',q:"Combien de plantes entrent dans la recette de la Chartreuse verte ?",n:130,min:0,max:400,u:"plantes",e:"Cent trente plantes, selon un manuscrit de 1605 que seuls deux moines connaissent à la fois. Ils ne voyagent jamais ensemble. La liqueur vieillit ensuite dans la plus grande cave à liqueur du monde."},
{t:'cuisine',q:"Combien d’unités Scoville atteint en moyenne le piment Carolina Reaper ?",n:1641183,min:0,max:12000000,u:"unités",e:"1 641 183 unités de moyenne au test Guinness, avec des pics au-delà de deux millions. Son créateur, Ed Currie, l’a obtenu en croisant un habanero rouge et un piment pakistanais."},
{t:'cuisine',q:"Combien d’unités Scoville atteint le piment Bhut Jolokia, dit piment fantôme ?",n:1000000,min:0,max:1200000,u:"unités",e:"Plus d’un million : premier piment à franchir cette barre en 2007. En Inde, l’armée en a rempli des grenades lacrymogènes, et les paysans en enduisent les clôtures pour éloigner les éléphants."},
{t:'cuisine',q:"Jusqu’à combien d’unités Scoville peut monter un piment habanero ?",n:350000,min:0,max:500000,u:"unités",e:"Jusqu’à 350 000 unités. Pendant des décennies il fut le plus fort du monde, avant d’être ridiculisé par ses propres descendants : le Carolina Reaper est cinq fois plus violent."},
{t:'cuisine',q:"Jusqu’à combien d’unités Scoville monte un simple jalapeño ?",n:8000,min:0,max:30000,u:"unités",e:"Autour de 8 000 au maximum, souvent moitié moins. C’est deux cents fois moins qu’un Carolina Reaper : le jalapeño passerait presque pour un poivron dans la cour des grands."},
{t:'cuisine',q:"Combien d’unités Scoville affiche la sauce Tabasco rouge classique ?",n:2500,min:0,max:8000,u:"unités",e:"Entre 2 500 et 5 000 seulement, soit moins qu’un jalapeño moyen. Le vinaigre et le sel diluent la purée de piments : la réputation de la petite bouteille dépasse largement sa force réelle."},
{t:'cuisine',q:"Combien d’unités Scoville atteint la capsaïcine pure ?",n:16000000,min:0,max:40000000,u:"unités",e:"Seize millions, le plafond absolu de l’échelle. C’est un cristal blanc inodore, insoluble dans l’eau : d’où l’inutilité totale de boire un verre d’eau après une bouchée trop pimentée."},
{t:'cuisine',q:"Combien pesait la pastèque la plus lourde jamais cultivée ?",n:159,min:0,max:250,u:"kg",e:"159 kg, cultivée dans le Tennessee par Chris Kent. Il faut plusieurs adultes et une sangle pour la soulever. À ce poids, le fruit s’écrase sous son propre jus s’il n’est pas soutenu."},
{t:'cuisine',q:"Combien pesait le chou le plus lourd jamais cultivé ?",n:62.71,min:0,max:200,u:"kg",e:"62,71 kg, en Alaska. Le secret local : l’été polaire offre près de vingt heures de lumière par jour, et les légumes géants y poussent comme nulle part ailleurs."},
{t:'cuisine',q:"Combien pesait le citron le plus lourd jamais récolté ?",n:5.265,min:0,max:25,u:"kg",e:"5,265 kg en Israël, l’équivalent d’un nouveau-né bien portant. Un citron ordinaire pèse 120 grammes : celui-ci en valait plus de quarante à lui seul."},
{t:'cuisine',q:"Combien pesait la fraise la plus lourde jamais récoltée ?",n:289,min:0,max:500,u:"g",e:"289 grammes, en Israël, née de la fusion accidentelle de plusieurs fleurs en un seul fruit difforme. Une fraise normale pèse 20 grammes : celle-ci en valait quatorze."},
{t:'cuisine',q:"Combien pesait la pomme la plus lourde jamais cueillie ?",n:1.849,min:0,max:10,u:"kg",e:"1,849 kg, cultivée au Japon par Chisato Iwasaki. Les vergers japonais de pommes géantes taillent brutalement l’arbre pour ne laisser qu’un fruit par branche, qui reçoit toute la sève."},
{t:'cuisine',q:"Combien pesait le radis le plus lourd jamais cultivé ?",n:31.1,min:0,max:50,u:"kg",e:"31,1 kg : un radis sakurajima de Kagoshima, au Japon, qui pousse dans les cendres volcaniques. Ces radis géants sont ronds comme des ballons de plage et se mangent mijotés."},
{t:'cuisine',q:"Combien pesait la plus grosse truffe blanche d’Alba jamais trouvée ?",n:1.89,min:0,max:3,u:"kg",e:"1,89 kg, adjugée aux enchères à un magnat de Macao. Impossible à cultiver, la truffe blanche ne pousse qu’en symbiose avec certains arbres : on ne peut que la chercher, jamais la produire."},
{t:'cuisine',q:"Combien pesait le thon rouge vendu 333 millions de yens au marché de Toyosu ?",n:278,min:0,max:300,u:"kg",e:"278 kg pour environ 2,7 millions d’euros, soit près de 10 000 euros le kilo. L’acheteur, surnommé le roi du thon, assumait payer très au-dessus du marché pour la publicité."},
{t:'cuisine',q:"Combien pèse un œuf d’autruche ?",n:1.4,min:0,max:2,u:"kg",e:"Environ 1,4 kg, l’équivalent de vingt-quatre œufs de poule. Sa coquille supporte le poids d’un adulte debout dessus, et il faut près d’une heure et demie pour le cuire dur."},
{t:'cuisine',q:"Combien de jours se conserve réellement un Twinkie, le gâteau réputé éternel ?",n:45,min:0,max:60,u:"jours",e:"Quarante-cinq jours, et non des décennies. La légende de l’immortalité vient de sa recette sans lait ni œufs frais : il ne moisit pas vite, il devient simplement immangeable."},
{t:'cuisine',q:"Quel âge a le plus vieux pain jamais retrouvé par les archéologues ?",n:14400,min:0,max:25000,u:"ans",e:"14 400 ans, dans un foyer du désert jordanien. Il précède l’agriculture de plusieurs millénaires : on faisait donc du pain avec des céréales sauvages avant même d’avoir l’idée de les semer."},
{t:'cuisine',q:"Quel âge ont les plus anciennes traces de vin jamais découvertes ?",n:8000,min:0,max:25000,u:"ans",e:"Environ 8 000 ans, dans des jarres géorgiennes du Caucase. Les chimistes y ont trouvé de l’acide tartrique, signature du raisin. La Géorgie s’en sert comme argument touristique national."},
{t:'cuisine',q:"Quel âge a le plus vieux fromage jamais retrouvé sur des momies ?",n:3600,min:0,max:12000,u:"ans",e:"3 600 ans, posé sur la poitrine de momies du désert du Taklamakan, en Chine. L’analyse ADN a identifié un fromage de kéfir : les bactéries lactiques étaient encore identifiables."},
{t:'cuisine',q:"Combien d’années un esturgeon beluga doit-il vivre avant de produire son premier caviar ?",n:20,min:0,max:25,u:"ans",e:"Une vingtaine d’années avant la première ponte. Un éleveur doit donc financer deux décennies de nourriture avant la moindre recette : c’est toute l’explication du prix du caviar."},
{t:'cuisine',q:"De combien de mètres carrés de prairie chaque poulet de Bresse dispose-t-il ?",n:10,min:0,max:50,u:"m²",e:"Dix mètres carrés d’herbe par volaille, imposés par l’AOP. Un élevage industriel en met vingt au mètre carré. Le poulet de Bresse est le seul au monde à bénéficier d’une appellation d’origine."},
{t:'cuisine',q:"Jusqu’à quelle note monte l’échelle japonaise de persillage du bœuf, le BMS ?",n:12,min:0,max:20,u:"points",e:"Douze. Au-delà de huit, la viande est plus grasse que maigre et fond presque à température ambiante. Les classements occidentaux s’arrêtent bien plus tôt : le fameux A5 japonais démarre à huit."},
{t:'cuisine',q:"Combien de mois doit vieillir une mimolette pour être dite extra-vieille ?",n:24,min:0,max:30,u:"mois",e:"Vingt-quatre mois. Sa croûte creusée est l’œuvre de micro-acariens vivants, les cirons, qu’on laisse volontairement la grignoter pour aérer la pâte. Les États-Unis l’ont un temps interdite pour cette raison."},
{t:'cuisine',q:"Combien de mois fermente le nuoc-mâm de Phu Quoc dans ses cuves de bois ?",n:12,min:0,max:15,u:"mois",e:"Douze mois d’anchois et de sel dans des tonneaux de bois, sans rien d’autre. Le premier jus tiré, le plus concentré, ne se cuisine pas : il se sert tel quel, comme un grand cru."},
{t:'cuisine',q:"De combien de centimètres une asperge peut-elle grandir en une seule journée ?",n:25,min:0,max:50,u:"cm",e:"Jusqu’à 25 cm par jour quand le sol est chaud. Les producteurs récoltent parfois deux fois dans la même journée : une asperge oubliée le matin est bonne à jeter le soir."},
{t:'cuisine',q:"Combien de mois un plant d’ananas met-il à produire un seul fruit ?",n:24,min:0,max:30,u:"mois",e:"Environ deux ans pour un fruit unique. Chaque ananas est en réalité la fusion de dizaines de fleurs soudées ensemble : les losanges de sa peau sont les cicatrices de chacune d’elles."},
{t:'cuisine',q:"Combien de café torréfié un caféier produit-il en une année ?",n:500,min:0,max:2500,u:"g",e:"Environ 500 grammes, soit un paquet de supermarché. Le buveur quotidien consomme donc à lui seul la récolte annuelle de plusieurs dizaines d’arbres."},
{t:'cuisine',q:"Combien de litres d’eau faut-il pour produire un kilo de bœuf ?",n:15400,min:0,max:20000,u:"litres",e:"Environ 15 400 litres, en comptant surtout l’eau des cultures fourragères. C’est le contenu d’une petite piscine pour un seul kilo, contre à peine 130 litres pour un kilo de tomates."},
{t:'cuisine',q:"À quelle vitesse maximale le ketchup Heinz doit-il couler pour être jugé conforme ?",n:0.045,min:0,max:0.15000000000000002,u:"km/h",e:"0,045 km/h. Si la sauce coule plus vite, le lot est refusé : elle est jugée trop liquide. C’est un des rares aliments au monde dont le contrôle qualité mesure la lenteur."},
{t:'cuisine',q:"Combien de grammes de sucre contient une canette de 33 cl de Coca-Cola classique ?",n:35,min:0,max:80,u:"g",e:"Trente-cinq grammes, soit environ sept morceaux de sucre. L’acide phosphorique masque le goût : sans lui, la boisson serait écœurante de douceur au point d’être imbuvable."},
{t:'cuisine',q:"Combien de dents compte le biscuit Petit-Beurre de LU ?",n:52,min:0,max:100,u:"dents",e:"Cinquante-deux dents, comme les semaines de l’année. Le biscuit a aussi quatre coins pour les saisons et vingt-quatre trous pour les heures : c’est un calendrier déguisé en gâteau."},
{t:'cuisine',q:"Combien de plis compte traditionnellement la toque d’un chef cuisinier ?",n:100,min:0,max:120,u:"plis",e:"Cent plis, censés représenter les cent façons de cuire un œuf. La hauteur, elle, marquait le rang : plus la toque était haute, plus le cuisinier régnait sur la brigade."},
{t:'cuisine',q:"Combien de grains de raisin les Espagnols avalent-ils au douzième coup de minuit le 31 décembre ?",n:12,min:0,max:60,u:"grains",e:"Douze, un par coup d’horloge et par mois de l’année. La tradition vient d’une surproduction de raisin d’Alicante en 1909 : les viticulteurs ont inventé la coutume pour écouler leur stock."},
{t:'cuisine',q:"Combien d’ingrédients la loi allemande de pureté de la bière de 1516 autorisait-elle ?",n:3,min:0,max:6,u:"ingrédients",e:"Trois : eau, orge et houblon. La levure manquait à l’appel, personne ne soupçonnait encore son existence. C’est la plus vieille réglementation alimentaire du monde encore invoquée aujourd’hui."},
{t:'cuisine',q:"Combien de cépages différents l’appellation Châteauneuf-du-Pape autorise-t-elle ?",n:13,min:0,max:20,u:"cépages",e:"Treize, blancs et rouges mélangés, cas unique en France. Presque personne ne les utilise tous : assembler treize vins issus de treize vendanges différentes relève de l’exploit sportif."},
{t:'cuisine',q:"Combien de cépages sont autorisés dans l’appellation Champagne ?",n:7,min:0,max:8,u:"cépages",e:"Sept, alors que tout le monde n’en cite que trois. L’arbanne, le petit meslier, le pinot blanc et le pinot gris survivent sur quelques parcelles confidentielles, jalousement entretenues."},
{t:'cuisine',q:"Combien de litres contient une bouteille de champagne appelée Melchisédech ?",n:30,min:0,max:200,u:"litres",e:"Trente litres, soit quarante bouteilles classiques, pour un poids total dépassant 50 kg. Il faut deux personnes pour la servir, et le verre doit tenir six bars de pression."},
{t:'cuisine',q:"Combien de secondes dure le service en deux temps d’une pinte de Guinness ?",n:119.5,min:0,max:400,u:"secondes",e:"Cent dix-neuf secondes et demie. La marque en a fait un argument publicitaire mondial : « Good things come to those who wait ». Le repos permet aux bulles d’azote de descendre puis de remonter."},
{t:'cuisine',q:"Combien de plis un chef doit-il faire sur un xiaolongbao dans les restaurants Din Tai Fung ?",n:18,min:0,max:20,u:"plis",e:"Dix-huit plis exactement, et le raviolo cru doit peser cinq grammes à un demi-gramme près. Chaque cuisine est vitrée pour que les clients vérifient le pliage en direct."},
{t:'cuisine',q:"Combien de grains de riz un maître sushi met-il dans un nigiri ?",n:300,min:0,max:600,u:"grains",e:"Environ trois cents, façonnés en quelques secondes sans jamais les écraser. Un vrai itamae obtient une boule assez ferme pour être saisie aux baguettes et qui se défait en bouche."},
{t:'cuisine',q:"Combien de personnes le foie d’un seul poisson-globe pourrait-il tuer ?",n:30,min:0,max:50,u:"personnes",e:"Une trentaine d’adultes. La tétrodotoxine est mille fois plus puissante que le cyanure et n’a aucun antidote : la victime reste consciente, paralysée, jusqu’à l’arrêt de la respiration."},
{t:'cuisine',q:"Combien d’années dure la formation obligatoire d’un cuisinier de fugu au Japon ?",n:3,min:0,max:4,u:"ans",e:"Environ trois ans avant l’examen de licence, que la majorité des candidats ratent. Il faut découper le poisson devant un jury, puis manger sa propre préparation. L’examen le plus persuasif du monde."},
{t:'cuisine',q:"De combien de centimètres les asticots du casu marzu sarde peuvent-ils bondir ?",n:15,min:0,max:30,u:"cm",e:"Jusqu’à quinze centimètres, d’où l’usage local de manger ce fromage en protégeant ses yeux. Les larves de mouche digèrent la pâte et la rendent crémeuse. Le fromage est officiellement interdit à la vente."},
{t:'cuisine',q:"Combien de tonnes de tomates sont écrasées lors de la Tomatina de Buñol ?",n:150,min:0,max:1500,u:"tonnes",e:"Environ 150 tonnes en une heure. Les tomates sont trop mûres pour la vente et cultivées exprès pour la bataille. Une règle : les écraser dans la main avant de les lancer."},
{t:'cuisine',q:"Combien de minutes les candidats du Bocuse d’Or ont-ils pour réaliser leurs plats ?",n:335,min:0,max:1200,u:"minutes",e:"Cinq heures trente-cinq, soit 335 minutes chrono, devant un public qui klaxonne et agite des drapeaux comme au stade. C’est le seul concours de cuisine où l’on encourage les chefs en criant."},
{t:'cuisine',q:"Combien de fromages différents la France comptait-elle selon la formule célèbre du général de Gaulle ?",n:246,min:0,max:400,u:"fromages",e:"Deux cent quarante-six, dans sa phrase sur l’impossibilité de gouverner un tel pays. Le chiffre exact varie selon les versions rapportées, mais 246 est resté celui de la légende."},
{t:'cuisine',q:"Combien de variétés de pommes de terre cultive-t-on au Pérou ?",n:4000,min:0,max:6000,u:"variétés",e:"Environ quatre mille, de toutes les couleurs, dont beaucoup ne poussent qu’à une altitude précise. Les supermarchés du monde entier en vendent une poignée : l’Europe n’a rapporté qu’une infime partie du trésor."},
{t:'cuisine',q:"Combien de grains porte un épi de maïs en moyenne ?",n:800,min:0,max:2000,u:"grains",e:"Environ huit cents, répartis sur seize rangées. Le nombre de rangées est toujours pair, sans exception : chaque fleur femelle se développe par paires le long de l’épi."},
{t:'cuisine',q:"Combien d’arilles contient une grenade en moyenne ?",n:600,min:0,max:4000,u:"arilles",e:"Environ six cents petites billes juteuses, chacune enfermant une graine. Un mythe tenace veut qu’elles soient toujours 613, comme les commandements de la Torah : les compteurs patients ont démenti."},
{t:'cuisine',q:"Combien de fèves contient une cabosse de cacao ?",n:40,min:0,max:200,u:"fèves",e:"Une quarantaine, entourées d’une pulpe blanche sucrée qu’on laisse fermenter plusieurs jours à même le sol. Sans cette fermentation, la fève reste amère et ne sentira jamais le chocolat."},
{t:'cuisine',q:"Combien de fleurs de crocus faut-il cueillir pour obtenir un seul gramme de safran sec ?",n:150,min:0,max:400,u:"fleurs",e:"Environ cent cinquante fleurs, dont on ne garde que les trois stigmates rouges. Tout se fait à la main, à l’aube, avant que le soleil n’ouvre les pétales. D’où le prix."},
{t:'cuisine',q:"Combien de cacahuètes entrent dans un pot de beurre de cacahuète de 340 grammes ?",n:540,min:0,max:2500,u:"cacahuètes",e:"Environ 540. La cacahuète n’est d’ailleurs pas une noix mais une légumineuse, cousine du petit pois, et son fruit mûrit sous terre après que la fleur s’est enfoncée dans le sol."},
{t:'cuisine',q:"Combien de kilos d’olives faut-il presser pour obtenir un litre d’huile d’olive ?",n:5,min:0,max:40,u:"kg",e:"Environ cinq kilos, soit le fruit de tout un arbre modeste. L’huile doit être extraite dans les heures qui suivent la cueillette : au-delà, l’olive s’oxyde et l’acidité grimpe."},
{t:'cuisine',q:"Combien de passages de louche exige le moulage d’un camembert de Normandie AOP ?",n:5,min:0,max:12,u:"louches",e:"Cinq passages minimum, espacés d’environ quarante minutes, à la louche et à la main. Cette lenteur laisse le caillé s’égoutter sans se casser : c’est ce qui donne la texture crémeuse."},
{t:'cuisine',q:"Combien de couches compte une pâte feuilletée classique après ses six tours ?",n:729,min:0,max:1000,u:"couches",e:"Sept cent vingt-neuf, car chaque tour triple le nombre de couches : trois puissance six. Chacune est plus fine qu’un cheveu, et c’est la vapeur d’eau qui les décolle à la cuisson."},

/* ---------- Machines ---------- */
{t:'techno',q:"Combien de bitcoins ont servi à payer deux pizzas en 2010 ?",n:10000,min:0,max:25000,u:"bitcoins",e:"10 000 bitcoins pour deux pizzas — la première transaction commerciale en cryptomonnaie. Les développeurs fêtent encore ce jour-là, avec un goût amer."},
{t:'techno',q:"Combien pesait le tout premier téléphone portable commercialisé ?",n:1100,min:0,max:1200,u:"grammes",e:"1,1 kg pour le DynaTAC de 1983, avec 30 minutes d'autonomie et 10 heures de charge. Il coûtait l'équivalent d'une petite voiture."},
{t:'techno',q:"Combien de temps a duré le premier vol des frères Wright ?",n:12,min:0,max:15,u:"secondes",e:"12 secondes et 37 mètres — moins que l'envergure d'un avion de ligne moderne. Le quatrième vol du même jour a tenu 59 secondes."},
{t:'techno',q:"Après combien de jours de vol continu un bug forçait-il à redémarrer le Boeing 787 ?",n:248,min:0,max:300,u:"jours",e:"248 jours : un compteur interne débordait et pouvait couper toute l'alimentation électrique en plein vol. Le correctif officiel a d'abord été « éteindre et rallumer l'avion »."},
{t:'techno',q:"Combien Knight Capital a-t-elle perdu en 45 minutes à cause d'un bug, en 2012 ?",n:440,min:0,max:800,u:"millions de dollars",e:"440 millions de dollars en trois quarts d'heure. Un vieux code réactivé par erreur s'est mis à acheter haut et vendre bas, en boucle, tout seul."},
{t:'techno',q:"Depuis combien d'années brûle l'ampoule centenaire de Livermore ?",n:125,min:0,max:200,u:"ans",e:"Allumée depuis 1901, elle a survécu à trois webcams chargées de la surveiller. Filament épais et jamais éteinte : le secret de sa longévité."},
{t:'techno',q:"Combien pesait l’ENIAC, le premier grand calculateur électronique ?",n:27,min:0,max:50,u:"tonnes",e:"27 tonnes étalées sur 167 m² pour moins de puissance qu’une calculette de supermarché. Les techniciens marchaient à l’intérieur de la machine pour aller remplacer les tubes grillés."},
{t:'techno',q:"Combien de tubes à vide contenait l’ENIAC ?",n:17468,min:0,max:20000,u:"tubes",e:"17 468 tubes, dont plusieurs claquaient chaque jour. L’équipe finit par ne plus jamais éteindre la machine : c’est l’allumage à froid qui tuait les tubes, pas le calcul."},
{t:'techno',q:"Après combien d’essais les chimistes ont-ils obtenu la formule du WD-40 ?",n:40,min:0,max:400,u:"essais",e:"WD-40 signifie « Water Displacement, 40th formula ». Le nom du produit est littéralement un compte-rendu d’échec : trente-neuf ratages affichés sur chaque bombe vendue depuis."},
{t:'techno',q:"Quelle capacité avait le tout premier disque dur, l’IBM 350 de 1956 ?",n:5,min:0,max:6,u:"mégaoctets",e:"5 mégaoctets, soit une seule photo de smartphone, dans une armoire d’une tonne louée des milliers de dollars par mois. Sa livraison exigeait un avion cargo."},
{t:'techno',q:"Combien de plateaux tournaient dans le premier disque dur d’IBM ?",n:50,min:0,max:80,u:"plateaux",e:"Cinquante disques de 61 cm empilés, tournant à 1 200 tours par minute, balayés par une tête unique qui se déplaçait de l’un à l’autre. Un juke-box en acier."},
{t:'techno',q:"Combien de pièces mécaniques comptait le calculateur Harvard Mark I ?",n:765000,min:0,max:5000000,u:"pièces",e:"765 000 composants, 800 km de fil et quinze mètres de long. Grace Hopper y programmait dans un vacarme d’horlogerie qu’on entendait dans tout le bâtiment."},
{t:'techno',q:"Combien de tubes électroniques comptait le Colossus Mark 2 de Bletchley Park ?",n:2400,min:0,max:5000,u:"tubes",e:"2 400 tubes pour casser les codes allemands. Machine si secrète que Churchill ordonna de détruire les exemplaires : l’Angleterre a effacé son propre premier ordinateur."},
{t:'techno',q:"Combien de mots de mémoire avait le Manchester Baby, premier ordinateur à programme enregistré ?",n:32,min:0,max:80,u:"mots",e:"32 mots, soit 1 024 bits en tout, moins qu’un SMS. Sa mémoire était un tube cathodique : les données étaient littéralement des points lumineux sur un écran."},
{t:'techno',q:"Combien de temps a tourné le tout premier programme informatique enregistré, en 1948 ?",n:52,min:0,max:120,u:"minutes",e:"52 minutes et 3,5 millions d’opérations pour trouver le plus grand diviseur d’un nombre. Un téléphone d’aujourd’hui règle le même calcul en une fraction de milliseconde."},
{t:'techno',q:"Combien pesait l’UNIVAC I, premier ordinateur commercial américain ?",n:13,min:0,max:20,u:"tonnes",e:"13 tonnes et 5 200 tubes. En 1952, il prédit correctement l’élection d’Eisenhower ; la chaîne CBS, incrédule, refusa de diffuser la prévision avant d’avoir le résultat."},
{t:'techno',q:"Combien pesait l’AN/FSQ-7 du réseau SAGE, le plus gros ordinateur jamais construit ?",n:250,min:0,max:800,u:"tonnes",e:"250 tonnes, 60 000 tubes, trois mégawatts : un ordinateur de la taille d’un immeuble pour surveiller le ciel américain. Chaque centre en abritait deux, pour ne jamais s’arrêter."},
{t:'techno',q:"Combien pesait le Cray-1, superordinateur star des années 1970 ?",n:5.5,min:0,max:8,u:"tonnes",e:"5,5 tonnes, dont une bonne part de circuit de refroidissement au fréon. Sa forme en C n’était pas du design : elle raccourcissait les câbles pour gagner des nanosecondes."},
{t:'techno',q:"Combien coûtait un Cray-1 à sa sortie ?",n:8800000,min:0,max:40000000,u:"dollars",e:"8,8 millions de dollars pièce, banquette en cuir comprise autour de la machine. Seuls des laboratoires nationaux et des météorologues pouvaient s’en offrir un."},
{t:'techno',q:"Combien de transistors comptait l’Intel 4004, le premier microprocesseur ?",n:2300,min:0,max:2500,u:"transistors",e:"2 300 transistors sur une puce plus petite qu’un ongle, conçue à l’origine pour une calculatrice japonaise. Les processeurs actuels en alignent des dizaines de milliards."},
{t:'techno',q:"Combien de mots de mémoire vive avait l’ordinateur de bord d’Apollo 11 ?",n:2048,min:0,max:2500,u:"mots",e:"2 048 mots de mémoire effaçable, environ 4 ko. La mémoire fixe, elle, était tissée à la main fil par fil par des ouvrières : on l’appelait la mémoire « petites vieilles »."},
{t:'techno',q:"À quelle fréquence tournait le processeur de l’ordinateur d’Apollo 11 ?",n:2.048,min:0,max:3,u:"mégahertz",e:"2,048 MHz, environ mille fois moins qu’un téléphone actuel. Cette machine a pourtant géré une descente lunaire tout en encaissant ses alarmes de surcharge en direct."},
{t:'techno',q:"Combien de kilooctets de mémoire embarque la sonde Voyager 1 ?",n:70,min:0,max:120,u:"kilooctets",e:"Environ 70 ko au total, moins qu’une petite image. Avec ça, la sonde pilote ses instruments depuis presque cinquante ans, à plus de vingt milliards de kilomètres de nous."},
{t:'techno',q:"Combien de mémoire vive avait le premier Macintosh, en 1984 ?",n:128,min:0,max:300,u:"kilooctets",e:"128 ko, si juste que le système et une application se disputaient chaque octet. Les développeurs parlaient du « Mac 128 » comme d’une épreuve sportive."},
{t:'techno',q:"Combien coûtait l’Apple I à sa mise en vente ?",n:666.66,min:0,max:1000,u:"dollars",e:"666,66 dollars. Wozniak a choisi ce prix parce qu’il aimait les chiffres répétés et que cela faisait un tiers de marge sur le prix de gros. Aucun rapport avec le diable."},
{t:'techno',q:"Combien coûtait l’Apple Lisa au lancement ?",n:9995,min:0,max:12000,u:"dollars",e:"9 995 dollars de 1983, le prix d’une voiture neuve, pour un échec commercial retentissant. Apple finit par enterrer près de trois mille Lisa invendues dans une décharge de l’Utah."},
{t:'techno',q:"Combien coûtaient trois minutes du premier service téléphonique transatlantique, en 1927 ?",n:75,min:0,max:100,u:"dollars",e:"75 dollars les trois minutes, soit plusieurs semaines de salaire ouvrier. La liaison passait par radio en ondes longues et le moindre orage rendait la conversation inaudible."},
{t:'techno',q:"Combien coûtait le kit de l’Altair 8800, l’ordinateur qui a lancé la micro-informatique ?",n:439,min:0,max:1200,u:"dollars",e:"439 dollars, livré en pièces détachées, sans clavier ni écran : on le programmait avec des interrupteurs. C’est pour lui que Gates et Allen écrivirent leur premier logiciel."},
{t:'techno',q:"De combien une pièce d’un penny posée sur le balancier de Big Ben modifie-t-elle son avance quotidienne ?",n:0.4,min:0,max:0.6000000000000001,u:"secondes",e:"Quatre dixièmes de seconde par jour et par penny. Les horlogers règlent encore la plus célèbre horloge du monde en empilant de la petite monnaie sur le balancier."},
{t:'techno',q:"Combien de brevets américains Thomas Edison a-t-il déposés ?",n:1093,min:0,max:3000,u:"brevets",e:"1 093 brevets à son nom, soit environ un tous les quinze jours pendant quarante ans. Son laboratoire de Menlo Park fonctionnait comme une usine à inventions salariée."},
{t:'techno',q:"Combien a coûté à IBM le développement de la gamme System/360 ?",n:5000000000,min:0,max:6000000000,u:"dollars",e:"Environ cinq milliards de dollars des années 1960, davantage que le projet Manhattan. IBM a littéralement misé l’existence de l’entreprise sur une seule famille d’ordinateurs."},
{t:'techno',q:"Combien de positions par seconde Deep Blue pouvait-il évaluer face à Kasparov ?",n:200000000,min:0,max:300000000,u:"positions",e:"200 millions de positions par seconde, contre deux ou trois pour un grand maître humain. Kasparov perdit surtout parce qu’un bug produisit un coup qu’il crut génial."},
{t:'techno',q:"Combien pesait Deep Blue, l’ordinateur qui a battu Kasparov ?",n:1.4,min:0,max:2,u:"tonnes",e:"1,4 tonne réparties en deux armoires noires de deux mètres. Le champion du monde d’échecs affrontait littéralement un réfrigérateur industriel de trente processeurs."},
{t:'techno',q:"Combien de lettres du tout premier message envoyé sur ARPANET sont arrivées à destination ?",n:2,min:0,max:5,u:"lettres",e:"Deux. Ils tapaient « LOGIN » ; le système a planté après le « L » et le « O ». Le premier mot d’Internet fut donc « LO », comme un « lo and behold » involontaire."},
{t:'techno',q:"Combien d’ordinateurs étaient reliés à ARPANET à ses débuts ?",n:4,min:0,max:6,u:"ordinateurs",e:"Quatre nœuds en Californie et dans l’Utah. Tout Internet descend d’un réseau qu’on pouvait dessiner intégralement sur un coin de nappe."},
{t:'techno',q:"Combien de personnes ont reçu le tout premier courriel publicitaire non sollicité, en 1978 ?",n:393,min:0,max:600,u:"destinataires",e:"393 utilisateurs d’ARPANET, invités à une démonstration d’ordinateurs. L’indignation fut immédiate et le premier spam de l’histoire valut un blâme officiel à son auteur."},
{t:'techno',q:"Combien d’ordinateurs le ver Morris a-t-il infectés en 1988 ?",n:6000,min:0,max:10000,u:"ordinateurs",e:"Environ 6 000 machines, soit près d’un dixième de l’Internet de l’époque. L’étudiant voulait mesurer la taille du réseau ; une erreur de code fit se recopier le ver sans fin."},
{t:'techno',q:"À quelle amende l’auteur du ver Morris a-t-il été condamné ?",n:10050,min:0,max:15000,u:"dollars",e:"10 050 dollars et du travail d’intérêt général : première condamnation au titre de la loi américaine sur la fraude informatique. Il est aujourd’hui professeur au MIT."},
{t:'techno',q:"Quel taux de clic affichait la toute première bannière publicitaire du Web, en 1994 ?",n:44,min:0,max:100,u:"%",e:"44 % des internautes cliquaient sur cette bannière d’AT&T qui demandait « Avez-vous déjà cliqué ici ? ». Trente ans plus tard, le taux moyen tourne autour de 0,05 %."},
{t:'techno',q:"À combien de vues le compteur de YouTube a-t-il débordé avec « Gangnam Style » ?",n:2147483647,min:0,max:6000000000,u:"vues",e:"2 147 483 647 : la limite d’un entier signé sur 32 bits. Le clip a forcé YouTube à repasser tous ses compteurs en 64 bits, de quoi tenir jusqu’à 9 trillions de vues."},
{t:'techno',q:"Combien de caractères peut contenir un SMS classique ?",n:160,min:0,max:600,u:"caractères",e:"160, chiffre choisi par un ingénieur allemand qui a tapé au hasard des phrases sur sa machine à écrire et constaté qu’une pensée complète tenait presque toujours dessous."},
{t:'techno',q:"Combien de boutons comptait la toute première souris d’ordinateur ?",n:3,min:0,max:4,u:"boutons",e:"Trois, faute de place dans le boîtier de bois : Engelbart en rêvait cinq, un par doigt. Sa souris ne rapporta rien, le brevet ayant expiré avant que le grand public en achète."},
{t:'techno',q:"Combien de temps a duré « la mère de toutes les démos » d’Engelbart en 1968 ?",n:90,min:0,max:120,u:"minutes",e:"90 minutes où il présenta d’un coup la souris, le visioconférence, l’hypertexte, le copier-coller et l’édition collaborative. La salle a applaudi debout, puis a mis vingt ans à comprendre."},
{t:'techno',q:"Combien de cartes perforées fallait-il pour tisser le célèbre portrait de Jacquard sur son propre métier ?",n:24000,min:0,max:40000,u:"cartes",e:"24 000 cartes perforées pour un seul portrait en soie. Babbage en possédait un exemplaire : cette image tissée est l’ancêtre direct du programme informatique."},
{t:'techno',q:"Combien de pièces compte la machine à différences n°2 de Babbage, construite au XXe siècle d’après ses plans ?",n:8000,min:0,max:30000,u:"pièces",e:"8 000 pièces et cinq tonnes de laiton et de fonte. Assemblée en 1991 selon les dessins d’origine, elle a fonctionné du premier coup : Babbage avait raison depuis cent cinquante ans."},
{t:'techno',q:"Combien d’engrenages en bronze a-t-on retrouvés dans la machine d’Anticythère ?",n:30,min:0,max:40,u:"engrenages",e:"Trente roues dentées repêchées d’une épave antique, capables de prédire éclipses et positions planétaires. Il faudra attendre les horloges médiévales pour revoir une telle mécanique."},
{t:'techno',q:"Combien de dents compte la plus grande roue de la machine d’Anticythère ?",n:223,min:0,max:400,u:"dents",e:"223 dents, exactement le nombre de mois du cycle de Saros qui régit le retour des éclipses. Les Grecs avaient encodé l’astronomie dans du métal découpé à la main."},
{t:'techno',q:"Combien d’exemplaires de la Bible à quarante-deux lignes Gutenberg a-t-il imprimés ?",n:180,min:0,max:1500,u:"exemplaires",e:"Environ 180 exemplaires, dont une quarantaine survivent. Chacun demandait la peau de plus de cent veaux pour le parchemin : l’imprimerie a d’abord été une affaire d’élevage."},
{t:'techno',q:"Combien de temps après le lancement la fusée Ariane 5 s’est-elle autodétruite lors de son vol inaugural ?",n:37,min:0,max:60,u:"secondes",e:"37 secondes. Un logiciel recyclé d’Ariane 4 a tenté de loger une vitesse trop grande dans un petit format de nombre ; l’ordinateur a rendu les armes en plein vol."},
{t:'techno',q:"Combien a coûté l’explosion du vol inaugural d’Ariane 5 ?",n:370000000,min:0,max:800000000,u:"dollars",e:"Environ 370 millions de dollars partis en fumée à cause de quelques lignes de code inutilisées, qui tournaient encore par simple héritage du modèle précédent."},
{t:'techno',q:"Combien a coûté la perte de la sonde Mars Climate Orbiter, victime d’une confusion d’unités ?",n:125000000,min:0,max:200000000,u:"dollars",e:"125 millions de dollars. Un sous-traitant calculait en livres-force, la NASA en newtons : la sonde a visé une orbite 170 km trop basse et s’est désintégrée dans l’atmosphère martienne."},
{t:'techno',q:"Combien a coûté à Intel le bug de division du Pentium ?",n:475000000,min:0,max:600000000,u:"dollars",e:"475 millions de dollars de provision pour remplacer les puces. L’erreur n’apparaissait qu’à la neuvième décimale d’une division, mais Intel avait d’abord répondu que cela n’avait aucune importance."},
{t:'techno',q:"Au bout de combien d’heures allumé fallait-il redémarrer les systèmes de l’Airbus A350 selon une directive de sécurité ?",n:149,min:0,max:250,u:"heures",e:"149 heures. Un compteur logiciel finissait par déborder ; l’autorité américaine a donc imposé d’éteindre et de rallumer l’avion, la solution la plus vieille de l’informatique."},
{t:'techno',q:"De combien de mois le système automatisé de bagages a-t-il retardé l’ouverture de l’aéroport de Denver ?",n:16,min:0,max:20,u:"mois",e:"Seize mois de retard pour des chariots robotisés qui déchiquetaient les valises pendant les essais. Le système fut finalement abandonné au profit de tapis roulants classiques."},
{t:'techno',q:"Combien a coûté le fiasco du système de bagages automatisé de l’aéroport de Denver ?",n:560000000,min:0,max:1200000000,u:"dollars",e:"560 millions de dollars pour un labyrinthe de 40 km de rails. Pendant les tests, les chariots lançaient les bagages en l’air : les images ont fait le tour du monde."},
{t:'techno',q:"De combien le miroir du télescope Hubble était-il mal poli au moment de son lancement ?",n:2.2,min:0,max:2.5,u:"micromètres",e:"2,2 micromètres d’écart sur les bords, soit un cinquantième d’épaisseur de cheveu. Assez pour rendre floues toutes les images et exiger une mission de réparation en orbite."},
{t:'techno',q:"Combien de points de défaillance unique comptait le déploiement du télescope James Webb ?",n:344,min:0,max:1000,u:"points",e:"344 mécanismes qui devaient tous fonctionner du premier coup, à un million et demi de kilomètres, sans possibilité de réparation. Les ingénieurs ont retenu leur souffle deux semaines."},
{t:'techno',q:"Quelle est la circonférence de l’anneau du Grand collisionneur de hadrons ?",n:26.659,min:0,max:40,u:"kilomètres",e:"26,659 km d’anneau enterré sous la frontière franco-suisse. Les protons y font environ onze mille tours par seconde, soit plus de trois cents millions de kilomètres par jour."},
{t:'techno',q:"À quelle température, en kelvins, sont refroidis les aimants du Grand collisionneur de hadrons ?",n:1.9,min:0,max:3,u:"kelvins",e:"1,9 kelvin, soit plus froid que l’espace intersidéral. L’accélérateur du CERN est l’endroit le plus glacial de tout le système solaire connu, et il est sous nos pieds."},
{t:'techno',q:"Quel pourcentage de la vitesse de la lumière atteignent les protons du Grand collisionneur de hadrons ?",n:99.9999991,min:0,max:100,u:"%",e:"99,9999991 %. Sur un tour d’anneau, ils ne perdent que quelques mètres par seconde face à un photon : la différence tient dans un mouchoir de poche relativiste."},
{t:'techno',q:"Quelle puissance a produit Chicago Pile-1, le premier réacteur nucléaire de l’histoire ?",n:0.5,min:0,max:1.5,u:"watts",e:"Un demi-watt lors de la première réaction en chaîne contrôlée, moins qu’une veilleuse. Le réacteur était empilé sous les gradins d’un terrain de squash universitaire."},
{t:'techno',q:"Combien de blocs de graphite ont été empilés pour construire Chicago Pile-1 ?",n:45000,min:0,max:80000,u:"blocs",e:"45 000 blocs taillés à la main par des étudiants couverts de poussière noire. Le premier réacteur nucléaire ressemblait à un gigantesque jeu de construction en crayon à papier."},
{t:'techno',q:"Quel diamètre faisait l’antenne du radiotélescope d’Arecibo ?",n:305,min:0,max:600,u:"mètres",e:"305 mètres de réflecteur posés dans une cuvette naturelle de Porto Rico. Impossible de l’orienter : on attendait simplement que la Terre tourne pour viser une autre région du ciel."},
{t:'techno',q:"Combien pesait une fusée Saturn V au décollage ?",n:2970,min:0,max:5000,u:"tonnes",e:"Près de 2 970 tonnes, dont l’essentiel en carburant. La charge utile envoyée vers la Lune représentait à peine 1,5 % de cette masse : tout le reste servait à s’arracher du sol."},
{t:'techno',q:"Quelle poussée développait le premier étage de la Saturn V ?",n:34.5,min:0,max:50,u:"méganewtons",e:"34,5 méganewtons pour cinq moteurs F-1 avalant plusieurs tonnes de kérosène et d’oxygène par seconde. Les vibrations faisaient tomber des morceaux de plafond à cinq kilomètres."},
{t:'techno',q:"À quelle vitesse le transporteur à chenilles de la NASA amène-t-il une fusée sur son pas de tir ?",n:1.6,min:0,max:5,u:"km/h",e:"1,6 km/h en charge, soit trois fois moins vite qu’un marcheur tranquille. Ce mastodonte de plus de deux mille tonnes met une demi-journée pour parcourir six kilomètres."},
{t:'techno',q:"Pendant combien de jours Spoutnik 1 a-t-il émis son fameux bip ?",n:21,min:0,max:30,u:"jours",e:"Vingt et un jours, jusqu’à épuisement des piles. Les radioamateurs du monde entier ont enregistré ce signal ; le satellite, lui, a continué de tourner muet pendant trois mois."},
{t:'techno',q:"Combien de temps a duré le vol de Youri Gagarine, premier homme dans l’espace ?",n:108,min:0,max:400,u:"minutes",e:"108 minutes, un seul tour de Terre. Gagarine ne pilotait rien : les commandes étaient verrouillées par un code, au cas où l’apesanteur lui ferait perdre la raison."},
{t:'techno',q:"Quelle vitesse maximale a atteint le rover lunaire des missions Apollo ?",n:18,min:0,max:25,u:"km/h",e:"18 km/h en descente, record établi par Eugene Cernan. Un garde-boue cassé fut réparé avec du ruban adhésif et des cartes plastifiées, sous peine de couvrir l’équipage de poussière."},
{t:'techno',q:"À quelle vitesse maximale roule le rover martien Curiosity ?",n:4,min:0,max:8,u:"cm/s",e:"Quatre centimètres par seconde, soit moins de 150 mètres par heure. Une tortue le distancerait sans effort, mais elle n’aurait pas à éviter les rochers avec dix minutes de décalage radio."},
{t:'techno',q:"Combien de temps a duré la descente de Curiosity dans l’atmosphère martienne ?",n:7,min:0,max:20,u:"minutes",e:"Sept minutes de terreur : parachute, rétrofusées puis grue volante déposant le rover au bout de câbles. Le signal mettant quatorze minutes à arriver, tout était joué avant qu’on le sache."},
{t:'techno',q:"Combien de vols l’hélicoptère martien Ingenuity a-t-il effectués ?",n:72,min:0,max:150,u:"vols",e:"72 vols pour une démonstration technologique qui n’en prévoyait que cinq. Il s’est arrêté sur une pale endommagée, après avoir prouvé qu’on peut voler dans un air cent fois plus ténu."},
{t:'techno',q:"Quelle distance la sonde Rosetta a-t-elle parcourue avant d’atteindre sa comète ?",n:6400000000,min:0,max:10000000000,u:"kilomètres",e:"6,4 milliards de kilomètres et dix ans de voyage, avec trois passages près de la Terre pour prendre de l’élan. Elle a même hiberné trente et un mois pour économiser l’énergie."},
{t:'techno',q:"Quelle vitesse record la sonde Parker Solar Probe a-t-elle atteinte près du Soleil ?",n:692000,min:0,max:1000000,u:"km/h",e:"692 000 km/h, l’objet le plus rapide jamais construit : elle traverserait la France en moins de dix secondes. Son bouclier encaisse plus de mille degrés pendant la manœuvre."},
{t:'techno',q:"Quelle est la puissance de l’émetteur radio de la sonde Voyager 1 ?",n:23,min:0,max:25,u:"watts",e:"23 watts, comme une ampoule de réfrigérateur. Après vingt milliards de kilomètres, le signal reçu sur Terre est un milliardième de milliardième de watt, et on l’entend quand même."},
{t:'techno',q:"Combien a coûté le développement privé du stylo à bille utilisable en apesanteur ?",n:1000000,min:0,max:2000000,u:"dollars",e:"Environ un million de dollars, payés par Paul Fisher seul, pas par la NASA. L’agence a simplement acheté les stylos ensuite, à quelques dollars pièce, tout comme les Soviétiques."},
{t:'techno',q:"De combien de microsecondes par jour les horloges des satellites GPS doivent-elles être corrigées à cause de la relativité ?",n:38,min:0,max:200,u:"microsecondes",e:"38 microsecondes par jour. Sans cette correction d’Einstein, le GPS dériverait de dix kilomètres par jour et deviendrait inutilisable en une matinée."},
{t:'techno',q:"Au bout de combien d’années l’horloge atomique NIST-F2 prendrait-elle une seconde d’écart ?",n:300000000,min:0,max:800000000,u:"années",e:"300 millions d’années pour se tromper d’une seconde. Cette horloge au césium est si stable qu’elle détecte le ralentissement du temps quand on la soulève de quelques centimètres."},
{t:'techno',q:"Quelle vitesse de croisière atteignait le Concorde ?",n:2179,min:0,max:10000,u:"km/h",e:"2 179 km/h, soit deux fois la vitesse du son. À 18 000 mètres, les passagers voyaient la courbure de la Terre et un ciel presque noir en plein après-midi."},
{t:'techno',q:"Combien de minutes a mis le Concorde pour son vol record New York–Londres ?",n:172,min:0,max:250,u:"minutes",e:"2 h 52 min 59 s en 1996. Avec le décalage horaire, on atterrissait à Londres à une heure locale antérieure à celle du décollage : on arrivait avant d’être parti."},
{t:'techno',q:"Quelle vitesse record a atteint le SR-71 Blackbird ?",n:3529.6,min:0,max:10000,u:"km/h",e:"3 529,6 km/h, record du monde toujours debout pour un avion à réaction habité. Le frottement chauffait la carlingue à plus de 300 °C et allongeait l’appareil de plusieurs centimètres."},
{t:'techno',q:"Combien de minutes a mis le SR-71 Blackbird pour relier New York à Londres ?",n:115,min:0,max:150,u:"minutes",e:"1 h 54 min 56 s en 1974. L’avion fuyait son carburant au sol, faute d’étanchéité : ses tôles ne se refermaient qu’une fois dilatées par la chaleur du vol supersonique."},
{t:'techno',q:"Quelle vitesse maximale a atteint l’avion-fusée X-15 ?",n:7274,min:0,max:12000,u:"km/h",e:"7 274 km/h, soit Mach 6,7 : record absolu pour un avion piloté. Largué depuis un bombardier, il brûlait tout son carburant en quatre-vingt-dix secondes puis planait jusqu’au désert."},
{t:'techno',q:"Combien de pièces compose un Boeing 747 ?",n:6000000,min:0,max:15000000,u:"pièces",e:"Environ six millions de pièces, dont la moitié sont des fixations. L’usine construite pour l’assembler à Everett reste le plus grand bâtiment du monde en volume."},
{t:'techno',q:"Quelle longueur de câblage électrique un Boeing 747 embarque-t-il ?",n:274,min:0,max:500,u:"kilomètres",e:"274 km de fils enroulés dans la carlingue, de quoi relier Paris à Lille. Chaque faisceau est monté à la main : l’avion est plus proche du tricot industriel qu’on ne l’imagine."},
{t:'techno',q:"Combien de passagers un Airbus A380 peut-il légalement transporter au maximum ?",n:853,min:0,max:1000,u:"passagers",e:"853 en configuration tout-économique certifiée. Le test d’évacuation impose de vider l’appareil en quatre-vingt-dix secondes, avec la moitié des issues condamnées et dans le noir."},
{t:'techno',q:"Combien de temps a duré l’unique vol du Spruce Goose, le plus grand hydravion jamais construit ?",n:26,min:0,max:60,u:"secondes",e:"Vingt-six secondes à vingt mètres au-dessus de l’eau, sur environ un mile. Howard Hughes voulait juste prouver que son avion en bois volait ; il ne l’a plus jamais fait décoller."},
{t:'techno',q:"Combien de roues comptait le train d’atterrissage de l’Antonov An-225 ?",n:32,min:0,max:50,u:"roues",e:"32 roues pour répartir plus de six cents tonnes au décollage. Le géant ukrainien, exemplaire unique, transportait des navettes spatiales sur son dos avant d’être détruit en 2022."},
{t:'techno',q:"Quelle distance a parcourue le tout premier vol des frères Wright ?",n:36.5,min:0,max:50,u:"mètres",e:"36,5 mètres, moins que l’envergure d’un long-courrier moderne. Le même jour, leur quatrième essai atteignait 260 mètres avant qu’une rafale ne retourne définitivement l’appareil."},
{t:'techno',q:"Quelle distance Bertha Benz a-t-elle parcourue lors du premier vrai voyage en automobile ?",n:106,min:0,max:150,u:"kilomètres",e:"106 km entre Mannheim et Pforzheim, sans prévenir son mari. Elle achetait l’essence en pharmacie et fit doubler une garniture de frein par un cordonnier : premier changement de plaquettes."},
{t:'techno',q:"Quel record de vitesse un TGV a-t-il établi sur rails en 2007 ?",n:574.8,min:0,max:1000,u:"km/h",e:"574,8 km/h avec des roues surdimensionnées et une caténaire poussée à très haute tension. Au-delà, les vagues de déformation du câble électrique deviennent plus rapides que le train."},
{t:'techno',q:"Quelle vitesse maximale a atteint la Mallard, locomotive à vapeur la plus rapide du monde ?",n:202.8,min:0,max:400,u:"km/h",e:"202,8 km/h en 1938, record jamais battu pour une machine à vapeur. Le palier moteur a fondu pendant la tentative : la locomotive a fini son voyage remorquée."},
{t:'techno',q:"De combien les deux tunnels creusés depuis la France et l’Angleterre se sont-ils décalés lors de leur jonction ?",n:358,min:0,max:400,u:"millimètres",e:"358 mm horizontalement et 58 mm verticalement, après vingt kilomètres creusés à l’aveugle sous la Manche. Une erreur de la largeur d’une main sur la longueur d’un marathon."},
{t:'techno',q:"À quelle profondeur le bathyscaphe Trieste est-il descendu dans la fosse des Mariannes ?",n:10916,min:0,max:20000,u:"mètres",e:"10 916 mètres en 1960. Une vitre extérieure s’est fissurée pendant la descente ; les deux hommes ont continué quand même, et sont restés vingt minutes au fond avant de remonter."},
{t:'techno',q:"Combien pèse le Bagger 288, l’excavatrice géante allemande ?",n:13500,min:0,max:20000,u:"tonnes",e:"13 500 tonnes pour 96 mètres de haut et 220 de long, mais seulement 0,6 km/h. La déplacer sur 22 kilomètres a demandé trois semaines et une équipe de soixante-dix personnes."},
{t:'techno',q:"Quel record de vitesse terrestre le ThrustSSC a-t-il établi dans le désert du Nevada ?",n:1227.985,min:0,max:1500,u:"km/h",e:"1 227,985 km/h en 1997 : première voiture à franchir le mur du son au sol. Le bang supersonique soulevait la poussière sur des kilomètres et le pilote était un pilote de chasse."},
{t:'techno',q:"Combien de temps fallait-il pour assembler un châssis de Ford T sur la chaîne de montage ?",n:93,min:0,max:120,u:"minutes",e:"93 minutes, contre 12 h 30 avant la chaîne mobile. Ford a divisé le temps par huit et le prix par trois : l’ouvrier a fini par pouvoir s’acheter la voiture qu’il fabriquait."},
{t:'techno',q:"Combien de prototypes James Dyson a-t-il construits avant son aspirateur sans sac ?",n:5127,min:0,max:10000,u:"prototypes",e:"5 127 prototypes en cinq ans, financés à crédit, avant qu’aucun fabricant n’en veuille. Il a fini par produire lui-même l’appareil qui a rendu le sac d’aspirateur obsolète."},
{t:'techno',q:"Combien de temps le premier appareil photo numérique mettait-il à enregistrer une image ?",n:23,min:0,max:50,u:"secondes",e:"23 secondes pour écrire une image sur une cassette audio, en 1975. Kodak a inventé la photo numérique, puis rangé le prototype de peur de tuer son marché de la pellicule."},
{t:'techno',q:"Combien pesait le Radarange, le premier four à micro-ondes commercialisé ?",n:340,min:0,max:500,u:"kilogrammes",e:"340 kg pour près d’un mètre quatre-vingts de haut, et un refroidissement à eau. L’invention vient d’un ingénieur radar qui a senti la barre chocolatée fondre dans sa poche."},
{t:'techno',q:"Quelle durée d’enregistrement a été retenue pour définir le disque compact ?",n:74,min:0,max:600,u:"minutes",e:"74 minutes, taille choisie pour faire tenir la Neuvième de Beethoven sur un seul disque, selon la légende soutenue par Sony. Le diamètre de 12 cm en découle directement."},
{t:'techno',q:"Combien de temps a duré l’exposition de la première photographie de l’histoire ?",n:8,min:0,max:20,u:"heures",e:"Environ huit heures de pose sur une plaque d’étain enduite de bitume, par Nicéphore Niépce. Sur l’image, le soleil éclaire les deux côtés de la cour : il a eu le temps de tourner."},

/* ---------- Bêtes ---------- */
{t:'animaux',q:"Combien de temps vit un requin du Groenland ?",n:400,min:0,max:500,u:"ans",e:"Environ 400 ans. Certains individus nageaient déjà quand Louis XIV régnait — et ils n'atteignent la maturité sexuelle qu'à 150 ans."},
{t:'animaux',q:"À quelle fréquence bat le cœur d'un colibri en plein vol ?",n:1200,min:0,max:5000,u:"battements/min",e:"Jusqu'à 1 200 battements par minute. La nuit, pour ne pas mourir d'épuisement, il tombe en torpeur et son cœur descend à 50."},
{t:'animaux',q:"Combien de pattes compte le mille-pattes record du monde ?",n:1306,min:0,max:1500,u:"pattes",e:"1 306 pattes pour une espèce trouvée en Australie en 2021 — la première à mériter vraiment son nom. Elle vit à 60 m sous terre et est aveugle."},
{t:'animaux',q:"Combien de kilomètres une sterne arctique parcourt-elle chaque année ?",n:90000,min:0,max:100000,u:"km",e:"Environ 90 000 km entre Arctique et Antarctique. Sur une vie, cela représente trois allers-retours Terre-Lune."},
{t:'animaux',q:"Combien de dents un escargot possède-t-il ?",n:14000,min:0,max:15000,u:"dents",e:"Environ 14 000, alignées sur une langue râpeuse appelée radula. Il ne mâche pas : il râpe."},
{t:'animaux',q:"Combien pèse la langue d'une baleine bleue ?",n:2700,min:0,max:3000,u:"kg",e:"2 700 kg, le poids d'un éléphant. Un être humain pourrait tenir debout dans son aorte."},
{t:'animaux',q:"Combien d'œufs une femelle poisson-lune peut-elle pondre en une saison ?",n:300000000,min:0,max:1000000000,u:"œufs",e:"Jusqu'à 300 millions, un record chez les vertébrés. Statistiquement, deux survivront."},
{t:'animaux',q:"Quel âge avait la baleine boréale la plus vieille jamais datée ?",n:211,min:0,max:600,u:"ans",e:"Des pointes de harpon en pierre retrouvées dans la graisse de certains individus ont mis la puce à l’oreille. La datation du cristallin a confirmé : 211 ans."},
{t:'animaux',q:"Quel âge avait Ming, la palourde islandaise la plus vieille jamais trouvée ?",n:507,min:0,max:1000,u:"ans",e:"Les chercheurs l’ont ouverte pour compter ses anneaux de croissance… et l’ont donc tuée. Elle était née vers 1499, avant la mort de Léonard de Vinci."},
{t:'animaux',q:"Quel âge a la plus vieille colonie de corail noir jamais datée à Hawaï ?",n:4265,min:0,max:8000,u:"ans",e:"Ce buisson d’eau profonde poussait déjà quand on bâtissait les pyramides. Il grandit d’environ 5 micromètres par an : l’épaisseur d’un cheveu tous les quinze ans."},
{t:'animaux',q:"Quel âge avait Creme Puff, le chat le plus vieux du monde ?",n:38,min:0,max:120,u:"ans",e:"Née au Texas, elle a vécu 38 ans et 3 jours. Son propriétaire lui donnait du bacon, des œufs, du brocoli et une goutte de café le matin."},
{t:'animaux',q:"Quel âge avait Bluey, le chien le plus vieux jamais homologué ?",n:29,min:0,max:250,u:"ans",e:"Ce bouvier australien a travaillé le bétail pendant vingt ans avant de prendre sa retraite. Vingt-neuf ans et cinq mois : le double d’une vie de chien normale."},
{t:'animaux',q:"Quel âge avait Old Billy, le cheval le plus vieux jamais documenté ?",n:62,min:0,max:120,u:"ans",e:"Ce cheval de halage anglais tirait encore des péniches à cinquante ans passés. Son crâne est conservé au musée de Manchester, sa tête empaillée à Bedford."},
{t:'animaux',q:"Quel âge avait Cookie, le perroquet le plus vieux du monde ?",n:83,min:0,max:250,u:"ans",e:"Ce cacatoès de Leadbeater est arrivé au zoo de Brookfield en 1934 et n’en est jamais reparti. Il a survécu à tous les soigneurs qui l’avaient accueilli."},
{t:'animaux',q:"Combien de temps vit une femelle éphémère Dolania americana une fois adulte ?",n:5,min:0,max:8,u:"minutes",e:"C’est la vie adulte la plus courte du règne animal. Elle émerge, s’accouple et pond en moins de cinq minutes, sans bouche pour manger. Tout était joué avant."},
{t:'animaux',q:"Combien de temps une cigale périodique passe-t-elle sous terre avant d’émerger ?",n:17,min:0,max:20,u:"ans",e:"Dix-sept ans à sucer des racines dans le noir, pour quatre semaines de vacarme au soleil. Le chiffre est premier, ce qui déjoue les cycles des prédateurs."},
{t:'animaux',q:"Quelle est la longévité record du rat-taupe nu, ce rongeur qui ignore le cancer ?",n:30,min:0,max:60,u:"ans",e:"Une souris vit trois ans, lui trente. Son risque de mourir n’augmente pas avec l’âge : il défie la loi de mortalité qui s’applique à presque tous les mammifères."},
{t:'animaux',q:"Quel âge peut atteindre le sébaste à œil épineux, poisson du Pacifique Nord ?",n:205,min:0,max:300,u:"ans",e:"On compte ses années comme celles d’un arbre, sur les otolithes de son oreille interne. Certains individus pêchés en Alaska étaient nés avant la ruée vers l’or."},
{t:'animaux',q:"Combien de temps a duré la plongée en apnée record d’une baleine à bec de Cuvier ?",n:222,min:0,max:1500,u:"minutes",e:"Trois heures quarante-deux minutes sous l’eau, mesurées par balise en 2020 au large de la Caroline du Nord. Un record d’apnée absolu chez les mammifères."},
{t:'animaux',q:"À quelle profondeur la baleine à bec de Cuvier a-t-elle été enregistrée en plongée ?",n:2992,min:0,max:5000,u:"mètres",e:"Presque trois kilomètres sous la surface, dans le noir absolu et 300 bars de pression. Aucun autre mammifère n’a été suivi aussi profond."},
{t:'animaux',q:"À quelle profondeur plonge un éléphant de mer austral ?",n:2388,min:0,max:5000,u:"mètres",e:"Il vide ses poumons avant de descendre et ralentit son cœur. Il passe environ 90 % de sa vie sous l’eau, ne remontant que quelques minutes entre deux plongées."},
{t:'animaux',q:"Quelle profondeur record atteint un manchot empereur en plongée ?",n:564,min:0,max:1000,u:"mètres",e:"Un oiseau, dans l’eau à moins d’un degré, à plus d’un demi-kilomètre de fond. Ses os pleins et ses poumons compressibles lui évitent l’accident de décompression."},
{t:'animaux',q:"Combien de temps un manchot empereur peut-il rester en apnée ?",n:27,min:0,max:60,u:"minutes",e:"Vingt-sept minutes sous la banquise, un record mesuré par balise. Il tolère un taux d’acide lactique qui mettrait un athlète humain au tapis."},
{t:'animaux',q:"À quelle profondeur record a-t-on suivi une tortue luth ?",n:1280,min:0,max:1500,u:"mètres",e:"Une tortue qui plonge plus profond qu’un sous-marin nucléaire. Sa carapace souple, cartilagineuse, se comprime au lieu d’imploser sous la pression."},
{t:'animaux',q:"À quelle profondeur a été filmé le poisson le plus profond jamais observé ?",n:8336,min:0,max:15000,u:"mètres",e:"Un jeune poisson-limace filmé dans la fosse d’Izu-Ogasawara. À cette profondeur, la chimie de ses cellules atteint la limite théorique du vivant vertébré."},
{t:'animaux',q:"Combien de jours dure la gestation d’une éléphante ?",n:660,min:0,max:4000,u:"jours",e:"Vingt-deux mois : la plus longue gestation de tous les mammifères. Le cerveau du petit doit être quasiment prêt à l’emploi pour suivre le troupeau dès le premier jour."},
{t:'animaux',q:"Combien de mois dure la gestation d’une girafe ?",n:15,min:0,max:20,u:"mois",e:"Quinze mois pour un petit qui naît de deux mètres de haut… et tombe d’environ deux mètres. La chute rompt le cordon et déclenche sa première respiration."},
{t:'animaux',q:"Combien de jours dure la gestation de l’opossum de Virginie ?",n:12,min:0,max:20,u:"jours",e:"La plus courte gestation connue chez un mammifère. Les nouveau-nés, gros comme une abeille, rampent jusqu’à la poche pour y finir leur développement."},
{t:'animaux',q:"Combien de jours dure la gestation d’un kangourou roux ?",n:33,min:0,max:60,u:"jours",e:"Un mois pour un animal de 90 kilos. Le vrai travail se fait dans la poche : le petit y reste huit mois, et la mère peut mettre en pause un embryon en attente."},
{t:'animaux',q:"Combien de mois dure la gestation du requin-lézard des grands fonds ?",n:42,min:0,max:80,u:"mois",e:"Trois ans et demi, la plus longue gestation estimée du règne animal. Dans le froid des abysses, tout se déroule au ralenti, y compris la fabrication d’un bébé requin."},
{t:'animaux',q:"Combien de mois une femelle poulpe Graneledone a-t-elle couvé ses œufs sans manger ?",n:53,min:0,max:60,u:"mois",e:"Quatre ans et demi accrochée au même rocher, observée par submersible. Elle n’a rien avalé, a fondu, puis est morte peu après l’éclosion. Record absolu de couvaison."},
{t:'animaux',q:"Combien de mois dure la gestation d’un rhinocéros blanc ?",n:16,min:0,max:20,u:"mois",e:"Seize mois pour un nouveau-né de 50 kilos qui tient debout en une heure. Une femelle ne produira qu’une poignée de petits dans toute sa vie."},
{t:'animaux',q:"Quelle force de morsure a-t-on mesurée chez un crocodile marin ?",n:16460,min:0,max:20000,u:"newtons",e:"L’équivalent d’une voiture posée sur ses dents. Les muscles qui ouvrent sa gueule sont si faibles qu’un simple élastique suffit à la maintenir fermée."},
{t:'animaux',q:"Quelle force développe le coup de massue d’une crevette-mante ?",n:1500,min:0,max:2000,u:"newtons",e:"Mille cinq cents newtons délivrés par un animal de quinze centimètres. En aquarium, certaines fêlent les vitres. Le coup part plus vite qu’une balle de calibre 22."},
{t:'animaux',q:"Quelle température atteint la bulle créée par le claquement de pince d’une crevette pistolet ?",n:4700,min:0,max:8000,u:"°C",e:"La pince claque si vite que l’eau se vaporise ; la bulle implose en émettant un flash de lumière et une chaleur proche de celle de la surface du Soleil."},
{t:'animaux',q:"À quelle vitesse se referment les mandibules d’une fourmi Odontomachus ?",n:230,min:0,max:500,u:"km/h",e:"Le mouvement le plus rapide connu chez un animal : 0,13 milliseconde. Si elle claque contre le sol, la fourmi est catapultée en l’air comme d’un tremplin."},
{t:'animaux',q:"Quelle vitesse a-t-on chronométrée pour un faucon pèlerin en piqué ?",n:389,min:0,max:800,u:"km/h",e:"Chronométré en 2005 lors d’un piqué depuis un avion, avec un compteur embarqué. Des replis dans ses narines l’empêchent d’avoir les poumons éclatés par l’air."},
{t:'animaux',q:"En combien de secondes le guépard Sarah a-t-il couru 100 mètres, record du monde de l’espèce ?",n:5.95,min:0,max:8,u:"secondes",e:"Chronométré au zoo de Cincinnati sur piste balisée. Usain Bolt met 9,58 secondes. Le guépard atteint 100 km/h en trois foulées et ne tient que vingt secondes."},
{t:'animaux',q:"Quelle vitesse soutenue atteint une antilope pronghorn américaine ?",n:88,min:0,max:250,u:"km/h",e:"Elle court plus longtemps que le guépard, avec une trachée démesurée et un cœur surdimensionné. Elle fuit toujours un prédateur disparu : le guépard américain."},
{t:'animaux',q:"À quelle vitesse un fou de Bassan percute-t-il l’eau en plongeant ?",n:100,min:0,max:150,u:"km/h",e:"Il replie ses ailes en flèche et entre comme un javelot. Des sacs d’air sous la peau du cou amortissent l’impact, et il n’a pas de narines externes."},
{t:'animaux',q:"À quelle vitesse part le coup de massue d’une crevette-mante dans l’eau ?",n:23,min:0,max:60,u:"m/s",e:"L’accélération est comparable à celle d’une balle de pistolet. Son appendice est stocké comme un ressort à arc, libéré d’un coup par un loquet de chitine."},
{t:'animaux',q:"Combien de battements d’ailes par seconde effectue le colibri d’Elena ?",n:80,min:0,max:300,u:"battements",e:"Quatre-vingts allers-retours par seconde, d’où le bourdonnement. Il est le seul oiseau capable de voler à reculons, en dessinant un huit avec ses ailes."},
{t:'animaux',q:"Combien de battements d’ailes par seconde fait un bourdon ?",n:200,min:0,max:300,u:"battements",e:"Ses muscles ne se contractent pas à chaque battement : ils vibrent en résonance, comme un élastique pincé. C’est ce qui rend une telle cadence possible."},
{t:'animaux',q:"Quel est le record de battements d’ailes par seconde chez un insecte ?",n:1000,min:0,max:2500,u:"battements",e:"Un moucheron du genre Forcipomyia, mesuré à plus de mille battements par seconde. Aucun muscle classique ne suivrait : le thorax entier vibre comme un diapason."},
{t:'animaux',q:"Combien de kilomètres une baleine grise parcourt-elle lors de sa migration annuelle aller-retour ?",n:20000,min:0,max:30000,u:"km",e:"De l’Arctique aux lagunes du Mexique et retour, en longeant la côte. Elle jeûne presque tout le voyage et vit sur ses réserves de graisse."},
{t:'animaux',q:"Combien de kilomètres un papillon monarque parcourt-il pour rejoindre le Mexique ?",n:4000,min:0,max:12000,u:"km",e:"Le plus fou : aucun papillon ne fait le trajet deux fois. C’est l’arrière-arrière-petit-enfant qui revient, vers un arbre qu’il n’a jamais vu."},
{t:'animaux',q:"Quelle distance annuelle parcourt la libellule Pantala flavescens, championne de migration ?",n:18000,min:0,max:80000,u:"km",e:"Un insecte de dix centimètres traverse l’océan Indien en planant sur les vents de mousson. Sa migration est la plus longue connue chez un insecte."},
{t:'animaux',q:"Quelle distance un ours polaire a-t-il nagé sans s’arrêter, record suivi par balise ?",n:687,min:0,max:2000,u:"km",e:"Neuf jours dans une eau à deux degrés, sans repos ni terre ferme, faute de banquise. Elle a perdu un cinquième de son poids et son ourson pendant la traversée."},
{t:'animaux',q:"Combien de jours la barge rousse vole-t-elle sans se poser au-dessus du Pacifique ?",n:11,min:0,max:12,u:"jours",e:"Onze jours sans manger, boire ni dormir vraiment. Avant de partir, elle réduit la taille de son foie et de ses intestins pour alléger le chargement."},
{t:'animaux',q:"Combien de mois un martinet noir peut-il rester en vol sans jamais se poser ?",n:10,min:0,max:30,u:"mois",e:"Il mange, s’accouple et dort en l’air, à mille mètres d’altitude. Ses pattes sont si atrophiées qu’il ne peut pas décoller depuis un sol plat."},
{t:'animaux',q:"Combien de temps par jour dort une frégate en plein vol océanique ?",n:42,min:0,max:50,u:"minutes",e:"Mesuré par électroencéphalogramme embarqué. Elle pique des micro-sommes de quelques secondes, souvent avec un seul hémisphère, en planant sur les ascendances."},
{t:'animaux',q:"Quelle distance un saumon chinook remonte-t-il dans le fleuve Yukon pour frayer ?",n:3000,min:0,max:10000,u:"km",e:"Trois mille kilomètres à contre-courant, sans avaler une bouchée. Il arrive décharné, pond, et meurt. Sa chair est la plus grasse du monde pour tenir le voyage."},
{t:'animaux',q:"À quelle fréquence bat le cœur d’une musaraigne étrusque, le plus petit mammifère du monde ?",n:1500,min:0,max:2000,u:"battements/minute",e:"Vingt-cinq battements par seconde. Elle doit manger deux fois son poids chaque jour et meurt en quelques heures si elle jeûne. Vivre vite, littéralement."},
{t:'animaux',q:"À quelle fréquence descend le cœur d’une baleine bleue lors d’une plongée profonde ?",n:2,min:0,max:2.5,u:"battements/minute",e:"Deux battements par minute, mesurés en 2019 avec un électrocardiogramme à ventouses. Entre deux contractions, la crosse de l’aorte se dilate pour maintenir le flux."},
{t:'animaux',q:"À quelle fréquence bat le cœur d’un ours noir en hibernation ?",n:8,min:0,max:20,u:"battements/minute",e:"Huit battements par minute, contre cinquante éveillé. Il ne boit ni ne mange pendant cinq mois, ne perd presque pas de muscle, et les femelles accouchent en dormant."},
{t:'animaux',q:"Quelle est la pression artérielle systolique d’une girafe ?",n:280,min:0,max:400,u:"mmhg",e:"Le double de la nôtre : il faut pousser le sang trois mètres plus haut, jusqu’au cerveau. Ses jambes portent une peau ultra-serrée, comme un bas de contention."},
{t:'animaux',q:"Combien pèse le cœur d’une girafe adulte ?",n:11,min:0,max:20,u:"kg",e:"Onze kilos de muscle, avec une paroi ventriculaire de sept centimètres d’épaisseur. Un réseau de vaisseaux à la base du crâne évite l’AVC quand elle relève la tête."},
{t:'animaux',q:"Quelle longueur atteint la langue d’une girafe ?",n:50,min:0,max:200,u:"cm",e:"Un demi-mètre, et presque noire : le pigment la protège des coups de soleil, puisqu’elle passe la journée dehors à contourner les épines des acacias."},
{t:'animaux',q:"Combien de temps par jour une girafe sauvage dort-elle profondément ?",n:30,min:0,max:120,u:"minutes",e:"Une demi-heure, souvent en micro-siestes de quelques minutes, la tête posée sur sa croupe. Se relever prend trop de temps quand un lion rôde."},
{t:'animaux',q:"Combien d’heures par jour un koala passe-t-il à dormir ?",n:22,min:0,max:120,u:"heures",e:"Les feuilles d’eucalyptus sont toxiques, coriaces et quasi sans calories. Digérer coûte tellement d’énergie qu’il ne lui reste que deux heures de vie éveillée."},
{t:'animaux',q:"Combien de temps un escargot peut-il rester endormi pour traverser une sécheresse ?",n:3,min:0,max:6,u:"ans",e:"Il se scelle dans sa coquille avec un opercule de mucus durci et attend l’humidité. Des spécimens collés sur des planches de musée se sont réveillés après des années."},
{t:'animaux',q:"Combien de siestes une fourmi de feu ouvrière fait-elle par jour ?",n:250,min:0,max:800,u:"siestes",e:"Environ 250 micro-sommes d’une minute, décalés entre individus : la colonie n’est jamais entièrement endormie. La reine, elle, dort par vraies tranches de neuf heures."},
{t:'animaux',q:"Combien de kilos un baleineau bleu prend-il chaque jour pendant l’allaitement ?",n:90,min:0,max:120,u:"kg",e:"Quatre kilos par heure. Le lait maternel titre près de 40 % de matière grasse, la consistance d’un dentifrice, et la mère le gicle directement dans sa gueule."},
{t:'animaux',q:"Combien pèse le cœur d’une baleine bleue ?",n:180,min:0,max:200,u:"kg",e:"Le seul spécimen conservé au monde, au musée de Toronto, pèse environ 180 kilos. On a longtemps raconté qu’un enfant pouvait ramper dans l’aorte : c’est faux, mais de peu."},
{t:'animaux',q:"Quel niveau sonore atteignent les clics d’un cachalot ?",n:230,min:0,max:250,u:"décibels",e:"L’animal le plus bruyant de la planète. À bout portant, le sonar d’un cachalot pourrait faire vibrer les tissus d’un plongeur. Le son sort d’un organe rempli de cire."},
{t:'animaux',q:"Quel niveau sonore atteint le cri d’écholocation d’une chauve-souris ?",n:140,min:0,max:300,u:"décibels",e:"Plus fort qu’un réacteur d’avion, mais en ultrasons, donc inaudible. Elle contracte un muscle de l’oreille moyenne à chaque cri pour ne pas se rendre sourde."},
{t:'animaux',q:"Combien pèse un bébé panda géant à la naissance ?",n:100,min:0,max:600,u:"grammes",e:"Un neuf-centième du poids de sa mère, rose, aveugle et sans poils. Proportionnellement, ce serait un bébé humain de soixante-dix grammes. La mère l’écrase parfois par accident."},
{t:'animaux',q:"Combien pèse un bébé kangourou roux à la naissance ?",n:1,min:0,max:1.2,u:"gramme",e:"Un gramme, deux centimètres, aveugle et sans pattes arrière. Il rampe seul dans la fourrure jusqu’à la poche, s’accroche à une tétine et y reste soudé des mois."},
{t:'animaux',q:"Combien pèse un éléphanteau à la naissance ?",n:120,min:0,max:600,u:"kg",e:"Le poids d’un homme adulte, debout dans l’heure. Il naît quasiment aveugle et se guide à la trompe, un organe qu’il met des mois à apprendre à contrôler."},
{t:'animaux',q:"Combien pèse le colibri d’Elena, plus petit oiseau du monde ?",n:1.8,min:0,max:10,u:"grammes",e:"Moins qu’une pièce de un centime. Son nid a le diamètre d’une pièce de monnaie et ses œufs la taille d’un grain de café."},
{t:'animaux',q:"Quelle tension électrique peut délivrer une anguille électrique ?",n:860,min:0,max:1200,u:"volts",e:"Mesuré en 2019 sur une espèce amazonienne nouvellement décrite. Trois organes empilent des milliers de cellules comme des piles en série. Une prise murale plafonne à 230 volts."},
{t:'animaux',q:"Jusqu’à quelle température un tardigrade déshydraté peut-il survivre quelques minutes ?",n:151,min:0,max:1000,u:"°C",e:"Il expulse presque toute son eau, remplace ses cellules par un sucre vitreux et attend. Il encaisse aussi le vide spatial et mille fois la dose de radiation mortelle pour nous."},
{t:'animaux',q:"Combien de temps a vécu Mike, le poulet qui a survécu à sa décapitation ?",n:18,min:0,max:40,u:"mois",e:"La hache avait épargné le tronc cérébral et une oreille. Son propriétaire le nourrissait à la pipette par l’œsophage. Il pesait 3,7 kilos à sa mort, contre 1,2 avant."},
{t:'animaux',q:"Combien de fois son propre poids un bousier peut-il tirer ?",n:1141,min:0,max:2000,u:"fois",e:"L’équivalent d’un humain tirant six autobus à deux étages pleins. Les mâles poussent ainsi pour déloger un rival d’un tunnel et garder l’accès à la femelle."},
{t:'animaux',q:"Combien de types de photorécepteurs possède l’œil d’une crevette-mante ?",n:16,min:0,max:40,u:"photorécepteurs",e:"Nous en avons trois. Elle voit l’ultraviolet, l’infrarouge proche et la lumière polarisée circulairement — un canal que seuls des instruments de laboratoire savent lire."},
{t:'animaux',q:"Combien de temps un cafard peut-il survivre sans sa tête ?",n:7,min:0,max:50,u:"jours",e:"Il respire par des orifices sur tout le corps et son sang n’est pas sous pression, donc il ne saigne pas. Il finit par mourir de soif, faute de bouche."},
{t:'animaux',q:"De combien d’étages un chat est-il tombé à New York avant de repartir sur ses pattes ?",n:32,min:0,max:40,u:"étages",e:"Documenté par une étude vétérinaire new-yorkaise : le chat a eu un poumon perforé et une dent cassée, puis est rentré chez lui. Au-delà de sept étages, les blessures diminuent."},
{t:'animaux',q:"À combien d’œufs de poule équivalait un œuf d’oiseau-éléphant de Madagascar ?",n:150,min:0,max:300,u:"œufs",e:"Neuf litres dans une seule coquille : le plus gros œuf jamais pondu par un animal, dinosaures compris. Les marins du XVIIe siècle s’en servaient de gourdes."},
{t:'animaux',q:"Combien pèse une grenouille Goliath, la plus grosse du monde ?",n:3.3,min:0,max:10,u:"kg",e:"Le poids d’un nouveau-né humain, pour trente-deux centimètres de corps. Elle déplace des pierres de plusieurs kilos pour construire ses bassins de ponte."},
{t:'animaux',q:"Quelle taille fait Paedophryne amauensis, le plus petit vertébré du monde ?",n:7.7,min:0,max:10,u:"mm",e:"Une grenouille de Papouasie qui tient sur un ongle. Elle n’a pas de têtard : elle sort de l’œuf déjà en miniature adulte, et son chant ressemble à un cri d’insecte."},
{t:'animaux',q:"Quelle est la longueur totale de Brookesia nana, le plus petit caméléon connu ?",n:22,min:0,max:60,u:"mm",e:"Le mâle tient sur le bout d’un doigt, queue comprise. Il chasse des acariens dans la litière malgache. Ses organes génitaux font près de 20 % de sa taille."},
{t:'animaux',q:"Combien pèse un weta géant de Nouvelle-Zélande, l’insecte le plus lourd du monde ?",n:70,min:0,max:150,u:"grammes",e:"Plus lourd qu’un moineau. Faute de mammifères terrestres sur l’île, les insectes ont pris leur place et leur gabarit. Une femelle pleine d’œufs a atteint 71 grammes."},
{t:'animaux',q:"Quelle longueur atteint le plus long insecte du monde, un phasme chinois ?",n:62,min:0,max:80,u:"cm",e:"Soixante-deux centimètres pattes tendues, découvert dans le Guangxi. Immobile sur une branche, il est parfaitement invisible ; il se balance même comme une brindille au vent."},
{t:'animaux',q:"Quel diamètre atteint l’œil d’un calmar colossal ?",n:27,min:0,max:80,u:"cm",e:"Le plus grand œil du règne animal, la taille d’une assiette. Il sert à repérer la lueur du plancton bousculé par un cachalot qui approche, à plus de cent mètres."},
{t:'animaux',q:"Combien pesait le calmar colossal le plus lourd jamais capturé ?",n:495,min:0,max:600,u:"kg",e:"Remonté en 2007 par un chalutier néo-zélandais, congelé, puis décongelé au micro-ondes industriel. Ses ventouses portent des crochets rotatifs qui laissent des cicatrices sur les cachalots."},
{t:'animaux',q:"Quelle longueur atteignait la plus grande méduse à crinière de lion jamais mesurée ?",n:36.6,min:0,max:80,u:"mètres",e:"Échouée dans la baie du Massachusetts, tentacules déployés : plus longue qu’une baleine bleue. Sa cloche ne faisait que deux mètres ; tout le reste, c’étaient des filaments urticants."},
{t:'animaux',q:"Quelle longueur atteignait le siphonophore géant filmé au large de l’Australie ?",n:45,min:0,max:100,u:"mètres",e:"Enroulé en spirale dans les abysses. Ce n’est pas un animal mais une colonie de milliers de clones spécialisés, certains pour nager, d’autres pour digérer ou pondre."},
{t:'animaux',q:"Quelle longueur atteint le ver lacet, l’animal le plus long jamais mesuré ?",n:55,min:0,max:120,u:"mètres",e:"Échoué en Écosse, plus long qu’une baleine bleue. Épais comme un lacet de chaussure, il chasse en projetant une trompe collante et sécrète une neurotoxine puissante."},
{t:'animaux',q:"Quelle longueur mesurait Medusa, le plus long serpent en captivité ?",n:7.67,min:0,max:15,u:"mètres",e:"Ce python réticulé du Missouri avalait un cerf entier toutes les deux semaines. Il fallait dix hommes pour le tenir lors des pesées officielles."},
{t:'animaux',q:"Quelle longueur mesurait Lolong, le plus grand crocodile jamais capturé vivant ?",n:6.17,min:0,max:20,u:"mètres",e:"Un crocodile marin philippin d’une tonne, attrapé après trois semaines de traque. Il a fini vedette d’un écopark local et son squelette est aujourd’hui exposé à Manille."},
{t:'animaux',q:"Combien de dents un requin use-t-il au cours de sa vie ?",n:30000,min:0,max:60000,u:"dents",e:"Ses dents poussent sur un tapis roulant : plusieurs rangées de rechange attendent derrière, prêtes à basculer en position. Il en perd une toutes les quelques semaines."},
{t:'animaux',q:"Combien de terminaisons nerveuses compte la défense d’un narval ?",n:10000000,min:0,max:12000000,u:"terminaisons",e:"Ce n’est pas une arme mais une canine gauche qui traverse la lèvre, retournée à l’envers : la pulpe est à l’extérieur. Elle goûte la salinité et la température de l’eau."},
{t:'animaux',q:"Combien d’œufs une reine termite peut-elle pondre en une seule journée ?",n:30000,min:0,max:40000,u:"œufs",e:"Un œuf toutes les trois secondes, sans interruption, pendant des décennies. Son abdomen gonfle jusqu’à devenir une saucisse blanche immobile, nourrie et nettoyée par ses ouvrières."},
{t:'animaux',q:"Combien d’œufs une reine des abeilles pond-elle par jour au printemps ?",n:2000,min:0,max:2500,u:"œufs",e:"Plus que son propre poids en œufs chaque jour. Elle a été fécondée une seule fois, lors d’un vol nuptial, et vit sur ce stock de sperme pendant des années."},
{t:'animaux',q:"Combien de récepteurs olfactifs compte le nez d’un chien de Saint-Hubert ?",n:300000000,min:0,max:2500000000,u:"récepteurs",e:"Nous en avons environ six millions. Il sent en stéréo, une narine à la fois, et peut suivre une piste vieille de deux semaines. Ses longues oreilles rabattent les odeurs vers son museau."},
{t:'animaux',q:"À quelle distance un ours polaire peut-il sentir un phoque ?",n:32,min:0,max:80,u:"km",e:"Trente-deux kilomètres au vent, et un mètre sous la glace compacte. Son odorat lui sert de radar sur une banquise où il n’y a strictement rien à voir."},
{t:'animaux',q:"À quelle distance un papillon de nuit mâle détecte-t-il les phéromones d’une femelle ?",n:10,min:0,max:25,u:"km",e:"Ses antennes en plumeau réagissent à quelques molécules seulement. Il ne suit pas une odeur mais remonte le vent en zigzag dès qu’il en perd la trace."},
{t:'animaux',q:"Jusqu’à quelle fréquence sonore un chat peut-il entendre ?",n:64000,min:0,max:200000,u:"hertz",e:"Nous plafonnons à 20 000 hertz. Cette gamme correspond exactement aux cris ultrasonores des souriceaux. Ses oreilles pivotent à 180 degrés grâce à trente-deux muscles chacune."},
{t:'animaux',q:"Quelle variation de température les fossettes d’un crotale peuvent-elles détecter ?",n:0.003,min:0,max:0.005,u:"°C",e:"Ces creux entre l’œil et la narine forment une caméra thermique biologique. Le serpent superpose cette image de chaleur à sa vision normale et frappe dans le noir absolu."},
{t:'animaux',q:"Quel champ électrique minimal un requin peut-il détecter ?",n:5,min:0,max:6,u:"nanovolts/cm",e:"Les ampoules de Lorenzini, des pores gélatineux sur son museau, captent le battement cardiaque d’un poisson caché sous le sable. C’est le sens électrique le plus fin du vivant."},
{t:'animaux',q:"Combien de muscles compte la trompe d’un éléphant ?",n:40000,min:0,max:200000,u:"muscles",e:"Le corps humain entier en compte six cents. Sans un seul os, cette trompe soulève trois cents kilos et ramasse une cacahuète, ou aspire huit litres d’eau d’un coup."},
{t:'animaux',q:"Combien pesait le nid d’oiseau le plus lourd jamais pesé, celui d’un pygargue de Floride ?",n:2000,min:0,max:12000,u:"kg",e:"Deux tonnes de branches accumulées pendant des décennies : trois mètres de large, six de profondeur. Les couples rajoutent une couche chaque année jusqu’à ce que l’arbre cède."},
{t:'animaux',q:"Quelle longueur atteignent les fils de pont tissés par l’araignée de Darwin ?",n:25,min:0,max:80,u:"mètres",e:"Elle lance un fil au-dessus d’une rivière entière et suspend sa toile au milieu, pour intercepter les insectes qui volent au ras de l’eau. Sa soie est la plus résistante connue."},
{t:'animaux',q:"Sur quelle longueur s’étend la supercolonie de fourmis d’Argentine en Europe du Sud ?",n:6000,min:0,max:12000,u:"km",e:"De l’Italie au Portugal, des milliards d’ouvrières issues du même clan ne s’attaquent jamais entre elles : elles portent la même signature chimique. Une seule colonie, six mille kilomètres."},
{t:'animaux',q:"Combien de temps un poisson volant a-t-il plané au-dessus de la mer, record filmé ?",n:45,min:0,max:300,u:"secondes",e:"Quarante-cinq secondes filmées depuis un ferry japonais. Il ne bat pas des ailes : il bat de la queue à soixante-dix coups par seconde pour se relancer sans retomber."},
{t:'animaux',q:"À quelle température du sable la fourmi argentée du Sahara sort-elle chercher sa nourriture ?",n:70,min:0,max:200,u:"°C",e:"Elle attend que le sable dépasse 70 degrés, quand tous les prédateurs se sont réfugiés à l’ombre. Des poils triangulaires réfléchissants font office de couverture de survie, et elle sprinte."},

/* ---------- Mots ---------- */
{t:'langue',q:"Combien de lettres compte « anticonstitutionnellement » ?",n:25,min:0,max:120,u:"lettres",e:"25 lettres, longtemps le mot le plus long du dictionnaire courant. Les termes chimiques, eux, dépassent allègrement la centaine."},
{t:'langue',q:"Combien de membres compte l'Académie française ?",n:40,min:0,max:250,u:"membres",e:"40, depuis Richelieu en 1635. On ne devient académicien qu'à la mort d'un autre — d'où le surnom d'« immortels »."},
{t:'langue',q:"Combien de mots compte environ le Petit Robert ?",n:60000,min:0,max:80000,u:"mots",e:"Environ 60 000. Le français en compterait des centaines de milliers au total, mais une conversation courante en utilise moins de 3 000."},
{t:'langue',q:"Combien de lettres compte l’alphabet khmer, le plus long du monde ?",n:74,min:0,max:600,u:"lettres",e:"74 signes, record homologué par le Guinness. Le cambodgien empile consonnes, voyelles et sous-consonnes : trois fois plus de caractères que notre alphabet latin, pour écrire la même chose."},
{t:'langue',q:"Combien de lettres compte l’alphabet rotokas, le plus court du monde ?",n:12,min:0,max:15,u:"lettres",e:"Douze lettres seulement, en Papouasie-Nouvelle-Guinée : A, E, G, I, K, O, P, R, S, T, U, V. Pas de C, pas de N, pas de M. Et ça suffit."},
{t:'langue',q:"Combien de lettres compte le mot désignant la peur des mots trop longs ?",n:36,min:0,max:300,u:"lettres",e:"« Hippopotomonstrosesquippedaliophobie » : 36 lettres pour nommer la peur des mots longs. Les linguistes ont rallongé exprès le terme savant « sesquipedaliophobie ». Une blague de spécialistes devenue sérieuse."},
{t:'langue',q:"Combien de lettres compte le nom du village gallois Llanfairpwllgwyngyll… ?",n:58,min:0,max:80,u:"lettres",e:"58 lettres, inventées vers 1860 par un cordonnier du coin pour attirer les touristes. Ça signifie à peu près : « église Sainte-Marie dans le creux du noisetier blanc près du tourbillon rapide »."},
{t:'langue',q:"Combien de lettres compte Taumatawhakatangihanga…, la colline néo-zélandaise ?",n:85,min:0,max:150,u:"lettres",e:"85 lettres, record mondial homologué pour un nom de lieu. En maori, cela raconte l’histoire de Tamatea, l’homme aux gros genoux qui jouait de la flûte pour sa bien-aimée."},
{t:'langue',q:"Combien de lettres compte le plus long mot du dictionnaire d’Oxford ?",n:45,min:0,max:100,u:"lettres",e:"« Pneumonoultramicroscopicsilicovolcanoconiosis », 45 lettres, une maladie pulmonaire due aux poussières volcaniques. Le mot a été forgé en 1935 par un amateur de mots longs, presque exprès pour battre le record."},
{t:'langue',q:"Combien de lettres comptait ce mot allemand officiel : la loi sur l’étiquetage du bœuf ?",n:63,min:0,max:120,u:"lettres",e:"« Rindfleischetikettierungsüberwachungsaufgabenübertragungsgesetz » : 63 lettres, une vraie loi du Mecklembourg-Poméranie. Abrogée en 2013, elle a emporté avec elle le plus long mot allemand jamais publié officiellement."},
{t:'langue',q:"Combien de lettres compte le nom chimique complet de la titine, la plus grosse protéine humaine ?",n:189819,min:0,max:200000,u:"lettres",e:"189 819 lettres. Le lire à voix haute prend plus de trois heures. Les dictionnaires refusent de l’enregistrer : ce n’est pas un mot, disent-ils, mais une formule déguisée."},
{t:'langue',q:"Combien de lettres compte le nom cérémoniel complet de Bangkok ?",n:168,min:0,max:400,u:"lettres",e:"168 lettres en translittération, record Guinness du plus long nom de lieu. Les Thaïlandais l’apprennent en chanson à l’école. Au quotidien, ils disent simplement « Krung Thep » : la cité des anges."},
{t:'langue',q:"Combien de lettres compte le nom de la plus petite commune de France par son nom ?",n:1,min:0,max:1.5,u:"lettre",e:"Une seule : Y, dans la Somme. Ses habitants sont les Ypsiloniens. Le panneau d’entrée du village est régulièrement volé par des collectionneurs, ce qui coûte cher à la mairie."},
{t:'langue',q:"Combien de lettres compte le nom de la commune française au nom le plus long ?",n:38,min:0,max:80,u:"lettres",e:"Saint-Remy-en-Bouzemont-Saint-Genest-et-Isson, dans la Marne : 38 lettres et 45 caractères avec les tirets. Trois villages fusionnés qui n’ont jamais voulu renoncer à leur nom."},
{t:'langue',q:"Combien de lettres compte Chargoggagoggmanchauggagoggchaubunagungamaugg, le lac du Massachusetts ?",n:45,min:0,max:400,u:"lettres",e:"45 lettres, le plus long toponyme des États-Unis. La traduction plaisante « tu pêches de ton côté, je pêche du mien » est un canular ; le nom nipmuc signifie plutôt « lieu de pêche à la frontière »."},
{t:'langue',q:"Combien de caractères recense le dictionnaire chinois de Kangxi, publié en 1716 ?",n:47035,min:0,max:150000,u:"caractères",e:"Environ 47 035 caractères, compilés en six ans par une trentaine de lettrés impériaux. Un lecteur chinois cultivé en connaît moins d’un dixième : l’immense majorité n’a jamais servi."},
{t:'langue',q:"Combien de caractères recense le Zhonghua Zihai, le plus gros dictionnaire de caractères chinois ?",n:85568,min:0,max:120000,u:"caractères",e:"85 568 caractères, publiés en 1994. La plupart sont des variantes mortes, des noms propres oubliés ou des signes vus une seule fois dans un texte ancien. Un cimetière de signes."},
{t:'langue',q:"Combien de clés (radicaux) permettent de classer tous les caractères chinois ?",n:214,min:0,max:400,u:"clés",e:"214 clés, fixées par le dictionnaire de Kangxi en 1716 et toujours utilisées trois siècles plus tard. Sans elles, chercher un caractère inconnu dans un dictionnaire papier serait impossible."},
{t:'langue',q:"Combien de kanjis un élève japonais doit-il maîtriser à la fin de sa scolarité ?",n:2136,min:0,max:2500,u:"kanjis",e:"2 136 kanjis « d’usage courant », la liste officielle jōyō. Les six années de primaire en couvrent 1 026 ; le reste tombe au collège et au lycée. Et il en reste des dizaines de milliers."},
{t:'langue',q:"Combien de signes compte l’alphabet japonais hiragana de base ?",n:46,min:0,max:150,u:"signes",e:"46 signes de base, chacun valant une syllabe. Un enfant japonais les maîtrise avant six ans, puis passe le reste de sa scolarité à affronter les milliers de kanjis chinois."},
{t:'langue',q:"Combien de lettres comptait le hangeul coréen à sa création ?",n:28,min:0,max:30,u:"lettres",e:"28 lettres inventées de toutes pièces au XVe siècle par le roi Sejong, dont les formes imitent la position de la langue et des lèvres. Quatre sont tombées en désuétude : il en reste 24."},
{t:'langue',q:"Combien de signes compte le syllabaire cherokee inventé par Sequoyah ?",n:85,min:0,max:800,u:"signes",e:"85 signes, créés par un homme qui ne savait ni lire ni écrire aucune langue. En quelques années, le peuple cherokee est devenu plus alphabétisé que ses voisins colons."},
{t:'langue',q:"Combien d’années Sequoyah a-t-il mis à créer l’écriture cherokee ?",n:12,min:0,max:30,u:"ans",e:"Douze ans d’obsession. Ses voisins l’ont accusé de sorcellerie et ont brûlé sa cabane avec ses premières notes. Il a tout recommencé, puis convaincu les chefs en faisant lire sa fille."},
{t:'langue',q:"Combien de combinaisons différentes permettent les six points d’une cellule braille ?",n:64,min:0,max:600,u:"combinaisons",e:"64 combinaisons, cellule vide comprise. Six points, deux états chacun : deux puissance six. De quoi coder tout l’alphabet, les chiffres, la ponctuation et même la musique."},
{t:'langue',q:"Quel âge avait Louis Braille quand il a achevé son alphabet ?",n:15,min:0,max:100,u:"ans",e:"Quinze ans. Aveugle depuis ses trois ans, il s’était inspiré d’un code militaire à douze points destiné à lire des ordres la nuit. Il l’a simplifié à six pour que le doigt embrasse tout d’un coup."},
{t:'langue',q:"Combien de signes compte l’écriture amharique utilisée en Éthiopie ?",n:231,min:0,max:600,u:"signes",e:"231 signes de base : 33 consonnes déclinées chacune en 7 formes selon la voyelle qui suit. Chaque caractère est donc une syllabe entière, et le clavier devient un casse-tête."},
{t:'langue',q:"Combien de consonnes compte l’alphabet thaï ?",n:44,min:0,max:60,u:"consonnes",e:"44 consonnes pour seulement 21 sons distincts : plusieurs lettres se prononcent pareil, héritage de mots sanskrits importés. Ajoutez une trentaine de signes vocaliques et quatre marques de ton."},
{t:'langue',q:"Combien de lettres compte l’alphabet arménien ?",n:38,min:0,max:120,u:"lettres",e:"38 lettres. Mesrop Machtots en avait créé 36 vers l’an 405, dit-on après une vision. Deux ont été ajoutées au Moyen Âge. Seize siècles plus tard, on écrit toujours avec."},
{t:'langue',q:"Combien de lettres comptait l’alphabet latin des Romains ?",n:23,min:0,max:150,u:"lettres",e:"23 lettres. Ni J, ni U, ni W : le I servait pour I et J, le V pour U et V. Nos trois lettres manquantes ne sont apparues qu’au Moyen Âge et à la Renaissance."},
{t:'langue',q:"Combien de lettres compte l’alphabet espagnol officiel ?",n:27,min:0,max:40,u:"lettres",e:"27 lettres : les 26 latines plus le ñ. Le CH et le LL, longtemps comptés comme des lettres à part entière, ont été rétrogradés en 2010 par l’Académie royale espagnole."},
{t:'langue',q:"Combien de lettres compte l’alphabet italien ?",n:21,min:0,max:30,u:"lettres",e:"21 lettres. J, K, W, X et Y sont considérées comme étrangères et n’apparaissent que dans les mots importés. Un Italien épelle « jazz » en nommant des lettres qui ne sont pas les siennes."},
{t:'langue',q:"Combien de lettres compte l’alphabet vietnamien ?",n:29,min:0,max:80,u:"lettres",e:"29 lettres, dérivées du latin par des missionnaires portugais et français au XVIIe siècle. Le F, le J, le W et le Z en sont absents, mais on y trouve Ơ, Ư, Ă, Â, Ê, Ô et Đ."},
{t:'langue',q:"Combien de lettres compte l’alphabet cyrillique russe ?",n:33,min:0,max:40,u:"lettres",e:"33 lettres, dont deux qui ne se prononcent pas du tout : le signe dur et le signe mou, simples indications sur la consonne précédente. Des lettres qui ne font aucun bruit."},
{t:'langue',q:"Combien de lettres compte l’alphabet grec moderne ?",n:24,min:0,max:30,u:"lettres",e:"24 lettres, d’alpha à oméga. C’est le premier alphabet de l’histoire à noter les voyelles séparément : les Phéniciens n’écrivaient que les consonnes, à charge du lecteur de deviner."},
{t:'langue',q:"Combien de lettres compte l’alphabet hébreu ?",n:22,min:0,max:60,u:"lettres",e:"22 lettres, toutes des consonnes. Les voyelles sont de petits points ajoutés au XIe siècle par les massorètes ; un journal israélien moderne s’en passe complètement."},
{t:'langue',q:"Combien de lettres compte l’alphabet arabe ?",n:28,min:0,max:60,u:"lettres",e:"28 lettres, dont chacune change de forme selon sa place dans le mot : initiale, médiane, finale ou isolée. Une même lettre peut donc avoir quatre visages différents."},
{t:'langue',q:"Combien de traits faut-il pour écrire le caractère chinois le plus complexe des dictionnaires ?",n:64,min:0,max:200,u:"traits",e:"64 traits : le caractère 𪚥, formé de quatre fois le signe « dragon », signifie « verbeux, bavard ». Écrire « bavard » demande donc soixante-quatre coups de pinceau. Cruellement logique."},
{t:'langue',q:"Combien de caractères compte le poème chinois où tout se prononce « shi » ?",n:92,min:0,max:100,u:"caractères",e:"92 caractères, tous prononcés « shi » avec des tons différents. Écrit par le linguiste Zhao Yuanren, ce texte sur un poète mangeur de lions est parfaitement clair à l’écrit, incompréhensible à l’oral."},
{t:'langue',q:"Combien de caractères chinois faut-il connaître pour lire un journal ?",n:3000,min:0,max:6000,u:"caractères",e:"Environ 3 000 caractères couvrent 99 % d’un texte de presse. Le reste des dizaines de milliers recensés ne sert qu’aux noms propres, aux poèmes anciens et aux concours d’érudition."},
{t:'langue',q:"Combien de signes compte la liste de Gardiner, le catalogue de référence des hiéroglyphes ?",n:763,min:0,max:1500,u:"signes",e:"763 signes classés par Alan Gardiner : oiseaux, membres humains, meubles, cordages. Les scribes en utilisaient quelques centaines au quotidien ; l’époque gréco-romaine en a inventé des milliers d’autres."},
{t:'langue',q:"Combien de temps les hiéroglyphes égyptiens sont-ils restés illisibles ?",n:1400,min:0,max:3000,u:"ans",e:"Environ 1 400 ans. La dernière inscription connue date de 394 après J.-C., à Philae ; Champollion perce le code en 1822. Entre les deux, personne au monde ne savait plus lire l’Égypte."},
{t:'langue',q:"Combien d’années après sa découverte la pierre de Rosette a-t-elle livré son secret ?",n:23,min:0,max:120,u:"ans",e:"23 ans : trouvée en 1799 par un soldat de Bonaparte, déchiffrée par Champollion en 1822. Les meilleurs savants d’Europe s’y sont cassé les dents pendant deux décennies."},
{t:'langue',q:"Combien de temps a duré la rédaction de la première édition de l’Oxford English Dictionary ?",n:71,min:0,max:250,u:"ans",e:"71 ans, de 1857 à 1928. Le projet devait durer dix ans et tenir en quatre volumes ; il en a fallu douze. Le premier fascicule s’arrêtait au mot « ant »."},
{t:'langue',q:"Combien de mots la première édition de l’Oxford English Dictionary définissait-elle ?",n:414825,min:0,max:800000,u:"mots",e:"414 825 mots définis. À l’arrivée du dernier fascicule en 1928, les premiers volumes étaient déjà obsolètes : il a fallu publier un supplément dans la foulée."},
{t:'langue',q:"Combien de citations littéraires la première édition de l’Oxford English Dictionary contenait-elle ?",n:1827306,min:0,max:4000000,u:"citations",e:"1 827 306 citations, envoyées par des milliers de bénévoles sur des petits bouts de papier. Les rédacteurs les triaient dans un hangar de tôle surnommé le « Scriptorium »."},
{t:'langue',q:"Combien de citations un des bénévoles internés de l’Oxford English Dictionary a-t-il envoyées ?",n:10000,min:0,max:60000,u:"citations",e:"Plus de 10 000, expédiées par William Chester Minor, chirurgien américain enfermé dans un asile pour meurtre. Le rédacteur en chef a mis vingt ans à découvrir que son meilleur contributeur était interné."},
{t:'langue',q:"Combien pèse l’édition papier complète de l’Oxford English Dictionary de 1989 ?",n:62.6,min:0,max:80,u:"kg",e:"62,6 kilos répartis sur 20 volumes et près de 21 700 pages. Aucune deuxième édition papier n’a suivi : le successeur est numérique, faute de dos capables de le porter."},
{t:'langue',q:"Combien de sens différents le verbe anglais « run » compte-t-il dans l’Oxford English Dictionary ?",n:645,min:0,max:1200,u:"sens",e:"645 sens pour le seul verbe. Il a détrôné « set » lors de la révision moderne. Le rédacteur qui s’en est chargé y a passé neuf mois à plein temps."},
{t:'langue',q:"Combien de définitions le mot anglais « set » comptait-il dans l’Oxford English Dictionary ?",n:430,min:0,max:1000,u:"définitions",e:"430 définitions, longtemps le record absolu. L’entrée occupait 60 000 mots, soit la taille d’un roman entier, pour trois lettres de rien du tout."},
{t:'langue',q:"Combien de mots contenait le dictionnaire de Samuel Johnson, publié en 1755 ?",n:42773,min:0,max:150000,u:"mots",e:"42 773 mots. Johnson y glissait des définitions vengeresses : l’avoine y est « une céréale donnée en Angleterre aux chevaux, et en Écosse aux gens »."},
{t:'langue',q:"Combien d’années Samuel Johnson a-t-il mis à écrire son dictionnaire ?",n:9,min:0,max:15,u:"ans",e:"Neuf ans. Il en avait promis trois. Quarante académiciens français avaient mis quarante ans pour le leur : Johnson y voyait la preuve mathématique qu’un Anglais valait plusieurs Français."},
{t:'langue',q:"Combien de temps a duré la rédaction du grand dictionnaire allemand des frères Grimm ?",n:123,min:0,max:200,u:"ans",e:"123 ans, de 1838 à 1961. Wilhelm Grimm est mort à la lettre D, Jacob quatre ans plus tard sur le mot « Frucht », fruit. Des générations de philologues ont dû finir le travail."},
{t:'langue',q:"Combien de temps a duré la rédaction du dictionnaire néerlandais, le plus long chantier lexicographique du monde ?",n:134,min:0,max:300,u:"ans",e:"134 ans, de 1864 à 1998, pour 43 volumes et 400 000 mots : le plus gros dictionnaire jamais imprimé. Commencé sous la reine Sophie, achevé à l’ère d’Internet."},
{t:'langue',q:"Combien d’entrées comptait le dictionnaire américain de Noah Webster de 1828 ?",n:70000,min:0,max:200000,u:"entrées",e:"70 000 entrées. Pour retracer les étymologies, Webster avait appris une vingtaine de langues, dont le sanskrit et l’arabe. C’est aussi lui qui a fait perdre son U au « color » américain."},
{t:'langue',q:"Combien d’années séparent la fondation de l’Académie française de son premier dictionnaire ?",n:59,min:0,max:120,u:"ans",e:"59 ans : fondée en 1635, elle publie son dictionnaire en 1694. Entre-temps, un académicien exclu, Furetière, avait sorti le sien en douce et coiffé la Compagnie au poteau."},
{t:'langue',q:"Combien d’années a demandé la neuvième édition du Dictionnaire de l’Académie française ?",n:38,min:0,max:60,u:"ans",e:"38 ans, de 1986 à 2024. Le tome un s’arrêtait à « Enzyme ». Quand le dernier est paru, les premiers volumes ignoraient encore le smartphone, le courriel et le télétravail."},
{t:'langue',q:"Combien de volumes compte le Trésor de la langue française, le plus grand dictionnaire du français ?",n:16,min:0,max:30,u:"volumes",e:"16 volumes publiés de 1971 à 1994, décrivant la langue des XIXe et XXe siècles. Un des tout premiers dictionnaires bâtis sur ordinateur, à partir d’un corpus de 90 millions de mots."},
{t:'langue',q:"Combien de langues parle-t-on en Papouasie-Nouvelle-Guinée ?",n:840,min:0,max:1500,u:"langues",e:"Environ 840 langues pour un seul pays : plus de 10 % de toutes les langues du monde. Les montagnes ont isolé les vallées pendant des millénaires, chacune fabriquant la sienne."},
{t:'langue',q:"Combien de langues parle-t-on en Indonésie ?",n:710,min:0,max:1500,u:"langues",e:"Environ 710 langues vivantes réparties sur 17 000 îles. L’indonésien officiel n’est la langue maternelle que d’une petite minorité : c’est une langue de commerce promue au rang de ciment national."},
{t:'langue',q:"Combien de langues parle-t-on au Nigeria ?",n:520,min:0,max:800,u:"langues",e:"Environ 520 langues, record africain. Aucune n’est officielle : c’est l’anglais qui arbitre, précisément parce qu’il n’appartient à aucun des grands groupes du pays."},
{t:'langue',q:"Combien de langues la Constitution indienne reconnaît-elle officiellement ?",n:22,min:0,max:30,u:"langues",e:"22 langues inscrites à la fameuse « huitième annexe ». Le recensement, lui, dénombre plus de 1 600 langues maternelles déclarées. Le hindi et l’anglais servent d’intermédiaires officiels."},
{t:'langue',q:"Combien de langues figurent sur le panneau linguistique d’un billet de roupie indienne ?",n:15,min:0,max:120,u:"langues",e:"15 langues listées au dos, en plus du hindi et de l’anglais au recto : dix-sept écritures cohabitent sur un bout de papier. Le billet le plus multilingue du monde."},
{t:'langue',q:"Combien de langues officielles la Bolivie reconnaît-elle ?",n:37,min:0,max:150,u:"langues",e:"37 langues officielles : l’espagnol et 36 langues indigènes inscrites dans la Constitution de 2009. Certaines d’entre elles ne comptent plus qu’une poignée de locuteurs vivants."},
{t:'langue',q:"Combien de langues officielles compte le Zimbabwe ?",n:16,min:0,max:60,u:"langues",e:"16 langues officielles, record mondial pour une constitution. Outre l’anglais, le shona et le ndébélé, on y trouve la langue des signes zimbabwéenne, reconnue à égalité avec les langues parlées."},
{t:'langue',q:"Combien de langues indigènes le Mexique reconnaît-il comme langues nationales ?",n:68,min:0,max:400,u:"langues",e:"68 langues nationales, déclinées en 364 variantes, toutes juridiquement égales à l’espagnol. Un accusé a donc le droit d’être jugé en mixtèque, en zapotèque ou en nahuatl."},
{t:'langue',q:"Combien de langues parle-t-on au Cameroun ?",n:250,min:0,max:500,u:"langues",e:"Environ 250 langues sur un territoire grand comme la moitié de la France, ce qui vaut au pays le surnom d’« Afrique en miniature ». Le français et l’anglais servent d’arbitres."},
{t:'langue',q:"Combien de langues parle-t-on au Vanuatu, archipel de 300 000 habitants ?",n:110,min:0,max:150,u:"langues",e:"Plus de 110 langues, soit la plus forte densité linguistique de la planète : environ une langue pour 2 000 personnes. Pour se comprendre, tout le monde bascule sur le bichelamar."},
{t:'langue',q:"Combien de langues officielles compte l’Union européenne ?",n:24,min:0,max:30,u:"langues",e:"24 langues officielles. Tout texte juridique doit exister dans les 24, et chaque version fait également foi. Le maltais, parlé par un demi-million de personnes, a exactement le même statut que l’allemand."},
{t:'langue',q:"Combien de couples de langues les traducteurs de l’Union européenne doivent-ils gérer ?",n:552,min:0,max:2000,u:"combinaisons",e:"552 combinaisons possibles entre 24 langues. Impossible d’avoir un traducteur maltais-finnois sous la main : on passe par une langue relais, le « pivot », au risque du téléphone arabe."},
{t:'langue',q:"Combien de langues officielles compte l’Organisation des Nations unies ?",n:6,min:0,max:12,u:"langues",e:"Six seulement : anglais, français, espagnol, russe, chinois et arabe, ajouté en 1973. Pour 193 États membres, cela veut dire que la grande majorité des pays plaident dans une langue étrangère."},
{t:'langue',q:"Combien de langues différentes parle-t-on dans la seule ville de New York ?",n:800,min:0,max:1000,u:"langues",e:"Jusqu’à 800 langues, la plus grande concentration linguistique de l’histoire humaine. Des langues d’Himalaya ou d’Amazonie ont aujourd’hui plus de locuteurs dans le Queens que dans leur vallée d’origine."},
{t:'langue',q:"Combien de langues parle-t-on aujourd’hui sur Terre ?",n:7000,min:0,max:10000,u:"langues",e:"Environ 7 000. Mais la moitié de l’humanité n’en parle qu’une vingtaine : des milliers de ces langues comptent moins de mille locuteurs et s’éteindront avec eux."},
{t:'langue',q:"Combien de langues suffisent pour couvrir la moitié de la population mondiale ?",n:23,min:0,max:30,u:"langues",e:"23 langues seulement, sur environ 7 000. Le mandarin, l’espagnol, l’anglais, le hindi et l’arabe en tête. Les 6 977 autres se partagent l’autre moitié de l’humanité."},
{t:'langue',q:"Tous les combien de temps une langue disparaît-elle dans le monde ?",n:2,min:0,max:3,u:"semaines",e:"Environ toutes les deux semaines, selon l’UNESCO : le dernier locuteur meurt et emporte grammaire, chansons et noms de plantes. Près de la moitié des langues actuelles sont menacées."},
{t:'langue',q:"Combien de langues sont gravées sur le disque d’or embarqué par les sondes Voyager ?",n:55,min:0,max:100,u:"langues",e:"55 salutations, de l’akkadien au wu chinois. Le message en anglais a été enregistré par le fils de six ans de Carl Sagan : « Bonjour à tous, quels que soient vous »."},
{t:'langue',q:"Combien de règles de grammaire l’espéranto compte-t-il ?",n:16,min:0,max:50,u:"règles",e:"16 règles, sans une seule exception. Zamenhof avait grandi dans une ville où quatre communautés se détestaient dans quatre langues ; il a bâti la sienne pour tenir sur une page."},
{t:'langue',q:"Combien de mots comptait le toki pona, la langue minimaliste, à sa création ?",n:120,min:0,max:200,u:"mots",e:"Environ 120 mots. Pas de mot pour « voiture » : on dit « machine qui roule ». Ses locuteurs assurent qu’on l’apprend en un week-end et qu’elle rend philosophe."},
{t:'langue',q:"Combien de lettres compte « supercalifragilisticexpialidocious » de Mary Poppins ?",n:34,min:0,max:50,u:"lettres",e:"34 lettres. Deux auteurs ont attaqué Disney en justice en jurant avoir inventé le mot avant ; le tribunal a jugé qu’il traînait déjà dans les cours d’école depuis les années 1930."},
{t:'langue',q:"Combien de lettres compte « intergouvernementalisations », le plus long mot des dictionnaires français ?",n:27,min:0,max:30,u:"lettres",e:"27 lettres, deux de plus qu’« anticonstitutionnellement », le champion officieux. Le français fabrique ses mots longs par empilement de suffixes administratifs : plus la bureaucratie enfle, plus les mots s’allongent."},
{t:'langue',q:"Combien de lettres compte le plus long palindrome du français, « ressasser » ?",n:9,min:0,max:15,u:"lettres",e:"Neuf lettres qui se lisent pareil dans les deux sens, comme le fait le mot lui-même : ressasser, c’est revenir sans cesse au point de départ. Le sens et la forme d’accord."},
{t:'langue',q:"Combien de lettres compte « saippuakivikauppias », le plus long palindrome courant du monde ?",n:19,min:0,max:40,u:"lettres",e:"19 lettres en finnois, pour désigner un vendeur de pierre à savon. Un métier quasi inexistant, mais le mot est bien dans les dictionnaires : le finnois colle ses mots bout à bout."},
{t:'langue',q:"Combien de lettres compte le plus long mot anglais tapable de la seule main gauche ?",n:12,min:0,max:40,u:"lettres",e:"12 lettres : « stewardesses ». Le clavier QWERTY, conçu pour ralentir les frappes et éviter que les marteaux se coincent, a laissé toutes les lettres fréquentes à gauche."},
{t:'langue',q:"Combien de lettres compte « rhythms », le plus long mot anglais sans aucune voyelle ?",n:7,min:0,max:25,u:"lettres",e:"Sept lettres, pas un seul A, E, I, O ou U. Le Y fait tout le travail. Les Gallois font mieux encore : « cwtch », un câlin, se passe même du Y."},
{t:'langue',q:"Combien de lettres compte le plus long acronyme jamais homologué ?",n:56,min:0,max:60,u:"lettres",e:"56 lettres pour un institut soviétique de béton armé, « NIIOMTPLABOPARMBETZHELBETRABSBOMONIMONKONOTDTEKHSTROMONT ». Un sigle censé faire gagner du temps, plus long que la plupart des phrases qu’il abrège."},
{t:'langue',q:"Combien de mots anglais Shakespeare a-t-il inventés selon l’Oxford English Dictionary ?",n:1700,min:0,max:4000,u:"mots",e:"Environ 1 700 premières attestations : « eyeball », « lonely », « bedroom ». Les lexicographes modernes nuancent : il les a peut-être seulement écrits le premier, dans une langue qui bouillonnait autour de lui."},
{t:'langue',q:"Combien de mots compte la Bible du roi Jacques, la traduction anglaise de 1611 ?",n:783137,min:0,max:1000000,u:"mots",e:"783 137 mots, produits par 47 traducteurs répartis en six comités. Chaque passage devait être lu à voix haute devant les autres : le texte a été calibré pour l’oreille, pas pour l’œil."},
{t:'langue',q:"Quelle part d’un texte anglais courant les 100 mots les plus fréquents représentent-ils ?",n:50,min:0,max:100,u:"%",e:"La moitié. Cent petits mots — the, of, and, to — occupent un mot sur deux d’un texte ordinaire. Tout le vocabulaire savant se dispute l’autre moitié."},
{t:'langue',q:"Combien de caractères compte À la recherche du temps perdu, le plus long roman du monde ?",n:9609000,min:0,max:40000000,u:"caractères",e:"9 609 000 caractères, record homologué par le Guinness. Soit environ 1,2 million de mots. Proust corrigeait tellement ses épreuves que ses imprimeurs facturaient les retouches plus cher que la composition."},
{t:'langue',q:"Combien de mots compte la plus longue phrase de la littérature anglaise, dans un roman de Jonathan Coe ?",n:13955,min:0,max:25000,u:"mots",e:"13 955 mots sans un seul point : la dernière phrase du Cercle fermé. Coe visait explicitement le record, détenu jusque-là par une phrase de 12 931 mots."},
{t:'langue',q:"Combien de mots compte la dernière phrase d’Ulysse de James Joyce ?",n:4391,min:0,max:10000,u:"mots",e:"4 391 mots sans ponctuation, le monologue de Molly Bloom qui s’achève sur « oui je veux bien Oui ». Joyce disait avoir mis assez d’énigmes dedans pour occuper les professeurs pendant trois siècles."},
{t:'langue',q:"Combien de mots compte le roman « Gadsby », écrit entièrement sans la lettre E ?",n:50110,min:0,max:100000,u:"mots",e:"50 110 mots sans un seul E, en anglais, où c’est la lettre la plus fréquente. Ernest Vincent Wright avait attaché la touche E de sa machine à écrire pour ne pas céder à la tentation."},
{t:'langue',q:"Combien de mots compte le Mahabharata, la plus longue épopée jamais écrite ?",n:1800000,min:0,max:3000000,u:"mots",e:"Environ 1,8 million de mots, soit près de dix fois l’Iliade et l’Odyssée réunies. Transmis oralement pendant des siècles avant d’être fixé : des générations d’aèdes l’ont su par cœur."},
{t:'langue',q:"À quelle vitesse parlait l’homme le plus rapide du monde, record en poche ?",n:637,min:0,max:1200,u:"mots/minute",e:"637 mots par minute, quatre fois le débit normal. Steve Woodmore, vendeur d’électronique britannique, récitait du Shakespeare à cette allure en restant parfaitement compréhensible."},
{t:'langue',q:"Combien de langues parlait l’homme le plus polyglotte jamais homologué ?",n:42,min:0,max:80,u:"langues",e:"42 langues, vérifiées une par une par des examinateurs assermentés : le Canadien Powell Janulus a passé les tests pendant des années pour décrocher le record officiel."},
{t:'langue',q:"Combien de consonnes claquantes (« clics ») compte la langue xhosa d’Afrique du Sud ?",n:18,min:0,max:30,u:"clics",e:"18 clics différents, produits par la langue contre le palais ou les dents. Ces sons, absents de presque toutes les langues du monde, viennent du contact ancien avec les peuples khoïsan."},
{t:'langue',q:"Combien de voyelles comptait l’oubykh, langue du Caucase éteinte au XXe siècle ?",n:2,min:0,max:5,u:"voyelles",e:"Deux voyelles… pour plus de quatre-vingts consonnes, un record mondial. Le dernier locuteur, Tevfik Esenç, est mort en 1992 en Turquie ; il avait fait enregistrer sa langue avant de partir."},
{t:'langue',q:"Combien de cas grammaticaux compte le tsez, langue du Daghestan ?",n:64,min:0,max:150,u:"cas",e:"64 cas, contre six en latin et zéro en français. La plupart servent à situer précisément : dessus, dessous, à l’intérieur, en s’approchant, en s’éloignant. Une préposition intégrée à chaque nom."},
{t:'langue',q:"Combien de formes différentes un seul verbe peut-il prendre en artchi, langue du Caucase ?",n:1500000,min:0,max:4000000,u:"formes",e:"Environ 1,5 million de formes théoriques pour un unique verbe, selon les linguistes qui les ont recensées. Le français plafonne à une petite centaine. Personne ne les emploie toutes, évidemment."},
{t:'langue',q:"Combien de points rapporterait « oxyphenbutazone », le meilleur coup théorique au Scrabble ?",n:1778,min:0,max:3000,u:"points",e:"1 778 points en un seul coup, pour un anti-inflammatoire de quinze lettres. Il faudrait une grille préparée au millimètre : le meilleur score jamais réalisé en partie réelle est de 830 points."},
{t:'langue',q:"Combien de mots la perruche la plus bavarde du monde connaissait-elle ?",n:1728,min:0,max:2000,u:"mots",e:"1 728 mots pour Puck, une perruche ondulée américaine : plus de vocabulaire que bien des enfants de trois ans. Son record figure toujours au Guinness des records."},
{t:'langue',q:"Combien d’objets différents le chien le plus savant du monde savait-il nommer ?",n:1022,min:0,max:2500,u:"objets",e:"1 022 jouets, appris un par un par Chaser, une border collie du Wofford College. Elle savait aussi qu’un mot inconnu désignait forcément l’objet inconnu : un raisonnement d’enfant humain."}
];
